#[derive(Debug, Clone, PartialEq)]
pub struct SinkEvent {
    /// Stable durable queue identity for receiver deduplication across retries.
    pub action_id: u64,
    pub event_type: String,
    pub table: String,
    pub row_values: HashMap<String, Value>,
    pub severity: String,
    pub at_lsn: Lsn,
}

// Public serialization carries the identity in both human-readable and binary
// formats. The durable queue has its own positional codec below.
impl Serialize for SinkEvent {
    fn serialize<S>(&self, serializer: S) -> std::result::Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        if serializer.is_human_readable() {
            use serde::ser::SerializeStruct;
            let mut state = serializer.serialize_struct("SinkEvent", 6)?;
            state.serialize_field("action_id", &self.action_id)?;
            state.serialize_field("event_type", &self.event_type)?;
            state.serialize_field("table", &self.table)?;
            state.serialize_field("row_values", &self.row_values)?;
            state.serialize_field("severity", &self.severity)?;
            state.serialize_field("at_lsn", &self.at_lsn)?;
            state.end()
        } else {
            (
                &self.action_id,
                &self.event_type,
                &self.table,
                &self.row_values,
                &self.severity,
                &self.at_lsn,
            )
                .serialize(serializer)
        }
    }
}

impl<'de> Deserialize<'de> for SinkEvent {
    fn deserialize<D>(deserializer: D) -> std::result::Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        if deserializer.is_human_readable() {
            #[derive(Deserialize)]
            struct HumanSinkEvent {
                #[serde(default)]
                action_id: u64,
                event_type: String,
                table: String,
                row_values: HashMap<String, Value>,
                severity: String,
                at_lsn: Lsn,
            }
            let event = HumanSinkEvent::deserialize(deserializer)?;
            Ok(Self {
                action_id: event.action_id,
                event_type: event.event_type,
                table: event.table,
                row_values: event.row_values,
                severity: event.severity,
                at_lsn: event.at_lsn,
            })
        } else {
            let (action_id, event_type, table, row_values, severity, at_lsn) =
                <(u64, String, String, HashMap<String, Value>, String, Lsn)>::deserialize(
                    deserializer,
                )?;
            Ok(Self {
                action_id,
                event_type,
                table,
                row_values,
                severity,
                at_lsn,
            })
        }
    }
}

#[cfg(test)]
mod sink_event_encoding_tests {
    use super::*;

    #[test]
    fn action_identity_survives_external_json_and_binary_encoding() {
        let event = SinkEvent {
            action_id: 17,
            event_type: "notice".to_string(),
            table: "notifications".to_string(),
            row_values: HashMap::new(),
            severity: "warning".to_string(),
            at_lsn: Lsn(9),
        };
        let previous_bytes =
            bincode::serde::encode_to_vec(&event, bincode::config::standard()).unwrap();
        let (decoded, _): (SinkEvent, usize) =
            bincode::serde::decode_from_slice(&previous_bytes, bincode::config::standard())
                .unwrap();
        assert_eq!(decoded.action_id, 17);
        assert_eq!(decoded.event_type, event.event_type);
        assert_eq!(serde_json::to_value(&event).unwrap()["action_id"], 17);
    }
}

