/// Identity of one open database handle, handed out at construction and never
/// reused.
///
/// The thread-local registers below ask "is this work THIS database's?" -- is
/// the rows-examined scope on the stack this statement's, is the callback that
/// is running this handle's, is this handle's operation already open. An
/// address cannot answer that: a dropped handle frees its address for the next
/// one, so two handles that never coexisted can carry the same number and one
/// is then mistaken for the other. What that costs is not theoretical for the
/// first of those registers -- a colliding key mixes one database's examined
/// rows into another's trace, and the number an operator reads to judge a
/// query is then partly somebody else's.
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub(crate) struct DatabaseId(u64);

static NEXT_DATABASE_ID: AtomicU64 = AtomicU64::new(1);

impl DatabaseId {
    fn next() -> Self {
        Self(NEXT_DATABASE_ID.fetch_add(1, Ordering::Relaxed))
    }
}

#[cfg(any(test, feature = "test-seams"))]
#[derive(Debug, Default)]
struct MaintenancePollIntervalUpdateProbe {
    entries: Mutex<u64>,
    changed: Condvar,
}

#[cfg(any(test, feature = "test-seams"))]
impl MaintenancePollIntervalUpdateProbe {
    fn note_entered(&self) {
        let mut entries = self.entries.lock();
        *entries = entries.saturating_add(1);
        self.changed.notify_all();
    }

    fn entries(&self) -> u64 {
        *self.entries.lock()
    }

    fn wait_for(&self, target: u64) {
        let mut entries = self.entries.lock();
        while *entries < target {
            self.changed.wait(&mut entries);
        }
    }
}

#[derive(Debug)]
struct ActiveQueryRowsExaminedScope {
    id: u64,
    database_key: DatabaseId,
    rows_examined: u64,
}

#[derive(Debug, Default)]
struct QueryRowsExaminedScopes {
    next_id: u64,
    active: Vec<ActiveQueryRowsExaminedScope>,
}

thread_local! {
    static QUERY_ROWS_EXAMINED_SCOPES: std::cell::RefCell<QueryRowsExaminedScopes> =
        std::cell::RefCell::new(QueryRowsExaminedScopes::default());
}

#[cfg(any(test, feature = "test-seams"))]
thread_local! {
    static PASSIVE_DISCLOSURE_HIDDEN_WORK: std::cell::Cell<(u64, u64)> =
        const { std::cell::Cell::new((0, 0)) };
}

struct QueryRowsExaminedScope<'a> {
    database: &'a Database,
    database_key: DatabaseId,
    id: u64,
    finished: bool,
}

impl<'a> QueryRowsExaminedScope<'a> {
    fn enter(database: &'a Database) -> Self {
        let database_key = database.id;
        let id = QUERY_ROWS_EXAMINED_SCOPES.with(|scopes| {
            let mut scopes = scopes.borrow_mut();
            let id = scopes.next_id;
            scopes.next_id = scopes.next_id.wrapping_add(1);
            scopes.active.push(ActiveQueryRowsExaminedScope {
                id,
                database_key,
                rows_examined: 0,
            });
            id
        });
        database.rows_examined.store(0, Ordering::SeqCst);
        Self {
            database,
            database_key,
            id,
            finished: false,
        }
    }

    fn finish(mut self, result: &mut Result<QueryResult>) {
        let rows_examined = self.remove_active_scope();
        self.database
            .rows_examined
            .store(rows_examined, Ordering::SeqCst);
        if let Ok(result) = result {
            result.trace.rows_examined = rows_examined;
        }
        self.finished = true;
    }

    fn remove_active_scope(&self) -> u64 {
        QUERY_ROWS_EXAMINED_SCOPES.with(|scopes| {
            let mut scopes = scopes.borrow_mut();
            let position = scopes
                .active
                .iter()
                .rposition(|scope| scope.id == self.id && scope.database_key == self.database_key)
                .expect("active query rows-examined scope");
            scopes.active.remove(position).rows_examined
        })
    }
}

impl Drop for QueryRowsExaminedScope<'_> {
    fn drop(&mut self) {
        if !self.finished {
            let _ = self.remove_active_scope();
        }
    }
}

