struct DatabaseOperationGuard<'a> {
    db_id: DatabaseId,
    _lock: Option<parking_lot::RwLockReadGuard<'a, ()>>,
    // Every outer public operation observes one table-schema publication.
    // Local/received DDL already owns the write side before entering here, so
    // this re-entrant read acquisition never attempts a read-to-write upgrade.
    _schema_publication: Option<SchemaPublicationGuard<'a>>,
}

#[derive(Default)]
struct ReadPublicationGateState {
    readers: BTreeMap<String, usize>,
    writer_scope: Option<BTreeSet<String>>,
    writer_active: bool,
    wake_generation: u64,
}

#[derive(Default)]
struct ReadPublicationGate {
    state: Mutex<ReadPublicationGateState>,
    changed: Condvar,
}

struct ReadPublicationWake(std::sync::Weak<ReadPublicationGate>);

impl std::task::Wake for ReadPublicationWake {
    fn wake(self: Arc<Self>) {
        if let Some(gate) = self.0.upgrade() {
            let mut state = gate.state.lock();
            state.wake_generation = state.wake_generation.wrapping_add(1);
            gate.changed.notify_all();
        }
    }

    fn wake_by_ref(self: &Arc<Self>) {
        if let Some(gate) = self.0.upgrade() {
            let mut state = gate.state.lock();
            state.wake_generation = state.wake_generation.wrapping_add(1);
            gate.changed.notify_all();
        }
    }
}

pub(crate) struct AuthoritativeReadPublicationGuard {
    gate: Arc<ReadPublicationGate>,
    tables: BTreeSet<String>,
}

struct AuthoritativePurgePublicationGuard {
    gate: Arc<ReadPublicationGate>,
}

fn publication_scopes_conflict(left: &BTreeSet<String>, right: &BTreeSet<String>) -> bool {
    left.contains("*") || right.contains("*") || left.iter().any(|table| right.contains(table))
}

impl ReadPublicationGate {
    fn acquire_read(
        self: &Arc<Self>,
        scope: &crate::executor::ReadPublicationScope,
    ) -> Result<AuthoritativeReadPublicationGuard> {
        let budget = &scope.budget;
        // Active time expires only after the boundary, not at equality.
        let deadline_ms = budget.deadline_ms();
        let mut expiry = budget.clock.wait_until(deadline_ms);
        let mut expiry_completed = false;
        let waker = std::task::Waker::from(Arc::new(ReadPublicationWake(Arc::downgrade(self))));
        let mut context = std::task::Context::from_waker(&waker);
        let weak = Arc::downgrade(self);
        let _cancellation = budget.cancellation.tell_on_cancel(move || {
            if let Some(gate) = weak.upgrade() {
                let mut state = gate.state.lock();
                state.wake_generation = state.wake_generation.wrapping_add(1);
                gate.changed.notify_all();
            }
        });
        let mut state = self.state.lock();
        loop {
            if budget.cancellation.is_cancelled() {
                return Err(Error::ReadCancelled);
            }
            if budget.elapsed() {
                return Err(Error::ReadFailure(budget.exceeded_failure()));
            }
            let conflicts = state
                .writer_scope
                .as_ref()
                .is_some_and(|writer| publication_scopes_conflict(&scope.tables, writer));
            if !conflicts {
                for table in &scope.tables {
                    *state.readers.entry(table.clone()).or_default() += 1;
                }
                return Ok(AuthoritativeReadPublicationGuard {
                    gate: Arc::clone(self),
                    tables: scope.tables.clone(),
                });
            }
            // The timer governs time spent waiting behind an authoritative
            // purge. Polling it on an uncontended publication lets a clock's
            // wake implementation veto a result that never waited at all.
            let observed_wake = state.wake_generation;
            drop(state);
            if !expiry_completed {
                expiry_completed =
                    std::future::Future::poll(std::pin::Pin::as_mut(&mut expiry), &mut context)
                        .is_ready();
            }
            if budget.elapsed() {
                return Err(Error::ReadFailure(budget.exceeded_failure()));
            }
            state = self.state.lock();
            // Timer, cancellation, and publication release all advance this
            // generation while holding the same mutex. A wake between polling
            // and sleeping is therefore observed here instead of being lost.
            if state.wake_generation == observed_wake {
                if expiry_completed {
                    match budget.remaining_wait() {
                        crate::executor::ReadPublicationDeadline::Active(remaining) => {
                            self.changed.wait_for(&mut state, remaining);
                        }
                        crate::executor::ReadPublicationDeadline::Elapsed => continue,
                    }
                } else {
                    self.changed.wait(&mut state);
                }
            }
        }
    }

    fn acquire_write(
        self: &Arc<Self>,
        tables: &BTreeSet<String>,
    ) -> AuthoritativePurgePublicationGuard {
        let mut state = self.state.lock();
        while state.writer_scope.is_some() {
            self.changed.wait(&mut state);
        }
        state.writer_scope = Some(tables.clone());
        while state.readers.iter().any(|(table, count)| {
            *count != 0 && (tables.contains("*") || table == "*" || tables.contains(table))
        }) {
            self.changed.wait(&mut state);
        }
        state.writer_active = true;
        AuthoritativePurgePublicationGuard {
            gate: Arc::clone(self),
        }
    }
}

impl Drop for AuthoritativeReadPublicationGuard {
    fn drop(&mut self) {
        let mut state = self.gate.state.lock();
        for table in &self.tables {
            if let Some(count) = state.readers.get_mut(table) {
                *count = count.saturating_sub(1);
                if *count == 0 {
                    state.readers.remove(table);
                }
            }
        }
        state.wake_generation = state.wake_generation.wrapping_add(1);
        drop(state);
        self.gate.changed.notify_all();
    }
}

impl Drop for AuthoritativePurgePublicationGuard {
    fn drop(&mut self) {
        let mut state = self.gate.state.lock();
        state.writer_active = false;
        state.writer_scope = None;
        state.wake_generation = state.wake_generation.wrapping_add(1);
        drop(state);
        self.gate.changed.notify_all();
    }
}

#[cfg(test)]
mod read_publication_wait_tests {
    use super::*;
    use crate::local_transport::MonotonicDeadlineClock;
    use contextdb_core::read_contract::{DeadlineClock, DeadlineWait, OwnerReadCancellation};
    use std::future::poll_fn;
    use std::sync::Barrier;
    use std::sync::atomic::{AtomicU64, AtomicUsize, Ordering};
    use std::sync::mpsc::{Receiver, SyncSender, sync_channel};

    struct ControlledReadyClock {
        now: AtomicU64,
        advance_on_poll: Option<u64>,
        first_poll: Mutex<Option<SyncSender<()>>>,
        release_first_poll: Option<Arc<Barrier>>,
        polls: AtomicUsize,
    }

    impl DeadlineClock for ControlledReadyClock {
        fn now_ms(&self) -> u64 {
            self.now.load(Ordering::SeqCst)
        }

        fn wait_until(&self, _deadline_ms: u64) -> DeadlineWait<'_> {
            Box::pin(poll_fn(move |_| {
                let poll = self.polls.fetch_add(1, Ordering::SeqCst);
                if let Some(now) = self.advance_on_poll {
                    self.now.store(now, Ordering::SeqCst);
                }
                if poll == 0 {
                    if let Some(started) = self.first_poll.lock().take() {
                        let _ = started.send(());
                    }
                    if let Some(release) = self.release_first_poll.as_ref() {
                        release.wait();
                    }
                }
                std::task::Poll::Ready(())
            }))
        }
    }

    fn controlled_clock(
        now: u64,
        advance_on_poll: Option<u64>,
        block_first_poll: bool,
    ) -> (
        Arc<ControlledReadyClock>,
        Receiver<()>,
        Option<Arc<Barrier>>,
    ) {
        let (sent, received) = sync_channel(1);
        let release = block_first_poll.then(|| Arc::new(Barrier::new(2)));
        (
            Arc::new(ControlledReadyClock {
                now: AtomicU64::new(now),
                advance_on_poll,
                first_poll: Mutex::new(Some(sent)),
                release_first_poll: release.clone(),
                polls: AtomicUsize::new(0),
            }),
            received,
            release,
        )
    }

    fn scope(
        clock: Arc<dyn DeadlineClock>,
        cancellation: OwnerReadCancellation,
    ) -> crate::executor::ReadPublicationScope {
        crate::executor::ReadPublicationScope {
            snapshot_lsn: Lsn(1),
            tables: BTreeSet::from(["items".to_owned()]),
            budget: crate::executor::ReadPublicationBudget {
                clock,
                cancellation,
                started_ms: 0,
                active_ms: 20,
            },
        }
    }

    #[test]
    fn owner_publication_wait_has_no_false_timer_refusal_repoll_or_lost_release_wake() {
        let gate = Arc::new(ReadPublicationGate::default());
        let writer = gate.acquire_write(&BTreeSet::from(["items".to_owned()]));
        let (clock, polled, release) = controlled_clock(20, None, true);
        let reader_gate = Arc::clone(&gate);
        let reader_scope = scope(clock.clone(), OwnerReadCancellation::new());
        let reader = std::thread::spawn(move || reader_gate.acquire_read(&reader_scope));
        polled.recv().expect("the contended reader polls its timer");
        drop(writer);
        release.expect("first poll is controlled").wait();
        let admission = reader.join().expect("owner reader thread exits");
        assert!(
            admission.is_ok(),
            "timer readiness at the exact active-time boundary cannot refuse admission"
        );
        assert_eq!(
            clock.polls.load(Ordering::SeqCst),
            1,
            "a completed early timer is not repolled after the release wake"
        );
    }

    #[test]
    fn owner_publication_wait_wakes_for_cancellation_and_refuses_only_after_elapsed_deadline() {
        let gate = Arc::new(ReadPublicationGate::default());
        let writer = gate.acquire_write(&BTreeSet::from(["items".to_owned()]));
        let cancellation = OwnerReadCancellation::new();
        let (clock, polled, release) = controlled_clock(0, None, true);
        let reader_gate = Arc::clone(&gate);
        let reader_scope = scope(clock.clone(), cancellation.clone());
        let reader = std::thread::spawn(move || reader_gate.acquire_read(&reader_scope));
        polled
            .recv()
            .expect("the cancellable reader polls its timer");
        cancellation.cancel();
        release.expect("first poll is controlled").wait();
        assert!(matches!(
            reader.join().expect("cancelled owner reader exits"),
            Err(Error::ReadCancelled)
        ));
        assert_eq!(clock.polls.load(Ordering::SeqCst), 1);
        drop(writer);

        let deadline_gate = Arc::new(ReadPublicationGate::default());
        let _deadline_writer = deadline_gate.acquire_write(&BTreeSet::from(["items".to_owned()]));
        let (deadline_clock, _, _) = controlled_clock(0, Some(21), false);
        let error = match deadline_gate
            .acquire_read(&scope(deadline_clock, OwnerReadCancellation::new()))
        {
            Ok(_) => panic!("elapsed contended publication must refuse"),
            Err(error) => error,
        };
        assert!(matches!(
            error,
            Error::ReadFailure(failure)
                if failure.kind()
                    == contextdb_core::read_contract::ReadFailureKind::OwnerLimitExceeded
        ));
    }

    #[test]
    fn owner_publication_timer_arm_failure_uses_the_real_remaining_budget_once() {
        let gate = Arc::new(ReadPublicationGate::default());
        let writer = gate.acquire_write(&BTreeSet::from(["items".to_owned()]));
        let clock = Arc::new(MonotonicDeadlineClock::with_timer_arm_failure_for_test());
        let reader_gate = Arc::clone(&gate);
        let reader_scope = scope(clock.clone(), OwnerReadCancellation::new());
        let (sent, received) = sync_channel(1);
        let reader = std::thread::spawn(move || {
            let _ = sent.send(reader_gate.acquire_read(&reader_scope));
        });

        let result = received
            .recv_timeout(std::time::Duration::from_secs(1))
            .expect("the native remaining-budget wait bounds a failed timer arm");
        let error = match result {
            Ok(_) => panic!("a blocked writer still owns publication after the budget"),
            Err(error) => error,
        };
        assert!(matches!(
            error,
            Error::ReadFailure(failure)
                if failure.kind()
                    == contextdb_core::read_contract::ReadFailureKind::OwnerLimitExceeded
        ));
        assert_eq!(clock.timer_arm_failure_waits_for_test(), 1);
        assert_eq!(clock.timer_arm_failure_polls_for_test(), 1);
        drop(writer);
        reader.join().expect("owner arm-failure reader exits");
    }

    struct DeadlineCrossingClock {
        now_reads: AtomicUsize,
        polls: AtomicUsize,
    }

    impl DeadlineClock for DeadlineCrossingClock {
        fn now_ms(&self) -> u64 {
            let read = self.now_reads.fetch_add(1, Ordering::SeqCst);
            if read < 2 { 20 } else { 21 }
        }

        fn wait_until(&self, _deadline_ms: u64) -> DeadlineWait<'_> {
            Box::pin(poll_fn(move |_| {
                self.polls.fetch_add(1, Ordering::SeqCst);
                std::task::Poll::Ready(())
            }))
        }
    }

    #[test]
    fn owner_publication_deadline_crossing_never_becomes_an_unbounded_wait() {
        let gate = Arc::new(ReadPublicationGate::default());
        let writer = gate.acquire_write(&BTreeSet::from(["items".to_owned()]));
        let clock = Arc::new(DeadlineCrossingClock {
            now_reads: AtomicUsize::new(0),
            polls: AtomicUsize::new(0),
        });
        let reader_gate = Arc::clone(&gate);
        let reader_scope = scope(clock.clone(), OwnerReadCancellation::new());
        let (sent, received) = sync_channel(1);
        let reader = std::thread::spawn(move || {
            let _ = sent.send(reader_gate.acquire_read(&reader_scope));
        });

        let result = received
            .recv_timeout(std::time::Duration::from_secs(1))
            .expect("crossing the deadline must answer without publication release");
        let error = match result {
            Ok(_) => panic!("the elapsed publication budget must refuse"),
            Err(error) => error,
        };
        assert!(matches!(
            error,
            Error::ReadFailure(failure)
                if failure.kind()
                    == contextdb_core::read_contract::ReadFailureKind::OwnerLimitExceeded
        ));
        assert_eq!(clock.polls.load(Ordering::SeqCst), 1);
        drop(writer);
        reader.join().expect("deadline-crossing owner reader exits");
    }

    struct CommitWaitClock {
        now: AtomicU64,
        reads: AtomicUsize,
        waiting: SyncSender<()>,
    }

    impl DeadlineClock for CommitWaitClock {
        fn now_ms(&self) -> u64 {
            // The fourth read occurs after the commit-lock attempt has failed
            // and its first bounded wait has ended. This signals from the
            // wait itself, without sleeping to guess where the reader is.
            if self.reads.fetch_add(1, Ordering::SeqCst) == 3 {
                self.waiting
                    .send(())
                    .expect("test observes the commit wait");
            }
            self.now.load(Ordering::SeqCst)
        }

        fn wait_until(&self, _deadline_ms: u64) -> DeadlineWait<'_> {
            Box::pin(std::future::pending())
        }
    }

    #[test]
    fn final_read_publication_wait_refuses_cancellation_and_deadline_before_writer_release() {
        for expire in [false, true] {
            let database = Arc::new(Database::open_memory());
            let computed_answer = String::from("computed before the writer paused");
            let (writer_held, held_rx) = sync_channel(0);
            let (release_writer, release_rx) = sync_channel(0);
            let writer_database = Arc::clone(&database);
            let writer = std::thread::spawn(move || {
                writer_database.with_commit_lock(|| {
                    writer_held.send(()).expect("writer announces its lock");
                    release_rx.recv().expect("test releases the writer");
                });
            });
            held_rx
                .recv()
                .expect("writer reached the publication boundary");

            let cancellation = OwnerReadCancellation::new();
            let (waiting, waiting_rx) = sync_channel(0);
            let clock = Arc::new(CommitWaitClock {
                now: AtomicU64::new(0),
                reads: AtomicUsize::new(0),
                waiting,
            });
            let mut publication_scope = scope(clock.clone(), cancellation.clone());
            publication_scope.budget.active_ms = if expire { 1_000 } else { 5_000 };
            let published = Arc::new(std::sync::atomic::AtomicBool::new(false));
            let reader_database = Arc::clone(&database);
            let reader_published = Arc::clone(&published);
            let (answer, answer_rx) = sync_channel(0);
            let reader = std::thread::spawn(move || {
                let result = reader_database.publish_authoritative_read(
                    &publication_scope,
                    |error| error,
                    || {
                        reader_published.store(true, Ordering::SeqCst);
                        Ok(computed_answer)
                    },
                );
                answer.send(result).expect("test receives the read outcome");
            });
            waiting_rx
                .recv_timeout(std::time::Duration::from_secs(1))
                .expect("read reached the contended commit-lock wait");
            if expire {
                clock.now.store(1_001, Ordering::SeqCst);
            } else {
                cancellation.cancel();
            }
            let result = answer_rx
                .recv_timeout(std::time::Duration::from_secs(1))
                .expect("read refuses while the writer still holds the commit lock");
            if expire {
                assert!(matches!(
                    result,
                    Err(Error::ReadFailure(failure))
                        if failure.kind()
                            == contextdb_core::read_contract::ReadFailureKind::OwnerLimitExceeded
                ));
            } else {
                assert!(matches!(result, Err(Error::ReadCancelled)));
            }
            assert!(!published.load(Ordering::SeqCst));
            assert!(
                database
                    .read_publication_gate
                    .state
                    .lock()
                    .readers
                    .is_empty()
            );
            release_writer
                .send(())
                .expect("writer resumes after refusal");
            reader.join().expect("reader exits");
            writer.join().expect("writer exits");
        }
    }
}

/// Serializes table-schema publication against a whole SQL statement. Local
/// table DDL takes the write side; ordinary statements and EXPLAIN take the
/// read side. It is deliberately separate from the close-operation gate:
/// schema writers may wait for readers without changing close semantics.
pub(crate) struct SchemaPublicationGuard<'a> {
    gate_id: usize,
    _read: Option<parking_lot::RwLockReadGuard<'a, ()>>,
    _write: Option<parking_lot::RwLockWriteGuard<'a, ()>>,
}

/// Internal transport-orchestration lease that keeps one outbound extraction
/// and its wire evidence on the same published table schema.
///
/// The compiled transport orchestration lives in this crate; the server-path copy
/// is an uncompiled exact-source audit mirror. This lease therefore remains
/// crate-private and adds no downstream database capability.
#[cfg(feature = "sync-orchestration")]
pub(crate) struct OutboundSyncSchemaReadGuard<'a> {
    _inner: SchemaPublicationGuard<'a>,
}

struct TriggerCloseWaiterGuard<'a> {
    trigger: &'a TriggerState,
}

impl Drop for DatabaseOperationGuard<'_> {
    fn drop(&mut self) {
        DB_OPERATION_STACK.with(|stack| {
            let popped = stack.borrow_mut().pop();
            debug_assert_eq!(
                popped,
                Some(self.db_id),
                "database operation stack mismatch"
            );
        });
    }
}

impl DatabaseOperationGuard<'_> {
    /// A maintenance cycle keeps the close barrier but must not pin one
    /// schema publication across long vector preparation. The vector path
    /// samples its declaration and rejects a candidate whose revision changed
    /// before publication, so online policy DDL can proceed while an old
    /// candidate is being built.
    fn release_schema_publication_for_online_maintenance(&mut self) {
        self._schema_publication.take();
    }
}

impl Drop for SchemaPublicationGuard<'_> {
    fn drop(&mut self) {
        SCHEMA_PUBLICATION_STACK.with(|stack| {
            let popped = stack.borrow_mut().pop();
            debug_assert_eq!(
                popped,
                Some(self.gate_id),
                "schema publication stack mismatch"
            );
        });
    }
}

impl<'a> TriggerCloseWaiterGuard<'a> {
    fn new(trigger: &'a TriggerState) -> Self {
        trigger.close_waiter_count.fetch_add(1, Ordering::SeqCst);
        Self { trigger }
    }
}

impl Drop for TriggerCloseWaiterGuard<'_> {
    fn drop(&mut self) {
        self.trigger
            .close_waiter_count
            .fetch_sub(1, Ordering::SeqCst);
        self.trigger.waiters.notify_all();
    }
}

impl OpenRegistryReservation {
    fn acquire(path: PathBuf) -> Result<Self> {
        let registry = open_file_registry();
        let mut entries = registry.entries.lock();
        loop {
            match entries.get(&path).copied() {
                Some(state) if state.is_opening() => {
                    registry.waiters.wait(&mut entries);
                }
                Some(state) => {
                    return Err(Error::DatabaseLocked {
                        holder_pid: state.pid(),
                        path,
                    });
                }
                None => {
                    entries.insert(
                        path.clone(),
                        OpenRegistryState::Opening {
                            pid: std::process::id(),
                        },
                    );
                    return Ok(Self { path, active: true });
                }
            }
        }
    }

    fn disarm(mut self) -> PathBuf {
        let registry = open_file_registry();
        let mut entries = registry.entries.lock();
        entries.insert(
            self.path.clone(),
            OpenRegistryState::Open {
                pid: std::process::id(),
            },
        );
        registry.waiters.notify_all();
        self.active = false;
        self.path.clone()
    }
}

impl Drop for OpenRegistryReservation {
    fn drop(&mut self) {
        if self.active {
            let registry = open_file_registry();
            let mut entries = registry.entries.lock();
            if entries
                .get(&self.path)
                .copied()
                .is_some_and(|state| state.is_opening() && state.pid() == std::process::id())
            {
                entries.remove(&self.path);
                registry.waiters.notify_all();
            }
        }
    }
}

/// `readers` is the runtime directory this deployment's direct readers publish
/// themselves in, so a refusal names the readers actually holding the store.
/// `None` means nobody stated one and the platform default is where they are.
fn acquire_registry_and_persistence(
    canonical_path: &Path,
    open_disposition: OpenDisposition,
    cache_bytes: usize,
    runtime_dir: Option<&Path>,
) -> Result<(OpenRegistryReservation, Arc<RedbPersistence>)> {
    let retry_deadline = Instant::now() + SAME_PROCESS_REOPEN_RETRY;
    let cross_process_retry_deadline = Instant::now() + CROSS_PROCESS_LOCK_SETTLE_RETRY;

    loop {
        let registry_reservation =
            match OpenRegistryReservation::acquire(canonical_path.to_path_buf()) {
                Ok(reservation) => reservation,
                Err(Error::DatabaseLocked { holder_pid, path })
                    if holder_pid == std::process::id()
                        && path == canonical_path
                        && Instant::now() < retry_deadline =>
                {
                    wait_for_open_registry_change(Duration::from_millis(1));
                    continue;
                }
                Err(err) => return Err(err),
            };

        // This is the one place a writable open decides between taking a
        // store and bringing one into being, so it is the only place the
        // disposition can be enforced without inventing a second door. Under
        // `ExistingOnly` the existence question is not asked at all -- asking
        // it and then acting on the answer is precisely the race the
        // disposition exists to remove -- the ordinary open is attempted, and
        // the attempt's own "nothing here" is the typed refusal.
        let persistence = match open_disposition {
            OpenDisposition::ExistingOnly => {
                RedbPersistence::open_existing_only_with_cache_in_runtime_dir(
                    canonical_path,
                    cache_bytes,
                    runtime_dir,
                )
            }
            OpenDisposition::CreateIfMissing => {
                if canonical_path.exists() {
                    RedbPersistence::open_with_cache_in_runtime_dir(
                        canonical_path,
                        cache_bytes,
                        runtime_dir,
                    )
                } else {
                    RedbPersistence::create_with_accountant_in_runtime_dir(
                        canonical_path,
                        None,
                        cache_bytes,
                        runtime_dir,
                    )
                }
            }
        };

        match persistence {
            Ok(persistence) => return Ok((registry_reservation, Arc::new(persistence))),
            Err(Error::DatabaseLocked { holder_pid, path })
                if holder_pid == std::process::id()
                    && path == canonical_path
                    && Instant::now() < retry_deadline =>
            {
                drop(registry_reservation);
                wait_for_open_registry_change(Duration::from_millis(1));
            }
            Err(Error::DatabaseLocked { holder_pid, path })
                if holder_pid != std::process::id()
                    && path == canonical_path
                    && Instant::now() < cross_process_retry_deadline =>
            {
                drop(registry_reservation);
                wait_for_open_registry_change(Duration::from_millis(1));
            }
            Err(Error::ReadFailure(failure))
                if failure.kind() == ReadFailureKind::HeldByWriter
                    && Instant::now() < cross_process_retry_deadline =>
            {
                drop(registry_reservation);
                wait_for_open_registry_change(Duration::from_millis(1));
            }
            // HeldByReaders deliberately falls through: Redb has already
            // proved reader contention, so writer open refuses on this one
            // attempt instead of spending the writer-settle retry window.
            Err(err) => return Err(err),
        }
    }
}

fn wait_for_open_registry_change(timeout: Duration) {
    let registry = open_file_registry();
    let mut entries = registry.entries.lock();
    registry.waiters.wait_for(&mut entries, timeout);
}

fn release_open_registry_path(path: &Path) {
    let registry = open_file_registry();
    let mut entries = registry.entries.lock();
    if entries
        .get(path)
        .copied()
        .is_some_and(|state| state.pid() == std::process::id())
    {
        entries.remove(path);
        registry.waiters.notify_all();
    }
}

fn closed_database_error() -> Error {
    Error::Other("database handle is closed".to_string())
}

fn bounded_snapshot_publication_timeout() -> Error {
    Error::ReadFailure(
        ReadFailure::new(
            ReadFailureKind::OwnerTimeout,
            ReadFailureDetail::Reason {
                reason: "the writer has not published a complete read snapshot".to_string(),
            },
        )
        .expect("owner timeout accepts a reason"),
    )
}

pub(crate) struct ReadRegistrationBudget {
    clock: Arc<dyn DeadlineClock>,
    started_ms: u64,
    active_ms: u64,
}

impl ReadRegistrationBudget {
    pub(crate) fn new(clock: Arc<dyn DeadlineClock>, started_ms: u64, active_ms: u64) -> Self {
        Self {
            clock,
            started_ms,
            active_ms,
        }
    }

    fn remaining(&self) -> Result<Duration> {
        let elapsed = self
            .clock
            .now_ms()
            .checked_sub(self.started_ms)
            .ok_or_else(|| Error::Other("bounded deadline clock moved backwards".to_string()))?;
        if elapsed > self.active_ms {
            return Err(Error::ReadFailure(ReadFailure::owner_limit_exceeded(
                contextdb_core::read_contract::OwnerLimitExceededDetail {
                    limit: contextdb_core::read_contract::ReadFailureLimit::ActiveMs,
                    value: self.active_ms,
                    required: None,
                    statement: None,
                },
            )));
        }
        // The established active-time contract admits the exact boundary;
        // one millisecond of wait allowance lets the next clock observation
        // decide whether it has crossed that boundary.
        Ok(Duration::from_millis(
            (self.active_ms - elapsed).saturating_add(1),
        ))
    }

    fn elapsed_timeout(&self) -> Error {
        self.remaining()
            .err()
            .unwrap_or_else(bounded_snapshot_publication_timeout)
    }
}

#[cfg(test)]
mod owner_cursor_pin_retry_tests;

#[cfg(test)]
mod read_registration_budget_tests {
    use super::*;
    use contextdb_core::read_contract::{DeadlineWait, ReadFailureLimit};

    struct ManualClock(AtomicU64);

    impl DeadlineClock for ManualClock {
        fn now_ms(&self) -> u64 {
            self.0.load(Ordering::SeqCst)
        }

        fn wait_until(&self, _: u64) -> DeadlineWait<'_> {
            Box::pin(async {})
        }
    }

    #[test]
    fn active_time_exact_boundary_still_allows_registration() {
        let clock = Arc::new(ManualClock(AtomicU64::new(10)));
        let budget = ReadRegistrationBudget::new(clock.clone(), 0, 10);
        assert_eq!(budget.remaining().unwrap(), Duration::from_millis(1));
        clock.0.store(11, Ordering::SeqCst);
        assert!(matches!(
            budget.remaining(),
            Err(Error::ReadFailure(failure))
                if failure.kind() == ReadFailureKind::OwnerLimitExceeded
                    && matches!(failure.detail(), ReadFailureDetail::OwnerLimitExceeded(detail)
                        if detail.limit == ReadFailureLimit::ActiveMs)
        ));
    }
}

impl Database {
    pub(crate) fn custody_runtime(&self) -> Option<crate::custody::policy::Runtime> {
        self.custody_runtime.lock().clone()
    }
    pub(crate) fn set_custody_runtime(
        &self,
        tenant: TenantId,
        node: String,
        signer: crate::custody::preparation::LineageSigner,
    ) {
        *self.custody_runtime.lock() = Some(crate::custody::policy::Runtime {
            tenant,
            node,
            signer,
        });
    }

    pub(crate) fn stage_delivery_registration(
        &self,
        tx: TxId,
        registration: crate::custody::preparation::SourceRegistration,
    ) -> Result<()> {
        // A rejected registration aborts the writing transaction.
        let validated = self.tx_mgr.with_write_set(tx, |ws| {
            crate::custody::preparation::validate_registration(self, ws, &registration)?;
            ws.requires_commit_lsn = true;
            Ok(())
        })?;
        if let Err(error) = validated {
            self.rollback(tx)?;
            return Err(error);
        }
        self.pending_commit_metadata
            .lock()
            .entry(tx)
            .or_default()
            .delivery_registrations
            .push(registration);
        Ok(())
    }

    pub(crate) fn commit_delivery_prepared(
        &self,
        tx: TxId,
        prepare: &mut crate::custody::preparation::CommitPreparation<'_>,
    ) -> Result<()> {
        self.tx_mgr
            .with_write_set(tx, |ws| ws.requires_commit_lsn = true)?;
        self.commit_with_source_and_sync_ddl_and_trigger_audit_projection(
            tx,
            CommitSource::User,
            &[],
            &[],
            None,
            None,
            false,
            Some(prepare),
        )
        .map(|_| ())
    }

    pub(crate) fn rotate_custody_incarnation(
        &self,
        tenant: &TenantId,
        hub: &str,
        previous: Incarnation,
        next: Incarnation,
    ) -> Result<()> {
        use crate::custody::{canonical::*, preparation::*, records::*};
        let runtime = self.custody_runtime().ok_or_else(invalid)?;
        if runtime.tenant != *tenant || runtime.node != hub || self.retention_sync_peer().is_some()
        {
            return Err(invalid());
        }
        let signer = runtime.signer;
        let tx = self.begin()?;
        let mut installed = false;
        self.commit_delivery_prepared(tx, &mut |db, ws| {
            if db.existing_sync_incarnation(tenant)? != Some(previous) {
                return Ok(Vec::new());
            }
            let state = StateRecord {
                state: StateRef {
                    logical_store_id: uuid::Uuid::new_v4(),
                    incarnation: next,
                    birth_id: uuid::Uuid::new_v4(),
                    token: random_digest(),
                },
                parent: None,
                sequence: 0,
                retirement_root: crate::custody::authority::empty_history_root(),
            };
            let old = db.custody_records()?;
            let mut bindings = old
                .iter()
                .filter_map(|r| match r {
                    Record::Binding(b)
                        if b.namespace.tenant == *tenant
                            && b.namespace.hub_node == hub
                            && b.namespace.hub_incarnation == previous =>
                    {
                        Some(b.clone())
                    }
                    _ => None,
                })
                .collect::<Vec<_>>();
            // A declared snapshot can predate every binding.
            // The authenticated hub runtime already owns the tenant and identity.
            let mut records = state_records(db, state.clone(), tenant, hub)?;
            for b in &mut bindings {
                b.namespace.hub_incarnation = next;
                b.issuance_state = state.state.clone();
                b.issuance_source = (ws.commit_lsn.ok_or_else(invalid)?, 0);
                b.signature = signer(&b.bytes()?)?;
                records.push(Record::Binding(b.clone()));
            }
            ws.config_writes.push((
                tenant.config_key("sync_incarnation"),
                RedbPersistence::encode_config_value(&next.to_hex())?,
            ));
            installed = true;
            Ok(records)
        })?;
        if installed {
            self.sync_incarnations
                .lock()
                .insert(tenant.as_str().into(), next);
        }
        Ok(())
    }

    pub(crate) fn commit_delivery_metadata<F>(&self, prepare: F) -> Result<()>
    where
        F: FnOnce(Lsn) -> Result<Vec<crate::custody::records::Record>>,
    {
        let tx = self.begin()?;
        let mut prepare = Some(prepare);
        self.commit_delivery_prepared(tx, &mut |_, ws| {
            prepare
                .take()
                .ok_or_else(crate::custody::canonical::invalid)?(
                ws.commit_lsn
                    .ok_or_else(crate::custody::canonical::invalid)?,
            )
        })
    }

    /// A snapshot-in-time read of "is this handle closed right now" — reads
    /// the SAME two atomics `open_operation` checks, but takes NO lock and
    /// holds nothing: unlike `open_operation`'s guard, this cannot be held
    /// across a park/wait. Exists ONLY to let a `Result`-returning surface
    /// reject an ALREADY-closed handle before doing any work that would
    /// otherwise panic on it (`execute`'s snapshot-registration pre-flight,
    /// which resolves through the panicking public `Database::snapshot`) —
    /// never as a substitute for `open_operation`'s own real guard, whose
    /// `operation_gate` read lock is exactly what a parked waiter (e.g. a
    /// `BEGIN` waiting on an in-flight trigger callback) must NOT hold for
    /// the duration of its wait, since `close()` needs that gate's WRITE
    /// lock to ever complete. Racing this check against a close in
    /// progress is fine either way: a `false` here just means the function
    /// proceeds to its own real, later `open_operation()`/wait logic, which
    /// resolves the race correctly either way.
    fn already_closed(&self) -> bool {
        self.closed.load(Ordering::SeqCst) || self.resource_closed.load(Ordering::SeqCst)
    }
}

impl std::fmt::Debug for Database {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Database")
            .field("instance_id", &self.instance_id)
            .finish_non_exhaustive()
    }
}

