#[derive(Debug)]
struct PruningRuntime {
    shutdown: Arc<AtomicBool>,
    handle: Option<JoinHandle<()>>,
    interval_ms: Arc<AtomicU64>,
    // Wake-cycles STARTED by the current maintenance thread (incremented on
    // each wake, before the pending gate). Test-build only — production
    // carries neither the field nor the increment; the unit tests poll it as
    // the liveness half of a state-based wait.
    #[cfg(test)]
    wakes: Arc<AtomicU64>,
    worker_clock: Arc<MaintenanceWorkerClock>,
}

#[derive(Debug, Default)]
struct MaintenanceWorkerClockState {
    #[cfg(any(test, feature = "test-seams"))]
    held: bool,
    #[cfg(any(test, feature = "test-seams"))]
    requested_serial: u64,
    #[cfg(any(test, feature = "test-seams"))]
    completed_serial: u64,
    #[cfg(any(test, feature = "test-seams"))]
    completed_thread_id: Option<thread::ThreadId>,
    #[cfg(any(test, feature = "test-seams"))]
    waiting_while_held: bool,
    #[cfg(any(test, feature = "test-seams"))]
    worker_exited: bool,
}

#[derive(Debug, Default)]
struct MaintenanceWorkerClock {
    state: Mutex<MaintenanceWorkerClockState>,
    changed: Condvar,
}

impl MaintenanceWorkerClock {
    /// Wake the real maintenance wait in every build. Shutdown callers set
    /// the flag first, then notify, so a worker either observes shutdown
    /// before waiting or is released from this wait to observe it.
    fn wake(&self) {
        // Pair notification with the worker's predicate check under this
        // mutex. `wait_for` releases the mutex as it begins to wait, so the
        // notifier cannot slip between that check and the wait.
        let _state = self.state.lock();
        self.changed.notify_all();
    }

    fn reschedule(&self) {
        let _state = self.state.lock();
        self.changed.notify_all();
    }

    fn wait_for_cycle(&self, shutdown: &AtomicBool, interval_ms: &AtomicU64) -> Option<u64> {
        let mut state = self.state.lock();
        loop {
            if shutdown.load(Ordering::SeqCst) {
                #[cfg(any(test, feature = "test-seams"))]
                {
                    state.waiting_while_held = false;
                }
                self.changed.notify_all();
                return None;
            }
            #[cfg(any(test, feature = "test-seams"))]
            if state.held {
                state.waiting_while_held = true;
                self.changed.notify_all();
                if state.requested_serial > state.completed_serial {
                    state.waiting_while_held = false;
                    return Some(state.requested_serial);
                }
                self.changed.wait(&mut state);
                continue;
            }
            let interval = Duration::from_millis(interval_ms.load(Ordering::SeqCst).max(1));
            if self.changed.wait_for(&mut state, interval).timed_out() {
                return Some(0);
            }
        }
    }

    fn complete(&self, _serial: u64) {
        #[cfg(any(test, feature = "test-seams"))]
        if _serial != 0 {
            let mut state = self.state.lock();
            state.completed_serial = _serial;
            state.completed_thread_id = Some(thread::current().id());
            self.changed.notify_all();
        }
    }

    fn mark_worker_exited(&self) {
        #[cfg(any(test, feature = "test-seams"))]
        {
            let mut state = self.state.lock();
            state.waiting_while_held = false;
            state.worker_exited = true;
        }
        self.changed.notify_all();
    }

    #[cfg(any(test, feature = "test-seams"))]
    fn hold(&self) {
        self.state.lock().held = true;
        self.changed.notify_all();
    }

    #[cfg(any(test, feature = "test-seams"))]
    fn release(&self) {
        self.state.lock().held = false;
        self.changed.notify_all();
    }

    #[cfg(test)]
    fn wait_until_held_asleep(&self) {
        let mut state = self.state.lock();
        while !state.waiting_while_held && !state.worker_exited {
            self.changed.wait(&mut state);
        }
    }

    #[cfg(test)]
    fn worker_exited(&self) -> bool {
        self.state.lock().worker_exited
    }

    #[cfg(any(test, feature = "test-seams"))]
    fn wake_once(&self, shutdown: &AtomicBool) -> Result<VectorMaintenanceWorkerCycleForTest> {
        let mut state = self.state.lock();
        if !state.held {
            return Err(Error::Other(
                "engine-owned vector maintenance clock is not held".to_string(),
            ));
        }
        state.requested_serial = state.requested_serial.saturating_add(1);
        let requested = state.requested_serial;
        self.changed.notify_all();
        while state.completed_serial < requested && !shutdown.load(Ordering::SeqCst) {
            self.changed.wait(&mut state);
        }
        if state.completed_serial < requested {
            return Err(Error::Other(
                "engine-owned vector maintenance worker stopped before completing its wake"
                    .to_string(),
            ));
        }
        Ok(VectorMaintenanceWorkerCycleForTest {
            cycle_serial: requested,
            worker_thread_id: state.completed_thread_id.ok_or_else(|| {
                Error::Other("maintenance wake completed without a worker identity".to_string())
            })?,
        })
    }
}

#[doc(hidden)]
#[cfg(any(test, feature = "test-seams"))]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct VectorMaintenanceWorkerCycleForTest {
    pub cycle_serial: u64,
    pub worker_thread_id: thread::ThreadId,
}

#[doc(hidden)]
#[cfg(any(test, feature = "test-seams"))]
pub struct VectorMaintenanceWorkerClockGuardForTest {
    clock: Arc<MaintenanceWorkerClock>,
    shutdown: Arc<AtomicBool>,
}

#[cfg(any(test, feature = "test-seams"))]
impl VectorMaintenanceWorkerClockGuardForTest {
    pub fn wake_once(&self) -> Result<VectorMaintenanceWorkerCycleForTest> {
        self.clock.wake_once(&self.shutdown)
    }

    #[cfg(test)]
    fn wait_until_held_asleep(&self) {
        self.clock.wait_until_held_asleep();
    }

    #[cfg(test)]
    fn worker_exited(&self) -> bool {
        self.clock.worker_exited()
    }
}

#[cfg(any(test, feature = "test-seams"))]
impl Drop for VectorMaintenanceWorkerClockGuardForTest {
    fn drop(&mut self) {
        self.clock.release();
    }
}

#[derive(Debug, Clone, Default, PartialEq)]
pub struct PruningReport {
    pub pruned_rows: u64,
    pub blocked_count: u64,
    pub blocked: Vec<String>,
    /// An ESTIMATE of the live bytes the pruned row versions — and the vectors
    /// and edges that went with them — accounted for, on the same estimator
    /// [`TableSizeEstimate`] uses. It tracks the SIZE of what left, so two
    /// populations with the same row count and different payloads report
    /// materially different reclaim, but it is an accounting figure and NOT
    /// the number of bytes handed back to the filesystem: the estimator
    /// deliberately over-counts large values, and freed pages are reused in
    /// place unless a compaction runs. `file_bytes_before` / `file_bytes_after`
    /// carry the physical truth.
    pub reclaimed_bytes: u64,
    /// The database file's size before and after this cycle; `None` for an
    /// in-memory database, which has no file.
    pub file_bytes_before: Option<u64>,
    pub file_bytes_after: Option<u64>,
    /// Whether the file itself actually got smaller. Freed pages are reused in
    /// place, so a prune that does not compact frees space WITHOUT shrinking
    /// the file — this field says which happened.
    pub file_shrank: bool,
    /// Whether this cycle advanced durable storage compaction. A bounded
    /// sweep may require subsequent maintenance cycles to finish.
    pub compacted: bool,
    /// The storage layer's observed dead-space fraction as it stood BEFORE
    /// this cycle pruned anything — accumulated waste that survived page reuse
    /// from earlier cycles, not the space this prune just released. It is the
    /// value the compaction decision was taken on, so a cycle that pruned rows
    /// compacted exactly when this reached
    /// [`REDB_COMPACT_FRAGMENTATION_THRESHOLD`]. A cycle that pruned NOTHING
    /// never compacts, whatever this reads.
    pub fragmentation_before: f64,
    /// Rows carrying a timestamp further into the future than
    /// [`RETENTION_CLOCK_SKEW_TOLERANCE`]. They are never pruned early — and
    /// never silently pinned either: every cycle they stay future-dated counts
    /// them here and names their table below.
    pub future_dated_rows: u64,
    pub future_dated_tables: Vec<String>,
    /// Commit-index entries this cycle removed. The index holds one entry per
    /// commit and nothing used to remove them, so it grew with every write
    /// forever; retention now trims it to what a consumer can still name.
    pub pruned_commit_index_entries: u64,
    /// Expired rows this cycle left physically in place because a REGISTERED
    /// READER managed independently of an ordinary SQL statement — a
    /// caller-held snapshot pin or a bounded reader, including a suspended
    /// cursor — can still resolve to them. They are not blocked and not lost:
    /// the next cycle that runs with no reader holding them reclaims them.
    /// Without this count a cycle that deferred everything reads exactly like
    /// a cycle with nothing to reclaim, so an operator watching disk that is
    /// not coming back cannot tell that closing a reader is what would move
    /// it. Counted from the rows the pass actually held back, never from a
    /// configured expectation.
    pub rows_deferred_for_readers: u64,
}

/// What the engine-owned maintenance loop is doing for this database.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct MaintenanceStatus {
    /// Exactly `active_maintenance_loops > 0`.
    pub running: bool,
    /// This database holds at least one table that declares RETAIN.
    pub retention_enabled: bool,
    /// This database holds at least one table that declares `HISTORY
    /// CURRENT ONLY` — declaration-driven, not a fixed table-name list.
    pub currency_compaction_enabled: bool,
    /// Loops spawned for this database. Both jobs share ONE loop, so this is
    /// 1 whenever anything is maintained and 0 when nothing is.
    pub active_maintenance_loops: usize,
    /// Whether this database's maintenance is engine-owned (the default) or
    /// handed to the caller — see [`MaintenancePolicy`].
    pub policy: MaintenancePolicy,
}

/// Whether a database's maintenance loop is owned by the engine or handed to
/// the caller.
///
/// `EngineOwned` (the default) is what every database gets until a caller
/// asks otherwise: the engine spawns its own background thread the moment
/// anything is declared (a `RETAIN` window, `HISTORY CURRENT ONLY`, a
/// durable trigger-audit history, or maintained vector work), and stops it
/// when nothing remains to maintain. Initial vector construction and repair
/// advance through this maintenance path, outside foreground declarations,
/// writes, open, and queries; none waits for a full graph build.
///
/// `CallerDriven` hands the schedule to the host: the engine spawns ZERO
/// threads for this database, however much is declared, and the caller is
/// expected to drive `Database::run_maintenance_cycle` itself. A caller that
/// declares something and then never calls it does not fail silently: the
/// engine warns once, lazily, the next time a commit touches a declared
/// table after a full tick interval has passed with no cycle call (there is
/// no watchdog thread to emit the warning otherwise — `CallerDriven` means
/// zero threads, not "zero threads except a warning one").
///
/// This is engine OPEN-CONFIG, exactly like [`Database::trigger_audit_
/// retention`]: it lives on this in-process handle only, is never written to
/// the redb config store, and is never a DDL surface or a transported value.
/// A fresh handle reopened on the same path with no call to the setter is
/// `EngineOwned` again.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum MaintenancePolicy {
    #[default]
    EngineOwned,
    CallerDriven,
}

/// Everything one maintenance cycle did: generic retention, currency version
/// compaction, maintained vector-index progress, and the engine's own durable
/// trigger-audit retention.
#[derive(Debug, Clone, Default)]
pub struct MaintenanceReport {
    pub pruning: PruningReport,
    pub currency: CurrencyCompactionReport,
    pub vector: VectorMaintenanceReport,
    pub pruned_trigger_audit_rows: u64,
    /// The rare, interval-gated automatic compaction attempt this cycle made
    /// (see [`AUTO_COMPACT_MIN_INTERVAL`]) — `ran=false` on almost every
    /// cycle. Separate from, and never counted in, `currency.redb_compacted`
    /// / `pruning.compacted`, which now describe ONLY what those two scoped
    /// passes decided on their own (currency never compacts at all;
    /// retention keeps its existing per-cycle decision, unchanged).
    pub compaction: CompactionReport,
}

/// An honest per-table size answer: an ESTIMATE of the table's live bytes plus
/// its exact row count, with the whole file's size reported ALONGSIDE as
/// itself. The whole-file number is never divided between tables — several
/// tables share one file, and attributing physical bytes to one of them would
/// be a claim the engine cannot make.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TableSizeEstimate {
    pub table: String,
    pub estimated_live_bytes: u64,
    pub row_count: u64,
    pub whole_file_bytes: Option<u64>,
}

/// Every read snapshot currently entitled to resolve a version, keyed by a
/// registration token. Version cleanup consults EVERY registered snapshot
/// (not merely the lowest), while retention consults every reader-held
/// registration but not short-lived SQL statements. Each pass defers any
/// version visible to the registrations it samples rather than physically
/// removing it out from under a protected reader.
///
/// Three classes of caller register here:
/// - Every top-level statement execution (`execute`, `execute_in_tx`, and
///   `execute_at_snapshot` riding through `execute`) registers its own
///   snapshot for exactly that call's duration -- this closes the
///   mid-statement race with version cleanup: a long read resolving rows later
///   in the same statement can no longer have a superseded version vanish
///   underneath it.
/// - `Database::pin_snapshot` registers a snapshot for as long as the
///   returned guard lives, for a caller that holds a `SnapshotId` ACROSS
///   separate calls (the shape `execute_at_snapshot` alone cannot protect,
///   since a bare `SnapshotId` is a plain `Copy` value the engine has no way
///   to know is still wanted once a call returns).
/// - Bounded reads register independently of SQL statements; a suspended
///   cursor keeps that registration between pages for exactly its published
///   idle window.
#[derive(Default)]
struct SnapshotFloorRegistry {
    next_token: AtomicU64,
    /// The registered set AND the in-flight removal pass marker, under ONE
    /// lock -- a registration and a pass's registered-set/watermark sample
    /// can never interleave un-observed. (A previous design guarded these
    /// under two SEPARATE `Mutex`es and only claimed to share one; a
    /// `register` between the pass's sample and its persisted removal could
    /// land un-accounted-for and then return, promising protection the
    /// SAME in-flight pass was still free to violate.)
    state: Arc<Mutex<SnapshotFloorState>>,
    /// Wakes a `register` call blocked in the `while` loop below when a
    /// pass's `ActiveRemovalPassGuard` drops.
    pass_finished: Arc<Condvar>,
    /// Test-only pause point between a removal pass's registered-set/
    /// watermark sample (via `begin_removal_pass`) and its persisted
    /// removal -- armed only by
    /// `Database::pause_after_currency_floor_sample_for_test`; the
    /// production path's `maybe_pause` reads state that is never armed
    /// outside a test, so it is an immediate no-op there. Same
    /// `ApplyPhasePause`/`ApplyPhasePauseGuard` shape as the sync-apply
    /// pause seams -- real cross-thread wait/release is needed here (a
    /// `pin_snapshot` call on another thread must observe the pass as
    /// genuinely in progress), which a same-thread injection flag alone
    /// cannot provide.
    removal_pass_test_pause: Arc<ApplyPhasePause>,
    /// Production-dead interleaving seam: the durable read has captured its
    /// root but has not yet installed its registry hold. The commit lock must
    /// still be held here for both pulls and cursor openings.
    #[cfg(test)]
    durable_admission_test_pause: Arc<ApplyPhasePause>,
    #[cfg(test)]
    owner_cursor_busy_test_pause: Arc<ApplyPhasePause>,
}

/// One registered read snapshot, plus whatever the holder published about
/// how long it stays entitled to that snapshot. A statement's registration,
/// a caller-held pin, and an active bounded read carry no window: they last
/// exactly as long as the guard does. A suspended bounded cursor carries its
/// idle window, because the engine already refuses that cursor's next page
/// once the window has passed -- see [`CursorIdleWindow`].
struct RegisteredSnapshot {
    snapshot: SnapshotId,
    /// SQL statements own the rows they scan before completing the rest of
    /// their read, so retention does not let a continuous stream of those
    /// short-lived registrations pin every expired row. Reader-held
    /// registrations remain authoritative to retention as well as version
    /// cleanup.
    class: SnapshotRegistrationClass,
    /// `None` for a registration that stays entitled for as long as it is
    /// registered; `Some` for one whose holder has an idle deadline of its
    /// own.
    idle_window: Option<Arc<CursorIdleWindow>>,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum SnapshotRegistrationClass {
    Statement,
    ReaderHeld,
}

impl RegisteredSnapshot {
    /// Whether removal must still defer to this registration. A holder past
    /// its own idle deadline is refused its next page, so deferring to it
    /// would hold rows back for a reader that can never read them again.
    fn holder_still_entitled(&self) -> bool {
        self.idle_window
            .as_ref()
            .is_none_or(|window| window.holder_still_entitled())
    }
}

/// The idle window a suspended bounded cursor publishes to removal, read
/// off the SAME clock and the SAME `cursor_idle_ms` limit the cursor's own
/// next-page check uses, so both answer "is this reader still entitled?"
/// identically. The cursor stamps [`Self::touch`] every time it hands a page
/// back; a reader that walks away stops stamping and falls out of the
/// registered set that removal defers to.
pub(crate) struct CursorIdleWindow {
    clock: Arc<dyn DeadlineClock>,
    idle_ms: u64,
    last_used_ms: AtomicU64,
}

impl CursorIdleWindow {
    pub(crate) fn new(clock: Arc<dyn DeadlineClock>, idle_ms: u64, opened_ms: u64) -> Self {
        Self {
            clock,
            idle_ms,
            last_used_ms: AtomicU64::new(opened_ms),
        }
    }

    /// Record that the holder just used the cursor.
    pub(crate) fn touch(&self, now_ms: u64) {
        self.last_used_ms.store(now_ms, Ordering::SeqCst);
    }

    /// `true` while the holder is still inside its idle window. A clock that
    /// reads BACKWARDS yields a zero-length idle here rather than an early
    /// expiry: removal stays on the safe side and keeps deferring, and the
    /// cursor's own next-page check is the one that reports the disordered
    /// clock.
    fn holder_still_entitled(&self) -> bool {
        let idle = self
            .clock
            .now_ms()
            .saturating_sub(self.last_used_ms.load(Ordering::SeqCst));
        idle <= self.idle_ms
    }
}

#[derive(Default)]
struct SnapshotFloorState {
    active: HashMap<u64, RegisteredSnapshot>,
    /// `Some(pass)` while a physical-removal pass is in flight;
    /// `None` means no pass is active. Set by `begin_removal_pass` the
    /// moment a pass samples its registered set and watermark; cleared (and
    /// `pass_finished` notified) only by `ActiveRemovalPassGuard`'s `Drop`
    /// -- covering every exit path (success, an early return, or a
    /// `?`-propagated error) uniformly, so a pass can never leave this
    /// marker stuck.
    active_pass: Option<ActiveRemovalPass>,
}

/// One in-flight removal pass's own sampled marker -- captured ONCE, at the
/// moment `begin_removal_pass` locks `SnapshotFloorState`, and never
/// updated for the rest of the pass. The registered-snapshot set itself is
/// NOT duplicated here: it lives solely on `ActiveRemovalPassGuard` (the
/// pass's own deferral loop reads it from there), so this marker carries
/// only what `register`'s blocking rule needs.
#[derive(Clone, Copy)]
struct ActiveRemovalPass {
    /// The highest-committed `TxId` at the moment this pass began
    /// (`Database::committed_watermark`, threaded in by the caller under
    /// the SAME commit-lock hold the whole pass runs inside -- see
    /// `compact_currency_versions_inner`). Used ONLY to decide whether a
    /// registration racing in DURING this pass needs to block -- see
    /// `SnapshotFloorRegistry::register`'s blocking rule.
    watermark: TxId,
}

impl SnapshotFloorRegistry {
    /// Whether an in-flight removal pass must hold a registration for
    /// `snapshot` until the pass finishes.
    ///
    /// Blocking rule: a pass can only ever prune a version superseded AT OR
    /// BEFORE its own sampled `watermark` -- every row it can see was
    /// committed under the SAME commit-lock hold that produced `watermark`
    /// (`compact_currency_versions_inner` runs entirely inside
    /// `with_commit_lock`, so nothing commits in between). A registration
    /// for a snapshot STRICTLY AFTER `watermark` can therefore never
    /// resolve a version this pass might remove (its `deleted_tx` is
    /// `<= watermark < snapshot`, so `VersionedRow::visible_at` is false
    /// regardless), and may register immediately. A snapshot AT OR BEFORE
    /// `watermark` might be exactly what this pass is deciding about, and
    /// this pass's own deferral only consulted the registered set at ITS
    /// start -- which cannot already include a registration racing in now
    /// -- so it must wait for the pass to finish rather than register onto
    /// a sample that will never account for it.
    fn pass_holds(state: &SnapshotFloorState, snapshot: SnapshotId) -> bool {
        state
            .active_pass
            .is_some_and(|pass| snapshot.0 <= pass.watermark.0)
    }

    /// Cheap, racy peek at whether anything is registered right now, without
    /// beginning a removal pass. A registration can land the instant after
    /// this reads, so a caller may use `true` only to decide whether
    /// beginning a pass is worth attempting this cycle -- never as a
    /// correctness gate. The pass's own `begin_removal_pass_inner` samples
    /// the authoritative set atomically under the lock regardless of what
    /// this returned.
    fn no_snapshots_currently_registered(&self) -> bool {
        self.state.lock().active.is_empty()
    }

    fn register(self: &Arc<Self>, snapshot: SnapshotId) -> SnapshotRegistration {
        self.register_as(snapshot, SnapshotRegistrationClass::ReaderHeld)
    }

    fn register_as(
        self: &Arc<Self>,
        snapshot: SnapshotId,
        class: SnapshotRegistrationClass,
    ) -> SnapshotRegistration {
        let mut state = self.state.lock();
        while Self::pass_holds(&state, snapshot) {
            self.pass_finished.wait(&mut state);
        }
        self.admit(state, snapshot, class, None)
    }

    /// Register one statement and remember its exact token on this thread.
    /// The separate wrapper is deliberately not `Send`: its thread-local
    /// nesting marker must be removed on the same thread that installed it.
    fn register_statement(self: &Arc<Self>, snapshot: SnapshotId) -> StatementSnapshotRegistration {
        let registration = self.register_as(snapshot, SnapshotRegistrationClass::Statement);
        STATEMENT_SNAPSHOT_REGISTRATION_STACK
            .with(|stack| stack.borrow_mut().push(registration.token));
        StatementSnapshotRegistration {
            registration,
            _same_thread: std::marker::PhantomData,
        }
    }

    /// Register `snapshot` for a caller that can withdraw the read it is
    /// registering for -- a bounded read, whose holder may cancel while this
    /// call is parked behind an in-flight pass. The blocking rule is exactly
    /// [`Self::pass_holds`], but the park is answerable: pass completion and
    /// cancellation wake the condition variable, and the active read limit
    /// bounds the wait. A withdrawn caller gets `None` rather than a hold it
    /// no longer wants. `idle_window` is the window a SUSPENDED cursor
    /// publishes, so removal defers to it only while it is entitled to a page.
    fn register_withdrawable_with_budget(
        self: &Arc<Self>,
        snapshot: SnapshotId,
        idle_window: Option<Arc<CursorIdleWindow>>,
        budget: &ReadRegistrationBudget,
        withdrawn: &OwnerReadCancellation,
    ) -> Result<Option<SnapshotRegistration>> {
        let wake_on_cancel = Arc::clone(&self.pass_finished);
        let state_on_cancel = Arc::clone(&self.state);
        let _cancel_listener = withdrawn.tell_on_cancel(move || {
            // Take the condition's mutex so cancellation cannot notify in
            // the gap between the waiter's flag check and its atomic park.
            let _state = state_on_cancel.lock();
            wake_on_cancel.notify_all();
        });
        let mut state = self.state.lock();
        while Self::pass_holds(&state, snapshot) {
            if withdrawn.is_cancelled() {
                return Ok(None);
            }
            let remaining = budget.remaining()?;
            // A test clock may advance without notifying the pass condition.
            // Park between checks instead of busy-spinning on the registry.
            self.pass_finished
                .wait_for(&mut state, remaining.min(Duration::from_millis(5)));
        }
        if withdrawn.is_cancelled() {
            return Ok(None);
        }
        budget.remaining()?;
        Ok(Some(self.admit(
            state,
            snapshot,
            SnapshotRegistrationClass::ReaderHeld,
            idle_window,
        )))
    }

    /// Called only while holding the commit mutex that encloses every
    /// removal pass. Admission cannot park for a pass while that mutex is
    /// held. If this invariant is broken, refuse the read instead of waiting
    /// with the writer blocked and claiming to protect an unsafe snapshot.
    fn register_withdrawable_at_commit_boundary(
        self: &Arc<Self>,
        snapshot: SnapshotId,
        idle_window: Option<Arc<CursorIdleWindow>>,
        budget: &ReadRegistrationBudget,
        withdrawn: &OwnerReadCancellation,
    ) -> Result<Option<SnapshotRegistration>> {
        let state = self.state.lock();
        if Self::pass_holds(&state, snapshot) {
            return Err(bounded_snapshot_publication_timeout());
        }
        if withdrawn.is_cancelled() {
            return Ok(None);
        }
        budget.remaining()?;
        Ok(Some(self.admit(
            state,
            snapshot,
            SnapshotRegistrationClass::ReaderHeld,
            idle_window,
        )))
    }

    /// Take the registration slot under the lock the caller already holds,
    /// so nothing can begin a pass between the admission decision above and
    /// the registered set growing here.
    fn admit(
        self: &Arc<Self>,
        mut state: MutexGuard<'_, SnapshotFloorState>,
        snapshot: SnapshotId,
        class: SnapshotRegistrationClass,
        idle_window: Option<Arc<CursorIdleWindow>>,
    ) -> SnapshotRegistration {
        let token = self.next_token.fetch_add(1, Ordering::SeqCst);
        state.active.insert(
            token,
            RegisteredSnapshot {
                snapshot,
                class,
                idle_window,
            },
        );
        drop(state);
        SnapshotRegistration {
            registry: self.clone(),
            token,
        }
    }

    /// Begin a removal pass: clone the currently-registered snapshot set
    /// (sorted) and record `watermark` (the committed watermark the caller
    /// already sampled via `Database::committed_watermark`, under the same
    /// commit-lock hold the whole pass runs inside) as this pass's own,
    /// atomically with each other under `state`'s single lock -- a
    /// registration can never land between these two reads un-observed.
    /// Returns a guard that clears the marker and wakes every blocked
    /// `register` on drop -- hold it for the pass's FULL duration,
    /// including its persisted removal, so a late registration can never
    /// land on a sample the pass no longer accounts for. See
    /// `SnapshotFloorState::active_pass`'s doc comment.
    fn begin_removal_pass(self: &Arc<Self>, watermark: TxId) -> ActiveRemovalPassGuard {
        self.begin_removal_pass_inner(watermark, None, true)
    }

    /// Retention reclaims only versions no registered statement, explicit
    /// snapshot pin, or suspended bounded cursor can still observe.
    fn begin_retention_removal_pass(self: &Arc<Self>, watermark: TxId) -> ActiveRemovalPassGuard {
        self.begin_removal_pass_inner(watermark, None, true)
    }

    /// Begin the commit-time pass while omitting at most the exact statement
    /// registration that is publishing this commit. An explicit pin at the
    /// same snapshot has a different token and remains in the sample, as do
    /// every concurrent statement, suspended cursor, and outer callback.
    fn begin_removal_pass_excluding(
        self: &Arc<Self>,
        watermark: TxId,
        excluded_registration: Option<u64>,
    ) -> ActiveRemovalPassGuard {
        self.begin_removal_pass_inner(watermark, excluded_registration, true)
    }

    /// Begin a repair removal pass after admitting both allocations that
    /// coexist while its registered-snapshot sample moves from a collection
    /// buffer into the guard's retained slice. The registry lock stays held
    /// from the authoritative count through admission and sampling, and the
    /// pass marker is installed before that lock is released.
    fn begin_removal_pass_with_sample_admission(
        self: &Arc<Self>,
        watermark: TxId,
        admit_transition: impl FnOnce(usize) -> Result<()>,
    ) -> Result<(ActiveRemovalPassGuard, usize)> {
        let mut state = self.state.lock();
        // Capacity is bounded from the complete registered set before the
        // eligibility filter. This remains safe if an idle cursor expires
        // while the lock is held, and no registration can race the count.
        let sample_capacity = state.active.len();
        let vector_capacity_bound = if sample_capacity == 0 {
            0
        } else {
            sample_capacity.saturating_mul(2).max(4)
        };
        let arc_metadata_bound = std::mem::size_of::<usize>().saturating_mul(4);
        let transition_bound = vector_capacity_bound
            .saturating_mul(std::mem::size_of::<SnapshotId>())
            .saturating_add(sample_capacity.saturating_mul(std::mem::size_of::<SnapshotId>()))
            .saturating_add(arc_metadata_bound);
        admit_transition(transition_bound)?;

        let mut sampled_snapshots = Vec::with_capacity(sample_capacity);
        sampled_snapshots.extend(
            state
                .active
                .values()
                .filter(|registered| registered.holder_still_entitled())
                .map(|registered| registered.snapshot),
        );
        sampled_snapshots.sort_unstable();
        state.active_pass = Some(ActiveRemovalPass { watermark });
        drop(state);

        let retained_bytes = sampled_snapshots
            .len()
            .saturating_mul(std::mem::size_of::<SnapshotId>())
            .saturating_add(arc_metadata_bound);
        let registered_snapshots = Arc::<[SnapshotId]>::from(sampled_snapshots.as_slice());
        let guard = ActiveRemovalPassGuard {
            registry: self.clone(),
            registered_snapshots,
        };
        #[cfg(any(test, feature = "test-seams"))]
        maybe_pause_vector_repair_snapshot_sample_transition_for_test();
        drop(sampled_snapshots);
        Ok((guard, retained_bytes))
    }

    fn begin_removal_pass_inner(
        self: &Arc<Self>,
        watermark: TxId,
        excluded_registration: Option<u64>,
        include_statement_registrations: bool,
    ) -> ActiveRemovalPassGuard {
        let mut state = self.state.lock();
        // A registration whose holder is past its own idle deadline is left
        // out: the engine already refuses that holder's next page, so it is
        // no longer entitled to hold anything back. See
        // `RegisteredSnapshot::holder_still_entitled`.
        let mut registered_snapshots: Vec<SnapshotId> = state
            .active
            .iter()
            .filter(|(token, registered)| {
                Some(**token) != excluded_registration
                    && (include_statement_registrations
                        || registered.class != SnapshotRegistrationClass::Statement)
                    && registered.holder_still_entitled()
            })
            .map(|(_, registered)| registered.snapshot)
            .collect();
        registered_snapshots.sort_unstable();
        state.active_pass = Some(ActiveRemovalPass { watermark });
        drop(state);
        ActiveRemovalPassGuard {
            registry: self.clone(),
            registered_snapshots: registered_snapshots.into(),
        }
    }
}

/// RAII marker for one in-progress physical-removal pass -- see
/// `SnapshotFloorRegistry::begin_removal_pass` and
/// `SnapshotFloorRegistry::begin_retention_removal_pass`.
struct ActiveRemovalPassGuard {
    registry: Arc<SnapshotFloorRegistry>,
    /// This pass's own sorted snapshot of the registered set at the moment
    /// it began -- see `ActiveRemovalPass::registered_snapshots`. Exposed
    /// via `Self::registered_snapshots` so the pass's deferral loop
    /// consults the EXACT SAME set `register`'s blocking rule was computed
    /// against.
    registered_snapshots: Arc<[SnapshotId]>,
}

impl ActiveRemovalPassGuard {
    /// Every snapshot registered when this pass began, sorted ascending.
    fn registered_snapshots(&self) -> &[SnapshotId] {
        &self.registered_snapshots
    }
}

impl Drop for ActiveRemovalPassGuard {
    fn drop(&mut self) {
        self.registry.state.lock().active_pass = None;
        self.registry.pass_finished.notify_all();
    }
}

/// RAII handle for one registered read snapshot. Unregisters on drop,
/// whether that is the end of one statement's execution or the caller
/// dropping a held [`SnapshotPin`].
struct SnapshotRegistration {
    registry: Arc<SnapshotFloorRegistry>,
    token: u64,
}

impl Drop for SnapshotRegistration {
    fn drop(&mut self) {
        self.registry.state.lock().active.remove(&self.token);
    }
}

/// A statement-owned snapshot registration plus its same-thread nesting
/// marker. The inner registration remains live until this wrapper has removed
/// the token from the thread-local stack.
struct StatementSnapshotRegistration {
    registration: SnapshotRegistration,
    _same_thread: std::marker::PhantomData<std::rc::Rc<()>>,
}

impl Drop for StatementSnapshotRegistration {
    fn drop(&mut self) {
        STATEMENT_SNAPSHOT_REGISTRATION_STACK.with(|stack| {
            let mut stack = stack.borrow_mut();
            let position = stack
                .iter()
                .rposition(|token| *token == self.registration.token);
            debug_assert!(position.is_some(), "statement snapshot token is registered");
            if let Some(position) = position {
                stack.remove(position);
            }
        });
    }
}

/// Whether ANY snapshot in `registered_snapshots` (sorted ascending) is
/// still entitled to see `row` -- the generalization of
/// [`VersionedRow::visible_at`] to a full registered set rather than one
/// floor value. The smallest registered snapshot at or after
/// `row.created_tx` is the only candidate worth checking: a LARGER
/// registered snapshot can only ever have an EQUAL or LATER
/// `row.deleted_tx` comparison point, never an earlier one, so if the
/// smallest such candidate cannot see the row, no larger one can either --
/// this makes the check `O(log n)` per version (a binary search) rather
/// than `O(n)`.
fn any_registered_snapshot_sees(registered_snapshots: &[SnapshotId], row: &VersionedRow) -> bool {
    any_registered_snapshot_sees_version(registered_snapshots, row.created_tx, row.deleted_tx)
}

/// The same question for an ADJACENCY entry. An edge carries its own
/// creation and deletion stamps, and a schema-free store lets it point at an
/// id that carries no row at all, so whether a reader can still see the edge
/// is never answerable from the node rows around it -- see
/// [`any_registered_snapshot_sees_version`].
fn any_registered_snapshot_sees_edge(
    registered_snapshots: &[SnapshotId],
    entry: &AdjEntry,
) -> bool {
    any_registered_snapshot_sees_version(registered_snapshots, entry.created_tx, entry.deleted_tx)
}

/// Whether any registered snapshot still resolves a version created at
/// `created_tx` and deleted at `deleted_tx` -- the shared rule behind both
/// helpers above, with the same binary search over the sorted registered
/// set.
fn any_registered_snapshot_sees_version(
    registered_snapshots: &[SnapshotId],
    created_tx: TxId,
    deleted_tx: Option<TxId>,
) -> bool {
    let idx = registered_snapshots.partition_point(|s| s.0 < created_tx.0);
    match registered_snapshots.get(idx) {
        Some(candidate) => deleted_tx.is_none_or(|deleted| candidate.0 < deleted.0),
        None => false,
    }
}

/// A read snapshot held across separate calls. While this guard lives,
/// retention and version cleanup defer any version still visible at the
/// pinned snapshot to a later cycle.
///
/// Without a pin, a `SnapshotId` obtained from [`Database::snapshot`] and
/// reused in a LATER [`Database::execute_at_snapshot`] call is invisible to
/// the engine between the two calls: a cleanup cycle that runs in between
/// may reclaim a version that snapshot was entitled to see, and the later
/// call then silently returns fewer rows than it should — never a wrong
/// value, never an error, just missing data. This is the documented boundary
/// on a table declaring `RETAIN` or `HISTORY CURRENT ONLY`; a table that
/// declares neither keeps every version, so it never arises there. Pin the
/// snapshot for as long as you intend to reuse it if the table matters.
pub struct SnapshotPin<'a> {
    _database: &'a Database,
    _registration: SnapshotRegistration,
}

/// Whether a maintenance cycle's currency pass runs unconditionally (an
/// explicit call) or behind the cheap superseded-version gate (a scheduled
/// tick, so a quiet node never pays the commit lock).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum CurrencyGate {
    Always,
    Scheduled,
}

/// Persistence-owned raw-body loader for one partition. The object keeps no
/// vector values and no stale membership snapshot: each load resolves the
/// partition's current checksummed directory, which means a committed write
/// can leave the same partition evictable without publishing a new loader.
struct DurableRawVectorPartitionLoader {
    source: DurableRawVectorSource,
    accountant: Arc<MemoryAccountant>,
    partition: VectorPartitionRef,
    dimension: usize,
    quantization: VectorQuantization,
}

#[derive(Clone)]
enum DurableRawVectorSource {
    Writable(Arc<RedbPersistence>),
    CommittedImage(Arc<crate::persistence::RetainedReadSource>),
}

impl DurableRawVectorSource {
    fn stream_memberships<T>(
        &self,
        partition: &VectorPartitionRef,
        dimension: usize,
        quantization: VectorQuantization,
        prepare: impl FnOnce(usize) -> Result<T>,
        visit: impl FnMut(
            &mut T,
            VectorPartitionMembershipRecord,
            &mut dyn FnMut(&VectorPartitionMembershipRecord) -> Result<VectorEntry>,
        ) -> Result<()>,
    ) -> Result<T> {
        match self {
            Self::Writable(persistence) => persistence.stream_vector_partition_memberships(
                partition,
                dimension,
                quantization,
                prepare,
                visit,
            ),
            Self::CommittedImage(source) => source.stream_raw_vector_memberships(
                partition,
                dimension,
                quantization,
                prepare,
                visit,
            ),
        }
    }

    fn load_candidate(
        &self,
        partition: &VectorPartitionRef,
        identity: &RawVectorDirectoryEntry,
        dimension: usize,
        quantization: VectorQuantization,
    ) -> Result<VectorEntry> {
        match self {
            Self::Writable(persistence) => persistence.load_vector_entry_for_partition_identity(
                &partition.index,
                &partition.partition_key,
                identity,
                dimension,
                quantization,
            ),
            Self::CommittedImage(source) => source.load_raw_vector_entry_for_partition_identity(
                &partition.index,
                &partition.partition_key,
                identity,
                dimension,
                quantization,
            ),
        }
    }
}

impl DurableRawVectorPartitionLoader {
    fn checked_mul(left: usize, right: usize, name: &str) -> Result<usize> {
        left.checked_mul(right).ok_or_else(|| {
            Error::Other(format!(
                "raw vector {name} exceeds this process's addressable range"
            ))
        })
    }

    fn checked_add(left: usize, right: usize, name: &str) -> Result<usize> {
        left.checked_add(right).ok_or_else(|| {
            Error::Other(format!(
                "raw vector {name} exceeds this process's addressable range"
            ))
        })
    }

    fn stored_bytes_per_entry(&self) -> Result<usize> {
        match self.quantization {
            VectorQuantization::F32 => Self::checked_mul(
                self.dimension,
                std::mem::size_of::<f32>(),
                "stored F32 body",
            ),
            VectorQuantization::SQ8 => Self::checked_add(self.dimension, 8, "stored SQ8 body"),
            VectorQuantization::SQ4 => {
                Self::checked_add(self.dimension.div_ceil(2), 8, "stored SQ4 body")
            }
        }
    }

    fn load_checkpoint(request: &mut dyn FnMut(DormantVectorLoadRequest) -> bool) -> Result<()> {
        if request(DormantVectorLoadRequest::Checkpoint) {
            Ok(())
        } else {
            Err(Error::ReadCancelled)
        }
    }
}

impl DormantRawVectorLoader for DurableRawVectorPartitionLoader {
    fn supports_bounded_candidate_load(&self) -> bool {
        true
    }

    fn exact_comparison_streams_when_partition_does_not_fit(&self) -> bool {
        matches!(self.source, DurableRawVectorSource::CommittedImage(_))
    }

    fn load(&self, directory: &[RawVectorDirectoryEntry]) -> Result<LoadedRawVectorPartition> {
        let expected_entry_count = directory.len();
        let decoded_bytes_per_entry = Self::checked_mul(
            self.dimension,
            std::mem::size_of::<f32>(),
            "decoded F32 body",
        )?;
        let resident_bytes = Self::checked_mul(
            expected_entry_count,
            self.stored_bytes_per_entry()?,
            "partition residency",
        )?;
        // The returned entries also own their container and index strings.
        let index_bytes = Self::checked_add(
            self.partition.index.table.len(),
            self.partition.index.column.len(),
            "index metadata",
        )?;
        let workspace_per_entry = Self::checked_add(
            decoded_bytes_per_entry,
            Self::checked_add(
                std::mem::size_of::<VectorEntry>(),
                index_bytes,
                "entry metadata",
            )?,
            "entry workspace",
        )?;
        let workspace_bytes = Self::checked_mul(
            expected_entry_count,
            workspace_per_entry,
            "returned decode workspace",
        )?;
        // Prefix construction, one decoded route, key verification, and the
        // one-body decoder coexist. Route copies stay constant in row count.
        let route_bytes = Self::checked_add(
            index_bytes,
            self.partition.partition_key.estimated_bytes(),
            "route metadata",
        )?;
        let metadata_scratch = Self::checked_mul(
            Self::checked_add(route_bytes, 128, "route framing")?,
            8,
            "streamed route scratch",
        )?;
        let decode_scratch = Self::checked_add(
            Self::checked_add(
                decoded_bytes_per_entry,
                self.stored_bytes_per_entry()?,
                "decode scratch",
            )?,
            Self::checked_add(
                metadata_scratch,
                1024 * 1024,
                "serde initial sequence capacity",
            )?,
            "body and metadata scratch",
        )?;
        type Identity = (RowId, TxId, Option<TxId>, Lsn);
        let directory_slots = Self::checked_mul(
            expected_entry_count,
            Self::checked_add(
                4 * (std::mem::size_of::<(Identity, usize)>() + 1),
                std::mem::size_of::<(usize, VectorEntry)>(),
                "directory and ordering slots",
            )?,
            "directory scratch",
        )?;
        // Four buckets per item cover power-of-two rounding at 7/8 load.
        // Include the terminal control group and alignment for small tables.
        let directory_scratch = Self::checked_add(
            directory_slots,
            usize::from(expected_entry_count != 0) * 32,
            "directory table controls",
        )?;
        let retained = Self::checked_add(
            resident_bytes,
            workspace_bytes,
            "partition retained reservation",
        )?;
        let transient = Self::checked_add(
            decode_scratch,
            directory_scratch,
            "partition transient reservation",
        )?;
        let mut total = Self::checked_add(retained, transient, "partition load reservation")?;
        self.accountant.try_allocate_for(total, "vector_store", "load_raw_vector_partition",
            "Evict another raw vector partition, narrow the selected scope, or raise MEMORY_LIMIT before reading these vector bodies.")?;
        let mut membership_scratch = 0;
        let loaded = (|| -> Result<Vec<VectorEntry>> {
            let (_, positions, mut selected) = self.source.stream_memberships(&self.partition, self.dimension, self.quantization,
                |durable_count| {
                    // Include unexpected durable records; directory length is
                    // not an upper bound for the validation identity set.
                    membership_scratch = Self::checked_add(
                        Self::checked_mul(durable_count, 4 * (std::mem::size_of::<Identity>() + 1), "durable identity slots")?,
                        usize::from(durable_count != 0) * 32, "durable identity table controls",
                    )?;
                    let new_total = Self::checked_add(total, membership_scratch, "complete partition reservation")?;
                    self.accountant.try_allocate_for(membership_scratch, "vector_store", "load_raw_vector_partition",
                        "Reduce the selected scope or raise MEMORY_LIMIT before validating durable raw memberships.")?;
                    total = new_total;
                    let positions = directory.iter().enumerate().map(|(position, entry)|
                        ((entry.row_id, entry.created_tx, entry.deleted_tx, entry.lsn), position)).collect::<HashMap<_, _>>();
                    Ok((HashSet::<Identity>::with_capacity(durable_count), positions, Vec::<(usize, VectorEntry)>::with_capacity(expected_entry_count)))
                },
                |(seen, positions, selected), membership, load_body| {
                    if membership.visible_from != TxId(membership.row_created_tx.0.max(membership.vector_created_tx.0))
                        || membership.deleted_tx.is_some_and(|deleted| deleted.0 <= membership.visible_from.0) {
                        return Err(Error::Other("raw vector partition membership has an invalid lifecycle boundary".to_string()));
                    }
                    let identity = (membership.row_id, membership.vector_created_tx, membership.deleted_tx, membership.vector_lsn);
                    if !seen.insert(identity) {
                        return Err(Error::Other("raw vector partition contains duplicate directory identities".to_string()));
                    }
                    if let Some(position) = positions.remove(&identity) {
                        selected.push((position, load_body(&membership)?));
                    }
                    Ok(())
                })?;
            if !positions.is_empty() || selected.len() != expected_entry_count {
                return Err(Error::Other(
                    "raw vector partition identity changed outside its atomic publication"
                        .to_string(),
                ));
            }
            selected.sort_unstable_by_key(|(position, _)| *position);
            // Allocate the exact returned entry layout: in-place collect may
            // retain the wider (position, entry) allocation after its transient
            // charge is released.
            let mut entries = Vec::with_capacity(expected_entry_count);
            for (_, entry) in selected {
                entries.push(entry);
            }
            Ok(entries)
        })();

        match loaded {
            Err(error) => {
                self.accountant.release(total);
                Err(error)
            }
            Ok(entries) => {
                self.accountant.release(transient + membership_scratch);
                Ok(LoadedRawVectorPartition {
                    entries,
                    resident_bytes,
                    workspace_bytes,
                    accountant: self.accountant.clone(),
                })
            }
        }
    }

    fn load_candidate(
        &self,
        identity: &RawVectorDirectoryEntry,
        caller_charged: bool,
        request: &mut dyn FnMut(DormantVectorLoadRequest) -> bool,
    ) -> Result<LoadedRawVectorCandidate> {
        self.load_candidate_via(identity, caller_charged, request, &mut || {
            self.source
                .load_candidate(&self.partition, identity, self.dimension, self.quantization)
        })
    }

    fn body_scan_source(&self) -> usize {
        match &self.source {
            DurableRawVectorSource::CommittedImage(source) => Arc::as_ptr(source) as usize,
            DurableRawVectorSource::Writable(persistence) => Arc::as_ptr(persistence) as usize,
        }
    }

    fn open_body_scan(&self) -> Result<Option<Box<dyn RawVectorBodyScan>>> {
        match &self.source {
            DurableRawVectorSource::CommittedImage(source) => {
                Ok(Some(Box::new(source.open_raw_vector_body_scan()?)))
            }
            DurableRawVectorSource::Writable(persistence) => {
                Ok(Some(Box::new(persistence.open_raw_vector_body_scan()?)))
            }
        }
    }

    fn load_candidate_with_scan(
        &self,
        scan: &mut dyn RawVectorBodyScan,
        identity: &RawVectorDirectoryEntry,
        caller_charged: bool,
        request: &mut dyn FnMut(DormantVectorLoadRequest) -> bool,
    ) -> Result<LoadedRawVectorCandidate> {
        self.load_candidate_via(identity, caller_charged, request, &mut || {
            scan.read_body(&self.partition, identity, self.dimension, self.quantization)
        })
    }
}

impl contextdb_vector::store::RawVectorBodyScan for crate::persistence::RetainedRawVectorBodyScan {
    fn read_body(
        &mut self,
        partition: &VectorPartitionRef,
        identity: &RawVectorDirectoryEntry,
        dimension: usize,
        quantization: VectorQuantization,
    ) -> Result<VectorEntry> {
        self.read_partition_body(
            &partition.index,
            &partition.partition_key,
            identity,
            dimension,
            quantization,
        )
    }
}

impl contextdb_vector::store::RawVectorBodyScan for crate::persistence::WritableRawVectorBodyScan {
    fn read_body(
        &mut self,
        partition: &VectorPartitionRef,
        identity: &RawVectorDirectoryEntry,
        dimension: usize,
        quantization: VectorQuantization,
    ) -> Result<VectorEntry> {
        self.read_partition_body(
            &partition.index,
            &partition.partition_key,
            identity,
            dimension,
            quantization,
        )
    }
}

impl DurableRawVectorPartitionLoader {
    /// Admit one candidate body's peak before it is read, read it with
    /// `fetch`, and check it is exactly the directory identity asked for.
    fn load_candidate_via(
        &self,
        identity: &RawVectorDirectoryEntry,
        caller_charged: bool,
        request: &mut dyn FnMut(DormantVectorLoadRequest) -> bool,
        fetch: &mut dyn FnMut() -> Result<VectorEntry>,
    ) -> Result<LoadedRawVectorCandidate> {
        let decoded_bytes = Self::checked_mul(
            self.dimension,
            std::mem::size_of::<f32>(),
            "candidate decoded F32 body",
        )?;
        let stored_bytes = self.stored_bytes_per_entry()?;
        let retained = Self::checked_add(
            decoded_bytes,
            stored_bytes,
            "candidate decoded and stored bodies",
        )?;
        // One persisted body may coexist with its decoded F32 allocation and
        // the quantized score representation. Charge that complete peak before
        // opening Redb; none of it becomes partition residency.
        let decode_scratch =
            Self::checked_add(decoded_bytes, stored_bytes, "candidate decode scratch")?;
        let transient_bytes =
            Self::checked_add(retained, decode_scratch, "candidate point-load reservation")?;

        Self::load_checkpoint(request)?;
        if caller_charged {
            if !request(DormantVectorLoadRequest::Reserve(transient_bytes)) {
                return Err(Error::ReadCancelled);
            }
        } else {
            self.accountant.try_allocate_for(
                transient_bytes,
                "vector_store",
                "load_raw_vector_candidate",
                "Reduce the selected candidate scope or raise MEMORY_LIMIT before reading this vector body.",
            )?;
        }

        let loaded = (|| -> Result<VectorEntry> {
            Self::load_checkpoint(request)?;
            let entry = fetch()?;
            Self::load_checkpoint(request)?;
            if entry.index != self.partition.index
                || entry.row_id != identity.row_id
                || entry.created_tx != identity.created_tx
                || entry.deleted_tx != identity.deleted_tx
                || entry.lsn != identity.lsn
                || entry.vector.len() != self.dimension
            {
                return Err(Error::Other(
                    "raw vector candidate disagrees with its exact durable identity".to_string(),
                ));
            }
            Ok(entry)
        })();

        match loaded {
            Err(error) => {
                if !caller_charged {
                    self.accountant.release(transient_bytes);
                }
                Err(error)
            }
            Ok(entry) if caller_charged => Ok(LoadedRawVectorCandidate::caller_charged(
                entry,
                transient_bytes,
            )),
            Ok(entry) => Ok(LoadedRawVectorCandidate::loader_charged(
                entry,
                transient_bytes,
                self.accountant.clone(),
            )),
        }
    }
}

fn durable_raw_vector_partitions(
    vector: &VectorStore,
    source: DurableRawVectorSource,
    memberships: Vec<VectorPartitionMembershipRecord>,
    accountant: &Arc<MemoryAccountant>,
) -> Result<Vec<DormantRawVectorPartition>> {
    // Historical EXACT reads need the same immutable vector identities after
    // reopen. Membership retirement affects maintained graphs, not retained
    // raw bodies: keep every durable visibility interval in the directory.
    let mut grouped = HashMap::<VectorPartitionRef, Vec<VectorPartitionMembershipRecord>>::new();
    for membership in memberships {
        grouped
            .entry(VectorPartitionRef::new(
                membership.index.clone(),
                membership.partition_key.clone(),
            ))
            .or_default()
            .push(membership);
    }

    let mut grouped = grouped.into_iter().collect::<Vec<_>>();
    grouped.sort_by(|(left, _), (right, _)| {
        left.index
            .table
            .cmp(&right.index.table)
            .then(left.index.column.cmp(&right.index.column))
            .then(
                left.partition_key
                    .canonical_bytes()
                    .cmp(&right.partition_key.canonical_bytes()),
            )
    });
    let mut dormant = Vec::with_capacity(grouped.len());
    for (partition, mut memberships) in grouped {
        memberships.sort_by_key(|membership| {
            (
                membership.row_id,
                membership.row_created_tx,
                membership.row_lsn,
                membership.vector_created_tx,
                membership.vector_lsn,
            )
        });
        let layout = vector.index_layout(&partition.index)?;
        let directory = memberships
            .iter()
            .map(|membership| RawVectorDirectoryEntry {
                row_id: membership.row_id,
                created_tx: membership.vector_created_tx,
                deleted_tx: membership.deleted_tx,
                lsn: membership.vector_lsn,
            })
            .collect::<Vec<_>>();
        if let DurableRawVectorSource::CommittedImage(read_source) = &source {
            read_source.retain_raw_vector_memberships(partition.clone(), memberships)?;
        }
        let loader: Arc<dyn DormantRawVectorLoader> = Arc::new(DurableRawVectorPartitionLoader {
            source: source.clone(),
            accountant: accountant.clone(),
            partition: partition.clone(),
            dimension: layout.dimension,
            quantization: layout.quantization,
        });
        dormant.push(DormantRawVectorPartition {
            partition,
            directory,
            loader,
        });
    }
    Ok(dormant)
}

fn register_dormant_raw_vector_partitions(
    vector: &VectorStore,
    persistence: &Arc<RedbPersistence>,
    accountant: &Arc<MemoryAccountant>,
) -> Result<()> {
    let memberships = persistence.load_vector_partition_memberships()?;
    vector.replace_with_dormant_raw_partitions(durable_raw_vector_partitions(
        vector,
        DurableRawVectorSource::Writable(persistence.clone()),
        memberships,
        accountant,
    )?)
}

/// Persistence-owned loader attached to one lightweight generation
/// descriptor. Opening a database registers this object without reading graph
/// bytes. The first ordinary indexed read reserves the complete decode and
/// replay working set, verifies the saved graph, and replays only journal
/// entries after the selected sealed boundary.
struct DurableVectorGenerationLoader {
    source: DurableVectorGenerationSource,
    accountant: Arc<MemoryAccountant>,
    partition: VectorPartitionRef,
    descriptor: VectorPartitionGenerationDescriptor,
    base_generation_id: u64,
    is_base: bool,
    /// The base generation's coverage as the catalog names it; a change
    /// layer's saved record is checked against it.
    base_covered: (TxId, Lsn),
    dimension: usize,
    quantization: VectorQuantization,
    /// Only the final selected sealed layer owns fresh-tail replay. A base
    /// with a selected change layer leaves this `None`; the change loader owns
    /// the suffix instead.
    tail_covered_lsn: Option<Lsn>,
    layout: VectorIndexLayout,
    live_rows: usize,
    /// Where this loader reads the declared serving-cache size.
    ///
    /// A writable store carries the live cell, so a partition faulted in after
    /// `SET VECTOR_SERVING_CACHE` sizes from the value in force at LOAD time —
    /// the same moment the accountant's limit beside it is read. A committed
    /// image carries the value as of its open, which is what that reader is
    /// entitled to and cannot change under it.
    declared_serving_cache: DeclaredServingCache,
}

/// Where a loader reads the declared serving-cache size from.
#[derive(Clone)]
enum DeclaredServingCache {
    /// The store's live cell; read at load time.
    Live(Arc<AtomicU64>),
    /// The value as of a committed image's open.
    AsOfOpen(Option<usize>),
}

impl DeclaredServingCache {
    fn get(&self) -> Option<usize> {
        match self {
            Self::Live(cell) => declared_serving_cache_bytes(cell.load(Ordering::SeqCst)),
            Self::AsOfOpen(bytes) => *bytes,
        }
    }
}

#[derive(Clone)]
enum DurableVectorGenerationSource {
    Writable(Arc<RedbPersistence>),
    CommittedImage(ReadOnlyVectorGenerationSource),
}

impl DurableVectorGenerationSource {
    fn is_committed_image(&self) -> bool {
        matches!(self, Self::CommittedImage(_))
    }

    fn with_paged_graph<T>(
        &self,
        partition: &VectorPartitionRef,
        base_generation_id: u64,
        generation_id: u64,
        base: Option<&crate::persistence::ChangeGenerationBase>,
        consume: impl FnOnce(crate::persistence::ReadOnlyVectorGenerationGraph<'_>) -> Result<T>,
    ) -> Result<T> {
        match self {
            Self::CommittedImage(source) => match base {
                None => source.with_base_graph(
                    &partition.index,
                    &partition.partition_key,
                    generation_id,
                    consume,
                ),
                Some(base) => source.with_change_graph(
                    &partition.index,
                    &partition.partition_key,
                    base_generation_id,
                    generation_id,
                    base,
                    consume,
                ),
            },
            Self::Writable(_) => Err(Error::Other(
                "paged graph loading requires a retained read image".to_string(),
            )),
        }
    }

    fn tail_entry_count(
        &self,
        index: &VectorIndexRef,
        partition_key: &VectorPartitionKey,
        covered_lsn: Lsn,
    ) -> Result<usize> {
        #[cfg(feature = "test-seams")]
        let _reads = crate::vector_observations::observe_reads(index, partition_key, covered_lsn);
        match self {
            Self::Writable(persistence) => {
                persistence.vector_partition_tail_entry_count(index, partition_key, covered_lsn)
            }
            Self::CommittedImage(source) => {
                source.tail_entry_count(index, partition_key, covered_lsn)
            }
        }
    }

    fn record_bytes(
        &self,
        partition: &VectorPartitionRef,
        base: u64,
        change: Option<u64>,
    ) -> Result<usize> {
        match self {
            Self::Writable(persistence) => persistence.vector_generation_record_bytes(
                &partition.index,
                &partition.partition_key,
                base,
                change,
            ),
            Self::CommittedImage(source) => source.generation_record_bytes(
                &partition.index,
                &partition.partition_key,
                base,
                change,
            ),
        }
    }

    fn load_base(
        &self,
        index: &VectorIndexRef,
        partition_key: &VectorPartitionKey,
        generation_id: u64,
    ) -> Result<VectorPartitionBaseGenerationRecord> {
        match self {
            Self::Writable(persistence) => persistence.load_vector_partition_base_generation(
                index,
                partition_key,
                generation_id,
            ),
            Self::CommittedImage(source) => source.load_base(index, partition_key, generation_id),
        }
    }

    fn load_change(
        &self,
        index: &VectorIndexRef,
        partition_key: &VectorPartitionKey,
        base_generation_id: u64,
        change_generation_id: u64,
    ) -> Result<VectorPartitionChangeGenerationRecord> {
        match self {
            Self::Writable(persistence) => persistence.load_vector_partition_change_generation(
                index,
                partition_key,
                base_generation_id,
                change_generation_id,
            ),
            Self::CommittedImage(source) => source.load_change(
                index,
                partition_key,
                base_generation_id,
                change_generation_id,
            ),
        }
    }

    fn load_tail(
        &self,
        index: &VectorIndexRef,
        partition_key: &VectorPartitionKey,
        covered_lsn: Lsn,
    ) -> Result<(Vec<VectorEntry>, Lsn)> {
        #[cfg(feature = "test-seams")]
        let _reads = crate::vector_observations::observe_reads(index, partition_key, covered_lsn);
        match self {
            Self::Writable(persistence) => {
                persistence.load_vector_partition_tail_entries(index, partition_key, covered_lsn)
            }
            Self::CommittedImage(source) => source.load_tail(index, partition_key, covered_lsn),
        }
    }
}

impl DurableVectorGenerationLoader {
    fn descriptor_usize(value: u64, name: &str) -> Result<usize> {
        usize::try_from(value).map_err(|_| {
            Error::Other(format!(
                "durable vector {name} exceeds this process's addressable range"
            ))
        })
    }

    fn checked_mul(left: usize, right: usize, name: &str) -> Result<usize> {
        left.checked_mul(right).ok_or_else(|| {
            Error::Other(format!(
                "durable vector {name} exceeds this process's addressable range"
            ))
        })
    }

    fn checked_add(left: usize, right: usize, name: &str) -> Result<usize> {
        left.checked_add(right).ok_or_else(|| {
            Error::Other(format!(
                "durable vector {name} exceeds this process's addressable range"
            ))
        })
    }

    fn tail_reservation(&self, count: usize) -> Result<(usize, usize)> {
        let resident = HnswIndex::estimated_resident_bytes_with_m(
            count,
            self.dimension,
            self.quantization,
            self.layout.resolve_policy(self.live_rows, 1).hnsw_m,
        );
        let vector_values = count
            .checked_mul(self.dimension)
            .and_then(|values| values.checked_mul(std::mem::size_of::<f32>()))
            .ok_or_else(|| {
                Error::Other(
                    "durable vector tail values exceed this process's addressable range"
                        .to_string(),
                )
            })?;
        let entry_overhead = count
            .checked_mul(std::mem::size_of::<VectorEntry>().saturating_add(256))
            .ok_or_else(|| {
                Error::Other(
                    "durable vector tail entries exceed this process's addressable range"
                        .to_string(),
                )
            })?;
        // During construction the immutable journal values, the converted
        // stored values, and the new graph coexist. This is an admission upper
        // bound; the unused part is returned immediately after construction.
        let workspace = Self::checked_add(vector_values, entry_overhead, "tail workspace")?;
        let workspace = Self::checked_add(
            workspace,
            resident.checked_mul(2).ok_or_else(|| {
                Error::Other(
                    "durable vector tail build exceeds this process's addressable range"
                        .to_string(),
                )
            })?,
            "tail workspace",
        )?;
        let build_reservation = HnswIndex::estimated_build_reservation(
            count,
            self.dimension,
            self.quantization,
            self.layout.resolve_policy(self.live_rows, 1),
        );
        let workspace = workspace.max(build_reservation.saturating_sub(resident));
        Ok((resident, workspace))
    }

    fn route_metadata_workspace(&self) -> Result<usize> {
        // Expected-prefix prevalidation caps decoded route lengths before serde.
        // Two base/change routes, geometric component capacity, physical keys,
        // page-manifest route and framing coexist independently of graph size.
        let route = Self::checked_add(
            Self::checked_add(
                self.partition.index.table.len(),
                self.partition.index.column.len(),
                "generation index metadata",
            )?,
            self.partition.partition_key.estimated_bytes(),
            "generation route metadata",
        )?;
        Self::checked_add(
            Self::checked_mul(
                Self::checked_add(route, 128, "generation route framing")?,
                8,
                "generation route owners",
            )?,
            1024,
            "generation metadata scratch",
        )
    }

    fn load_checkpoint(request: &mut dyn FnMut(DormantVectorLoadRequest) -> bool) -> Result<()> {
        if request(DormantVectorLoadRequest::Checkpoint) {
            Ok(())
        } else {
            Err(Error::ReadCancelled)
        }
    }

    fn load_retained(
        &self,
        generation: DormantVectorGraphGeneration,
        caller_reserved_load_bytes: usize,
        request: &mut dyn FnMut(DormantVectorLoadRequest) -> bool,
    ) -> Result<LoadedVectorGraphGeneration> {
        if generation.identity.generation_id != self.descriptor.generation_id
            || generation.identity.covered_tx != self.descriptor.covered_tx
            || generation.identity.covered_lsn != self.descriptor.covered_lsn
            || generation.resident_bytes != 1
            || generation.load_bytes != 1
            || generation.reclaim_bytes
                != committed_layer_least_load(
                    self.live_rows,
                    self.descriptor.durable_bytes,
                    self.dimension,
                    self.quantization,
                    generation.identity.hnsw_m as usize,
                )
            || (caller_reserved_load_bytes != 0 && caller_reserved_load_bytes != 1)
        {
            return Err(Error::Other(
                "retained vector loader received a descriptor other than the one it owns"
                    .to_string(),
            ));
        }
        Self::load_checkpoint(request)?;
        let metadata_workspace = self.route_metadata_workspace()?.max(64 * 1024);
        let _metadata = crate::memory_accounting::ScopedMemoryReservation::try_new_for(
            &self.accountant,
            metadata_workspace,
            "vector_index",
            "load_retained_vector_generation",
            "Evict another vector partition or raise MEMORY_LIMIT before loading this maintained route.",
        )?;

        let tail_count = match self.tail_covered_lsn {
            Some(covered_lsn) => self.source.tail_entry_count(
                &self.partition.index,
                &self.partition.partition_key,
                covered_lsn,
            )?,
            None => 0,
        };
        let (tail_resident, tail_workspace) = if self.tail_covered_lsn.is_some() {
            self.tail_reservation(tail_count)?
        } else {
            (0, 0)
        };
        let mut owned = 0usize;
        // What this load costs, for the attribution sink only: when it
        // started, and the hash meters before it, so its entry can say how
        // many full passes it made over the saved bytes.
        let load_started = contextdb_core::find_attribution::enabled().then(Instant::now);
        let hashes_before = contextdb_core::find_attribution::load_meters();
        // A change layer is checked against its base as the catalog names it.
        let base = (!self.is_base).then_some(crate::persistence::ChangeGenerationBase {
            covered_tx: self.base_covered.0,
            covered_lsn: self.base_covered.1,
            dimension: self.dimension as u32,
            quantization: self.quantization,
            algorithm_version: VECTOR_GRAPH_ALGORITHM_VERSION,
            graph_format_version: VECTOR_GRAPH_FORMAT_VERSION,
        });
        let loaded = self.source.with_paged_graph(
            &self.partition,
            self.base_generation_id,
            self.descriptor.generation_id,
            base.as_ref(),
            |saved| {
                if saved.covered_tx != self.descriptor.covered_tx
                    || saved.covered_lsn != self.descriptor.covered_lsn
                    || saved.bytes.len() as u64 != self.descriptor.durable_bytes
                    || saved.dimension as usize != self.dimension
                    || saved.quantization != self.quantization
                    || saved.algorithm_version != VECTOR_GRAPH_ALGORITHM_VERSION
                    || saved.graph_format_version != VECTOR_GRAPH_FORMAT_VERSION
                {
                    return Err(Error::Other(
                        "saved vector graph disagrees with its catalog or column declaration"
                            .to_string(),
                    ));
                }
                // The serving cache's ceiling follows the declaration and the
                // data, not a constant: a size this reader was given, else a
                // share of the memory the session declared, else what this
                // partition's own pages occupy. A ceiling below the partition
                // makes a walk re-read pages it has already authenticated,
                // which is what a first find over a large partition was paying.
                let ceiling = contextdb_vector::hnsw::durable_reader_cache_ceiling(
                    // What the consumer declared, where it declared one. It
                    // beats the share below, and the partition still caps both.
                    self.declared_serving_cache.get(),
                    self.accountant.usage().limit,
                    saved
                        .source
                        .total_page_bytes()
                        .unwrap_or(saved.bytes.len()),
                );
                let (minimum_cache, maximum_cache) =
                    HnswIndex::durable_reader_cache_bounds(ceiling);
                let source_resident = saved.source.retained_bytes();
                let minimum_resident = HnswIndex::durable_reader_resident_bound_for_cache(
                    saved.bytes,
                    self.dimension,
                    self.quantization,
                    generation.identity.hnsw_m as usize,
                    minimum_cache,
                )?
                .checked_add(source_resident)
                .ok_or_else(|| {
                    Error::Other("retained vector page metadata overflow".to_string())
                })?;
                let minimum_total = minimum_resident
                    .checked_add(tail_resident)
                    .and_then(|value| value.checked_add(tail_workspace))
                    .ok_or_else(|| Error::Other("retained vector load overflow".to_string()))?;
                // Route metadata is already held by its scoped reservation,
                // so admission below asks only for the remaining bytes. Load
                // attribution still reports the complete coexisting charge.
                let complete_minimum_total = minimum_total
                    .checked_add(metadata_workspace)
                    .ok_or_else(|| Error::Other("retained vector load overflow".to_string()))?;
                // Leave room for later layers' least loads. When the declared
                // spare memory also covers every later layer's page bodies,
                // keep this layer's complete cache: dividing it equally would
                // leave a large partition short even though all pages fit.
                // Otherwise retain the old equal share, so a tight reader
                // still admits every later topology and least serving slot.
                let share = contextdb_core::serving_cache_share::claim_share(
                    generation.reclaim_bytes,
                    usize::try_from(generation.identity.durable_bytes).unwrap_or(usize::MAX),
                );
                let wanted = minimum_total.saturating_add(share.reserved_for_later);
                // Make room for exactly this load's least footprint, read from
                // its saved topology, and the room reserved for the rest, by
                // evicting idle graphs this statement is not searching.
                if let Some(available) = self.accountant.usage().available
                    && available < wanted
                {
                    self.accountant.make_room_for_graph_load(wanted - available);
                }
                let future_page_headroom = share.full_page_bytes_for_later.saturating_sub(
                    share
                        .divisor
                        .saturating_sub(1)
                        .saturating_mul(minimum_cache),
                );
                // A filled slot has a lookup entry and a recency stamp in
                // addition to its page body. Reserve the maximum directory
                // growth before rounding spare bytes to whole pages; using
                // page bodies alone can make a fitting smaller cache refuse.
                let directory_growth = HnswIndex::durable_reader_cache_directory_growth(
                    saved.bytes.len(),
                    maximum_cache,
                );
                let cache_headroom = self
                    .accountant
                    .usage()
                    .available
                    .map_or(maximum_cache - minimum_cache, |available| {
                        let spare = available
                            .saturating_sub(wanted)
                            .saturating_sub(directory_growth);
                        let full_extra = maximum_cache - minimum_cache;
                        if spare >= full_extra.saturating_add(future_page_headroom) {
                            full_extra
                        } else {
                            spare.saturating_div(share.divisor).min(full_extra)
                        }
                    });
                let cache_bytes = minimum_cache
                    + cache_headroom / minimum_cache * minimum_cache;
                contextdb_core::find_attribution::count("paged_graph_loads", 1);
                contextdb_core::find_attribution::count(
                    "paged_load_available_bytes",
                    self.accountant.usage().available.unwrap_or(0) as u64,
                );
                contextdb_core::find_attribution::count(
                    "paged_load_used_bytes",
                    self.accountant.usage().used as u64,
                );
                contextdb_core::find_attribution::count(
                    "paged_load_minimum_total_bytes",
                    complete_minimum_total as u64,
                );
                contextdb_core::find_attribution::count(
                    "paged_load_maximum_cache_bytes",
                    maximum_cache as u64,
                );
                contextdb_core::find_attribution::count(
                    "paged_load_cache_bytes",
                    cache_bytes as u64,
                );
                let resident = HnswIndex::durable_reader_resident_bound_for_cache(
                    saved.bytes,
                    self.dimension,
                    self.quantization,
                    generation.identity.hnsw_m as usize,
                    cache_bytes,
                )?
                .checked_add(source_resident)
                .ok_or_else(|| {
                    Error::Other("retained vector page metadata overflow".to_string())
                })?;
                let total = resident
                    .checked_add(tail_resident)
                    .and_then(|value| value.checked_add(tail_workspace))
                    .ok_or_else(|| Error::Other("retained vector load overflow".to_string()))?;
                let complete_total = total
                    .checked_add(metadata_workspace)
                    .ok_or_else(|| Error::Other("retained vector load overflow".to_string()))?;
                self.accountant
                    .try_allocate_for(
                        total,
                        "vector_index",
                        "load_retained_vector_generation",
                        "Evict another vector partition or raise MEMORY_LIMIT before loading this maintained route.",
                    )
                    .inspect_err(|_| {
                        contextdb_core::find_attribution::note_refused_saved_graph_load();
                        contextdb_core::find_attribution::count("paged_graph_loads_refused", 1);
                    })?;
                owned = total;
                Self::load_checkpoint(request)?;
                let _decoding = contextdb_core::find_attribution::stage("graph_load_decode");
                // The record these bytes came from was read under its own
                // digest, which covers every one of them; the decode does not
                // hash them a second time.
                let graph = HnswIndex::decode_paged_authenticated_generation(
                    saved.bytes,
                    saved.source,
                    self.dimension,
                    self.quantization,
                    resident,
                    cache_bytes,
                )?;
                let actual_resident = graph.estimated_resident_bytes();
                contextdb_core::find_attribution::note_saved_graph_load(
                    contextdb_core::find_attribution::LoadCharge {
                        saved_bytes: saved.bytes.len(),
                        priced_bytes: generation.reclaim_bytes,
                        minimum_bytes: complete_minimum_total,
                        admitted_bytes: complete_total,
                        held_bytes: actual_resident,
                        cache_bytes,
                        minimum_cache_bytes: minimum_cache,
                        maximum_cache_bytes: maximum_cache,
                    },
                );
                if let Some(started) = load_started {
                    use contextdb_core::find_attribution::Field;
                    let now = contextdb_core::find_attribution::load_meters();
                    contextdb_core::find_attribution::note_load(vec![
                        (
                            "partition".to_string(),
                            Field::Text(format!("{:?}", self.partition.partition_key)),
                        ),
                        (
                            "layer".to_string(),
                            Field::Text(if self.is_base { "base" } else { "change" }.to_string()),
                        ),
                        (
                            "saved_bytes".to_string(),
                            Field::Count(saved.bytes.len() as u64),
                        ),
                        (
                            "priced_bytes".to_string(),
                            Field::Count(generation.reclaim_bytes as u64),
                        ),
                        (
                            "minimum_total_bytes".to_string(),
                            Field::Count(complete_minimum_total as u64),
                        ),
                        ("admitted_bytes".to_string(), Field::Count(complete_total as u64)),
                        ("held_bytes".to_string(), Field::Count(actual_resident as u64)),
                        ("cache_bytes".to_string(), Field::Count(cache_bytes as u64)),
                        (
                            "hash_passes".to_string(),
                            Field::Count(now.hash_passes.saturating_sub(hashes_before.hash_passes)),
                        ),
                        (
                            "hashed_bytes".to_string(),
                            Field::Count(now.hashed_bytes.saturating_sub(hashes_before.hashed_bytes)),
                        ),
                        (
                            "ms".to_string(),
                            Field::Millis(started.elapsed().as_secs_f64() * 1e3),
                        ),
                    ]);
                }
                Self::load_checkpoint(request)?;
                Ok((graph, actual_resident))
            },
        );
        let (graph, resident_bytes) = match loaded {
            Ok(loaded) => loaded,
            Err(error) => {
                self.accountant.release(owned);
                return Err(error);
            }
        };
        let fresh_tail = (|| -> Result<_> {
            Ok(match self.tail_covered_lsn {
                None => None,
                Some(covered_lsn) => {
                    let (entries, replayed_through_lsn) = self.source.load_tail(
                        &self.partition.index,
                        &self.partition.partition_key,
                        covered_lsn,
                    )?;
                    if entries.len() > tail_count {
                        return Err(Error::Other(
                            "vector journal grew beyond its admitted replay bound".to_string(),
                        ));
                    }
                    let graph = HnswIndex::from_vector_entries_with_progress(
                        &entries,
                        self.dimension,
                        self.quantization,
                        self.layout.resolve_policy(self.live_rows, 1),
                        |done| {
                            if request(DormantVectorLoadRequest::Progress {
                                done,
                                total: entries.len(),
                            }) {
                                Ok(())
                            } else {
                                Err(Error::ReadCancelled)
                            }
                        },
                    )?;
                    let actual = graph.estimated_resident_bytes();
                    if actual > tail_resident {
                        return Err(Error::Other(
                            "vector tail graph exceeded its admitted resident bound".to_string(),
                        ));
                    }
                    Some((graph, actual, replayed_through_lsn))
                }
            })
        })();
        let fresh_tail = match fresh_tail {
            Ok(fresh_tail) => fresh_tail,
            Err(error) => {
                self.accountant.release(owned);
                return Err(error);
            }
        };
        let actual_tail = fresh_tail.as_ref().map(|(_, bytes, _)| *bytes).unwrap_or(0);
        let retained = resident_bytes.saturating_add(actual_tail);
        if let Err(error) = Self::load_checkpoint(request) {
            self.accountant.release(owned);
            return Err(error);
        }
        self.accountant.release(owned.saturating_sub(retained));
        Ok(LoadedVectorGraphGeneration {
            graph,
            resident_bytes,
            accountant: self.accountant.clone(),
            caller_adopted_bytes: 0,
            fresh_tail: fresh_tail.map(|(graph, resident_bytes, replayed_through_lsn)| {
                LoadedVectorFreshTail {
                    graph,
                    resident_bytes,
                    accountant: self.accountant.clone(),
                    replayed_through_lsn,
                }
            }),
        })
    }
}

impl DormantVectorGraphLoader for DurableVectorGenerationLoader {
    fn load(
        &self,
        generation: DormantVectorGraphGeneration,
        caller_reserved_load_bytes: usize,
        request: &mut dyn FnMut(DormantVectorLoadRequest) -> bool,
    ) -> Result<LoadedVectorGraphGeneration> {
        if self.source.is_committed_image() {
            return self.load_retained(generation, caller_reserved_load_bytes, request);
        }
        let mut resident_bytes =
            Self::descriptor_usize(self.descriptor.resident_bytes, "resident byte declaration")?;
        let graph_workspace =
            Self::descriptor_usize(self.descriptor.durable_bytes, "graph decode workspace")?;
        let known_load_reservation =
            Self::checked_add(resident_bytes, graph_workspace, "known generation load")?;
        if generation.identity.generation_id != self.descriptor.generation_id
            || generation.identity.covered_tx != self.descriptor.covered_tx
            || generation.identity.covered_lsn != self.descriptor.covered_lsn
            || generation.resident_bytes != resident_bytes
            || generation.load_bytes != known_load_reservation
        {
            return Err(Error::Other(
                "durable vector loader received a descriptor other than the one it owns"
                    .to_string(),
            ));
        }
        if caller_reserved_load_bytes != 0 && caller_reserved_load_bytes != known_load_reservation {
            return Err(Error::Other(
                "durable vector caller reservation disagrees with graph load admission".to_string(),
            ));
        }

        Self::load_checkpoint(request)?;
        let _metadata = crate::memory_accounting::ScopedMemoryReservation::try_new_for(
            &self.accountant,
            self.route_metadata_workspace()?,
            "vector_index",
            "load_durable_vector_generation",
            "Evict another vector partition or raise MEMORY_LIMIT before loading this maintained route.",
        )?;
        let record_workspace = self.source.record_bytes(
            &self.partition,
            self.base_generation_id,
            (!self.is_base).then_some(self.descriptor.generation_id),
        )?;
        let tail_count = match self.tail_covered_lsn {
            Some(covered_lsn) => self.source.tail_entry_count(
                &self.partition.index,
                &self.partition.partition_key,
                covered_lsn,
            )?,
            None => 0,
        };
        Self::load_checkpoint(request)?;
        let (tail_resident_reservation, tail_workspace) = if self.tail_covered_lsn.is_some() {
            self.tail_reservation(tail_count)?
        } else {
            (0, 0)
        };
        let retained_reservation = Self::checked_add(
            resident_bytes,
            tail_resident_reservation,
            "resident generation reservation",
        )?;
        let workspace_reservation = Self::checked_add(
            graph_workspace.max(record_workspace.saturating_mul(2)),
            tail_workspace,
            "generation workspace reservation",
        )?;
        let mut total_reservation = Self::checked_add(
            retained_reservation,
            workspace_reservation,
            "generation load reservation",
        )?;
        let caller_charged = caller_reserved_load_bytes != 0;
        if caller_charged {
            let additional = total_reservation
                .checked_sub(caller_reserved_load_bytes)
                .ok_or_else(|| {
                    Error::Other(
                        "durable vector caller reservation exceeds load admission".to_string(),
                    )
                })?;
            if additional != 0 && !request(DormantVectorLoadRequest::Reserve(additional)) {
                return Err(Error::ReadCancelled);
            }
        }
        let mut loader_reservation = if caller_charged { 0 } else { total_reservation };
        self.accountant.try_allocate_for(
            loader_reservation,
            "vector_index",
            "load_durable_vector_generation",
            "Evict another vector partition, reduce the selected scope, or raise MEMORY_LIMIT before loading this maintained route.",
        )?;

        let loaded = (|| -> Result<_> {
            Self::load_checkpoint(request)?;
            let graph_bytes = if self.is_base {
                let record = self.source.load_base(
                    &self.partition.index,
                    &self.partition.partition_key,
                    self.descriptor.generation_id,
                )?;
                if record.highest_included_tx != self.descriptor.covered_tx
                    || record.highest_included_lsn != self.descriptor.covered_lsn
                    || record.dimension as usize != self.dimension
                    || record.quantization != self.quantization
                    || record.algorithm_version != VECTOR_GRAPH_ALGORITHM_VERSION
                    || record.graph_format_version != VECTOR_GRAPH_FORMAT_VERSION
                {
                    return Err(Error::Other(
                        "saved vector base disagrees with its catalog or column declaration"
                            .to_string(),
                    ));
                }
                record.graph.bytes
            } else {
                let record = self.source.load_change(
                    &self.partition.index,
                    &self.partition.partition_key,
                    self.base_generation_id,
                    self.descriptor.generation_id,
                )?;
                if record.covered_through_tx != self.descriptor.covered_tx
                    || record.covered_through_lsn != self.descriptor.covered_lsn
                    || record.dimension as usize != self.dimension
                    || record.quantization != self.quantization
                    || record.algorithm_version != VECTOR_GRAPH_ALGORITHM_VERSION
                    || record.graph_format_version != VECTOR_GRAPH_FORMAT_VERSION
                {
                    return Err(Error::Other(
                        "saved vector change graph disagrees with its catalog or column declaration"
                            .to_string(),
                    ));
                }
                record.graph.bytes
            };
            Self::load_checkpoint(request)?;
            if graph_bytes.len() != graph_workspace {
                return Err(Error::Other(
                    "saved vector graph length disagrees with its catalog".to_string(),
                ));
            }
            #[cfg(feature = "test-seams")]
            if contextdb_vector::test_seam::take_dormant_vector_decode_failure_for_test() {
                return Err(Error::Other(
                    "injected dormant vector decode failure".to_string(),
                ));
            }
            Self::load_checkpoint(request)?;
            let current_resident = HnswIndex::durable_resident_bound(
                &graph_bytes,
                self.dimension,
                self.quantization,
                generation.identity.hnsw_m as usize,
            )?;
            // The codec moves point values into the serving graph and consumes
            // adjacency as it installs edges. Its encoded payload coexists with
            // one graph, not a second graph with full neighbour capacity.
            let decode_total = current_resident
                .saturating_add(record_workspace.saturating_mul(2))
                .saturating_add(tail_resident_reservation)
                .saturating_add(tail_workspace);
            let additional = decode_total.saturating_sub(total_reservation);
            if additional != 0 {
                if caller_charged {
                    if !request(DormantVectorLoadRequest::Reserve(additional)) {
                        return Err(Error::ReadCancelled);
                    }
                } else {
                    self.accountant.try_allocate_for(additional, "vector_index", "load_durable_vector_generation", "Evict another vector partition or raise MEMORY_LIMIT before loading this maintained route.")?;
                    loader_reservation = loader_reservation.saturating_add(additional);
                }
                total_reservation = total_reservation.saturating_add(additional);
            }
            resident_bytes = current_resident;
            let graph = HnswIndex::decode_durable_generation(
                &graph_bytes,
                self.dimension,
                self.quantization,
            )?;
            Self::load_checkpoint(request)?;
            if graph.estimated_resident_bytes() != resident_bytes {
                return Err(Error::Other(
                    "saved vector graph residency disagrees with its catalog".to_string(),
                ));
            }

            let fresh_tail = match self.tail_covered_lsn {
                None => None,
                Some(covered_lsn) => {
                    Self::load_checkpoint(request)?;
                    let (entries, replayed_through_lsn) = self.source.load_tail(
                        &self.partition.index,
                        &self.partition.partition_key,
                        covered_lsn,
                    )?;
                    Self::load_checkpoint(request)?;
                    if entries.len() > tail_count {
                        return Err(Error::Other(
                            "vector journal grew beyond its admitted replay bound".to_string(),
                        ));
                    }
                    let graph = HnswIndex::from_vector_entries_with_progress(
                        &entries,
                        self.dimension,
                        self.quantization,
                        self.layout.resolve_policy(self.live_rows, 1),
                        |done| {
                            if request(DormantVectorLoadRequest::Progress {
                                done,
                                total: entries.len(),
                            }) {
                                Ok(())
                            } else {
                                Err(Error::ReadCancelled)
                            }
                        },
                    )?;
                    Self::load_checkpoint(request)?;
                    let actual_resident = graph.estimated_resident_bytes();
                    if actual_resident > tail_resident_reservation {
                        return Err(Error::Other(
                            "vector tail graph exceeded its admitted resident bound".to_string(),
                        ));
                    }
                    Some((graph, actual_resident, replayed_through_lsn))
                }
            };
            Ok((graph, fresh_tail))
        })();

        match loaded {
            Err(error) => {
                self.accountant.release(loader_reservation);
                Err(error)
            }
            Ok((graph, fresh_tail)) => {
                let actual_tail_resident =
                    fresh_tail.as_ref().map(|(_, bytes, _)| *bytes).unwrap_or(0);
                let retained = Self::checked_add(
                    resident_bytes,
                    actual_tail_resident,
                    "loaded generation residency",
                )
                .inspect_err(|_| {
                    self.accountant.release(loader_reservation);
                })?;
                Self::load_checkpoint(request).inspect_err(|_| {
                    self.accountant.release(loader_reservation);
                })?;
                if caller_charged {
                    match self.accountant.adopt_caller_reservation(retained) {
                        Ok(true) => {}
                        Ok(false) => {
                            self.accountant.release(loader_reservation);
                            return Err(Error::Other(
                                "bounded vector load lost its caller reservation transfer"
                                    .to_string(),
                            ));
                        }
                        Err(error) => {
                            self.accountant.release(loader_reservation);
                            return Err(error);
                        }
                    }
                }
                if !caller_charged {
                    self.accountant
                        .release(total_reservation.saturating_sub(retained));
                }
                let fresh_tail = fresh_tail.map(|(graph, resident_bytes, replayed_through_lsn)| {
                    LoadedVectorFreshTail {
                        graph,
                        resident_bytes,
                        accountant: self.accountant.clone(),
                        replayed_through_lsn,
                    }
                });
                Ok(LoadedVectorGraphGeneration {
                    graph,
                    resident_bytes,
                    accountant: self.accountant.clone(),
                    caller_adopted_bytes: if caller_charged { retained } else { 0 },
                    fresh_tail,
                })
            }
        }
    }
}

/// What a statement keeps for one committed-image layer it has still to
/// load, from the catalog alone: a paged load of the points that layer can
/// hold, never more than its partition's rows. A statement keeps room for
/// every layer it has still to load at that layer's own estimate, so pricing
/// a small change layer at its whole partition would starve the loads before
/// it of serving cache the reservation never needed.
fn committed_layer_least_load(
    live_rows: usize,
    durable_bytes: u64,
    dimension: usize,
    quantization: VectorQuantization,
    m: usize,
) -> usize {
    let points = if quantization == VectorQuantization::F32 {
        live_rows.min(
            contextdb_vector::hnsw::HnswIndex::paged_reader_points_bound(durable_bytes, dimension),
        )
    } else {
        live_rows
    };
    contextdb_vector::hnsw::HnswIndex::paged_reader_resident_bound(points, m)
}

fn durable_vector_generation_identity(
    descriptor: VectorPartitionGenerationDescriptor,
    layout: &VectorIndexLayout,
    live_rows: usize,
) -> Result<VectorGraphGeneration> {
    let fallback = layout.resolve_policy(live_rows, 1);
    let fallback_m = u32::try_from(fallback.hnsw_m)
        .map_err(|_| Error::Other("resolved HNSW M exceeds the durable range".to_string()))?;
    let fallback_ef_construction = u32::try_from(fallback.hnsw_ef_construction).map_err(|_| {
        Error::Other("resolved HNSW EF_CONSTRUCTION exceeds the durable range".to_string())
    })?;
    Ok(VectorGraphGeneration {
        generation_id: descriptor.generation_id,
        covered_tx: descriptor.covered_tx,
        covered_lsn: descriptor.covered_lsn,
        durable_bytes: descriptor.durable_bytes,
        policy_revision: if descriptor.policy_revision == 0 {
            fallback.policy_revision
        } else {
            descriptor.policy_revision
        },
        hnsw_m: if descriptor.hnsw_m == 0 {
            fallback_m
        } else {
            descriptor.hnsw_m
        },
        hnsw_ef_construction: if descriptor.hnsw_ef_construction == 0 {
            fallback_ef_construction
        } else {
            descriptor.hnsw_ef_construction
        },
    })
}

fn register_dormant_vector_generations(
    vector: &VectorStore,
    persistence: &Arc<RedbPersistence>,
    accountant: &Arc<MemoryAccountant>,
    declared_serving_cache: DeclaredServingCache,
) -> Result<()> {
    let known_routes = vector_partition_routes(vector)?;
    let loaded = persistence.inspect_vector_partition_generation_catalog(&known_routes)?;
    register_loaded_dormant_vector_generations(
        vector,
        loaded,
        DurableVectorGenerationSource::Writable(persistence.clone()),
        accountant,
        Some(persistence.as_ref()),
        declared_serving_cache,
    )
}

fn register_loaded_dormant_vector_generations(
    vector: &VectorStore,
    loaded: LoadedVectorPartitionGenerationCatalog,
    source: DurableVectorGenerationSource,
    accountant: &Arc<MemoryAccountant>,
    journal_truncation_owner: Option<&RedbPersistence>,
    declared_serving_cache: DeclaredServingCache,
) -> Result<()> {
    for (partition, reason) in loaded.quarantines {
        vector.quarantine_partition_route(&partition, reason);
    }
    let catalogs = loaded.catalogs;
    for catalog in catalogs {
        let partition =
            VectorPartitionRef::new(catalog.index.clone(), catalog.partition_key.clone());
        let Ok(layout) = vector.index_layout(&catalog.index) else {
            continue;
        };
        if vector.partition_is_historical_only(&catalog.index, &catalog.partition_key) {
            // Historical raw values remain exact-readable, but a retired
            // partition no longer owns an indexed route.
            continue;
        }
        if vector
            .partition_info(&catalog.index, &catalog.partition_key)
            .is_none()
        {
            continue;
        }
        let live_rows = vector
            .partition_info(&catalog.index, &catalog.partition_key)
            .map(|info| info.live_rows)
            .unwrap_or(0);
        if catalog.base.generation_id == 0
            || catalog.base.resident_bytes == 0
            || catalog.base.durable_bytes == 0
            || catalog.base.covered_tx.0 > catalog.published_tx.0
            || catalog.base.covered_lsn.0 > catalog.published_lsn.0
        {
            vector.quarantine_partition_route(&partition, VectorRouteQuarantineReason::CorruptBase);
            continue;
        }
        if catalog.change.is_some_and(|change| {
            change.generation_id == 0
                || change.resident_bytes == 0
                || change.durable_bytes == 0
                || change.covered_tx.0 < catalog.base.covered_tx.0
                || change.covered_lsn.0 < catalog.base.covered_lsn.0
                || change.covered_tx.0 > catalog.published_tx.0
                || change.covered_lsn.0 > catalog.published_lsn.0
        }) {
            vector.quarantine_partition_route(
                &partition,
                VectorRouteQuarantineReason::CorruptChanges,
            );
            continue;
        }

        // Reopen is also a retry owner for T2. Only a validated catalog may
        // witness covered deletion; quarantined bytes never authorize it.
        if let Some(persistence) = journal_truncation_owner {
            let mut cleanup_workspace = vector.reserve_workspace(
                accountant.clone(),
                0,
                "truncate_vector_partition_journal",
                "Raise MEMORY_LIMIT with SET MEMORY_LIMIT <SIZE> (or reopen with --memory-limit <SIZE>) before cleaning this maintained route.",
            )?;
            match persistence
                .truncate_vector_partition_journal_through_catalog(&catalog, &mut cleanup_workspace)
            {
                Ok(_) => {}
                Err(Error::StoreCorrupted { .. }) => {
                    vector.quarantine_partition_route(
                        &partition,
                        VectorRouteQuarantineReason::CorruptChanges,
                    );
                    continue;
                }
                Err(error) => return Err(error),
            }
        }

        let base_resident_bytes = DurableVectorGenerationLoader::descriptor_usize(
            catalog.base.resident_bytes,
            "base resident byte declaration",
        )?;
        let base_durable_bytes = DurableVectorGenerationLoader::descriptor_usize(
            catalog.base.durable_bytes,
            "base durable byte declaration",
        )?;
        let base_load_bytes = if source.is_committed_image() {
            1
        } else {
            DurableVectorGenerationLoader::checked_add(
                base_resident_bytes,
                base_durable_bytes,
                "base graph load admission",
            )?
        };
        let base_identity = durable_vector_generation_identity(catalog.base, &layout, live_rows)?;
        let base_descriptor = DormantVectorGraphGeneration {
            identity: base_identity,
            resident_bytes: if source.is_committed_image() {
                1
            } else {
                base_resident_bytes
            },
            load_bytes: base_load_bytes,
            // A committed-image generation is served PAGED: it keeps topology
            // and a serving cache and never holds its vectors. Its load is
            // admitted at what it reads from the saved topology; this
            // catalog-only estimate of that lets a statement keep room for
            // the loads it has not reached yet.
            reclaim_bytes: if source.is_committed_image() {
                committed_layer_least_load(
                    live_rows,
                    catalog.base.durable_bytes,
                    layout.dimension,
                    layout.quantization,
                    base_identity.hnsw_m as usize,
                )
            } else {
                base_load_bytes
            },
        };
        let base_loader: Arc<dyn DormantVectorGraphLoader> =
            Arc::new(DurableVectorGenerationLoader {
                source: source.clone(),
                accountant: accountant.clone(),
                partition: partition.clone(),
                descriptor: catalog.base,
                base_generation_id: catalog.base.generation_id,
                is_base: true,
                base_covered: (catalog.base.covered_tx, catalog.base.covered_lsn),
                dimension: layout.dimension,
                quantization: layout.quantization,
                layout: layout.clone(),
                live_rows,
                declared_serving_cache: declared_serving_cache.clone(),
                tail_covered_lsn: catalog.change.is_none().then_some(catalog.base.covered_lsn),
            });
        vector.register_dormant_partition_generation(
            &partition,
            true,
            base_descriptor,
            base_loader,
        )?;

        if let Some(change) = catalog.change {
            let change_resident_bytes = DurableVectorGenerationLoader::descriptor_usize(
                change.resident_bytes,
                "change resident byte declaration",
            )?;
            let change_durable_bytes = DurableVectorGenerationLoader::descriptor_usize(
                change.durable_bytes,
                "change durable byte declaration",
            )?;
            let change_load_bytes = if source.is_committed_image() {
                1
            } else {
                DurableVectorGenerationLoader::checked_add(
                    change_resident_bytes,
                    change_durable_bytes,
                    "change graph load admission",
                )?
            };
            let change_identity = durable_vector_generation_identity(change, &layout, live_rows)?;
            let change_descriptor = DormantVectorGraphGeneration {
                identity: change_identity,
                resident_bytes: if source.is_committed_image() {
                    1
                } else {
                    change_resident_bytes
                },
                load_bytes: change_load_bytes,
                reclaim_bytes: if source.is_committed_image() {
                    committed_layer_least_load(
                        live_rows,
                        change.durable_bytes,
                        layout.dimension,
                        layout.quantization,
                        change_identity.hnsw_m as usize,
                    )
                } else {
                    change_load_bytes
                },
            };
            let change_loader: Arc<dyn DormantVectorGraphLoader> =
                Arc::new(DurableVectorGenerationLoader {
                    source: source.clone(),
                    accountant: accountant.clone(),
                    partition: partition.clone(),
                    descriptor: change,
                    base_generation_id: catalog.base.generation_id,
                    is_base: false,
                    base_covered: (catalog.base.covered_tx, catalog.base.covered_lsn),
                    dimension: layout.dimension,
                    quantization: layout.quantization,
                    layout: layout.clone(),
                    live_rows,
                    declared_serving_cache: declared_serving_cache.clone(),
                    tail_covered_lsn: Some(change.covered_lsn),
                });
            vector.register_dormant_partition_generation(
                &partition,
                false,
                change_descriptor,
                change_loader,
            )?;
        }
    }
    Ok(())
}

fn vector_partition_routes(vector: &VectorStore) -> Result<Vec<VectorPartitionRef>> {
    let mut routes = Vec::new();
    for index in vector.index_layout_infos() {
        routes.extend(
            vector
                .partition_infos(&index.index)?
                .into_iter()
                .map(|partition| partition.partition),
        );
    }
    Ok(routes)
}

struct MetadataAuthorizedCandidates {
    ids: Option<RoaringTreemap>,
    _memory: crate::memory_accounting::OwnedMemoryReservation,
}
impl MetadataAuthorizedCandidates {
    fn as_ref(&self) -> Option<&RoaringTreemap> {
        self.ids.as_ref()
    }
}

const VECTOR_GENERATION_PERSISTENCE_COPIES: usize = 6;

#[derive(Debug, Clone, Copy)]
struct VectorGenerationWorkspacePlan {
    graph_build_bytes: usize,
    raw_entry_bytes: usize,
    raw_decode_scratch_bytes: usize,
    selected_entry_bytes: usize,
    encoded_graph_bound: usize,
    encoding_scratch_bytes: usize,
    prior_base_bytes: usize,
    durable_metadata_bytes: usize,
    digest_reference_bytes: usize,
    carrier_metadata_bytes: usize,
}

impl VectorGenerationWorkspacePlan {
    fn new(
        raw_count: usize,
        graph_count: usize,
        layout: &VectorIndexLayout,
        partition: &VectorPartitionRef,
        policy: contextdb_vector::store::ResolvedVectorPolicy,
        prior_base_bytes: usize,
    ) -> Result<Self> {
        let graph_build_bytes = HnswIndex::estimated_build_reservation(
            graph_count,
            layout.dimension,
            layout.quantization,
            policy,
        );
        let entry_bytes = std::mem::size_of::<VectorEntry>()
            .saturating_add(layout.dimension.saturating_mul(4))
            .saturating_add(partition.index.table.len())
            .saturating_add(partition.index.column.len())
            .saturating_add(128);
        let raw_entry_bytes = raw_count.saturating_mul(entry_bytes);
        let selected_entry_bytes = graph_count.saturating_mul(entry_bytes);
        let encoded_graph_bound = HnswIndex::durable_generation_capacity_bound(
            graph_count,
            layout.dimension,
            layout.quantization,
            policy.hnsw_m,
        )?;
        // Encoding sorts borrowed exact-map entries and copied row-id pairs;
        // the vendor codec copies one point's adjacency at a time. Each
        // nonempty Vec has a minimum capacity of four neighbour slots.
        let encoding_scratch_bytes = graph_count
            .saturating_mul(32)
            .saturating_add(policy.hnsw_m.max(4).saturating_mul(17).saturating_mul(32))
            .saturating_add(16 * std::mem::size_of::<Vec<usize>>());
        let durable_metadata_bytes = partition
            .partition_key
            .estimated_bytes()
            .saturating_mul(4)
            .saturating_add(
                partition
                    .index
                    .table
                    .len()
                    .saturating_add(partition.index.column.len())
                    .saturating_mul(4),
            )
            .saturating_add(4096);
        Ok(Self {
            graph_build_bytes,
            raw_entry_bytes,
            // Direct raw loading decodes one persisted value then clones or
            // dequantizes it. Cover declared-body copies and serde's capped
            // initial Vec allocation on a short malformed length prefix, even
            // when construction has no live-point allowance.
            raw_decode_scratch_bytes: layout
                .dimension
                .saturating_mul(4)
                .saturating_mul(3)
                .saturating_add(std::mem::size_of::<VectorEntry>())
                .saturating_add(1024 * 1024),
            selected_entry_bytes,
            encoded_graph_bound,
            encoding_scratch_bytes,
            prior_base_bytes,
            durable_metadata_bytes,
            digest_reference_bytes: graph_count
                .saturating_mul(std::mem::size_of::<&VectorEntry>())
                .saturating_mul(2),
            carrier_metadata_bytes: 0,
        })
    }

    fn assign_raw_decode_owner(&mut self, partition_state_present: bool, delete_carriers: bool) {
        // Partition snapshots copy resident entries into the funded raw owner.
        // If its bodies are dormant/evicted, the partition loader independently
        // admits its decoder scratch before hydration. Direct durable reads and
        // delete-only carriers instead decode under this generation workspace.
        if partition_state_present && !delete_carriers {
            self.raw_decode_scratch_bytes = 0;
        }
    }

    fn estimated_generation_bytes(self) -> usize {
        self.encoded_graph_bound
            .saturating_add(self.prior_base_bytes)
            .saturating_add(self.durable_metadata_bytes)
    }

    fn build_phase_bytes(self) -> usize {
        // Raw snapshot, selected input clones and construction workspace coexist.
        // Neither the envelope nor a prior base is loaded during construction.
        self.graph_build_bytes
            .saturating_add(self.raw_entry_bytes)
            .saturating_add(self.raw_decode_scratch_bytes)
            .saturating_add(self.selected_entry_bytes)
            .saturating_add(self.durable_metadata_bytes)
            .saturating_add(self.carrier_metadata_bytes)
    }

    fn encoding_phase_bytes(self, graph_resident_bytes: usize) -> usize {
        // Input clones are gone. The builder, authoritative raw snapshot and
        // one checked codec envelope (including sorting scratch) remain.
        graph_resident_bytes
            .saturating_add(self.raw_entry_bytes)
            .saturating_add(self.encoded_graph_bound)
            .saturating_add(self.encoding_scratch_bytes)
            .saturating_add(self.durable_metadata_bytes)
    }

    fn persistence_phase_bytes(self, encoded_graph_capacity: usize) -> usize {
        // The builder is gone. The raw snapshot and one candidate graph
        // coexist; change publication decodes one prior base directly from
        // its borrowed durable record. Digesting sorts borrowed raw entries
        // and streams their encoding into the hasher.
        self.raw_entry_bytes
            .saturating_add(encoded_graph_capacity)
            .saturating_add(self.prior_base_bytes)
            .saturating_add(self.durable_metadata_bytes)
            .saturating_add(self.digest_reference_bytes)
    }

    fn prepared_phase_bytes(self, encoded_graph_capacity: usize) -> usize {
        // Builder and input clones are gone. The change path alone loads its
        // prior base. Six payload bounds cover candidate, bincode payload,
        // record envelope, validation decode, prepared body, and insertion.
        // Page keys are streamed one at a time: even a near-64KiB root never
        // repeats in retained preparation memory. Reserve its framed page
        // (key + header + body <= 64KiB) separately before insertion.
        encoded_graph_capacity
            .saturating_add(self.prior_base_bytes)
            .saturating_add(self.durable_metadata_bytes)
            .saturating_mul(VECTOR_GENERATION_PERSISTENCE_COPIES)
            .saturating_add(64 * 1024)
    }

    fn prepared_candidate_phase_bytes(
        self,
        encoded_graph_capacity: usize,
        frame_bytes: usize,
    ) -> usize {
        let candidate = encoded_graph_capacity
            .saturating_add(self.prior_base_bytes)
            .saturating_add(self.durable_metadata_bytes)
            .saturating_mul(VECTOR_GENERATION_PERSISTENCE_COPIES)
            .saturating_add(frame_bytes);
        debug_assert!(candidate <= self.prepared_phase_bytes(encoded_graph_capacity));
        candidate
    }
}

#[derive(Default)]
struct RetentionDeferredEdges {
    nodes: HashSet<NodeId>,
    // The published carry-over owns its hash buckets until replacement/drop.
    _memory: Option<crate::memory_accounting::OwnedMemoryReservation>,
}

/// The engine-owned pieces one maintenance cycle needs, cloned out of the
/// `Database` handle so the SAME cycle code runs whether a caller drives it
/// synchronously (`Database::run_maintenance_cycle`) or the engine's own loop
/// dispatches it on a tick.
pub(crate) struct MaintenanceContext {
    disk_limit: Arc<AtomicU64>,
    vector_serving_cache_bytes: Arc<AtomicU64>,
    resource_closed: Arc<AtomicBool>,
    publication_interrupted: Arc<AtomicBool>,
    worker_stop: Option<Arc<AtomicBool>>,
    relational: Arc<RelationalStore>,
    graph: Arc<GraphStore>,
    vector: Arc<VectorStore>,
    accountant: Arc<MemoryAccountant>,
    persistence: Option<Arc<RedbPersistence>>,
    change_log: Arc<RwLock<Vec<ChangeLogEntry>>>,
    change_log_table_index: Arc<RwLock<ChangeLogTableIndex>>,
    change_log_lsn_refcounts: Arc<RwLock<ChangeLogLsnRefcounts>>,
    trigger: Arc<trigger::TriggerState>,
    tx_mgr: Arc<TransactionManager<DynStore>>,
    sync_watermark: Arc<AtomicLsn>,
    /// Shared with `Database::trigger_audit_retention_secs` (same `Arc`,
    /// cloned at context-build time) and re-read on every
    /// `run_trigger_audit_retention` call, so a declared override reaches
    /// this already-spawned loop's next tick -- not only a loop spawned
    /// after the setter runs. See that field's doc comment.
    trigger_audit_retention_secs: Arc<AtomicU64>,
    snapshot_registry: Arc<SnapshotFloorRegistry>,
    /// Shared with the `Database` handle (same `Arc`) -- see that field's
    /// doc comment.
    retention_deferred_edge_nodes: Arc<Mutex<RetentionDeferredEdges>>,
    last_maintenance_cycle_at: Arc<Mutex<Option<std::time::Instant>>>,
    last_auto_compact_at: Arc<Mutex<Option<std::time::Instant>>>,
    auto_compact_min_interval: Arc<Mutex<Duration>>,
    /// Shared with the `Database` handle (same `Arc`) -- see that field's
    /// doc comment.
    #[cfg(feature = "test-seams")]
    snapshot_free_retirement_pass_count: Arc<AtomicUsize>,
}

#[derive(Debug, Clone, Copy, Default)]
struct VectorPartitionPublicationOutcome {
    published: bool,
    cleanup_failure: Option<VectorMaintenanceFailureDetails>,
}

#[derive(Debug, Default)]
struct VectorJournalCleanupRetryOutcome {
    first_failure_details: Option<VectorMaintenanceFailureDetails>,
    failed_partitions: FailedMaintenancePartitions,
}

impl VectorPartitionPublicationOutcome {
    fn published() -> Self {
        Self {
            published: true,
            cleanup_failure: None,
        }
    }

    fn published_with_cleanup_failure(error: &Error) -> Self {
        Self {
            published: true,
            cleanup_failure: Some(
                VectorMaintenanceFailureDetails::from_published_cleanup_error(error),
            ),
        }
    }
}

impl MaintenanceContext {
    fn retain_published_vector_cleanup_failure(
        &self,
        partition: &VectorPartitionRef,
        error: &Error,
    ) -> Result<VectorPartitionPublicationOutcome> {
        let outcome = VectorPartitionPublicationOutcome::published_with_cleanup_failure(error);
        let details = outcome
            .cleanup_failure
            .expect("a cleanup-failure outcome carries its retained detail");
        self.vector
            .record_partition_maintenance_failure_details(partition, details)?;
        Ok(outcome)
    }

    fn build_checkpoint(&self) -> Result<()> {
        // Maintenance derives its work from memory, which no longer matches
        // the durable image once a publication was interrupted.
        if self.publication_interrupted.load(Ordering::SeqCst) {
            return Err(Error::PublicationInterrupted);
        }
        if self.resource_closed.load(Ordering::SeqCst)
            || self
                .worker_stop
                .as_ref()
                .is_some_and(|stop| stop.load(Ordering::SeqCst))
        {
            return Err(Error::ReadCancelled);
        }
        Ok(())
    }

    fn admit_generation_disk(&self, bytes: usize) -> Result<()> {
        self.build_checkpoint()?;
        let limit = self.disk_limit.load(Ordering::SeqCst);
        let current_bytes = self.file_bytes().unwrap_or(0);
        if limit == 0 || current_bytes.saturating_add(bytes as u64) <= limit {
            return Ok(());
        }
        Err(Error::DiskBudgetExceeded {
            operation: "prepare_vector_generation".into(),
            current_bytes,
            budget_limit_bytes: limit,
            hint: "Reduce retained file-backed data or raise DISK_LIMIT before writing more data."
                .into(),
        })
    }

    fn retry_one_vector_journal_truncation(
        &self,
        persistence: &RedbPersistence,
        catalog: &VectorPartitionGenerationCatalogRecord,
        partition: &VectorPartitionRef,
        partition_state_present: bool,
    ) -> Result<()> {
        vector_source_page_admission::with_source_page_admission(
            Arc::clone(&self.accountant),
            || {
                self.retry_one_vector_journal_truncation_with_source_admission(
                    persistence,
                    catalog,
                    partition,
                    partition_state_present,
                )
            },
        )
    }

    fn retry_one_vector_journal_truncation_with_source_admission(
        &self,
        persistence: &RedbPersistence,
        catalog: &VectorPartitionGenerationCatalogRecord,
        partition: &VectorPartitionRef,
        partition_state_present: bool,
    ) -> Result<()> {
        let mut cleanup_workspace = self.vector.reserve_workspace(
            self.accountant.clone(),
            0,
            "truncate_vector_partition_journal",
            "Raise MEMORY_LIMIT with SET MEMORY_LIMIT <SIZE> (or reopen with --memory-limit <SIZE>) before cleaning this maintained route.",
        )?;
        self.retry_one_vector_journal_truncation_in_workspace(
            persistence,
            catalog,
            partition,
            partition_state_present,
            &mut cleanup_workspace,
        )
    }

    fn retry_one_vector_journal_truncation_in_workspace(
        &self,
        persistence: &RedbPersistence,
        catalog: &VectorPartitionGenerationCatalogRecord,
        partition: &VectorPartitionRef,
        partition_state_present: bool,
        cleanup_workspace: &mut contextdb_vector::VectorWorkspaceReservation,
    ) -> Result<()> {
        match persistence.truncate_vector_partition_journal_through_catalog_with_checkpoint(
            catalog,
            cleanup_workspace,
            || self.build_checkpoint(),
        ) {
            Ok(_) => {}
            Err(Error::StoreCorrupted { .. }) => {
                self.vector.quarantine_partition_route(
                    partition,
                    VectorRouteQuarantineReason::CorruptChanges,
                );
                return Ok(());
            }
            Err(error) => return Err(error),
        }
        if !partition_state_present {
            // The route was safely retired after its final live vector
            // disappeared. Physical journal cleanup still runs, but must not
            // recreate an empty partition merely because its catalog remains.
            return Ok(());
        }
        let selected = catalog.change.unwrap_or(catalog.base).generation_id;
        let installed = self
            .vector
            .partition_graph_generation_status(partition)
            .is_some_and(|status| {
                [
                    status.base,
                    status.change,
                    status.dormant_base,
                    status.dormant_change,
                ]
                .into_iter()
                .flatten()
                .any(|generation| generation.generation_id == selected)
            });
        // A quarantined descriptor or body must be replaced from the
        // authoritative raw vectors. Reinstalling the same catalog here
        // would decode the damaged generation before repair can replace it.
        if self.vector.partition_route_quarantine(partition).is_some() {
            return Ok(());
        }
        if !installed {
            self.install_published_vector_catalog(catalog)?;
        }
        Ok(())
    }

    fn retry_vector_journal_truncations(&self) -> Result<VectorJournalCleanupRetryOutcome> {
        self.build_checkpoint()?;
        let Some(persistence) = self.persistence.as_ref() else {
            return Ok(VectorJournalCleanupRetryOutcome::default());
        };
        let mut inventory = self.maintenance_catalog_inventory()?;
        #[cfg(test)]
        vector_journal_cleanup_cancellation_tests::after_inventory_capture_for_test();
        self.build_checkpoint()?;
        let mut outcome = VectorJournalCleanupRetryOutcome {
            first_failure_details: inventory.failures.first,
            failed_partitions: FailedMaintenancePartitions::default(),
        };
        let mut terminal = None;
        inventory.catalogs.retain_mut(|entry| {
            if terminal.is_some() {
                return false;
            }
            if let Err(error) = self.build_checkpoint() {
                terminal = Some(error);
                return false;
            }
            let catalog = &entry.catalog;
            let mut route_memory =
                crate::memory_accounting::OwnedMemoryReservation::new(Arc::clone(&self.accountant));
            let heap = RedbPersistence::maintenance_vector_catalog_heap_bytes(catalog);
            let route_admission = route_memory.try_grow_for(
                heap,
                "vector_maintenance",
                "prepare_vector_generation",
                "Raise MEMORY_LIMIT before inspecting this maintained route.",
            );
            let retry = route_admission.and_then(|()| {
                let partition =
                    VectorPartitionRef::new(catalog.index.clone(), catalog.partition_key.clone());
                let partition_state_present = self.tx_mgr.with_commit_lock(|| {
                    self.vector
                        .try_partition_state(&partition.index, &partition.partition_key)
                        .is_some_and(|state| !state.source_maintenance_metadata().historical_only)
                });
                let selected = catalog.change.unwrap_or(catalog.base).generation_id;
                let installed = self
                    .vector
                    .partition_graph_generation_status(&partition)
                    .is_some_and(|status| {
                        [
                            status.base,
                            status.change,
                            status.dormant_base,
                            status.dormant_change,
                        ]
                        .into_iter()
                        .flatten()
                        .any(|generation| generation.generation_id == selected)
                    });
                // The same catalog workspace funds route keys before the
                // identity probe; pending cleanup keeps its early operation.
                entry.workspace.resize(
                    heap.saturating_add(RedbPersistence::vector_journal_cleanup_key_reservation(
                        &catalog.index,
                        &catalog.partition_key,
                    )),
                    if entry.pending_cleanup {
                        "truncate_vector_partition_journal"
                    } else {
                        "prepare_vector_generation"
                    },
                    "Raise MEMORY_LIMIT before inspecting this maintained route.",
                )?;
                let cleanup_only = !partition_state_present
                    || installed
                    || self.vector.partition_route_quarantine(&partition).is_some();
                let covered = if cleanup_only {
                    vector_source_page_admission::with_preparation_source_page_admission(
                        Arc::clone(&self.accountant),
                        || persistence.vector_partition_has_covered_journal_records(catalog),
                    )
                } else {
                    Ok(true)
                };
                match covered {
                    Ok(false) => Ok(()),
                    Err(
                        error @ (Error::MemoryBudgetExceeded { .. }
                        | Error::ReadCancelled
                        | Error::PublicationInterrupted),
                    ) => Err(error),
                    _ => {
                        let retry = || {
                            self.retry_one_vector_journal_truncation_in_workspace(
                                persistence,
                                catalog,
                                &partition,
                                partition_state_present,
                                &mut entry.workspace,
                            )
                        };
                        if cleanup_only {
                            vector_source_page_admission::with_journal_cleanup_source_page_admission(
                                Arc::clone(&self.accountant),
                                retry,
                            )
                        } else {
                            // Restoring an uninstalled catalog reads and
                            // installs its generation after cleaning the journal.
                            vector_source_page_admission::with_source_page_admission(
                                Arc::clone(&self.accountant),
                                retry,
                            )
                        }
                    }
                }
            });
            #[cfg(test)]
            vector_journal_cleanup_cancellation_tests::after_retry_for_test(catalog);
            // A completed T2 stays committed, but a stop must reach the
            // caller before a later route or the cycle's closing work starts.
            let retry = self.build_checkpoint().and(retry);
            match retry {
                Ok(()) => false,
                Err(error @ (Error::ReadCancelled | Error::PublicationInterrupted)) => {
                    terminal = Some(error);
                    false
                }
                Err(error) => {
                    let details =
                        VectorMaintenanceFailureDetails::from_published_cleanup_error(&error);
                    self.record_catalog_metadata_failure(catalog, details);
                    outcome.first_failure_details.get_or_insert(details);
                    // Cleanup locals are gone. Retain only this authenticated
                    // catalog's actual heap; its route blocks a build this cycle.
                    if let Err(shrink_error) = entry.workspace.resize(
                        heap,
                        "truncate_vector_partition_journal",
                        "Raise MEMORY_LIMIT before cleaning this maintained route.",
                    ) {
                        terminal = Some(shrink_error);
                    }
                    true
                }
            }
        });
        if let Some(error) = terminal {
            return Err(error);
        }
        outcome.failed_partitions.inventory = Some(inventory);
        Ok(outcome)
    }

    /// The serving cache size this store declares, as the loaders read it.
    fn declared_serving_cache_bytes(&self) -> Option<usize> {
        declared_serving_cache_bytes(self.vector_serving_cache_bytes.load(Ordering::SeqCst))
    }

    fn install_published_vector_catalog(
        &self,
        catalog: &VectorPartitionGenerationCatalogRecord,
    ) -> Result<()> {
        let Some(persistence) = self.persistence.as_ref() else {
            return Ok(());
        };
        // Final-delete publication still advances and cleans the durable
        // catalog, but retired raw history must not regain an indexed route.
        if self
            .vector
            .partition_is_historical_only(&catalog.index, &catalog.partition_key)
        {
            return Ok(());
        }
        let partition =
            VectorPartitionRef::new(catalog.index.clone(), catalog.partition_key.clone());
        let layout = self.vector.index_layout(&catalog.index)?;
        let live_rows = self
            .vector
            .partition_info(&catalog.index, &catalog.partition_key)
            .map(|info| info.live_rows)
            .unwrap_or(0);
        let base_resident_bytes = DurableVectorGenerationLoader::descriptor_usize(
            catalog.base.resident_bytes,
            "published base generation resident byte declaration",
        )?;
        let base_load_bytes = DurableVectorGenerationLoader::checked_add(
            base_resident_bytes,
            DurableVectorGenerationLoader::descriptor_usize(
                catalog.base.durable_bytes,
                "published base generation durable byte declaration",
            )?,
            "published base graph load admission",
        )?;
        let base_dormant = DormantVectorGraphGeneration {
            identity: durable_vector_generation_identity(catalog.base, &layout, live_rows)?,
            resident_bytes: base_resident_bytes,
            load_bytes: base_load_bytes,
            reclaim_bytes: base_load_bytes,
        };
        let base_loader: Arc<dyn DormantVectorGraphLoader> =
            Arc::new(DurableVectorGenerationLoader {
                source: DurableVectorGenerationSource::Writable(persistence.clone()),
                accountant: self.accountant.clone(),
                partition: partition.clone(),
                descriptor: catalog.base,
                base_generation_id: catalog.base.generation_id,
                is_base: true,
                base_covered: (catalog.base.covered_tx, catalog.base.covered_lsn),
                dimension: layout.dimension,
                quantization: layout.quantization,
                layout: layout.clone(),
                live_rows,
                declared_serving_cache: DeclaredServingCache::Live(
                    self.vector_serving_cache_bytes.clone(),
                ),
                tail_covered_lsn: catalog.change.is_none().then_some(catalog.base.covered_lsn),
            });
        self.vector.register_dormant_partition_generation(
            &partition,
            true,
            base_dormant,
            base_loader,
        )?;
        if let Some(change) = catalog.change {
            let change_resident_bytes = DurableVectorGenerationLoader::descriptor_usize(
                change.resident_bytes,
                "published change generation resident byte declaration",
            )?;
            let change_load_bytes = DurableVectorGenerationLoader::checked_add(
                change_resident_bytes,
                DurableVectorGenerationLoader::descriptor_usize(
                    change.durable_bytes,
                    "published change generation durable byte declaration",
                )?,
                "published change graph load admission",
            )?;
            let change_dormant = DormantVectorGraphGeneration {
                identity: durable_vector_generation_identity(change, &layout, live_rows)?,
                resident_bytes: change_resident_bytes,
                load_bytes: change_load_bytes,
                reclaim_bytes: change_load_bytes,
            };
            let change_loader: Arc<dyn DormantVectorGraphLoader> =
                Arc::new(DurableVectorGenerationLoader {
                    source: DurableVectorGenerationSource::Writable(persistence.clone()),
                    accountant: self.accountant.clone(),
                    partition: partition.clone(),
                    descriptor: change,
                    base_generation_id: catalog.base.generation_id,
                    is_base: false,
                    base_covered: (catalog.base.covered_tx, catalog.base.covered_lsn),
                    dimension: layout.dimension,
                    quantization: layout.quantization,
                    layout: layout.clone(),
                    live_rows,
                    declared_serving_cache: DeclaredServingCache::Live(
                        self.vector_serving_cache_bytes.clone(),
                    ),
                    tail_covered_lsn: Some(change.covered_lsn),
                });
            self.vector.register_dormant_partition_generation(
                &partition,
                false,
                change_dormant,
                change_loader,
            )?;
        }
        if catalog.base.resident_bytes != 0 {
            self.vector
                .preload_dormant_partition_generation(&partition, true)?;
        }
        if catalog
            .change
            .is_some_and(|change| change.resident_bytes != 0)
        {
            self.vector
                .preload_dormant_partition_generation(&partition, false)?;
        }
        self.vector.clear_partition_route_quarantine(&partition);
        Ok(())
    }

    fn file_bytes(&self) -> Option<u64> {
        self.persistence
            .as_ref()
            .and_then(|persistence| std::fs::metadata(persistence.path()).ok())
            .map(|meta| meta.len())
    }

    /// The optional, MUCH RARER automatic compaction path — see
    /// [`AUTO_COMPACT_MIN_INTERVAL`]'s own doc comment for why this exists
    /// separately from any scoped cleanup pass's own compact decision.
    /// Starts a sweep only after the configured interval and fragmentation
    /// threshold are satisfied. An active sweep advances one bounded durable
    /// batch per cycle; completion starts the next interval. It runs outside
    /// the commit lock, since
    /// this is called from `run_cycle` after both `run_pruning` and
    /// `run_currency` have already returned.
    fn maybe_auto_compact(&self) -> Result<CompactionReport> {
        let Some(persistence) = self.persistence.as_ref() else {
            return Ok(CompactionReport::default());
        };
        let min_interval = *self.auto_compact_min_interval.lock();
        let due = self
            .last_auto_compact_at
            .lock()
            .is_none_or(|at| at.elapsed() >= min_interval);
        let previous_sample = vector_source_page_admission::with_preparation_source_page_admission(
            self.accountant.clone(),
            || persistence.storage_compaction_fragmentation_ratio(),
        )?;
        if !due && previous_sample.is_none() {
            return Ok(CompactionReport::default());
        }
        let fragmentation_before = match previous_sample {
            Some(sample) => sample,
            None => vector_source_page_admission::with_preparation_source_page_admission(
                self.accountant.clone(),
                || persistence.fragmentation_ratio(),
            )?,
        };
        if previous_sample.is_none() && fragmentation_before < REDB_COMPACT_FRAGMENTATION_THRESHOLD
        {
            return Ok(CompactionReport::default());
        }
        let bytes_before = self.file_bytes();
        let start = Instant::now();
        let (progress, handle_recycle_micros) =
            persistence.compact_incremental(self.accountant.clone(), fragmentation_before)?;
        let duration_micros = start.elapsed().as_micros() as u64;
        if progress.complete {
            *self.last_auto_compact_at.lock() = Some(std::time::Instant::now());
        }
        let bytes_after = self.file_bytes();
        Ok(CompactionReport {
            ran: true,
            duration_micros,
            bytes_before,
            bytes_after,
            file_shrank: matches!((bytes_before, bytes_after), (Some(b), Some(a)) if a < b),
            fragmentation_before,
            handle_recycled: handle_recycle_micros.is_some(),
            handle_recycle_micros: handle_recycle_micros.unwrap_or(0),
        })
    }

    /// Generic retention, then — once the rows are gone — the compaction
    /// decision on the SAME conservative threshold the currency path uses.
    /// True when any table declares RETAIN. Retention borrows eligible rows
    /// at the commit frontier and admits only selected identities and mutations;
    /// without a retention declaration even that selection has no possible effect.
    fn has_retention_work(&self) -> bool {
        self.relational
            .table_meta
            .read()
            .values()
            .any(|meta| meta.default_ttl_seconds.is_some())
    }

    fn stamp_expired_rows(&self, now: Wallclock) -> Result<()> {
        let tx = self.tx_mgr.begin();
        let workspace = std::cell::RefCell::new(
            crate::memory_accounting::OwnedMemoryReservation::new(self.accountant.clone()),
        );
        // Armed just before the durable apply; see `PublicationInterruptionWatch`.
        // This commit is durable the moment the manager applies it, and the
        // in-memory commit bookkeeping that makes it visible happens after --
        // so an unwind in between leaves this handle behind its own durable
        // image, exactly as it does on the local and received doors.
        let publication_watch = std::cell::RefCell::new(None::<PublicationInterruptionWatch>);
        let result = self.tx_mgr.commit_with_reserved_lsn_callback_mut(
            tx,
            |expiry_lsn| {
                // The reserved-LSN callback holds the commit frontier. Borrow
                // authoritative rows there; copy only admitted mutation identities.
                let metas = self.relational.table_meta.read();
                let tables = self.relational.tables.read();
                let watermark = self.sync_watermark.load(Ordering::SeqCst);
                let candidates = retention_prune_candidates(
                    &metas,
                    &tables,
                    now,
                    watermark,
                    &self.relational,
                    &mut workspace.borrow_mut(),
                    RetentionPreparation::Expiry,
                )?;
                let protected = fk_protected_prune_candidates(&metas, &tables, &candidates);
                self.tx_mgr.with_write_set(tx, |ws| -> Result<()> {
                    let mut expired_nodes = HashSet::new();
                    for (table, rows) in tables.iter() {
                        if metas
                            .get(table)
                            .is_none_or(|meta| meta.default_ttl_seconds.is_none())
                        {
                            continue;
                        }
                        for row in rows {
                            if row.deleted_tx.is_some()
                                || !candidates.contains(&RetentionRowKey::new(
                                    table,
                                    row.row_id,
                                    row.created_tx,
                                ))
                            {
                                continue;
                            }
                            if prune_blocker_for_referenced_parent(
                                table,
                                row,
                                &metas,
                                &tables,
                                &candidates,
                                &protected,
                            )
                            .is_some()
                            {
                                continue;
                            }
                            // Own the write-set strings, config encoding, node
                            // set and vector deletion identities before allocating.
                            let vector_bytes = metas.get(table).map_or(0, |meta| {
                                meta.columns
                                    .iter()
                                    .filter(|column| {
                                        matches!(column.column_type, ColumnType::Vector(_))
                                    })
                                    .fold(0usize, |bytes, column| {
                                        bytes.saturating_add(256 + table.len() + column.name.len())
                                    })
                            });
                            workspace.borrow_mut().try_grow_for(
                                1024usize
                                    .saturating_add(table.len().saturating_mul(8))
                                    .saturating_add(vector_bytes),
                                "retention",
                                "prepare_expiry",
                                "Raise MEMORY_LIMIT to admit the expiry transaction workspace.",
                            )?;
                            ws.relational_deletes.push((table.clone(), row.row_id, tx));
                            if let Some(Value::Uuid(id)) = row.values.get("id") {
                                expired_nodes.insert(*id);
                            }
                            if let Some(meta) = metas.get(table) {
                                for column in &meta.columns {
                                    if matches!(column.column_type, ColumnType::Vector(_)) {
                                        ws.vector_deletes.push((
                                            VectorIndexRef::new(table, &column.name),
                                            row.row_id,
                                            tx,
                                        ));
                                    }
                                }
                            }
                            let identity = (table.clone(), row.row_id, row.created_tx, expiry_lsn);
                            ws.config_writes.push((
                                crate::composite_store::retention_expiry_key(
                                    table,
                                    row.row_id,
                                    row.created_tx,
                                ),
                                RedbPersistence::encode_config_value(&identity)?,
                            ));
                        }
                    }
                    for entry in self.graph.forward_adj.read().values().flatten() {
                        if entry.deleted_tx.is_none()
                            && (expired_nodes.contains(&entry.source)
                                || expired_nodes.contains(&entry.target))
                        {
                            workspace.borrow_mut().try_grow_for(
                                128usize.saturating_add(entry.edge_type.len()),
                                "retention",
                                "prepare_expiry",
                                "Raise MEMORY_LIMIT to admit the expiry transaction workspace.",
                            )?;
                            ws.adj_deletes.push((
                                entry.source,
                                entry.edge_type.clone(),
                                entry.target,
                                tx,
                            ));
                        }
                    }
                    Ok(())
                })?
            },
            |_| {
                *publication_watch.borrow_mut() = Some(PublicationInterruptionWatch::arm(
                    &self.publication_interrupted,
                ));
                Ok(())
            },
        );
        #[cfg(test)]
        take_local_commit_stage_fault_for_test(
            LocalCommitStageFaultPoint::AfterReservedLsnDurableCommit,
        );
        let watch_completed = publication_watch.borrow_mut().take();
        match result {
            Ok(_) => {
                if let Some(watch) = watch_completed {
                    watch.completed();
                }
                Ok(())
            }
            Err(failure) => {
                // A failure before the manager takes the write set leaves the
                // transaction active; both failure paths publish no expiry.
                if let Some(watch) = watch_completed {
                    watch.completed();
                }
                let _ = self.tx_mgr.rollback(tx);
                Err(failure.error)
            }
        }
    }

    fn run_pruning(&self) -> Result<PruningReport> {
        // Nothing declares RETAIN, so there is nothing this pass could prune,
        // no fragmentation decision it could take, and no report field it could
        // fill. Bail BEFORE the commit lock and candidate selection.
        if !self.has_retention_work() {
            return Ok(PruningReport::default());
        }
        let file_bytes_before = self.file_bytes();
        // Sampled BEFORE the prune, deliberately. redb counts just-freed pages
        // as fragmented, so a reading taken AFTER a prune is dominated by the
        // pages that prune released — it measures the prune, not the file, and
        // reads high whatever fraction was removed. The pre-prune sample
        // measures the thing the shared threshold is written about: waste that
        // SURVIVED page reuse across earlier cycles. One consequence is
        // deliberate: a large prune of a previously tight file may not compact
        // until the next cycle, which is the rare-not-per-cycle posture the
        // constant's own doc describes.
        let fragmentation_before = self
            .persistence
            .as_ref()
            .map(|persistence| persistence.fragmentation_ratio().unwrap_or(0.0))
            .unwrap_or(0.0);
        let now = Wallclock::now();
        self.stamp_expired_rows(now)?;
        let mut report = self.tx_mgr.with_commit_lock(|| {
            prune_expired_rows(self, self.sync_watermark.load(Ordering::SeqCst), now)
        })?;
        report.file_bytes_before = file_bytes_before;
        report.fragmentation_before = fragmentation_before;
        // Compaction itself still runs AFTER the prune (there is no point
        // rewriting the file before the rows leave it) and OUTSIDE the commit
        // lock: redb compaction takes the redb mutex with `&mut` and must not
        // run while a txn is outstanding on this thread. Only the DECISION
        // rides the pre-prune observation above, and the reported
        // `fragmentation_before` is that same observed value — the decision
        // input and the receipt are one number, never a derived stand-in.
        if report.pruned_rows > 0
            && let Some(persistence) = self.persistence.as_ref()
            && fragmentation_before >= REDB_COMPACT_FRAGMENTATION_THRESHOLD
        {
            let (progress, _) =
                persistence.compact_incremental(self.accountant.clone(), fragmentation_before)?;
            if progress.complete {
                *self.last_auto_compact_at.lock() = Some(std::time::Instant::now());
            }
            report.compacted = true;
        }
        report.file_bytes_after = self.file_bytes();
        report.file_shrank = matches!(
            (report.file_bytes_before, report.file_bytes_after),
            (Some(before), Some(after)) if after < before
        );
        Ok(report)
    }

    /// Every table that DECLARES `HISTORY CURRENT ONLY` right now, whether it
    /// was created here, arrived on reopen, or arrived over synced DDL. The
    /// declaration-driven replacement for the hardcoded `VERSION_COMPACTION_
    /// TABLES` list: eligibility is a property of what a table declared, not
    /// of its name.
    fn version_cleanup_eligible_tables(&self) -> Vec<String> {
        let mut tables: Vec<String> = self
            .relational
            .table_meta
            .read()
            .iter()
            .filter(|(_, meta)| meta.history_policy == Some(HistoryPolicy::CurrentOnly))
            .map(|(name, _)| name.clone())
            .collect();
        tables.sort();
        tables
    }

    /// The scoped cleanup pass only; this never compacts the storage file.
    /// Selection visits eligible row histories and their vector directories;
    /// durable removal visits selected keys and affected change-log LSN groups.
    /// Coupling this work to whole-file compaction made steady-state churn on
    /// a small file (where routine superseded-version debris is a large
    /// fraction of a small file) retrigger a full-file rewrite on every
    /// cycle, which is exactly the per-cycle-compaction cost the
    /// version-cleanup scaling bench measures and bounds separately from the
    /// scoped pass's own cost. Compaction is now EITHER an explicit operator
    /// action (`Database::compact_now`, `.maintenance compact`) or the much
    /// rarer, interval-gated automatic path `run_cycle` drives separately
    /// (`MaintenanceContext::maybe_auto_compact`) — see
    /// [`AUTO_COMPACT_MIN_INTERVAL`].
    fn run_currency(&self, gate: CurrencyGate) -> Result<CurrencyCompactionReport> {
        let eligible = self.version_cleanup_eligible_tables();
        let tables = eligible.iter().map(String::as_str).collect::<Vec<_>>();
        if gate == CurrencyGate::Scheduled
            && !currency_compaction_pending(
                &self.relational,
                &tables,
                CURRENCY_COMPACTION_SUPERSEDED_THRESHOLD,
            )
        {
            return Ok(CurrencyCompactionReport::default());
        }
        // Timed INSIDE the closure, from the first instruction that runs once
        // `with_commit_lock` has actually granted the lock -- never before it.
        // Timing from before the call measures however long this thread
        // waited to ACQUIRE the lock plus the hold itself, which is a
        // different, larger number that can make a quiet database look like
        // an expensive hold when the pass itself was instant.
        self.tx_mgr
            .with_commit_lock(|| -> Result<CurrencyCompactionReport> {
                let hold_start = Instant::now();
                let mut report = compact_currency_versions_inner(
                    &self.relational,
                    &self.graph,
                    &self.vector,
                    self.accountant.as_ref(),
                    self.persistence.as_ref(),
                    &self.change_log,
                    &self.change_log_table_index,
                    &self.change_log_lsn_refcounts,
                    &self.tx_mgr,
                    &self.snapshot_registry,
                    &tables,
                )?;
                report.commit_lock_hold_micros = hold_start.elapsed().as_micros() as u64;
                Ok(report)
            })
    }

    /// Test-only twin of `run_currency`: the identical real mechanism
    /// (`compact_currency_versions_inner`), unconditionally (no scheduled
    /// gate), over a CALLER-SUPPLIED table list instead of the declared
    /// eligibility set `run_currency` computes. `run_currency` above is
    /// untouched -- this exists so a test can exercise the real pass against
    /// a table shape it has not declared `HISTORY CURRENT ONLY` on (yet), with
    /// zero change to production behavior. Also never compacts -- see
    /// `run_currency`'s own doc comment.
    #[cfg(any(test, feature = "test-seams"))]
    fn run_currency_for_tables(&self, tables: &[&str]) -> Result<CurrencyCompactionReport> {
        // Hold-only timing -- see the comment in `run_currency` above.
        self.tx_mgr
            .with_commit_lock(|| -> Result<CurrencyCompactionReport> {
                let hold_start = Instant::now();
                let mut report = compact_currency_versions_inner(
                    &self.relational,
                    &self.graph,
                    &self.vector,
                    self.accountant.as_ref(),
                    self.persistence.as_ref(),
                    &self.change_log,
                    &self.change_log_table_index,
                    &self.change_log_lsn_refcounts,
                    &self.tx_mgr,
                    &self.snapshot_registry,
                    tables,
                )?;
                report.commit_lock_hold_micros = hold_start.elapsed().as_micros() as u64;
                Ok(report)
            })
    }

    /// The engine's own durable trigger-audit history is the first internal
    /// consumer of retention: entries older than the shipped default window
    /// age out, including entries a DROP TABLE orphaned. The in-memory ring
    /// keeps its own bounded semantics and is never touched here.
    fn run_trigger_audit_retention(&self) -> Result<u64> {
        let now = Wallclock::now();
        let window = Duration::from_secs(self.trigger_audit_retention_secs.load(Ordering::SeqCst));
        let cutoff = now.0.saturating_sub(window.as_millis() as u64);
        match self.persistence.as_ref() {
            Some(persistence) => persistence.prune_trigger_audit_history(cutoff),
            None => {
                let mut history = self.trigger.volatile_audit_history.lock();
                let before = history.len();
                history.retain(|(stamped_at, _)| stamped_at.0 >= cutoff);
                Ok((before - history.len()) as u64)
            }
        }
    }

    /// Cheap pre-check for `retire_snapshot_free_vector_partitions`: whether
    /// this maintenance cycle could retire or reclaim anything at all.
    /// Conservative -- `true` whenever real work cannot be ruled out
    /// cheaply -- so `false` is the only answer that may safely skip
    /// beginning the guarded removal pass, and with it, parking every new
    /// read for the pass's duration. Never takes the commit lock and never
    /// begins a pass itself; the pass's own sampling (registered snapshots,
    /// persisted catalog contents) remains exactly as before whenever it
    /// does run.
    fn vector_partition_retirement_is_possible(&self) -> bool {
        self.vector.has_snapshot_free_retirement_candidate()
            || self.vector.has_retired_graph_generations()
            || (self.persistence.is_some()
                && self.snapshot_registry.no_snapshots_currently_registered())
    }

    fn retire_snapshot_free_vector_partitions(&self) -> Result<MaintenanceMetadataFailures> {
        if !self.vector_partition_retirement_is_possible() {
            return Ok(MaintenanceMetadataFailures::default());
        }
        self.tx_mgr.with_commit_lock(|| {
            #[cfg(feature = "test-seams")]
            self.snapshot_free_retirement_pass_count
                .fetch_add(1, Ordering::SeqCst);
            let active_removal_pass = self
                .snapshot_registry
                .begin_removal_pass(self.tx_mgr.current_tx_max());
            let registered = active_removal_pass.registered_snapshots();
            // This is a fresh authenticated sample inside the removal boundary,
            // before any catalog-driven removal or resident retirement.
            let mut inventory = self.maintenance_closing_inventory_locked()?;
            if !inventory.complete {
                return Ok(inventory.failures);
            }
            let mut retired = self
                .vector
                .retire_snapshot_free_partition_states(registered, self.accountant.as_ref());
            for route in &inventory.routes {
                retired = retired.saturating_add(
                    self.vector
                        .reclaim_snapshot_free_partition_graph_generations(
                            &route.partition,
                            registered,
                        ),
                );
            }
            if registered.is_empty() || retired != 0 {
                self.reclaim_catalogs_locked(&mut inventory)?;
            }
            Ok(inventory.failures)
        })
    }

    fn reclaim_snapshot_free_vector_graphs(&self) -> Result<MaintenanceMetadataFailures> {
        if !self.vector.has_retired_graph_generations() {
            return Ok(MaintenanceMetadataFailures::default());
        }
        self.tx_mgr.with_commit_lock(|| {
            let active_removal_pass = self
                .snapshot_registry
                .begin_removal_pass(self.tx_mgr.current_tx_max());
            let mut inventory = self.maintenance_closing_inventory_locked()?;
            if !inventory.complete {
                return Ok(inventory.failures);
            }
            let mut reclaimed = 0usize;
            for route in &inventory.routes {
                reclaimed = reclaimed.saturating_add(
                    self.vector
                        .reclaim_snapshot_free_partition_graph_generations(
                            &route.partition,
                            active_removal_pass.registered_snapshots(),
                        ),
                );
            }
            if reclaimed != 0 {
                self.reclaim_catalogs_locked(&mut inventory)?;
            }
            Ok(inventory.failures)
        })
    }

    fn vector_partitions_requiring_build(&self) -> Result<MaintenanceBuildCandidates> {
        self.maintenance_build_candidates()
    }

    fn persist_built_vector_partition(
        &self,
        partition: &VectorPartitionRef,
    ) -> Result<VectorPartitionPublicationOutcome> {
        let Some(persistence) = self.persistence.as_ref() else {
            return Ok(VectorPartitionPublicationOutcome::default());
        };
        loop {
            let layout = self.vector.index_layout(&partition.index)?;
            let live_vectors = self
                .vector
                .partition_info(&partition.index, &partition.partition_key)
                .map(|info| info.live_rows)
                .unwrap_or(0);
            let policy = layout.resolve_policy(live_vectors, 1);
            let topology_replacement = self
                .vector
                .partition_info(&partition.index, &partition.partition_key)
                .is_some_and(|info| {
                    info.graph_available
                        && info.serving_policy.is_none_or(|serving| {
                            serving.hnsw_m != policy.hnsw_m
                                || serving.hnsw_ef_construction != policy.hnsw_ef_construction
                        })
                });
            let partition_state_present = self
                .vector
                .partition_graph_generation_status(partition)
                .is_some();
            // Durable-only routes have no state to own policy/progress marks.
            // Keep their source in persistence until the admitted cold build.
            let _policy_build = partition_state_present
                .then(|| {
                    self.vector
                        .begin_partition_policy_build(partition, policy.policy_revision)
                })
                .transpose()?;
            let quarantined = self.vector.partition_route_quarantine(partition).is_some();
            // Admit route keys, decoded count metadata and bounded catalog
            // clones before inspecting the frontier. This owns no vector body.
            let inventory_bytes = partition
                .partition_key
                .estimated_bytes()
                .saturating_add(partition.index.table.len())
                .saturating_add(partition.index.column.len())
                .saturating_add(1024)
                .saturating_mul(64);
            let mut workspace = self.vector.reserve_workspace(
                self.accountant.clone(),
                inventory_bytes,
                "prepare_vector_generation",
                "Raise MEMORY_LIMIT before inspecting this maintained route.",
            )?;
            // Borrow the fixed catalog suffix for pricing under the admitted
            // metadata workspace; graph owners wait for complete build sizing.
            let current_descriptors = if quarantined {
                None
            } else {
                vector_source_page_admission::with_preparation_source_page_admission(
                    Arc::clone(&self.accountant),
                    || {
                        persistence.load_vector_partition_generation_descriptors_for(
                            &partition.index,
                            &partition.partition_key,
                        )
                    },
                )?
            };
            let publish_change = current_descriptors
                .as_ref()
                .is_some_and(|(_, change)| change.is_none())
                && partition_state_present
                && !topology_replacement;
            let after_lsn = publish_change.then(|| {
                current_descriptors
                    .as_ref()
                    .expect("change publication has a base")
                    .0
                    .covered_lsn
            });
            // Count the raw snapshot and actual graph selection at the same
            // committed frontier, before cloning any unadmitted vector body.
            // The pin protects this history throughout preparation; later
            // commits remain in the journal suffix and mutable tail.
            let (covered_tx, covered_lsn, snapshot_pin, raw_count, graph_count, delete_carriers) =
                vector_source_page_admission::with_preparation_source_page_admission(
                    Arc::clone(&self.accountant),
                    || {
                        self.tx_mgr.with_commit_lock(|| -> Result<_> {
                    let covered_tx = self.tx_mgr.current_tx_max();
                    let covered_lsn = self.tx_mgr.current_lsn();
                    let snapshot = SnapshotId(covered_tx.0);
                    let pin = self.snapshot_registry.register(snapshot);
                    let (raw_count, mut graph_count) = if partition_state_present {
                        self.vector.partition_generation_entry_counts(
                            &partition.index,
                            &partition.partition_key,
                            snapshot,
                            after_lsn,
                        )?
                    } else {
                        persistence.vector_partition_maintenance_entry_counts(
                            partition, covered_tx, after_lsn,
                        )?
                    };
                    let delete_carriers = after_lsn.is_some() && graph_count == 0;
                    if let Some(after_lsn) = after_lsn
                        && delete_carriers
                    {
                        let carriers = persistence
                            .vector_partition_uncovered_tombstone_entry_count(
                                partition,
                                after_lsn,
                                covered_lsn,
                                |identities| {
                                    workspace.resize(
                                        inventory_bytes.saturating_add(identities.saturating_mul(128)),
                                        "prepare_vector_generation",
                                        "Raise MEMORY_LIMIT before counting delete-only graph carriers.",
                                    )
                                },
                            )?;
                        // Preserve the existing delete-only codec carrier rule.
                        graph_count = if carriers == 1 { 2 } else { carriers };
                    }
                    Ok((
                        covered_tx,
                        covered_lsn,
                        pin,
                        raw_count,
                        graph_count,
                        delete_carriers,
                    ))
                    })
                    },
                )?;
            let base_bytes = if publish_change {
                current_descriptors
                    .as_ref()
                    .map_or(0, |(base, _)| base.durable_bytes as usize)
            } else {
                0
            };
            // Ordinary resident builds consume only the pinned live selection.
            // Cold snapshots and delete-only carriers retain their full raw
            // owner and the existing independently funded decoder paths.
            let selected_resident_snapshot = partition_state_present && !delete_carriers;
            let snapshot_count = if selected_resident_snapshot {
                graph_count
            } else {
                raw_count
            };
            let mut workspace_plan = VectorGenerationWorkspacePlan::new(
                snapshot_count,
                graph_count,
                &layout,
                partition,
                policy,
                base_bytes,
            )?;
            workspace_plan.assign_raw_decode_owner(partition_state_present, delete_carriers);
            let encoded_bound = workspace_plan.estimated_generation_bytes();
            self.admit_generation_disk(encoded_bound.saturating_mul(2).saturating_add(64 * 1024))?;
            // Carrier collection retains selected membership metadata while
            // loading its bodies; ordinary graph selections never own it.
            if delete_carriers {
                workspace_plan.carrier_metadata_bytes = graph_count.saturating_mul(
                    partition
                        .partition_key
                        .estimated_bytes()
                        .saturating_add(partition.index.table.len())
                        .saturating_add(partition.index.column.len())
                        .saturating_add(512),
                );
            }
            workspace.resize(
                workspace_plan.build_phase_bytes(),
                "prepare_vector_generation",
                "Raise MEMORY_LIMIT before compacting this maintained route.",
            )?;
            // Catalog clones and quarantine inventory scratch are bounded
            // metadata owners. They cannot preempt the build's early refusal.
            workspace.resize(
                workspace_plan.build_phase_bytes().max(inventory_bytes),
                "prepare_vector_generation",
                "Raise MEMORY_LIMIT before inspecting this maintained route.",
            )?;
            let current = if quarantined {
                None
            } else {
                vector_source_page_admission::with_preparation_source_page_admission(
                    Arc::clone(&self.accountant),
                    || {
                        persistence.load_vector_partition_generation_catalog_for(
                            &partition.index,
                            &partition.partition_key,
                        )
                    },
                )?
            };
            if current
                .as_ref()
                .map(|catalog| (catalog.base, catalog.change))
                != current_descriptors
            {
                // A concurrent durable publication changed the priced chain.
                // Drop this pin and reservation before sampling its successor.
                continue;
            }
            // The pinned directory counts and complete construction admission
            // precede generation/vector-body reads. Metadata extents were
            // admitted separately during preparation. Keep the source guard
            // around quarantine inventory, payload, publication and cleanup.
            let outcome = vector_source_page_admission::with_source_page_admission(
                Arc::clone(&self.accountant),
                || -> Result<Option<VectorPartitionPublicationOutcome>> {
                    let previous_generation = if quarantined {
                        match persistence.load_vector_partition_generation_catalog_for(
                            &partition.index,
                            &partition.partition_key,
                        ) {
                            Ok(Some(catalog)) => catalog
                                .change
                                .map(|change| change.generation_id)
                                .unwrap_or(catalog.base.generation_id)
                                .max(catalog.base.generation_id),
                            Ok(None) | Err(Error::StoreCorrupted { .. }) => {
                                let highest = persistence.highest_vector_partition_generation_id(
                                    &partition.index,
                                    &partition.partition_key,
                                    |record_bytes| {
                                        workspace.resize(
                                            inventory_bytes.saturating_add(record_bytes),
                                            "inspect_vector_generation_inventory",
                                            "Raise MEMORY_LIMIT before inspecting this maintained route.",
                                        )
                                    },
                                )?;
                                // Inspection scratch is dead before construction
                                // begins allocating its payload owners.
                                workspace.resize(
                                    inventory_bytes,
                                    "inspect_vector_generation_inventory",
                                    "Raise MEMORY_LIMIT before inspecting this maintained route.",
                                )?;
                                highest
                            }
                            Err(error) => return Err(error),
                        }
                    } else {
                        current
                            .as_ref()
                            .map(|catalog| {
                                catalog
                                    .change
                                    .map(|change| change.generation_id)
                                    .unwrap_or(catalog.base.generation_id)
                                    .max(catalog.base.generation_id)
                            })
                            .unwrap_or(0)
                    };
                    let generation_id = previous_generation.checked_add(1).ok_or_else(|| {
                        Error::Other(format!(
                            "vector generation identity exhausted for {}.{}",
                            partition.index.table, partition.index.column
                        ))
                    })?;
                    workspace.resize(
                        workspace_plan.build_phase_bytes(),
                        "prepare_vector_generation",
                        "Raise MEMORY_LIMIT before compacting this maintained route.",
                    )?;
                    let quarantine = self.vector.partition_route_quarantine(partition);
                    let phase = if quarantine.is_some() {
                        "repairing"
                    } else if current.is_none() || topology_replacement {
                        "building"
                    } else if publish_change {
                        "replaying"
                    } else {
                        "compacting"
                    };
                    let reason = quarantine.map(|reason| reason.as_str()).unwrap_or_else(|| {
                        if current.is_none() {
                            "initial_build"
                        } else if self
                            .vector
                            .partition_info(&partition.index, &partition.partition_key)
                            .is_some_and(|info| info.tombstones != 0)
                        {
                            "tombstones"
                        } else {
                            "new_changes"
                        }
                    });
                    let progress = partition_state_present
                        .then(|| {
                            self.vector.begin_partition_maintenance_progress(
                                partition,
                                reason,
                                live_vectors,
                                covered_tx,
                                phase,
                            )
                        })
                        .transpose()?;
                    self.build_checkpoint()?;
                    #[cfg(any(test, feature = "test-seams"))]
                    self.vector.maybe_pause_maintenance_preparation_for_test(
                        partition,
                        VectorMaintenancePreparationPhaseForTest::LoadAuthoritativeRawVectors,
                    );

                    if selected_resident_snapshot {
                        let (_, selected_count) = self.tx_mgr.with_commit_lock(|| {
                            self.vector.partition_generation_entry_counts(
                                &partition.index,
                                &partition.partition_key,
                                SnapshotId(covered_tx.0),
                                after_lsn,
                            )
                        })?;
                        if selected_count != graph_count {
                            // Drop the old admission and pin, then price a new
                            // frontier before copying any generation body.
                            return Ok(None);
                        }
                    }
                    let mut entries = if selected_resident_snapshot {
                        self.vector.entries_for_partition_generation_at_snapshot(
                            &partition.index,
                            &partition.partition_key,
                            SnapshotId(covered_tx.0),
                            after_lsn,
                        )?
                    } else if partition_state_present {
                        self.vector.entries_for_partition_at_snapshot(
                            &partition.index,
                            &partition.partition_key,
                            SnapshotId(covered_tx.0),
                        )?
                    } else {
                        persistence.load_vector_partition_entries_at_frontier(
                            partition,
                            covered_tx,
                            layout.dimension,
                            raw_count,
                        )?
                    };
                    entries.retain(|entry| entry.created_tx <= covered_tx);
                    for entry in &mut entries {
                        if entry.deleted_tx.is_some_and(|tx| tx > covered_tx) {
                            entry.deleted_tx = None;
                        }
                    }

                    // Selection was counted at this pinned frontier. Allocate its
                    // slots once so the plan's exact selected-entry owner does not
                    // coexist with geometric old/new Vec allocations.
                    let mut graph_entries = Vec::with_capacity(graph_count);
                    if publish_change {
                        graph_entries.extend(
                            entries
                                .iter()
                                .filter(|entry| {
                                    entry.deleted_tx.is_none()
                                        && current.as_ref().is_none_or(|catalog| {
                                            catalog.change.is_some()
                                                || entry.lsn > catalog.base.covered_lsn
                                        })
                                })
                                .cloned(),
                        );
                        if graph_entries.is_empty() {
                            // HNSW's durable codec cannot decode a graph with fewer
                            // than two points. Tombstoned rows carry the delete-only
                            // frontier while authoritative raw membership still
                            // excludes every carrier from results.
                            let base_covered_lsn = current
                                .as_ref()
                                .expect("change publication has one current base catalog")
                                .base
                                .covered_lsn;
                            let carriers = persistence
                                .load_vector_partition_uncovered_tombstone_entries(
                                    &partition.index,
                                    &partition.partition_key,
                                    base_covered_lsn,
                                    covered_lsn,
                                    layout.dimension,
                                )?;
                            graph_entries.extend(carriers.into_iter().map(|mut entry| {
                                entry.deleted_tx = None;
                                entry
                            }));
                            if graph_entries.len() == 1 {
                                let mut second = graph_entries[0].clone();
                                if let Some(component) = second.vector.first_mut() {
                                    *component = if *component == 0.0 {
                                        f32::EPSILON
                                    } else {
                                        -*component
                                    };
                                }
                                graph_entries.push(second);
                            }
                        }
                    } else {
                        graph_entries.extend(
                            entries
                                .iter()
                                .filter(|entry| entry.deleted_tx.is_none())
                                .cloned(),
                        );
                    }
                    let progress = if partition_state_present && graph_entries.len() != live_vectors
                    {
                        drop(progress);
                        Some(self.vector.begin_partition_maintenance_progress(
                            partition,
                            reason,
                            graph_entries.len(),
                            covered_tx,
                            phase,
                        )?)
                    } else {
                        progress
                    };
                    let graph = HnswIndex::from_vector_entries_with_progress(
                        &graph_entries,
                        layout.dimension,
                        layout.quantization,
                        policy,
                        |done| {
                            self.build_checkpoint()?;
                            if let Some(progress) = &progress {
                                progress.advance(done);
                            }
                            self.build_checkpoint()
                        },
                    )?;
                    self.build_checkpoint()?;
                    // The builder owns its point values now; its input is not needed
                    // while the durable envelope is allocated.
                    drop(graph_entries);
                    #[cfg(any(test, feature = "test-seams"))]
                    self.vector.maybe_pause_maintenance_preparation_for_test(
                        partition,
                        VectorMaintenancePreparationPhaseForTest::AdmitEncoding,
                    );
                    workspace.resize(
                workspace_plan.encoding_phase_bytes(graph.estimated_resident_bytes()),
                "prepare_vector_generation",
                "Raise MEMORY_LIMIT with SET MEMORY_LIMIT <SIZE> (or reopen with --memory-limit <SIZE>) before compacting this maintained route.",
            )?;
                    #[cfg(any(test, feature = "test-seams"))]
                    self.vector.maybe_pause_maintenance_preparation_for_test(
                        partition,
                        VectorMaintenancePreparationPhaseForTest::EncodeGraph,
                    );
                    let encoded_graph = graph.encode_durable_generation()?;
                    let resident_bytes =
                        u64::try_from(graph.estimated_resident_bytes()).map_err(|_| {
                            Error::Other(
                                "vector generation residency exceeds the durable range".to_string(),
                            )
                        })?;
                    let durable_bytes = u64::try_from(encoded_graph.len()).map_err(|_| {
                        Error::Other("vector generation bytes exceed the durable range".to_string())
                    })?;
                    let encoded_graph_capacity = encoded_graph.capacity();
                    let descriptor = VectorPartitionGenerationDescriptor {
                        generation_id,
                        covered_tx,
                        covered_lsn,
                        resident_bytes,
                        durable_bytes,
                        policy_revision: policy.policy_revision,
                        hnsw_m: u32::try_from(policy.hnsw_m).map_err(|_| {
                            Error::Other("resolved HNSW M exceeds the durable range".to_string())
                        })?,
                        hnsw_ef_construction: u32::try_from(policy.hnsw_ef_construction).map_err(
                            |_| {
                                Error::Other(
                                    "resolved HNSW EF_CONSTRUCTION exceeds the durable range"
                                        .to_string(),
                                )
                            },
                        )?,
                    };
                    drop(graph);
                    #[cfg(any(test, feature = "test-seams"))]
                    self.vector.maybe_pause_maintenance_preparation_for_test(
                        partition,
                        VectorMaintenancePreparationPhaseForTest::AdmitCandidate,
                    );
                    workspace.resize(
                workspace_plan.persistence_phase_bytes(encoded_graph_capacity),
                "prepare_vector_generation",
                "Raise MEMORY_LIMIT with SET MEMORY_LIMIT <SIZE> (or reopen with --memory-limit <SIZE>) before compacting this maintained route.",
            )?;
                    #[cfg(any(test, feature = "test-seams"))]
                    self.vector.maybe_pause_maintenance_preparation_for_test(
                        partition,
                        VectorMaintenancePreparationPhaseForTest::CandidateAdmitted,
                    );
                    self.build_checkpoint()?;
                    let candidate = if publish_change {
                        let catalog = current
                            .as_ref()
                            .expect("change publication has one current base catalog");
                        let base = persistence
                            .load_vector_partition_base_generation_with_expected_graph_bytes(
                                &partition.index,
                                &partition.partition_key,
                                catalog.base.generation_id,
                                catalog.base.durable_bytes,
                            )?;
                        let change = VectorPartitionChangeGenerationRecord {
                            index: partition.index.clone(),
                            partition_key: partition.partition_key.clone(),
                            base_generation_id: catalog.base.generation_id,
                            change_generation_id: generation_id,
                            covered_through_tx: covered_tx,
                            covered_through_lsn: covered_lsn,
                            fresh_tail_from_tx: covered_tx,
                            fresh_tail_from_lsn: covered_lsn,
                            dimension: u32::try_from(layout.dimension).map_err(|_| {
                                Error::Other(
                                    "vector dimension exceeds the durable generation range"
                                        .to_string(),
                                )
                            })?,
                            quantization: layout.quantization,
                            algorithm_version: VECTOR_GRAPH_ALGORITHM_VERSION,
                            graph_format_version: VECTOR_GRAPH_FORMAT_VERSION,
                            graph: VectorPartitionGraphBytes::verified(encoded_graph),
                        };
                        VectorPartitionGenerationCandidate {
                            base,
                            change: Some(change),
                            catalog: VectorPartitionGenerationCatalogRecord {
                                index: partition.index.clone(),
                                partition_key: partition.partition_key.clone(),
                                base: catalog.base,
                                change: Some(descriptor),
                                published_tx: covered_tx,
                                published_lsn: covered_lsn,
                            },
                        }
                    } else {
                        let mut live_entries = entries
                            .iter()
                            .filter(|entry| entry.deleted_tx.is_none())
                            .collect::<Vec<_>>();
                        live_entries
                            .sort_by_key(|entry| (entry.row_id, entry.created_tx, entry.lsn));
                        #[cfg(any(test, feature = "test-seams"))]
                        self.vector.maybe_pause_maintenance_preparation_for_test(
                            partition,
                            VectorMaintenancePreparationPhaseForTest::HashStateDigest,
                        );
                        // Stream the identical bincode sequence directly into the
                        // digest; no vector-sized serialization buffer coexists.
                        let mut state_hasher = blake3::Hasher::new();
                        bincode::serde::encode_into_std_write(
                            &live_entries,
                            &mut state_hasher,
                            bincode::config::standard(),
                        )
                        .map_err(|error| {
                            Error::Other(format!(
                                "could not encode vector generation state digest: {error}"
                            ))
                        })?;
                        let base = VectorPartitionBaseGenerationRecord {
                            index: partition.index.clone(),
                            partition_key: partition.partition_key.clone(),
                            generation_id,
                            base_tx: covered_tx,
                            base_lsn: covered_lsn,
                            highest_included_tx: covered_tx,
                            highest_included_lsn: covered_lsn,
                            dimension: u32::try_from(layout.dimension).map_err(|_| {
                                Error::Other(
                                    "vector dimension exceeds the durable generation range"
                                        .to_string(),
                                )
                            })?,
                            quantization: layout.quantization,
                            algorithm_version: VECTOR_GRAPH_ALGORITHM_VERSION,
                            graph_format_version: VECTOR_GRAPH_FORMAT_VERSION,
                            graph: VectorPartitionGraphBytes::verified(encoded_graph),
                            state_digest: *state_hasher.finalize().as_bytes(),
                        };
                        VectorPartitionGenerationCandidate {
                            base,
                            change: None,
                            catalog: VectorPartitionGenerationCatalogRecord {
                                index: partition.index.clone(),
                                partition_key: partition.partition_key.clone(),
                                base: descriptor,
                                change: None,
                                published_tx: covered_tx,
                                published_lsn: covered_lsn,
                            },
                        }
                    };
                    #[cfg(any(test, feature = "test-seams"))]
                    self.vector.maybe_pause_maintenance_preparation_for_test(
                        partition,
                        VectorMaintenancePreparationPhaseForTest::PrepareDurableGeneration,
                    );
                    drop(entries);
                    drop(snapshot_pin);
                    #[cfg(any(test, feature = "test-seams"))]
                    self.vector.maybe_pause_maintenance_preparation_for_test(
                        partition,
                        VectorMaintenancePreparationPhaseForTest::AdmitPersistence,
                    );
                    let persistence_owned = workspace_plan.prepared_candidate_phase_bytes(
                        encoded_graph_capacity,
                        RedbPersistence::vector_candidate_streamed_frame_bytes(&candidate)?,
                    );
                    workspace.resize(
                persistence_owned,
                "prepare_vector_generation",
                "Raise MEMORY_LIMIT with SET MEMORY_LIMIT <SIZE> (or reopen with --memory-limit <SIZE>) before compacting this maintained route.",
            )?;
                    #[cfg(any(test, feature = "test-seams"))]
                    self.vector.maybe_pause_maintenance_preparation_for_test(
                        partition,
                        VectorMaintenancePreparationPhaseForTest::PersistenceAdmitted,
                    );
                    self.build_checkpoint()?;
                    let prepared = persistence
                        .prepare_vector_partition_generation_candidate_with_admission(
                            &candidate,
                            |scan_bytes| {
                                workspace.resize(
                            persistence_owned.saturating_add(scan_bytes),
                            "prepare_vector_generation",
                            "Raise MEMORY_LIMIT before preparing generation catalog metadata.",
                        )
                            },
                        )?;
                    let prepared_workspace_bytes =
                        persistence_owned.saturating_add(prepared.stale_metadata_bytes());
                    workspace.resize(
                        prepared_workspace_bytes,
                        "prepare_vector_generation",
                        "Raise MEMORY_LIMIT before publishing this maintained route.",
                    )?;
                    self.admit_generation_disk(prepared.write_reservation_bytes())?;

                    #[cfg(any(test, feature = "test-seams"))]
                    self.vector.maybe_pause_memory_workspace_for_test();
                    #[cfg(any(test, feature = "test-seams"))]
                    if take_vector_memory_fault(
                        &VECTOR_DURABLE_COMPACTION_FAILURE_ARMED,
                        &VECTOR_DURABLE_COMPACTION_FAILURE_CONSUMED,
                    ) {
                        return Err(Error::Other(
                            "injected vector compaction prepublication failure".to_string(),
                        ));
                    }

                    let published = self.tx_mgr.with_commit_lock(|| {
                self.vector.with_partition_generation_publication(
                    partition,
                    || -> contextdb_core::Result<bool> {
                        let current_layout = self.vector.index_layout(&partition.index)?;
                        if current_layout.policy_revision != layout.policy_revision
                            || current_layout.hnsw_m != layout.hnsw_m
                            || current_layout.hnsw_ef_construction != layout.hnsw_ef_construction
                        {
                            return Ok(false);
                        }
                        let durable_generation = if quarantined {
                            match persistence.load_vector_partition_generation_catalog_for(
                                &partition.index,
                                &partition.partition_key,
                            ) {
                                Ok(Some(catalog)) => catalog
                                    .change
                                    .map(|change| change.generation_id)
                                    .unwrap_or(catalog.base.generation_id)
                                    .max(catalog.base.generation_id),
                                Ok(None) | Err(Error::StoreCorrupted { .. }) => {
                                    let mut inventory = self.vector.reserve_workspace(
                                        self.accountant.clone(),
                                        0,
                                        "inspect_vector_generation_inventory",
                                        "Raise MEMORY_LIMIT before inspecting this maintained route.",
                                    )?;
                                    persistence.highest_vector_partition_generation_id(
                                        &partition.index,
                                        &partition.partition_key,
                                        |scratch_bytes| inventory.resize(
                                            scratch_bytes,
                                            "inspect_vector_generation_inventory",
                                            "Raise MEMORY_LIMIT before inspecting this maintained route.",
                                        ),
                                    )?
                                },
                                Err(error) => return Err(error),
                            }
                        } else {
                            persistence
                                .load_vector_partition_generation_catalog_for(
                                    &partition.index,
                                    &partition.partition_key,
                                )?
                                .as_ref()
                                .map(|catalog| {
                                    catalog
                                        .change
                                        .map(|change| change.generation_id)
                                        .unwrap_or(catalog.base.generation_id)
                                        .max(catalog.base.generation_id)
                                })
                                .unwrap_or(0)
                        };
                        if durable_generation != previous_generation {
                            return Ok(false);
                        }
                        self.admit_generation_disk(prepared.write_reservation_bytes())?;
                        persistence
                            .publish_prepared_vector_partition_generation_candidate(&prepared)?;
                        #[cfg(feature = "test-seams")]
                        if partition_state_present {
                            self.vector.observe_durable_base_publication(
                                partition,
                                candidate.catalog.base.generation_id,
                                candidate.catalog.base.covered_tx,
                            )?;
                        }
                        Ok(true)
                    },
                )
            })?;
                    if !published {
                        let current_layout = self.vector.index_layout(&partition.index)?;
                        if current_layout.policy_revision != layout.policy_revision
                            || current_layout.hnsw_m != layout.hnsw_m
                            || current_layout.hnsw_ef_construction != layout.hnsw_ef_construction
                        {
                            // A topology declaration made this candidate stale. One
                            // maintenance cycle owns one sampled revision; the next
                            // cycle builds the replacement the newer declaration asks
                            // for while the old complete graph keeps serving.
                            return Ok(Some(VectorPartitionPublicationOutcome::default()));
                        }
                        return Ok(None);
                    }
                    #[cfg(any(test, feature = "test-seams"))]
            if self.vector.take_journal_truncation_fault_for_test(
                partition,
                VectorJournalTruncationPhaseForTest::CatalogDurableBeforeCoveredJournalDelete,
            ) {
                let error = Error::Other(
                    "vector journal truncation crash injected after durable catalog T1".to_string(),
                );
                return self.retain_published_vector_cleanup_failure(partition, &error).map(Some);
            }

                    let (published_catalog, cleanup_complete) = if quarantined {
                        let cleanup = self.tx_mgr.with_commit_lock(|| -> Result<_> {
                    let persistence_phase_owned = prepared_workspace_bytes;
                    // Count, admit, and capture the registered snapshot sample
                    // under the registry's one atomic registration/removal
                    // lock. During Vec-to-Arc conversion both allocations are
                    // charged before either is constructed.
                    let (active_removal_pass, snapshot_guard_owned) = self
                        .snapshot_registry
                        .begin_removal_pass_with_sample_admission(
                            self.tx_mgr.current_tx_max(),
                            |sample_transition_bound| {
                                workspace.resize(
                                    persistence_phase_owned
                                        .saturating_add(sample_transition_bound),
                                    "finalize_repaired_vector_partition",
                                    "Raise MEMORY_LIMIT with SET MEMORY_LIMIT <SIZE> (or reopen with --memory-limit <SIZE>) before repairing this maintained route.",
                                )
                            },
                        )?;
                    let snapshot_count = active_removal_pass.registered_snapshots().len();
                    // `snapshot_retained_partition_chain_ids` temporarily
                    // builds a HashSet and returns a Vec with at most one
                    // chain per sampled snapshot. Grow before that allocation;
                    // the finalizer replaces this conservative capture bound
                    // with reported surviving capacities.
                    let repair_capture_bound = snapshot_count
                        .saturating_mul(
                            std::mem::size_of::<(u64, Option<u64>)>()
                                .saturating_mul(4)
                                .saturating_add(std::mem::size_of::<SnapshotId>()),
                        )
                        .saturating_add(snapshot_guard_owned)
                        .saturating_add(4096);
                    workspace.resize(
                        persistence_phase_owned.saturating_add(repair_capture_bound),
                        "finalize_repaired_vector_partition",
                        "Raise MEMORY_LIMIT with SET MEMORY_LIMIT <SIZE> (or reopen with --memory-limit <SIZE>) before repairing this maintained route.",
                    )?;
                    let retained_chains = self.vector.snapshot_retained_partition_chain_ids(
                        partition,
                        active_removal_pass.registered_snapshots(),
                    );
                    let repair_context_owned = retained_chains
                        .capacity()
                        .saturating_mul(std::mem::size_of::<(u64, Option<u64>)>())
                        .saturating_add(snapshot_guard_owned);

                    // Publication owns durable copies now. Repair needs only
                    // the catalog, not two more encoded graph buffers. The
                    // finalizer immediately replaces this persistence-phase
                    // reservation with its admitted cleanup ownership.
                    let VectorPartitionGenerationCandidate {
                        base,
                        change,
                        catalog: published_catalog,
                    } = candidate;
                    drop(base);
                    drop(change);
                    drop(prepared);
                    let (finalized, catalog_owned) =
                        persistence.finalize_repaired_vector_partition(
                            &published_catalog,
                            &retained_chains,
                            repair_context_owned,
                            &mut workspace,
                        )?;
                    drop(active_removal_pass);
                    drop(retained_chains);
                    workspace.resize(
                        catalog_owned,
                        "finalize_repaired_vector_partition",
                        "Raise MEMORY_LIMIT with SET MEMORY_LIMIT <SIZE> (or reopen with --memory-limit <SIZE>) before repairing this maintained route.",
                    )?;
                    Ok((published_catalog, finalized))
                });
                        match cleanup {
                            Ok(cleanup) => cleanup,
                            Err(error @ (Error::ReadCancelled | Error::PublicationInterrupted)) => {
                                return Err(error);
                            }
                            Err(error) => {
                                return self
                                    .retain_published_vector_cleanup_failure(partition, &error)
                                    .map(Some);
                            }
                        }
                    } else {
                        // Normal T2 likewise needs only the surviving catalog. Its
                        // first action replaces the graph-buffer reservation before
                        // allocating cleanup keys or decoded validation records.
                        let VectorPartitionGenerationCandidate {
                            base,
                            change,
                            catalog: published_catalog,
                        } = candidate;
                        drop(base);
                        drop(change);
                        drop(prepared);
                        #[cfg(test)]
                        vector_journal_cleanup_cancellation_tests::before_published_cleanup_for_test(
                            &published_catalog,
                        );
                        let truncated = match persistence
                            .truncate_vector_partition_journal_through_catalog_with_checkpoint(
                                &published_catalog,
                                &mut workspace,
                                || self.build_checkpoint(),
                            ) {
                            Ok(truncated) => truncated,
                            Err(error @ (Error::ReadCancelled | Error::PublicationInterrupted)) => {
                                return Err(error);
                            }
                            Err(error) => {
                                return self
                                    .retain_published_vector_cleanup_failure(partition, &error)
                                    .map(Some);
                            }
                        };
                        (published_catalog, truncated)
                    };
                    if !cleanup_complete {
                        if quarantined {
                            drop(published_catalog);
                            drop(workspace);
                            return Ok(Some(VectorPartitionPublicationOutcome::published()));
                        }
                        drop(published_catalog);
                        drop(workspace);
                        let cleanup_retry = self.retry_vector_journal_truncations()?;
                        return Ok(Some(VectorPartitionPublicationOutcome {
                            published: true,
                            cleanup_failure: cleanup_retry.first_failure_details,
                        }));
                    }
                    if partition_state_present {
                        #[cfg(test)]
                        published_vector_install_tests::maybe_pause_before_install(
                            &self.accountant,
                        );
                        match self.install_published_vector_catalog(&published_catalog) {
                            Ok(()) => {}
                            Err(
                                error @ (Error::MemoryBudgetExceeded { .. }
                                | Error::DiskBudgetExceeded { .. }),
                            ) => {
                                // T1 is authoritative even when T2 has already removed
                                // the covered journal. Keep the old serving chain and
                                // report this publication; catalog retry installs it
                                // once the refused resource becomes available.
                                return self
                                    .retain_published_vector_cleanup_failure(partition, &error)
                                    .map(Some);
                            }
                            Err(error) => return Err(error),
                        }
                    }
                    drop(published_catalog);
                    drop(workspace);
                    Ok(Some(VectorPartitionPublicationOutcome::published()))
                },
            )?;
            if let Some(outcome) = outcome {
                return Ok(outcome);
            }
        }
    }

    fn run_cycle(&self, gate: CurrencyGate) -> Result<MaintenanceReport> {
        // Release obsolete graphs before another partition allocates its
        // replacement. Pending route/journal work still forbids retiring the
        // route itself; the snapshot guard independently protects old graphs.
        let mut cycle_failures = self.reclaim_snapshot_free_vector_graphs()?;
        // Idempotent T2 retry never clears or rebuilds a healthy route. Newer
        // journal suffix records remain outside each catalog's covered LSN. A
        // local retry refusal is retained in the report while the rest of the
        // fixed cycle continues.
        let VectorJournalCleanupRetryOutcome {
            first_failure_details: cleanup_retry_failure,
            failed_partitions: cleanup_retry_failed_partitions,
        } = self.retry_vector_journal_truncations()?;
        let pruning = self.run_pruning()?;
        let pruned_trigger_audit_rows = self.run_trigger_audit_retention()?;
        let currency = self.run_currency(gate)?;
        let candidate_sample = self
            .persistence
            .as_ref()
            .map(|_| self.vector_partitions_requiring_build())
            .transpose()?;
        if let Some(sample) = candidate_sample.as_ref() {
            cycle_failures.first = cycle_failures.first.or(sample.failures.first);
        }
        let pending_vector_partitions = candidate_sample
            .as_ref()
            .map(|sample| sample.candidates.as_slice())
            .unwrap_or(&[]);
        let mut vector = if !pending_vector_partitions.is_empty() {
            // File-backed construction publishes through the durable catalog
            // first. Building a separate process-only graph here let the
            // writer call the route ready while a reader of the same
            // committed store still saw `initial_build`.
            let mut built_partitions = 0usize;
            let mut built_indexes = HashSet::new();
            let mut first_failure_details = cleanup_retry_failure.or(cycle_failures.first);
            for candidate in pending_vector_partitions {
                let partition = &candidate.partition;
                if cleanup_retry_failed_partitions.contains(partition) {
                    continue;
                }
                let outcome = match self.persist_built_vector_partition(partition) {
                    Ok(outcome) => outcome,
                    Err(error @ (Error::ReadCancelled | Error::PublicationInterrupted)) => {
                        return Err(error);
                    }
                    Err(error) => {
                        self.vector
                            .record_partition_maintenance_error(partition, &error)?;
                        first_failure_details.get_or_insert_with(|| {
                            VectorMaintenanceFailureDetails::from_error(&error)
                        });
                        continue;
                    }
                };
                if let Some(failure) = outcome.cleanup_failure {
                    first_failure_details.get_or_insert(failure);
                }
                // A repair can make its replacement catalog durable while the
                // worker is being stopped. Keep that publication authoritative,
                // but observe the stop before counting success or beginning any
                // later reclamation, retirement, compaction, or cycle stamping.
                self.build_checkpoint()?;
                if !outcome.published {
                    continue;
                }
                built_partitions = built_partitions.saturating_add(1);
                built_indexes.insert(partition.index.clone());
                first_failure_details =
                    first_failure_details.or(self.reclaim_snapshot_free_vector_graphs()?.first);
            }
            let mut report = self.vector.hnsw_maintenance_status();
            report.built_partitions = built_partitions;
            report.built_indexes = built_indexes.len();
            report.first_failure = first_failure_details.map(|details| details.failure);
            report.first_failure_details = first_failure_details;
            report
        } else if self.persistence.is_some() {
            let mut report = self.vector.hnsw_maintenance_status();
            let first_failure_details = cleanup_retry_failure
                .or(cycle_failures.first)
                .or(report.first_failure_details);
            report.first_failure = first_failure_details.map(|details| details.failure);
            report.first_failure_details = first_failure_details;
            report
        } else {
            self.vector
                .run_hnsw_maintenance_cycle_with(self.accountant.clone(), &mut || {
                    self.build_checkpoint()
                })?
        };
        // A replacement first publishes the prior graph as a retired snapshot
        // chain. Reclaim only after publication, under the registry's removal
        // guard, so active readers keep that route and unselected generations
        // do not linger until another maintenance wake.
        cycle_failures.first = cycle_failures
            .first
            .or(self.reclaim_snapshot_free_vector_graphs()?.first);
        // Retirement is independent of whether another partition had work,
        // but follows this wake's durable generation publications. That lets
        // a delete-only route first represent and truncate its final journal
        // prefix, then releases it even while a sibling keeps producing work.
        cycle_failures.first = cycle_failures
            .first
            .or(self.retire_snapshot_free_vector_partitions()?.first);
        vector.first_failure_details = vector.first_failure_details.or(cycle_failures.first);
        vector.first_failure = vector.first_failure_details.map(|details| details.failure);
        // The rare, interval-gated automatic compaction path -- see
        // `maybe_auto_compact`'s own doc comment. Runs LAST, after every
        // scoped pass this cycle already did its own work, and (like every
        // compact call) outside any commit lock.
        let compaction = match self.maybe_auto_compact() {
            Ok(report) => report,
            Err(Error::MemoryBudgetExceeded { .. } | Error::DiskBudgetExceeded { .. })
                if vector.first_failure.is_some() =>
            {
                // The cycle already exposes the first partition-local
                // resource refusal. An opportunistic closing compaction uses
                // the same exhausted limit; attempting it must not erase the
                // successful vector counts or prevent the closing stamp.
                CompactionReport::default()
            }
            Err(error) => return Err(error),
        };
        // Recorded whether this cycle reclaimed anything or not -- a caller
        // that dutifully drives an empty cycle is still driving, and must
        // never trip the caller-driven backlog warning.
        *self.last_maintenance_cycle_at.lock() = Some(std::time::Instant::now());
        Ok(MaintenanceReport {
            pruning,
            currency,
            vector,
            pruned_trigger_audit_rows,
            compaction,
        })
    }
}

/// Observability: an operator must be able to see maintenance happen. Silent
/// when a tick reclaimed nothing.
fn log_maintenance_cycle(report: &MaintenanceReport) {
    if report.pruning.pruned_rows == 0
        && report.currency.pruned_versions == 0
        && report.pruned_trigger_audit_rows == 0
        && report.pruning.future_dated_rows == 0
        && report.vector.built_indexes == 0
        && report.vector.built_partitions == 0
        && report.vector.first_failure.is_none()
        && !report.compaction.ran
    {
        return;
    }
    eprintln!(
        "maintenance_cycle pruned_rows={} reclaimed_bytes={} compacted={} file_shrank={} \
         future_dated_rows={} future_dated_tables={} trigger_audit_rows={} \
         currency_versions={} currency_redb_compacted={} auto_compact_ran={} \
         auto_compact_micros={} vector_nonempty_indexes={} vector_ready_indexes={} \
         vector_built_indexes={} vector_remaining_indexes={} \
         vector_nonempty_partitions={} vector_ready_partitions={} \
         vector_built_partitions={} vector_remaining_partitions={} vector_first_failure={}",
        report.pruning.pruned_rows,
        report.pruning.reclaimed_bytes,
        report.pruning.compacted,
        report.pruning.file_shrank,
        report.pruning.future_dated_rows,
        report.pruning.future_dated_tables.join(","),
        report.pruned_trigger_audit_rows,
        report.currency.pruned_versions,
        report.currency.redb_compacted,
        report.compaction.ran,
        report.compaction.duration_micros,
        report.vector.nonempty_indexes,
        report.vector.ready_indexes,
        report.vector.built_indexes,
        report.vector.remaining_indexes,
        report.vector.nonempty_partitions,
        report.vector.ready_partitions,
        report.vector.built_partitions,
        report.vector.remaining_partitions,
        report
            .vector
            .first_failure
            .map_or("none", VectorMaintenanceFailure::reason),
    );
}

/// Database-metadata key holding the ONE hub a retained table is delivered to.
pub(crate) const RETENTION_SYNC_PEER_CONFIG_KEY: &str = "retention_sync_peer";
const DESTINATION_REUPLOAD_TARGET_CONFIG_NAME: &str = "sync_destination_reupload_target";

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DestinationReuploadEpoch {
    /// Fresh identity for this explicit move. The hub name and held LSN can
    /// repeat (H -> X -> H with no local writes), so neither is an epoch
    /// identity that a delayed completion may safely retire.
    #[serde(default = "uuid::Uuid::nil")]
    epoch_id: uuid::Uuid,
    hub_node_id: String,
    held_through_lsn: Lsn,
    /// Retained only to decode epochs written before receiver-local DDL
    /// arrival evidence existed. Destination filtering now uses that evidence
    /// and the held frontier, rather than treating this snapshot as policy.
    #[serde(default)]
    held_ddl: Vec<(Lsn, Vec<u8>)>,
}

thread_local! {
    /// Test-only injection seam: when armed, the NEXT
    /// [`Database::change_retention_sync_peer`] on this thread fails at the point
    /// after the confirmation record is cleared, so a test can assert the
    /// operation lands on the SAFE side of a mid-operation I/O failure. Armed
    /// only by `__arm_retention_peer_persist_fault_for_test`; default off, so the
    /// production path reads a thread-local that is never set — production-dead,
    /// following the existing `__inject_*_for_test` precedent.
    static RETENTION_PEER_PERSIST_FAULT: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };

    /// Test-only injection seam, same shape as
    /// [`RETENTION_PEER_PERSIST_FAULT`]: when armed, the NEXT version-cleanup
    /// pass on this thread fails immediately before durable removal and before
    /// memory publication, so a test can assert that a failed cycle retains
    /// the complete removal set for retry. Armed only by
    /// `Database::__arm_currency_compaction_persist_fault_for_test`; default
    /// off, so production reads a thread-local that is never set.
    static CURRENCY_COMPACTION_PERSIST_FAULT: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };

    /// Test-only race seam: when armed, `execute`/`execute_in_tx` close
    /// their own database synchronously in the gap between the
    /// `already_closed` pre-check and the fallible snapshot registration
    /// just after it -- deterministically simulating a close that lands in
    /// that exact window, on the SAME thread, no real concurrency needed.
    /// Lets a test prove the registration's own fallible form catches a
    /// close in this window instead of panicking, without depending on a
    /// second thread ever winning a real race. Armed only by
    /// `Database::__arm_close_in_snapshot_registration_race_window_for_test`;
    /// default off.
    static CLOSE_IN_SNAPSHOT_REGISTRATION_RACE_WINDOW: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };

    /// Test-only, THREAD-LOCAL pause selector: when set on the calling
    /// thread, that thread's NEXT sync-apply pre-commit checkpoint
    /// (`sync_apply_pre_commit_pause`) actually pauses; a thread that never
    /// sets this reads `false` and passes the SAME checkpoint unconditionally
    /// -- even while the shared `ApplyPhasePause` is globally armed. This is
    /// what lets a test pause exactly one concurrent sync apply while a
    /// second, independent apply on another thread commits normally, proving
    /// an ordering race deterministically. Armed only by
    /// `Database::mark_this_thread_for_sync_apply_pre_commit_pause_for_test`,
    /// consumed (reset to `false`) the moment the checkpoint reads it;
    /// default off, so production reads a thread-local that is never set.
    static SYNC_APPLY_PRE_COMMIT_PAUSE_ARMED_HERE: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    #[cfg(test)]
    static QUERY_TRACE_ROWS_EXAMINED_CAPTURE_PAUSE_ARMED_HERE: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

/// Consume the armed currency-compaction injection flag, if any. Reads a
/// thread-local that is never set outside a test, so the production path
/// takes the `false` arm.
fn take_currency_compaction_persist_fault_for_test() -> bool {
    CURRENCY_COMPACTION_PERSIST_FAULT.with(|f| f.replace(false))
}

/// Consume the armed snapshot-registration race-window seam, if any. Reads
/// a thread-local that is never set outside a test, so the production path
/// takes the `false` arm.
fn take_close_in_snapshot_registration_race_window_for_test() -> bool {
    CLOSE_IN_SNAPSHOT_REGISTRATION_RACE_WINDOW.with(|f| f.replace(false))
}

/// Consume the armed thread-local sync-apply pre-commit pause selector, if
/// any. Reads a thread-local that is never set outside a test, so the
/// production path takes the `false` arm on every thread.
fn take_sync_apply_pre_commit_pause_armed_here_for_test() -> bool {
    SYNC_APPLY_PRE_COMMIT_PAUSE_ARMED_HERE.with(|f| f.replace(false))
}

#[cfg(test)]
fn maybe_pause_before_query_trace_rows_examined_capture_for_test() {
    if QUERY_TRACE_ROWS_EXAMINED_CAPTURE_PAUSE_ARMED_HERE.with(|flag| flag.replace(false)) {
        query_trace_rows_examined_capture_pause_for_test().maybe_pause();
    }
}

// Version-cleanup eligibility is DECLARED per table (`HISTORY CURRENT ONLY`),
// not a hardcoded table-name list -- see `Database::version_cleanup_eligible_
// tables`/`has_version_cleanup_tables`. High-churn tables rewritten every poll
// cadence via `INSERT … ON CONFLICT DO UPDATE` mint a new MVCC version and
// tombstone the prior one on every write, and nothing reclaims the superseded
// versions of a table that declares nothing, so a long-running fleet node can
// accumulate hundreds of thousands of physical versions for a handful of live
// rows (observed: 248,996 `work_capabilities` versions in a 365MB debris
// ledger for ~10 live rows). Version cleanup (`Database::compact_currency_
// versions`) collapses each logical row of a DECLARED table back to its
// single current version. The three built-in currency tables (`work_
// capabilities`, `peer_directory`, `work_node_contacts`) declare `HISTORY
// CURRENT ONLY` in their own `CREATE TABLE` text now, alongside the `SYNC
// CONFLICT KEEP LATEST` (or `SYNC OFF`) that made reclaiming their history
// safe in the first place — see the sync-safety argument on
// `compact_currency_versions`.

/// Reclaim freed pages with a full redb `compact()` after a version-compaction
/// pass once at least this fraction of the file is dead space. A first pass over
/// an accumulated debris ledger frees most of the file and trips this; steady
/// state stays well below it (freed pages are reused in place), so compaction is
/// rare, not per-cycle.
pub const REDB_COMPACT_FRAGMENTATION_THRESHOLD: f64 = 0.5;

/// Everything one storage-compaction call produced: how long its work took, the file's size before and after, whether it
/// actually shrank, and the fragmentation ratio that led to it. `ran=false`
/// (every other field at its zero value) means nothing happened this call —
/// either there is no file to compact (an in-memory database) or, for the
/// gated automatic path (see [`AUTO_COMPACT_MIN_INTERVAL`]), the threshold
/// and the minimum interval were not both satisfied and no sweep was active.
///
/// Explicit compaction drains the whole file. Automatic compaction advances
/// bounded durable batches and releases foreground access between them. Both
/// remain separate from the scoped cleanup passes ([`CurrencyCompactionReport`],
/// [`PruningReport`]) that free the pages they reclaim.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct CompactionReport {
    pub ran: bool,
    pub duration_micros: u64,
    pub bytes_before: Option<u64>,
    pub bytes_after: Option<u64>,
    pub file_shrank: bool,
    pub fragmentation_before: f64,
    /// Whether the redb handle was closed and reopened as part of this
    /// compaction — see `RedbPersistence::compact`'s doc comment for why
    /// this is bundled into every compaction rather than left optional: a
    /// file-level compact alone does not release the in-process
    /// allocator/region bookkeeping redb retains from a database's
    /// historical peak size, so it does not by itself restore steady-state
    /// write cost, only file size. Automatic batches keep the handle until
    /// their sweep completes; intermediate batches therefore report `false`.
    pub handle_recycled: bool,
    /// The recycle's own duration in microseconds, reported separately from
    /// `duration_micros` (which covers the whole compaction, recycle
    /// included) — the same convention this bench and the maintenance
    /// receipts already use for every compaction-adjacent cost.
    pub handle_recycle_micros: u64,
}

/// Minimum time between AUTOMATIC redb compactions the engine-owned
/// maintenance tick can trigger on its own. Currency-table version cleanup
/// (`compact_currency_versions`/`Database::run_maintenance_cycle`) NEVER
/// triggers `persistence.compact()` itself — a scoped, O(pruned) cleanup
/// pass and an O(whole-file) compaction are different-shaped costs, and
/// coupling them made steady-state churn on a small file (where routine
/// superseded-version debris is a large fraction of a small file, so the
/// SAME conservative [`REDB_COMPACT_FRAGMENTATION_THRESHOLD`] crosses on
/// every cycle) retrigger a full-file rewrite every tick — the exact
/// per-cycle-compaction cost the version-cleanup scaling bench measures and
/// bounds separately from the scoped pass's own cost. An operator who wants
/// compaction NOW has [`Database::compact_now`] (`.maintenance compact`),
/// which has no interval gate at all; this constant only throttles the
/// engine's OWN unattended background attempt.
pub const AUTO_COMPACT_MIN_INTERVAL: Duration = Duration::from_secs(60 * 60);

/// A worker whose clock runs ahead of the holder's stamps its rows in the
/// future. Drift within this much is ordinary fleet skew: the row ages
/// normally and is never reported. Beyond it the stamp is an operator event —
/// the row is never deleted early, and every maintenance cycle counts it and
/// names its table until the clocks agree again.
pub const RETENTION_CLOCK_SKEW_TOLERANCE: Duration = Duration::from_secs(5 * 60);

/// The shipped default retention for the engine's OWN durable trigger-audit
/// history, applied with zero consumer configuration. Generous enough that a
/// real operator still has a week of firing history to read, bounded enough
/// that a trigger-heavy node cannot grow the table without limit. Audit rows
/// orphaned by a DROP TABLE age out on the same window.
pub(crate) const TRIGGER_AUDIT_RETENTION: Duration = Duration::from_secs(7 * 24 * 60 * 60);

/// The engine-owned maintenance loop ticks at this cadence. One loop serves
/// both jobs: its currency pass is gated by
/// [`CURRENCY_COMPACTION_SUPERSEDED_THRESHOLD`], so a quiet node does near-zero
/// work, and only a tick that actually did something prints a receipt line.
pub(crate) const MAINTENANCE_TICK: Duration = Duration::from_secs(60);
pub(crate) const MAINTENANCE_POLL_INTERVAL_CONFIG_KEY: &str = "maintenance_poll_interval_ms";
pub(crate) const VECTOR_SERVING_CACHE_CONFIG_KEY: &str = "vector_serving_cache_bytes";

/// The declared serving-cache size a stored value stands for.
///
/// The setting is absent far more often than it is set, and both the durable
/// config value and the in-memory cell spell "absent" as zero, because there is
/// no size a consumer could mean by it — nothing serves from an empty cache.
/// Every reader of either goes through here, so that convention is written once
/// instead of at each site that happens to need it.
fn declared_serving_cache_bytes(stored: u64) -> Option<usize> {
    match stored {
        0 => None,
        bytes => Some(usize::try_from(bytes).unwrap_or(usize::MAX)),
    }
}

/// A maintenance tick compacts only once superseded versions across the eligible
/// tables reach this count, so steady-state churn below it never pays the
/// commit-lock/rewrite cost.
pub(crate) const CURRENCY_COMPACTION_SUPERSEDED_THRESHOLD: usize = 64;

/// Outcome of one `compact_currency_versions` pass.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct CurrencyCompactionReport {
    /// Superseded relational row versions physically removed.
    pub pruned_versions: u64,
    /// Change-log entries dropped in lockstep with those versions.
    pub pruned_change_log_entries: u64,
    /// Estimated in-memory row bytes released by the pruned versions.
    pub reclaimed_bytes: u64,
    /// The eligible tables that actually had superseded versions pruned, or
    /// a deleted row's vector copy reclaimed.
    pub compacted_tables: Vec<String>,
    /// Whether a redb file compaction ran to reclaim the freed pages.
    pub redb_compacted: bool,
    /// Wholesale survivor rewrites. Scoped cleanup leaves this at zero;
    /// it is not a count of all I/O. Affected change-log LSN groups are still
    /// read and densely rewritten when selected references are removed.
    pub keys_rewritten: u64,
    /// Selected durable vector bodies removed, despite the historical field
    /// name. This excludes unrelated vectors and is zero for in-memory stores.
    pub vector_keys_rewritten: u64,
    /// Physical adjacency keys rewritten. Currency cleanup leaves this at zero:
    /// graph edges have their own identities, independent of row versions.
    pub edge_keys_rewritten: u64,
    /// Wall-clock microseconds this pass held the commit lock -- the writer
    /// stall a concurrent commit waits behind. Timed from the FIRST
    /// instruction inside the `with_commit_lock` closure in
    /// `MaintenanceContext::run_currency`/`run_currency_for_tables` (i.e.
    /// from the moment the lock is actually granted), deliberately excluding
    /// however long this thread waited to acquire it -- a busy database
    /// timed from before the call would inflate this number with queueing
    /// delay that has nothing to do with what the pass itself cost.
    pub commit_lock_hold_micros: u64,
    /// Wall-clock microseconds the follow-on redb file compaction took, when
    /// one ran (`redb_compacted`) -- reported SEPARATELY from
    /// `commit_lock_hold_micros` on purpose: compaction runs OUTSIDE the
    /// commit lock (redb's compact needs `&mut` and must not run while a
    /// txn is outstanding), so it is not writer-stall time, and conflating
    /// the two would misreport the first pass over an accumulated debris
    /// ledger as a single, much larger writer stall than it actually was.
    /// 0 whenever `redb_compacted` is false.
    pub redb_compact_micros: u64,
    /// Eligible tables whose row histories were sampled in memory. Unrelated
    /// tables are not cloned into the cleanup selection.
    pub tables_in_memory_snapshot: u64,
    /// Commit-index entries removed after losing their last change-log reference,
    /// excluding the anchor needed to resolve the oldest surviving delete.
    /// Durable removal joins the row/vector cleanup transaction; this count
    /// records the matching in-memory removal, including on in-memory stores.
    pub commit_index_keys_removed: u64,
    /// Superseded versions left in place this cycle because a registered
    /// reader's snapshot (an in-flight statement, or a caller-held
    /// `SnapshotPin`) can still resolve to them. Reclaimed on a later cycle
    /// once no registered reader still needs them.
    pub versions_deferred_for_readers: u64,
    /// Set when this pass's own content-identity proof-maintenance charge
    /// (transient bookkeeping work layered on top of the actual reclaim) was
    /// refused by the memory or disk budget. The refusal is recovered from,
    /// not propagated: the durable and in-memory removal this pass exists
    /// for still completes, admitted unaccounted for that one already-
    /// refused attempt, so an essential currency cleanup never wedges the
    /// store merely because its own bookkeeping overhead briefly outgrew a
    /// tight budget. `None` on the ordinary accounted path. The charge
    /// itself is never removed -- the accounted attempt is always tried
    /// first, every pass.
    pub first_failure: Option<VectorMaintenanceFailure>,
    /// Safe typed context for `first_failure`, in the same shape
    /// `VectorMaintenanceReport` already reports vector-side refusals in.
    pub first_failure_details: Option<VectorMaintenanceFailureDetails>,
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct FkProbeStats {
    pub indexed_tuple_probes: u64,
    pub full_scan_fallbacks: u64,
}

/// Per-stage commit work counters. `#[doc(hidden)]` test-introspection surface
/// in the `FkProbeStats` precedent pattern. Stage order matches `commit_validate`:
/// conditional-update revalidation, UNIQUE / commit-time upsert rewrite validation,
/// FK, composite-FK, vector-schema revalidation, store apply / index maintenance,
/// and trigger-audit / event projection staging.
///
/// Tier 1 - always-on integer work counters (the acceptance arms assert on these).
/// Tier 2 - per-stage cumulative wall time, only populated under the `test-seams`
/// feature; `None` on default builds so non-feature builds compile and the field
/// is never load-bearing for correctness.
#[doc(hidden)]
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct CommitStageStats {
    /// Rows whose constraints were validated, summed across the validated stages.
    pub rows_validated: u64,
    /// Indexed probes issued by the validated stages (UNIQUE / FK / composite-FK).
    pub indexed_probes: u64,
    /// Staged-row-vs-staged-row comparisons performed across all validated stages.
    pub staged_vs_staged_comparisons: u64,
    /// Rows touched by full-table-scan primitives during commit validation.
    pub scan_rows_touched: u64,
    /// Index slots the apply-time maintenance loop iterated over for this write set.
    pub index_maintenance_visits: u64,
    /// Per-stage cumulative wall time in nanoseconds, ordered as in the struct doc.
    /// `None` unless built with `test-seams`. Never read by correctness assertions.
    pub stage_wall_nanos: Option<[u64; 7]>,
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct StagedTupleKey {
    table: String,
    columns: Vec<String>,
    values: Vec<DirectedValue>,
}

impl StagedTupleKey {
    fn new(table: &str, columns: &[String], values: &[Value]) -> Self {
        Self {
            table: table.to_string(),
            columns: columns.to_vec(),
            values: values
                .iter()
                .cloned()
                .map(|value| DirectedValue::Asc(TotalOrdAsc(value)))
                .collect(),
        }
    }
}

#[derive(Debug, Default)]
struct StagedTupleLookup {
    entries: BTreeMap<StagedTupleKey, BTreeSet<RowId>>,
}

impl StagedTupleLookup {
    fn rebuild(db: &Database, ws: &WriteSet) -> Result<Self> {
        let columns_by_table = db.staged_tuple_key_columns_by_table();
        Ok(Self::from_write_set(&columns_by_table, ws))
    }

    fn from_write_set(columns_by_table: &HashMap<String, Vec<Vec<String>>>, ws: &WriteSet) -> Self {
        let mut lookup = Self::default();
        for (table, row) in &ws.relational_inserts {
            lookup.add_row_with_columns(columns_by_table, table, row);
        }
        lookup
    }

    fn add_row_with_columns(
        &mut self,
        columns_by_table: &HashMap<String, Vec<Vec<String>>>,
        table: &str,
        row: &VersionedRow,
    ) {
        let Some(table_columns) = columns_by_table.get(table) else {
            return;
        };
        for columns in table_columns {
            let Some(values) = tuple_values_for_row(row, columns) else {
                continue;
            };
            if !Database::values_can_be_tuple_key(&values) {
                continue;
            }
            self.entries
                .entry(StagedTupleKey::new(table, columns, &values))
                .or_default()
                .insert(row.row_id);
        }
    }

    fn remove_row_with_columns(
        &mut self,
        columns_by_table: &HashMap<String, Vec<Vec<String>>>,
        table: &str,
        row: &VersionedRow,
    ) {
        let Some(table_columns) = columns_by_table.get(table) else {
            return;
        };
        for columns in table_columns {
            let Some(values) = tuple_values_for_row(row, columns) else {
                continue;
            };
            if !Database::values_can_be_tuple_key(&values) {
                continue;
            }
            let key = StagedTupleKey::new(table, columns, &values);
            let remove_entry = self.entries.get_mut(&key).is_some_and(|row_ids| {
                row_ids.remove(&row.row_id);
                row_ids.is_empty()
            });
            if remove_entry {
                self.entries.remove(&key);
            }
        }
    }

    fn apply_delta(
        &mut self,
        columns_by_table: &HashMap<String, Vec<Vec<String>>>,
        delta: &StagedTupleLookupDelta,
    ) {
        for event in &delta.events {
            match event {
                StagedTupleLookupEvent::Add { table, row } => {
                    self.add_row_with_columns(columns_by_table, table, row);
                }
                StagedTupleLookupEvent::Remove { table, row } => {
                    self.remove_row_with_columns(columns_by_table, table, row);
                }
            }
        }
    }

    fn staged_unique_conflict(
        &self,
        table: &str,
        row_id: RowId,
        columns: &[String],
        values: &[Value],
        stats: &mut CommitStageStats,
    ) -> Option<RowId> {
        stats.staged_vs_staged_comparisons = stats.staged_vs_staged_comparisons.saturating_add(1);
        self.entries
            .get(&StagedTupleKey::new(table, columns, values))
            .and_then(|row_ids| row_ids.iter().copied().find(|other| *other != row_id))
    }

    fn contains_tuple(
        &self,
        table: &str,
        columns: &[String],
        values: &[Value],
        stats: Option<&mut CommitStageStats>,
    ) -> bool {
        if let Some(stats) = stats {
            stats.staged_vs_staged_comparisons =
                stats.staged_vs_staged_comparisons.saturating_add(1);
        }
        self.entries
            .get(&StagedTupleKey::new(table, columns, values))
            .is_some_and(|row_ids| !row_ids.is_empty())
    }
}

#[derive(Debug)]
enum StagedTupleLookupEvent {
    Add { table: TableName, row: VersionedRow },
    Remove { table: TableName, row: VersionedRow },
}

#[derive(Debug, Default)]
struct StagedTupleLookupDelta {
    events: Vec<StagedTupleLookupEvent>,
}

impl StagedTupleLookupDelta {
    fn add(&mut self, table: &str, row: &VersionedRow) {
        self.events.push(StagedTupleLookupEvent::Add {
            table: table.to_string(),
            row: row.clone(),
        });
    }

    fn remove(&mut self, table: &str, row: &VersionedRow) {
        self.events.push(StagedTupleLookupEvent::Remove {
            table: table.to_string(),
            row: row.clone(),
        });
    }
}

#[derive(Debug)]
struct CommitTimeUpsertRewrite {
    table: TableName,
    row_id: RowId,
    lookup_delta: StagedTupleLookupDelta,
}

struct PreparedPropagationOptions<'a> {
    tx: TxId,
    snapshot: SnapshotId,
    lookup_delta: Option<&'a mut StagedTupleLookupDelta>,
}

struct CommitStageStatsGuard<'a> {
    db: &'a Database,
    stats: CommitStageStats,
    flushed: bool,
}

#[cfg(feature = "test-seams")]
struct CommitStageTimer {
    last: Instant,
}

#[cfg(feature = "test-seams")]
impl CommitStageTimer {
    fn new() -> Self {
        Self {
            last: Instant::now(),
        }
    }

    fn record(&mut self, stats: &mut CommitStageStats, stage: usize) {
        let now = Instant::now();
        let delta = now
            .duration_since(self.last)
            .as_nanos()
            .min(u128::from(u64::MAX)) as u64;
        self.last = now;
        let stages = stats.stage_wall_nanos.get_or_insert([0; 7]);
        if let Some(slot) = stages.get_mut(stage) {
            *slot = slot.saturating_add(delta);
        }
    }
}

impl<'a> CommitStageStatsGuard<'a> {
    fn new(db: &'a Database) -> Self {
        Self {
            db,
            stats: CommitStageStats::default(),
            flushed: false,
        }
    }

    fn stats_mut(&mut self) -> &mut CommitStageStats {
        &mut self.stats
    }

    fn flush(&mut self) {
        if !self.flushed {
            self.db.add_commit_stage_stats(&self.stats);
            self.flushed = true;
        }
    }
}

impl Drop for CommitStageStatsGuard<'_> {
    fn drop(&mut self) {
        self.flush();
    }
}

impl PruningRuntime {
    fn new() -> Self {
        Self {
            shutdown: Arc::new(AtomicBool::new(false)),
            handle: None,
            interval_ms: Arc::new(AtomicU64::new(MAINTENANCE_TICK.as_millis() as u64)),
            #[cfg(test)]
            wakes: Arc::new(AtomicU64::new(0)),
            worker_clock: Arc::new(MaintenanceWorkerClock::default()),
        }
    }

    /// Request shutdown before handing the worker to its joiner. The clock is
    /// the worker's production wait in every build, so notification cannot be
    /// limited to test configurations.
    fn request_shutdown_and_take_handle(&mut self) -> Option<JoinHandle<()>> {
        self.shutdown.store(true, Ordering::SeqCst);
        self.worker_clock.wake();
        self.handle.take()
    }
}

/// Open an in-memory database with a startup memory ceiling without exposing
/// the mutable accountant that enforces it. This is a safe bootstrap surface:
/// callers provide only the declared byte limit and every later limit change
/// still goes through [`Database::set_memory_limit`].
pub fn open_memory_with_startup_limit(
    plugin: Arc<dyn DatabasePlugin>,
    memory_limit: Option<usize>,
) -> Result<Database> {
    open_with_startup_limits(MEMORY_DATABASE_PATH, plugin, memory_limit, None)
}

/// Open a file-backed database with numeric startup ceilings. The mutable
/// memory-accounting capability never crosses the engine boundary.
pub fn open_with_startup_limits(
    path: impl AsRef<Path>,
    plugin: Arc<dyn DatabasePlugin>,
    memory_limit: Option<usize>,
    disk_limit: Option<u64>,
) -> Result<Database> {
    Database::open_with_options(
        path,
        DatabaseOpenOptions {
            plugin,
            memory_limit,
            disk_limit,
            ..DatabaseOpenOptions::default()
        },
    )
}

