    sync_test_seam! {
    /// A status reply from this authenticated edge's hub is behind the local
    /// push frontier, proving the hub was restored before some acknowledged
    /// local work. Mark only the affected `AcceptedLocal` order anchors as
    /// pending fresh ordering before the caller lowers its push watermark and
    /// resends; `Pulled` anchors still describe data this node received and
    /// must remain intact.
    ///
    /// The commit lock makes the current-version check and durable sidecar
    /// state change one boundary. A concurrent local write cannot be
    /// accidentally reclassified after this method chose its entries.
    fn invalidate_accepted_local_ordering_after_hub_regression(
        &self,
        hub_applied_source_watermark: Lsn,
    ) -> Result<()> {
        let _operation = self.assert_open_operation();
        self.with_commit_lock(|| {
            let entries = self
                .relational_store
                .tables
                .read()
                .iter()
                .flat_map(|(table, rows)| {
                    rows.iter()
                        .filter(|row| {
                            row.deleted_tx.is_none()
                                && row.lsn > hub_applied_source_watermark
                                && matches!(
                                    self.relational_store.sync_source_kind(table, row.row_id),
                                    Some(
                                        contextdb_relational::store::SyncSourceKind::AcceptedLocal
                                    )
                                )
                        })
                        .map(|row| {
                            (
                                table.clone(),
                                row.row_id,
                                self.relational_store
                                    .sync_source_lsn(table, row.row_id)
                                    .expect("AcceptedLocal always carries source LSN"),
                            )
                        })
                })
                .collect::<Vec<_>>();
            if !entries.is_empty() {
                if let Some(persistence) = &self.persistence {
                    persistence.append_sync_source_provenance_batch(
                        &entries
                            .iter()
                            .map(|(table, row_id, lsn)| (table.clone(), *row_id, *lsn, 2))
                            .collect::<Vec<_>>(),
                    )?;
                }
                self.relational_store
                    .set_sync_source_kinds(entries.into_iter().map(|(table, row_id, _)| {
                        (
                            table,
                            row_id,
                            contextdb_relational::store::SyncSourceKind::AcceptedLocalPending,
                        )
                    }));
            }
            for marker in self.sync_tombstone_arrivals.write().values_mut() {
                if matches!(
                    marker.kind,
                    contextdb_relational::store::SyncSourceKind::AcceptedLocal
                ) && marker.delete_lsn > hub_applied_source_watermark
                {
                    marker.accepted_local_order_invalidated = true;
                }
            }
            Ok(())
        })
    }
    }

    sync_test_seam! {
    /// A status confirms source work landed but not the hub order it received.
    /// Mark current, locally outbound work in the supplied source interval
    /// Pending before a pull can consume its echo. `through_inclusive = None`
    /// intentionally includes later local writes too: a restored-hub ordinary
    /// pull must not overwrite any current local work past its frontier.
    fn mark_outbound_rows_pending(
        &self,
        after_exclusive: Lsn,
        through_inclusive: Option<Lsn>,
    ) -> Result<()> {
        let _operation = self.assert_open_operation();
        self.with_commit_lock(|| {
            let entries = self
                .relational_store
                .tables
                .read()
                .iter()
                .flat_map(|(table, rows)| {
                    rows.iter()
                        .filter(|row| {
                            row.deleted_tx.is_none()
                                && row.lsn > after_exclusive
                                && through_inclusive.is_none_or(|through| row.lsn <= through)
                                && !matches!(
                                    self.relational_store.sync_source_kind(table, row.row_id),
                                    Some(contextdb_relational::store::SyncSourceKind::Pulled
                                        | contextdb_relational::store::SyncSourceKind::AcceptedLocal)
                                )
                        })
                        .map(|row| (table.clone(), row.row_id, row.lsn))
                })
                .collect::<Vec<_>>();
            let snapshot = self.snapshot();
            let empty_deleted = HashSet::new();
            let mut tombstones: HashMap<(String, String), (Lsn, RowId)> = HashMap::new();
            for entry in self.change_log_since_unlocked(after_exclusive) {
                let ChangeLogEntry::RowDelete {
                    table,
                    row_id,
                    natural_key,
                    lsn,
                } = entry
                else {
                    continue;
                };
                if through_inclusive.is_some_and(|through| lsn > through) {
                    continue;
                }
                let key = Self::sync_tombstone_key(&table, &natural_key);
                if self
                    .visible_row_by_natural_key(&table, &natural_key, snapshot, &empty_deleted)?
                    .is_some()
                {
                    continue;
                }
                let pulled = self
                    .sync_tombstone_arrivals
                    .read()
                    .get(&key)
                    .is_some_and(|marker| {
                        matches!(
                            marker.kind,
                            contextdb_relational::store::SyncSourceKind::Pulled
                        )
                    });
                if !pulled {
                    tombstones
                        .entry(key)
                        .and_modify(|latest| {
                            if lsn > latest.0 {
                                *latest = (lsn, row_id);
                            }
                        })
                        .or_insert((lsn, row_id));
                }
            }
            if !entries.is_empty() {
                if let Some(persistence) = &self.persistence {
                    persistence.append_sync_source_provenance_batch(
                        &entries
                            .iter()
                            .map(|(table, row_id, lsn)| (table.clone(), *row_id, *lsn, 2))
                            .collect::<Vec<_>>(),
                    )?;
                }
                self.relational_store.set_sync_source_lsns(entries.clone());
                self.relational_store
                    .set_sync_source_kinds(entries.into_iter().map(|(table, row_id, _)| {
                        (
                            table,
                            row_id,
                            contextdb_relational::store::SyncSourceKind::AcceptedLocalPending,
                        )
                    }));
            }
            if !tombstones.is_empty() {
                let mut markers = self.sync_tombstone_arrivals.write();
                for (key, (delete_lsn, row_id)) in tombstones {
                    markers.insert(
                        key,
                        SyncTombstoneArrival {
                            arrival: delete_lsn,
                            delete_lsn,
                            row_id: Some(row_id),
                            kind: contextdb_relational::store::SyncSourceKind::AcceptedLocalPending,
                            accepted_local_order_invalidated: false,
                        },
                    );
                }
            }
            Ok(())
        })
    }
    }

    pub(crate) fn reconciled_push_rows_have_arrivals(
        &self,
        changes: &ChangeSet,
        lineages: &OutboundRowLineages,
    ) -> Result<bool> {
        let _operation = self.open_operation()?;
        for row in &changes.rows {
            if row.deleted {
                return Ok(false);
            }
            let key = rmp_serde::to_vec(&row.natural_key)
                .map_err(|error| Error::SyncError(error.to_string()))?;
            let Some(_expected) = lineages.get(&(row.table.clone(), key, row.lsn)) else {
                return Ok(false);
            };
            let meta = self.table_meta(&row.table);
            let accepted =
                self.relational_store
                    .tables
                    .read()
                    .get(&row.table)
                    .map(|rows| {
                        rows.iter()
                            .filter(|local| {
                                local.lsn == row.lsn
                                    && matches!(
                                    self.relational_store
                                        .sync_source_kind(&row.table, local.row_id),
                                    Some(
                                        contextdb_relational::store::SyncSourceKind::AcceptedLocal
                                    )
                                ) && self
                                    .relational_store
                                    .sync_source_lsn(&row.table, local.row_id)
                                    .is_some()
                            })
                            .cloned()
                            .collect::<Vec<_>>()
                    })
                    .unwrap_or_default();
            let mut confirmed = false;
            for local in &accepted {
                if self.sync_incoming_row_matches_committed(
                    &row.values,
                    local,
                    &row.table,
                    meta.as_ref(),
                )? {
                    confirmed = true;
                    break;
                }
            }
            if !confirmed {
                return Ok(false);
            }
        }
        Ok(true)
    }

    pub(crate) fn has_unconfirmed_push_rows(&self, after: Lsn, through: Lsn) -> bool {
        self.relational_store
            .tables
            .read()
            .iter()
            .any(|(table, rows)| {
                rows.iter().any(|row| {
                    row.lsn > after
                        && row.lsn <= through
                        && !matches!(
                            self.relational_store.sync_source_kind(table, row.row_id),
                            Some(contextdb_relational::store::SyncSourceKind::AcceptedLocal)
                        )
                        // A pull can replace a refused local version while the
                        // provenance sidecar follows the current RowId. Its
                        // retained source version still lacks acceptance; a
                        // Pulled mark on the replacement cannot confirm it.
                        && (row.deleted_tx.is_some()
                            || !matches!(
                                self.relational_store.sync_source_kind(table, row.row_id),
                                Some(contextdb_relational::store::SyncSourceKind::Pulled)
                            ))
                })
            })
    }

    /// Select only authenticated echoes of the local lineage before applying a
    /// pull page. Equal values from a different creator do not acknowledge the
    /// local mutation. This reuses ordinary row provenance, with no new receipt.
    pub(crate) fn matching_pending_reconciliation_rows(
        &self,
        rows: &[RowChange],
        lineages: &[(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)],
    ) -> Result<Vec<RowChange>> {
        let mut matching = Vec::new();
        let lineage_state = self.lineage_state_lock.lock();
        for row in rows {
            let Some((_, _, _, lineage)) = lineages.iter().find(|(table, key, lsn, _)| {
                table == &row.table && key == &row.natural_key && *lsn == row.lsn
            }) else {
                continue;
            };
            let known = self.load_row_lineage_sidecar(
                &lineage_state,
                &Self::durable_row_lineage_config_key(
                    &row.table,
                    &row.natural_key,
                    lineage.table_generation,
                ),
            )?;
            if known
                .as_ref()
                .is_some_and(|known| Self::row_lineage_matches_wire(known, lineage))
            {
                matching.push(row.clone());
            }
        }
        Ok(matching)
    }

    sync_test_seam! {
    /// After status confirmed a re-send landed, a byte-identical pull echo
    /// has no row mutation to carry through the normal sync write set. Refresh
    /// matching Pending versions explicitly, in one durable provenance batch
    /// under the commit lock. Production callers first select authenticated
    /// lineage matches; retained history keeps evidence if a later page edit
    /// has already replaced the visible row.
    fn refresh_confirmed_pending_rows(
        &self,
        rows: &[RowChange],
        arrivals: &HashMap<Lsn, Option<Lsn>>,
    ) -> Result<()> {
        let _operation = self.assert_open_operation();
        self.with_commit_lock(|| {
            let mut entries = Vec::new();
            let mut tombstone_refreshes = Vec::new();
            for row in rows.iter().filter(|row| !row.deleted) {
                let Some(arrival) = Self::resolve_incoming_arrival(row, arrivals) else {
                    continue;
                };
                let tables = self.relational_store.tables.read();
                let Some(versions) = tables.get(&row.table) else {
                    continue;
                };
                let meta = self.table_meta(&row.table);
                for current in versions {
                    if matches!(
                        self.relational_store.sync_source_kind(&row.table, current.row_id),
                        Some(contextdb_relational::store::SyncSourceKind::AcceptedLocalPending)
                    ) && self.sync_incoming_row_matches_committed(
                        &row.values, current, &row.table, meta.as_ref(),
                    )? {
                        entries.push((row.table.clone(), current.row_id, arrival));
                    }
                }
            }
            for row in rows.iter().filter(|row| row.deleted) {
                let Some(arrival) = Self::resolve_incoming_arrival(row, arrivals) else {
                    continue;
                };
                let key = Self::sync_tombstone_key(&row.table, &row.natural_key);
                if self
                    .sync_tombstone_arrivals
                    .read()
                    .get(&key)
                    .is_some_and(|marker| {
                        matches!(
                            marker.kind,
                            contextdb_relational::store::SyncSourceKind::AcceptedLocal
                                | contextdb_relational::store::SyncSourceKind::AcceptedLocalPending
                        ) && (marker.accepted_local_order_invalidated
                            || matches!(
                                marker.kind,
                                contextdb_relational::store::SyncSourceKind::AcceptedLocalPending
                            ))
                            && marker.delete_lsn == row.lsn
                    })
                {
                    tombstone_refreshes.push((key, arrival));
                }
            }
            if !entries.is_empty() {
                if let Some(persistence) = &self.persistence {
                    persistence.append_sync_source_provenance_batch(
                        &entries
                            .iter()
                            .map(|(table, row_id, lsn)| (table.clone(), *row_id, *lsn, 1))
                            .collect::<Vec<_>>(),
                    )?;
                }
                self.relational_store.set_sync_source_lsns(entries.clone());
                self.relational_store
                    .set_sync_source_kinds(entries.into_iter().map(|(table, row_id, _)| {
                        (
                            table,
                            row_id,
                            contextdb_relational::store::SyncSourceKind::AcceptedLocal,
                        )
                    }));
            }
            if !tombstone_refreshes.is_empty() {
                let mut tombstones = self.sync_tombstone_arrivals.write();
                for (key, arrival) in tombstone_refreshes {
                    if let Some(marker) = tombstones.get_mut(&key) {
                        marker.arrival = arrival;
                        marker.kind = contextdb_relational::store::SyncSourceKind::AcceptedLocal;
                        marker.accepted_local_order_invalidated = false;
                    }
                }
            }
            Ok(())
        })
    }
    }

    /// Test-introspection: the commit index as this handle would report it,
    /// in LSN order. A fixture that wants the store's own answer asks for it
    /// here rather than assembling one from counters it watched go by.
    #[doc(hidden)]
    #[cfg(any(test, feature = "test-seams"))]
    pub fn commit_index_for_test(&self) -> Vec<(Lsn, TxId)> {
        let _operation = self.assert_open_operation();
        self.tx_mgr.commit_index_snapshot().into_iter().collect()
    }

    pub(crate) fn commit_index_for_read_image(&self) -> Result<Vec<(Lsn, TxId)>> {
        self.ensure_image_history()?;
        Ok(self.tx_mgr.commit_index_entries())
    }

    /// How many entries [`Self::commit_index_for_read_image`] copies.
    pub(crate) fn commit_index_len_for_read_image(&self) -> usize {
        self.tx_mgr.commit_index_len()
    }

    /// Read a committed image's history from its pinned snapshot the first
    /// time anything asks for it, and publish it into the same structures a
    /// live handle keeps. Until then those structures are empty and nothing
    /// that reads them runs. The history is admitted as it is read and every
    /// record is proved against the committed identity; the deleted edges'
    /// tombstones are checked against the commit index here, as a complete
    /// open checks them.
    pub(crate) fn ensure_image_history(&self) -> Result<()> {
        self.ensure_image_history_within(&|| Ok(()))
            .map_err(ImageHistoryError::into_engine_error)
    }

    /// [`Self::ensure_image_history`] for a request that owns a cancellation
    /// and an active-time budget: `checkpoint` is called as the walk advances
    /// and its refusal ends the walk, leaving nothing loaded or charged.
    pub(crate) fn ensure_image_history_within(
        &self,
        checkpoint: &dyn Fn() -> Result<()>,
    ) -> std::result::Result<(), ImageHistoryError> {
        let Some(history) = self.image_history.as_ref() else {
            return Ok(());
        };
        let mut loaded = history.loaded.lock();
        if loaded.is_some() {
            // Already loaded: this request still owns its own cancellation
            // and active-time budget, and the work still ahead of it --
            // projecting and encoding an answer from what is cached -- is
            // real work a cached history must not exempt from either check.
            return Ok(checkpoint()?);
        }
        let read = history.source.load_history(&self.accountant, checkpoint)?;
        crate::persistence::validate_read_history_tombstones(
            &history.deleted_edges,
            &read.change_log,
            &read.commit_index,
        )
        .map_err(|diagnosis| ImageHistoryError::Store {
            path: history.source.database_path().display().to_string(),
            diagnosis: Box::new(diagnosis),
        })?;
        checkpoint()?;
        // The aux indexes are admitted and built only once the history that
        // feeds them is itself admitted: a room too tight for both is
        // refused here, before either structure exists, and the history
        // charge just taken is released with `read` on the way out.
        let indexes = crate::read_image_memory::ImageMemory::charging(Arc::clone(&self.accountant));
        let (table_index, lsn_refcounts) =
            build_admitted_change_log_aux_indexes(&read.change_log, &indexes)?;
        self.with_commit_lock(|| {
            *self.change_log.write() = read.change_log;
            *self.change_log_table_index.write() = table_index;
            *self.change_log_lsn_refcounts.write() = lsn_refcounts;
            *self.ddl_log.write() = read.ddl_log;
            self.tx_mgr.replace_commit_index(read.commit_index);
        });
        *loaded = Some(LoadedImageHistoryCharge {
            _history: read.charge,
            _indexes: indexes,
        });
        Ok(())
    }

    /// Test-introspection: how many commit-index entries are retained, and the
    /// lowest LSN among them (`Lsn(0)` when the index is empty). Production-dead
    /// — nothing but tests reads it.
    #[doc(hidden)]
    #[cfg(any(test, feature = "test-seams"))]
    pub fn commit_index_census_for_test(&self) -> (usize, Lsn) {
        let _operation = self.assert_open_operation();
        self.tx_mgr.commit_index_census()
    }

    /// Test-introspection: how many commit-index entries sit strictly below
    /// `lsn`. The anchor rule wants exactly one after a prune — fewer drops the
    /// oldest surviving delete, more is unreclaimed growth. Production-dead.
    #[doc(hidden)]
    #[cfg(any(test, feature = "test-seams"))]
    pub fn commit_index_entries_below_for_test(&self, lsn: Lsn) -> usize {
        let _operation = self.assert_open_operation();
        self.tx_mgr.commit_index_snapshot().range(..lsn).count()
    }

    /// Test-introspection: a sorted copy of `change_log_table_index`'s own
    /// `(lsn, row_id)` coordinates for one table -- the per-table shadow a
    /// scoped cleanup/retention pass reads instead of scanning the whole
    /// change log. Sorted so a caller can compare it against a
    /// content-derived multiset without depending on internal ordering.
    /// Production-dead -- nothing but tests reads it.
    #[doc(hidden)]
    #[cfg(any(test, feature = "test-seams"))]
    pub fn __change_log_table_index_for_test(&self, table: &str) -> Vec<(Lsn, RowId)> {
        let _operation = self.assert_open_operation();
        let mut coords = self
            .change_log_table_index
            .read()
            .get(table)
            .cloned()
            .unwrap_or_default();
        coords.sort_by_key(|(lsn, row_id)| (*lsn, *row_id));
        coords
    }

    fn set_sync_row_source_lsn(
        &self,
        tx: TxId,
        table: &str,
        row_id: RowId,
        source_lsn: Lsn,
    ) -> Result<()> {
        self.tx_mgr.with_write_set(tx, |ws| {
            ws.set_relational_insert_source_lsn(table.to_string(), row_id, source_lsn);
        })
    }

    fn set_sync_row_source_lsn_kind(
        &self,
        tx: TxId,
        table: &str,
        row_id: RowId,
        source_lsn: Lsn,
        kind: contextdb_relational::store::SyncSourceKind,
    ) -> Result<()> {
        let kind = match kind {
            contextdb_relational::store::SyncSourceKind::Pulled => 0,
            contextdb_relational::store::SyncSourceKind::AcceptedLocal => 1,
            contextdb_relational::store::SyncSourceKind::AcceptedLocalPending => 2,
        };
        self.tx_mgr.with_write_set(tx, |ws| {
            ws.set_relational_insert_source_lsn_kind(table.to_string(), row_id, source_lsn, kind);
        })
    }

    /// Record sync provenance for a row this transaction leaves exactly as it
    /// stands. The row is not restaged: an immutable table refuses a rewrite,
    /// and republishing correct values would put a mutation in the change log
    /// that no peer asked for.
    fn mark_sync_row_provenance(
        &self,
        tx: TxId,
        table: &str,
        row_id: RowId,
        source_lsn: Lsn,
        kind: contextdb_relational::store::SyncSourceKind,
    ) -> Result<()> {
        let kind = match kind {
            contextdb_relational::store::SyncSourceKind::Pulled => 0,
            contextdb_relational::store::SyncSourceKind::AcceptedLocal => 1,
            contextdb_relational::store::SyncSourceKind::AcceptedLocalPending => 2,
        };
        self.tx_mgr.with_write_set(tx, |ws| {
            ws.set_sync_source_provenance_mark(table.to_string(), row_id, source_lsn, kind);
        })
    }

    /// Route each row cell through `coerce_value_for_column` for variant
    /// compatibility. The one concession to historical `insert_row` behavior
    /// is that `Value::Vector` payloads are accepted regardless of declared
    /// dimension — prior integration suites (e.g. the 3-component probe into
    /// a VECTOR(384) embedding column) depend on the library API NOT enforcing
    /// dim equality there. SQL execution (`exec_insert`/`exec_update`) still
    /// performs the full dim check because it always threads through the
    /// executor module's coercion helpers.
    fn coerce_row_for_insert(
        &self,
        table: &str,
        values: HashMap<ColName, Value>,
        current_tx_max: Option<TxId>,
        active_tx: Option<TxId>,
    ) -> Result<HashMap<ColName, Value>> {
        let meta = self.table_meta(table);
        let mut out: HashMap<ColName, Value> = HashMap::with_capacity(values.len());
        for (col, v) in values {
            // Vector + Value::Vector: pass straight through (dim check happens on SQL path).
            let is_vector_bypass = matches!(&v, Value::Vector(_))
                && meta
                    .as_ref()
                    .and_then(|m| m.columns.iter().find(|c| c.name == col))
                    .map(|c| matches!(c.column_type, contextdb_core::ColumnType::Vector(_)))
                    .unwrap_or(false);

            let coerced = if is_vector_bypass {
                v
            } else {
                crate::executor::coerce_into_column(
                    self,
                    table,
                    &col,
                    v,
                    current_tx_max,
                    active_tx,
                )?
            };
            out.insert(col, coerced);
        }
        Ok(out)
    }

    fn validate_primary_key_values_present(
        &self,
        table: &str,
        values: &HashMap<ColName, Value>,
    ) -> Result<()> {
        let meta = self
            .table_meta(table)
            .ok_or_else(|| Error::TableNotFound(table.to_string()))?;
        for column in &meta.columns {
            let is_primary_key = column.primary_key
                || meta
                    .primary_key_columns
                    .iter()
                    .any(|name| name == &column.name);
            if is_primary_key && matches!(values.get(&column.name), None | Some(Value::Null)) {
                return Err(Error::ColumnNotNullable {
                    table: table.to_string(),
                    column: column.name.clone(),
                });
            }
        }
        Ok(())
    }

    pub(crate) fn insert_row_with_unique_noop(
        &self,
        tx: TxId,
        table: &str,
        mut values: HashMap<ColName, Value>,
    ) -> Result<InsertRowResult> {
        self.ensure_trigger_table_ready(table, "insert_row")?;
        self.complete_insert_access_values(table, &mut values)?;
        let allow_duplicate_unique_noop =
            !self.table_meta(table).is_some_and(|meta| meta.immutable);
        match self.check_row_constraints(tx, table, &values, None, allow_duplicate_unique_noop)? {
            RowConstraintCheck::Valid => {
                let row_id = self.relational_store.new_row_id();
                self.assert_row_write_allowed(table, row_id, &values, self.snapshot_for_read())?;
                let natural_key = self
                    .table_meta(table)
                    .and_then(|meta| natural_key_from_row_values(&meta, &values));
                let row_vectors_source = values.clone();
                let staged_before = self.staged_row_count(tx);
                let mut values = values;
                self.blank_quantized_vector_values(table, &mut values);
                let inserted = self.relational.insert_with_row_id(
                    tx,
                    table,
                    row_id,
                    values,
                    self.snapshot_for_read(),
                )?;
                self.write_row_vectors_or_unstage(
                    tx,
                    table,
                    inserted,
                    &row_vectors_source,
                    staged_before,
                )?;
                if let Some(natural_key) = natural_key {
                    self.stage_local_creation_lineage(tx, table, natural_key, inserted)?;
                }
                Ok(InsertRowResult::Inserted(inserted))
            }
            RowConstraintCheck::DuplicateUniqueNoOp => Ok(InsertRowResult::NoOp),
        }
    }

    pub fn upsert_row(
        &self,
        tx: TxId,
        table: &str,
        conflict_col: &str,
        mut values: HashMap<ColName, Value>,
    ) -> Result<UpsertResult> {
        let _operation = self.open_operation_after_write_control_wait(tx, "upsert_row")?;
        self.ensure_trigger_table_ready(table, "upsert_row")?;
        self.complete_insert_access_values(table, &mut values)?;
        let snapshot = self.snapshot_for_read();
        let existing_row = values
            .get(conflict_col)
            .map(|conflict_value| {
                self.point_lookup_in_tx(tx, table, conflict_col, conflict_value, snapshot)
            })
            .transpose()?
            .flatten();
        let existing_row_id = existing_row.as_ref().map(|row| row.row_id);
        // Diff-respecting column-level IMMUTABLE check: reject any upsert whose
        // flagged-column value differs from the existing local value. Idempotent
        // replay (same-value) succeeds; new rows (no existing match) apply normally.
        if let (Some(existing), Some(meta)) = (existing_row.as_ref(), self.table_meta(table)) {
            for col_def in meta.columns.iter().filter(|c| c.immutable) {
                let Some(incoming) = values.get(&col_def.name) else {
                    continue;
                };
                let existing_value = existing.values.get(&col_def.name);
                if existing_value != Some(incoming) {
                    return Err(Error::ImmutableColumn {
                        table: table.to_string(),
                        column: col_def.name.clone(),
                    });
                }
            }
        }
        self.validate_row_constraints(tx, table, &values, existing_row_id)?;
        let Some(existing) = existing_row.as_ref() else {
            let row_id = self.relational_store.new_row_id();
            self.assert_row_write_allowed(table, row_id, &values, snapshot)?;

            let row_uuid = values.get("id").and_then(Value::as_uuid).copied();
            let meta = self.table_meta(table);
            let new_state = meta
                .as_ref()
                .and_then(|m| m.state_machine.as_ref())
                .and_then(|sm| values.get(&sm.column))
                .and_then(Value::as_text)
                .map(std::borrow::ToOwned::to_owned);
            let natural_key = meta
                .as_ref()
                .and_then(|meta| natural_key_from_row_values(meta, &values));

            // The same ownership the other write doors use: the vectors are
            // taken before the row is staged, the quantized slots are emptied
            // so the row costs what the column declared, the vectors are
            // placed in the store the column reads from, and a placement that
            // cannot be made takes the row back out. Without this an upserted
            // vector is in no index at all -- a search never finds the row,
            // and the caller is told the row was inserted.
            let row_vectors_source = values.clone();
            let staged_before = self.staged_row_count(tx);
            let mut values = values;
            self.blank_quantized_vector_values(table, &mut values);
            let inserted = self
                .relational
                .insert_with_row_id(tx, table, row_id, values, snapshot)?;
            self.write_row_vectors_or_unstage(
                tx,
                table,
                inserted,
                &row_vectors_source,
                staged_before,
            )?;
            if let Some(natural_key) = natural_key {
                self.stage_local_creation_lineage(tx, table, natural_key, inserted)?;
            }
            if let (Some(uuid), Some(state), Some(_meta)) =
                (row_uuid, new_state.as_deref(), meta.as_ref())
            {
                self.propagate_state_change_if_needed(tx, table, Some(uuid), Some(state))?;
            }
            return Ok(UpsertResult::Inserted);
        };
        {
            self.assert_row_write_allowed(table, existing.row_id, &existing.values, snapshot)?;
            self.assert_row_write_allowed(table, existing.row_id, &values, snapshot)?;
        }

        let row_uuid = values.get("id").and_then(Value::as_uuid).copied();
        let meta = self.table_meta(table);
        let new_state = meta
            .as_ref()
            .and_then(|m| m.state_machine.as_ref())
            .and_then(|sm| values.get(&sm.column))
            .and_then(Value::as_text)
            .map(std::borrow::ToOwned::to_owned);

        // Compare what the store would hold against what it holds. A
        // quantized column keeps an approximation and the row itself keeps
        // nothing, so a diff against the caller's own full-precision input
        // reports a change on every upsert of the same vector -- and each one
        // would rewrite the row and place the vector again.
        let stored_now = self.outbound_row_values(table, existing)?;
        let changed = values.iter().any(|(column, value)| {
            stored_now.get(column) != Some(&self.stored_form_of_value(table, column, value))
        });
        if !changed {
            return Ok(UpsertResult::NoOp);
        }
        self.validate_commit_time_upsert_state_transition(table, existing, &values)?;
        self.delete_relational_row_releasing_staged(tx, table, existing.row_id)?;
        // Placing the new vector is what retires the old one: the store
        // deletes the entry this row already had before it takes the new one,
        // so an updating upsert leaves one vector behind, not two.
        let row_vectors = self.row_vector_values(table, &values);
        let mut values = values;
        self.blank_quantized_vector_values(table, &mut values);
        let replaced =
            self.relational
                .insert_with_row_id(tx, table, existing.row_id, values, snapshot)?;
        self.write_row_vectors(tx, replaced, row_vectors)?;

        if let (Some(uuid), Some(state), Some(_meta)) =
            (row_uuid, new_state.as_deref(), meta.as_ref())
        {
            self.propagate_state_change_if_needed(tx, table, Some(uuid), Some(state))?;
        }

        Ok(UpsertResult::Updated)
    }

    fn validate_row_constraints(
        &self,
        tx: TxId,
        table: &str,
        values: &HashMap<ColName, Value>,
        skip_row_id: Option<RowId>,
    ) -> Result<()> {
        match self.check_row_constraints(tx, table, values, skip_row_id, false)? {
            RowConstraintCheck::Valid => Ok(()),
            RowConstraintCheck::DuplicateUniqueNoOp => {
                unreachable!("strict constraint validation cannot return no-op")
            }
        }
    }

    fn check_row_constraints(
        &self,
        tx: TxId,
        table: &str,
        values: &HashMap<ColName, Value>,
        skip_row_id: Option<RowId>,
        allow_duplicate_unique_noop: bool,
    ) -> Result<RowConstraintCheck> {
        // Constraint probes MUST see the current committed watermark, not any
        // thread-local override. A PK/UNIQUE violation on a committed row must
        // be detected even if the caller pinned a pre-violation snapshot for
        // read visibility.
        let snapshot = self.snapshot();
        self.check_row_constraints_at_snapshot(
            tx,
            table,
            values,
            skip_row_id,
            allow_duplicate_unique_noop,
            snapshot,
        )
    }

    fn check_row_constraints_at_snapshot(
        &self,
        tx: TxId,
        table: &str,
        values: &HashMap<ColName, Value>,
        skip_row_id: Option<RowId>,
        allow_duplicate_unique_noop: bool,
        snapshot: SnapshotId,
    ) -> Result<RowConstraintCheck> {
        let metas = self.relational_store.table_meta.read();
        let meta = metas
            .get(table)
            .ok_or_else(|| Error::TableNotFound(table.to_string()))?;

        for column in &meta.columns {
            let is_primary_key = column.primary_key
                || meta
                    .primary_key_columns
                    .iter()
                    .any(|name| name == &column.name);
            if is_primary_key && matches!(values.get(&column.name), None | Some(Value::Null)) {
                return Err(Error::ColumnNotNullable {
                    table: table.to_string(),
                    column: column.name.clone(),
                });
            }
        }

        // Scan the whole table only when no index covers any PK / UNIQUE
        // column we need to probe. Pulled lazily so the fast path skips it.
        let mut visible_rows_cache: Option<Vec<VersionedRow>> = None;

        for column in meta.columns.iter().filter(|column| column.primary_key) {
            let Some(value) = values.get(&column.name) else {
                continue;
            };
            if *value == Value::Null {
                continue;
            }
            match self.probe_column_for_constraint(
                tx,
                table,
                &column.name,
                value,
                snapshot,
                skip_row_id,
            )? {
                ConstraintProbe::Match(_) => {
                    return Err(Error::UniqueViolation {
                        table: table.to_string(),
                        column: column.name.clone(),
                    });
                }
                ConstraintProbe::NoMatch => {}
                ConstraintProbe::NoIndex => {
                    // Fallback to full scan for PK columns without an index.
                    if visible_rows_cache.is_none() {
                        visible_rows_cache = Some(self.relational.scan_filter_with_tx(
                            Some(tx),
                            table,
                            snapshot,
                            &|row| skip_row_id.is_none_or(|row_id| row.row_id != row_id),
                        )?);
                    }
                    let rows = visible_rows_cache.as_deref().unwrap();
                    if rows
                        .iter()
                        .any(|existing| existing.values.get(&column.name) == Some(value))
                    {
                        return Err(Error::UniqueViolation {
                            table: table.to_string(),
                            column: column.name.clone(),
                        });
                    }
                }
            }
        }

        let mut duplicate_unique_row_id = None;

        for column in meta
            .columns
            .iter()
            .filter(|column| column.unique && !column.primary_key)
        {
            let Some(value) = values.get(&column.name) else {
                continue;
            };
            if *value == Value::Null {
                continue;
            }
            let matching_row_ids: Vec<RowId> = match self.probe_column_for_constraint(
                tx,
                table,
                &column.name,
                value,
                snapshot,
                skip_row_id,
            )? {
                ConstraintProbe::Match(rid) => vec![rid],
                ConstraintProbe::NoMatch => Vec::new(),
                ConstraintProbe::NoIndex => {
                    if visible_rows_cache.is_none() {
                        visible_rows_cache = Some(self.relational.scan_filter_with_tx(
                            Some(tx),
                            table,
                            snapshot,
                            &|row| skip_row_id.is_none_or(|row_id| row.row_id != row_id),
                        )?);
                    }
                    let rows = visible_rows_cache.as_deref().unwrap();
                    rows.iter()
                        .filter(|existing| existing.values.get(&column.name) == Some(value))
                        .map(|existing| existing.row_id)
                        .collect()
                }
            };
            self.merge_unique_conflict(
                tx,
                table,
                &column.name,
                &matching_row_ids,
                allow_duplicate_unique_noop,
                &mut duplicate_unique_row_id,
            )?;
        }

        // A multi-column UNIQUE violation is a loud constraint error on every
        // INSERT path, exactly like a composite PRIMARY KEY duplicate (never
        // the single-column no-op-on-plain-insert convention
        // `allow_duplicate_unique_noop` governs below) — standard SQL never
        // silently drops a row on a UNIQUE violation. Same probe, one no-op
        // policy for both composite forms.
        let composite_pk =
            (meta.primary_key_columns.len() >= 2).then_some(&meta.primary_key_columns);
        for unique_constraint in meta.unique_constraints.iter().chain(composite_pk) {
            let mut candidate_values = Vec::with_capacity(unique_constraint.len());
            let mut has_null = false;

            for column_name in unique_constraint {
                match values.get(column_name) {
                    Some(Value::Null) | None => {
                        has_null = true;
                        break;
                    }
                    Some(value) => candidate_values.push(value.clone()),
                }
            }

            if has_null {
                continue;
            }

            let matching_row_ids: Vec<RowId> = if let Some(rid) = self.probe_composite_unique(
                tx,
                table,
                unique_constraint,
                &candidate_values,
                snapshot,
                skip_row_id,
            )? {
                vec![rid]
            } else if self.index_covers_composite(table, unique_constraint) {
                Vec::new()
            } else {
                if visible_rows_cache.is_none() {
                    visible_rows_cache = Some(self.relational.scan_filter_with_tx(
                        Some(tx),
                        table,
                        snapshot,
                        &|row| skip_row_id.is_none_or(|row_id| row.row_id != row_id),
                    )?);
                }
                let rows = visible_rows_cache.as_deref().unwrap();
                rows.iter()
                    .filter(|existing| {
                        unique_constraint.iter().zip(candidate_values.iter()).all(
                            |(column_name, value)| existing.values.get(column_name) == Some(value),
                        )
                    })
                    .map(|existing| existing.row_id)
                    .collect()
            };
            // Report a composite UNIQUE violation naming every column of the
            // constraint, not just the first — the caller needs the whole
            // tuple to know which declared constraint fired.
            let column_label = unique_constraint.join(", ");
            self.merge_unique_conflict(
                tx,
                table,
                &column_label,
                &matching_row_ids,
                false,
                &mut duplicate_unique_row_id,
            )?;
        }

        if duplicate_unique_row_id.is_some() {
            Ok(RowConstraintCheck::DuplicateUniqueNoOp)
        } else {
            Ok(RowConstraintCheck::Valid)
        }
    }

    fn merge_unique_conflict(
        &self,
        tx: TxId,
        table: &str,
        column: &str,
        matching_row_ids: &[RowId],
        allow_duplicate_unique_noop: bool,
        duplicate_unique_row_id: &mut Option<RowId>,
    ) -> Result<()> {
        if matching_row_ids.is_empty() {
            return Ok(());
        }

        if !allow_duplicate_unique_noop || matching_row_ids.len() != 1 {
            return Err(Error::UniqueViolation {
                table: table.to_string(),
                column: column.to_string(),
            });
        }

        let matched_row_id = matching_row_ids[0];
        if self.row_id_is_staged_insert(tx, table, matched_row_id)? {
            return Err(Error::UniqueViolation {
                table: table.to_string(),
                column: column.to_string(),
            });
        }

        if let Some(existing_row_id) = duplicate_unique_row_id {
            if *existing_row_id != matched_row_id {
                return Err(Error::UniqueViolation {
                    table: table.to_string(),
                    column: column.to_string(),
                });
            }
        } else {
            *duplicate_unique_row_id = Some(matched_row_id);
        }

        Ok(())
    }

    fn row_id_is_staged_insert(&self, tx: TxId, table: &str, row_id: RowId) -> Result<bool> {
        self.tx_mgr.with_write_set(tx, |ws| {
            ws.relational_inserts
                .iter()
                .any(|(staged_table, staged_row)| {
                    staged_table == table && staged_row.row_id == row_id
                })
        })
    }

    /// Returns true if `table` has an index whose leading key covers `column`.
    fn index_covers_column(&self, table: &str, column: &str) -> bool {
        let indexes = self.relational_store.indexes.read();
        indexes.get(table).is_some_and(|table_indexes| {
            table_indexes
                .values()
                .any(|idx| idx.columns.first().is_some_and(|(name, _)| name == column))
        })
    }

    /// Returns true if `table` has an index whose first-column prefix contains
    /// exactly the columns in `cols` (same order).
    fn index_covers_composite(&self, table: &str, cols: &[String]) -> bool {
        let indexes = self.relational_store.indexes.read();
        indexes.get(table).is_some_and(|table_indexes| {
            table_indexes.values().any(|idx| {
                idx.columns.len() >= cols.len()
                    && idx
                        .columns
                        .iter()
                        .zip(cols.iter())
                        .all(|((c, _), want)| c == want)
            })
        })
    }

    /// Look up `(table, column) = value` using a single-column index when one
    /// exists, layered with the tx's staged inserts and deletes.
    fn probe_column_for_constraint(
        &self,
        tx: TxId,
        table: &str,
        column: &str,
        value: &Value,
        snapshot: SnapshotId,
        skip_row_id: Option<RowId>,
    ) -> Result<ConstraintProbe> {
        use contextdb_core::{DirectedValue, TotalOrdAsc};
        let (tx_staged_deletes, tx_delete_predicates, staged_overlap) =
            self.tx_mgr.with_write_set(tx, |ws| {
                // Rows this tx has already staged for delete must not be treated as
                // obstructions by the constraint probe. The old index entry still
                // looks visible at the committed-watermark snapshot until commit.
                let deletes = if ws.relational_deletes.is_empty() {
                    std::collections::HashSet::new()
                } else {
                    ws.relational_deletes
                        .iter()
                        .filter(|(t, _, _)| t == table)
                        .map(|(_, row_id, _)| *row_id)
                        .collect()
                };
                let delete_predicates = ws
                    .relational_delete_predicates
                    .iter()
                    .filter(|predicate| predicate.table == table)
                    .cloned()
                    .collect::<Vec<_>>();
                let overlap = ws.relational_inserts.iter().find_map(|(t, row)| {
                    if t != table {
                        return None;
                    }
                    if let Some(sid) = skip_row_id
                        && row.row_id == sid
                    {
                        return None;
                    }
                    if row.values.get(column) == Some(value) {
                        Some(row.row_id)
                    } else {
                        None
                    }
                });
                (deletes, delete_predicates, overlap)
            })?;
        let entries = {
            let indexes = self.relational_store.indexes.read();
            // Prefer conventional auto-index names when they still match the
            // requested column, then fall back to any exact single-column index.
            let pk_key = format!("__pk_{column}");
            let unique_key = format!("__unique_{column}");
            let storage = indexes.get(table).and_then(|table_indexes| {
                table_indexes
                    .get(&pk_key)
                    .filter(|idx| idx.columns.len() == 1 && idx.columns[0].0 == column)
                    .or_else(|| {
                        table_indexes
                            .get(&unique_key)
                            .filter(|idx| idx.columns.len() == 1 && idx.columns[0].0 == column)
                    })
                    .or_else(|| {
                        table_indexes
                            .values()
                            .find(|idx| idx.columns.len() == 1 && idx.columns[0].0 == column)
                    })
            });
            let Some(storage) = storage else {
                return Ok(ConstraintProbe::NoIndex);
            };
            let key = vec![DirectedValue::Asc(TotalOrdAsc(value.clone()))];
            storage
                .exact_postings(&key)
                .map(|entries| entries.to_vec())
                .unwrap_or_default()
        };
        for entry in entries {
            if let Some(sid) = skip_row_id
                && entry.row_id == sid
            {
                continue;
            }
            if tx_staged_deletes.contains(&entry.row_id) {
                continue;
            }
            if !tx_delete_predicates.is_empty()
                && let Some(row) = self
                    .relational_store
                    .row_by_id(table, entry.row_id, snapshot)
                && row_matches_delete_predicates(&tx_delete_predicates, table, &row)
            {
                continue;
            }
            if entry.visible_at(snapshot) {
                return Ok(ConstraintProbe::Match(entry.row_id));
            }
        }
        Ok(match staged_overlap {
            Some(row_id) => ConstraintProbe::Match(row_id),
            None => ConstraintProbe::NoMatch,
        })
    }

    /// Probe a composite UNIQUE (a, b, ...) using the first index whose
    /// leading prefix matches `cols`. The probe walks the range for the full
    /// key prefix.
    fn probe_composite_unique(
        &self,
        tx: TxId,
        table: &str,
        cols: &[String],
        values: &[Value],
        snapshot: SnapshotId,
        skip_row_id: Option<RowId>,
    ) -> Result<Option<RowId>> {
        if cols.is_empty() || values.is_empty() || cols.len() != values.len() {
            return Ok(None);
        }
        // Rows this tx has already staged for delete are not obstructions.
        let (tx_staged_deletes, tx_delete_predicates): (
            std::collections::HashSet<RowId>,
            Vec<RelationalDeletePredicate>,
        ) = self.tx_mgr.with_write_set(tx, |ws| {
            let deletes = ws
                .relational_deletes
                .iter()
                .filter(|(t, _, _)| t == table)
                .map(|(_, row_id, _)| *row_id)
                .collect();
            let predicates = ws
                .relational_delete_predicates
                .iter()
                .filter(|predicate| predicate.table == table)
                .cloned()
                .collect();
            (deletes, predicates)
        })?;
        let index_name = self.relational_store.table_meta(table).and_then(|meta| {
            meta.indexes
                .iter()
                .find(|decl| {
                    decl.columns.len() >= cols.len()
                        && (decl.kind != IndexKind::Auto || decl.columns.len() == cols.len())
                        && decl
                            .columns
                            .iter()
                            .zip(cols.iter())
                            .all(|((c, _), w)| c == w)
                })
                .map(|decl| decl.name.clone())
        });
        let Some(index_name) = index_name else {
            return Ok(None);
        };
        let entries = {
            let indexes = self.relational_store.indexes.read();
            let Some(storage) = indexes
                .get(table)
                .and_then(|table_indexes| table_indexes.get(&index_name))
            else {
                return Ok(None);
            };
            let prefix = index_key_from_values(&storage.columns[..cols.len()], values);
            if storage.columns.len() == cols.len() {
                storage
                    .exact_postings(&prefix)
                    .map(|entries| entries.to_vec())
                    .unwrap_or_default()
            } else {
                storage
                    .tree
                    .range(prefix.clone()..)
                    .take_while(|(key, _)| {
                        key.len() >= prefix.len() && key[..prefix.len()] == prefix[..]
                    })
                    .flat_map(|(_, entries)| entries.iter().cloned())
                    .collect::<Vec<_>>()
            }
        };
        for entry in entries {
            if let Some(sid) = skip_row_id
                && entry.row_id == sid
            {
                continue;
            }
            if tx_staged_deletes.contains(&entry.row_id) {
                continue;
            }
            if !tx_delete_predicates.is_empty()
                && let Some(row) = self
                    .relational_store
                    .row_by_id(table, entry.row_id, snapshot)
                && row_matches_delete_predicates(&tx_delete_predicates, table, &row)
            {
                continue;
            }
            if entry.visible_at(snapshot) {
                return Ok(Some(entry.row_id));
            }
        }
        // Tx-staged inserts.
        let overlap = self.tx_mgr.with_write_set(tx, |ws| {
            for (t, row) in &ws.relational_inserts {
                if t != table {
                    continue;
                }
                if let Some(sid) = skip_row_id
                    && row.row_id == sid
                {
                    continue;
                }
                let matches = cols
                    .iter()
                    .zip(values.iter())
                    .all(|(c, v)| row.values.get(c) == Some(v));
                if matches {
                    return Some(row.row_id);
                }
            }
            None
        })?;
        Ok(overlap)
    }

    pub(crate) fn rewrite_txid_placeholders(
        &self,
        origin_tx: TxId,
        ws: &mut WriteSet,
    ) -> Result<()> {
        for (table, row) in &mut ws.relational_inserts {
            self.rewrite_txid_placeholders_in_values(
                table,
                origin_tx,
                row.created_tx,
                &mut row.values,
            );
        }
        Ok(())
    }

    fn rewrite_txid_placeholders_for_rows_not_in(
        &self,
        origin_tx: TxId,
        ws: &mut WriteSet,
        baseline: &HashSet<(String, RowId)>,
    ) {
        for (table, row) in &mut ws.relational_inserts {
            if baseline.contains(&(table.clone(), row.row_id)) {
                continue;
            }
            self.rewrite_txid_placeholders_in_values(
                table,
                origin_tx,
                row.created_tx,
                &mut row.values,
            );
        }
    }

    fn rewrite_txid_placeholders_in_values(
        &self,
        table: &str,
        origin_tx: TxId,
        canonical_tx: TxId,
        values: &mut HashMap<ColName, Value>,
    ) {
        let Some(meta) = self.table_meta(table) else {
            return;
        };
        for column in meta
            .columns
            .iter()
            .filter(|column| matches!(column.column_type, ColumnType::TxId))
        {
            if matches!(values.get(&column.name), Some(Value::TxId(tx)) if *tx == origin_tx) {
                values.insert(column.name.clone(), Value::TxId(canonical_tx));
            }
        }
    }

    fn commit_validate(
        &self,
        origin_tx: TxId,
        ws: &mut WriteSet,
    ) -> Result<CommitValidationOutcome> {
        // The guards below are one-shot: each describes work this pass is
        // about to validate and must not be re-applied. The recorded vector
        // schema epochs are NOT one-shot — they describe the whole
        // transaction, which an opted-in sync trigger can bring back here
        // more than once: dispatching a callback that writes into the applying
        // transaction re-enters commit validation for the same tx. Draining
        // the epochs with the guards left a later pass with nothing to compare
        // against, and an unchanged vector index was reported as concurrently
        // altered. They stay until the transaction itself ends, where every
        // commit and rollback path already clears this entry.
        let metadata = {
            let mut pending = self.pending_commit_metadata.lock();
            let entry = pending.entry(origin_tx).or_default();
            PendingCommitMetadata {
                discard_selections: entry.discard_selections.clone(),
                conditional_update_guards: std::mem::take(&mut entry.conditional_update_guards),
                sync_lineage_guards: std::mem::take(&mut entry.sync_lineage_guards),
                upsert_intents: std::mem::take(&mut entry.upsert_intents),
                vector_schema_epochs: entry.vector_schema_epochs.clone(),
                delivery_registrations: Vec::new(),
            }
        };
        let snapshot = self.snapshot();
        let mut stats_guard = CommitStageStatsGuard::new(self);
        #[cfg(feature = "test-seams")]
        let mut stage_timer = CommitStageTimer::new();
        self.validate_sync_lineage_guards(snapshot, &metadata.sync_lineage_guards)?;
        let validation = self.revalidate_conditional_updates(
            ws,
            snapshot,
            &metadata.conditional_update_guards,
            Some(stats_guard.stats_mut()),
        )?;
        #[cfg(feature = "test-seams")]
        stage_timer.record(stats_guard.stats_mut(), 0);
        self.validate_vector_schema_epochs(ws, &metadata.vector_schema_epochs)?;
        self.validate_vector_write_set_schema(ws)?;
        self.discard_deletes_of_rows_that_are_already_gone(ws);
        let mut deleted_rows_by_table = self.deleted_row_snapshots_by_table(ws);
        self.validate_unique_constraints_in_write_set(
            ws,
            snapshot,
            &metadata.upsert_intents,
            &mut deleted_rows_by_table,
            stats_guard.stats_mut(),
        )?;
        #[cfg(feature = "test-seams")]
        stage_timer.record(stats_guard.stats_mut(), 1);
        self.validate_foreign_keys_in_write_set(
            ws,
            snapshot,
            &deleted_rows_by_table,
            stats_guard.stats_mut(),
        )?;
        #[cfg(feature = "test-seams")]
        stage_timer.record(stats_guard.stats_mut(), 2);
        self.validate_composite_foreign_keys_in_write_set(
            ws,
            snapshot,
            &deleted_rows_by_table,
            stats_guard.stats_mut(),
        )?;
        #[cfg(feature = "test-seams")]
        stage_timer.record(stats_guard.stats_mut(), 3);
        self.validate_vector_schema_epochs(ws, &metadata.vector_schema_epochs)?;
        self.validate_vector_write_set_schema(ws)?;
        #[cfg(feature = "test-seams")]
        stage_timer.record(stats_guard.stats_mut(), 4);
        stats_guard.flush();
        Ok(validation)
    }

    fn validate_vector_schema_epochs(
        &self,
        ws: &WriteSet,
        recorded_epochs: &HashMap<VectorIndexRef, u64>,
    ) -> Result<()> {
        for index in Self::write_set_vector_schema_refs(ws) {
            let Some(recorded_epoch) = recorded_epochs.get(&index) else {
                return Err(Self::stale_vector_schema_error(&index));
            };
            let current_epoch = self.vector_schema_gates.epoch_for(&index);
            if current_epoch != *recorded_epoch {
                return Err(Self::stale_vector_schema_error(&index));
            }
        }
        Ok(())
    }

    fn stale_vector_schema_error(index: &VectorIndexRef) -> Error {
        Error::SchemaInvalid {
            reason: format!(
                "vector index {}.{} changed while transaction was open; retry transaction",
                index.table, index.column
            ),
        }
    }

    fn validate_vector_write_set_schema(&self, ws: &WriteSet) -> Result<()> {
        // A received unit that declares a table AND carries that table's
        // vectors commits both together atomically. At this
        // point the table exists only in the prepared stage, so reading the
        // receiver's CURRENT shape would refuse the unit for not yet having
        // installed the very schema it is installing. The detached worker has
        // already run this exact check against the arriving shape, with the
        // table and its declared layout present, which is what makes skipping
        // it here a re-check rather than a missing one.
        if ws
            .commit_lsn
            .is_some_and(|lsn| self.received_schema_stages.lock().contains_key(&lsn))
        {
            return Ok(());
        }
        let mut refs = ws
            .vector_inserts
            .iter()
            .map(|entry| entry.index.clone())
            .chain(ws.vector_deletes.iter().map(|(index, _, _)| index.clone()))
            .chain(ws.vector_moves.iter().map(|(index, _, _, _)| index.clone()))
            .collect::<Vec<_>>();
        refs.sort_by(|a, b| a.table.cmp(&b.table).then(a.column.cmp(&b.column)));
        refs.dedup();

        for index in refs {
            let Some(meta) = self.table_meta(&index.table) else {
                return Err(Error::UnknownVectorIndex { index });
            };
            let Some(column) = meta
                .columns
                .iter()
                .find(|column| column.name == index.column)
            else {
                return Err(Error::UnknownVectorIndex { index });
            };
            let ColumnType::Vector(expected) = column.column_type else {
                return Err(Error::UnknownVectorIndex { index });
            };
            let layout = self.vector_store.index_layout(&index)?;
            if layout.dimension != expected {
                return Err(Error::VectorIndexDimensionMismatch {
                    index,
                    expected,
                    actual: layout.dimension,
                });
            }
        }

        for entry in &ws.vector_inserts {
            let expected = self.vector_store.index_layout(&entry.index)?.dimension;
            if entry.vector.len() != expected {
                return Err(Error::VectorIndexDimensionMismatch {
                    index: entry.index.clone(),
                    expected,
                    actual: entry.vector.len(),
                });
            }
        }
        for (table, row) in &ws.relational_inserts {
            let Some(meta) = self.table_meta(table) else {
                continue;
            };
            for (column_name, value) in &row.values {
                let Value::Vector(vector) = value else {
                    continue;
                };
                let index = VectorIndexRef::new(table, column_name);
                let Some(column) = meta
                    .columns
                    .iter()
                    .find(|column| column.name == *column_name)
                else {
                    return Err(Error::UnknownVectorIndex { index });
                };
                let ColumnType::Vector(expected) = column.column_type else {
                    return Err(Error::UnknownVectorIndex { index });
                };
                if vector.len() != expected {
                    return Err(Error::VectorIndexDimensionMismatch {
                        index,
                        expected,
                        actual: vector.len(),
                    });
                }
            }
        }

        Ok(())
    }

    fn take_conditional_update_guards_for_tx(
        &self,
        tx: TxId,
    ) -> Vec<PendingConditionalUpdateGuard> {
        self.pending_commit_metadata
            .lock()
            .get_mut(&tx)
            .map(|metadata| std::mem::take(&mut metadata.conditional_update_guards))
            .unwrap_or_default()
    }

    /// What the durable writer's own in-memory retention is charged right
    /// now: the change log with its two side indexes, and the transaction
    /// manager's commit index.
    ///
    /// Both grow with the import and are trimmed only by a maintenance cycle
    /// the caller drives, so both are charged; this is the figure a close
    /// hands back, because the store stops holding them when it goes away.
    fn durable_writer_retained_bytes(&self) -> usize {
        // A committed read image is not a writer. It never appends a
        // change-log entry and never adds a commit-index entry, and the image
        // it holds of both was admitted when it was decoded -- so it is
        // charged nothing at this door and has nothing to hand back at close
        // or drop.
        if self.read_image_memory.is_some() {
            return 0;
        }
        crate::composite_store::change_log_retained_bytes(&self.change_log.read())
            .saturating_add(
                self.tx_mgr
                    .commit_index_prefix(Lsn(u64::MAX))
                    .len()
                    .saturating_mul(crate::composite_store::COMMIT_INDEX_ENTRY_BYTES),
            )
            .saturating_add(
                self.persistence
                    .as_ref()
                    .map_or(0, |persistence| persistence.cache_charge()),
            )
    }

    /// The same figure, for a proof that measures what storing a ROW costs.
    ///
    /// A proof about what STORING A ROW costs reads the accountant net of
    /// this. The two are different retentions with different lifetimes: a
    /// row's charge comes back when the row does, while the log keeps the
    /// history of that row being stored and deleted until a maintenance
    /// cycle trims it -- which is a thing the store is still holding, and a
    /// declared limit has to see it.
    #[cfg(any(test, feature = "test-seams"))]
    #[doc(hidden)]
    pub fn __durable_writer_charged_bytes_for_test(&self) -> usize {
        self.durable_writer_retained_bytes()
    }

    /// Test-only forced log-gap seam. Durable store state remains intact, so
    /// the next extraction must exercise the same persisted-state fallback a
    /// peer encounters when its requested watermark predates available logs.
    #[cfg(feature = "test-seams")]
    #[doc(hidden)]
    pub fn __force_sync_log_gap_for_test(&self) {
        let _schema_publication = self.enter_schema_publication_gate(false);
        self.with_commit_lock(|| {
            let mut change_log = self.change_log.write();
            self.accountant
                .release(crate::composite_store::change_log_retained_bytes(
                    &change_log,
                ));
            change_log.clear();
            drop(change_log);
            self.change_log_table_index.write().clear();
            self.change_log_lsn_refcounts.write().clear();
            self.ddl_log.write().clear();
        });
    }

    /// Test-only: drop the change log alone, keeping the schema log, as a
    /// store whose change history was pruned keeps its schema history.
    #[cfg(feature = "test-seams")]
    #[doc(hidden)]
    pub fn __force_change_log_gap_for_test(&self) {
        let _schema_publication = self.enter_schema_publication_gate(false);
        self.with_commit_lock(|| {
            self.change_log.write().clear();
            self.change_log_table_index.write().clear();
            self.change_log_lsn_refcounts.write().clear();
        });
    }

    fn pending_upsert_intents_for_tx(&self, tx: TxId) -> Vec<PendingUpsertIntent> {
        self.pending_commit_metadata
            .lock()
            .get(&tx)
            .map(|metadata| metadata.upsert_intents.clone())
            .unwrap_or_default()
    }

    fn upsert_intent_indexes_by_row(
        upsert_intents: &[PendingUpsertIntent],
    ) -> HashMap<(TableName, RowId), Vec<usize>> {
        let mut indexes = HashMap::<(TableName, RowId), Vec<usize>>::new();
        for (index, intent) in upsert_intents.iter().enumerate() {
            indexes
                .entry((intent.table.clone(), intent.row_id))
                .or_default()
                .push(index);
        }
        indexes
    }

    fn upsert_intent_index_by_conflict(
        upsert_intents: &[PendingUpsertIntent],
    ) -> HashMap<(TableName, RowId, Vec<ColName>), usize> {
        let mut indexes = HashMap::<(TableName, RowId, Vec<ColName>), usize>::new();
        for (index, intent) in upsert_intents.iter().enumerate() {
            indexes
                .entry((
                    intent.table.clone(),
                    intent.row_id,
                    intent.conflict_columns.clone(),
                ))
                .or_insert(index);
        }
        indexes
    }

    fn rewrite_commit_time_upserts_for_write_set(
        &self,
        ws: &mut WriteSet,
        snapshot: SnapshotId,
        upsert_intents: &[PendingUpsertIntent],
    ) -> Result<()> {
        if upsert_intents.is_empty() {
            return Ok(());
        }
        let upsert_lookup = CommitTimeUpsertLookup {
            intents: upsert_intents,
            by_row: Self::upsert_intent_indexes_by_row(upsert_intents),
        };
        let mut deleted_by_table = Self::deleted_row_ids_by_table(ws);
        let empty_deleted = HashSet::new();
        let mut index = 0;
        while index < ws.relational_inserts.len() {
            let table = ws.relational_inserts[index].0.clone();
            let skip_deleted = deleted_by_table.get(&table).unwrap_or(&empty_deleted);
            let prefix = Self::relational_insert_prefix_identity(ws, index);
            if let Some(rewrite) = self.apply_original_commit_time_upsert_if_needed(
                ws,
                index,
                skip_deleted,
                &upsert_lookup,
                snapshot,
                None,
            )? {
                deleted_by_table = Self::deleted_row_ids_by_table(ws);
                index =
                    Self::relational_insert_index_by_row(ws, &rewrite.table, rewrite.row_id, index)
                        .unwrap_or_else(|| {
                            if Self::relational_insert_prefix_unchanged(ws, &prefix) {
                                index.saturating_add(1)
                            } else {
                                index.min(ws.relational_inserts.len())
                            }
                        });
                continue;
            }
            index += 1;
        }
        Ok(())
    }

    fn deleted_row_ids_for_table(ws: &WriteSet, table: &str) -> HashSet<RowId> {
        ws.relational_deletes
            .iter()
            .filter(|(t, _, _)| t == table)
            .map(|(_, row_id, _)| *row_id)
            .collect()
    }

    /// Drop a staged delete whose row is no longer there to delete.
    ///
    /// Another writer can delete the same row between the moment this
    /// transaction staged its `DELETE` and the moment it commits. The delete
    /// then has nothing to do, and a no-op has to be traceless: leaving it in
    /// the write set would write a second deletion record into history and
    /// raise an outbound deletion obligation for a row this node did not
    /// delete. A row this same transaction is inserting is not gone -- it has
    /// simply not been committed yet -- so its delete stays.
    fn discard_deletes_of_rows_that_are_already_gone(&self, ws: &mut WriteSet) {
        if ws.relational_deletes.is_empty() {
            return;
        }
        let live = self.deleted_row_snapshots_by_table(ws);
        let staged = ws
            .relational_inserts
            .iter()
            .map(|(table, row)| (table.clone(), row.row_id))
            .collect::<HashSet<_>>();
        let mut discarded = HashSet::new();
        ws.relational_deletes.retain(|(table, row_id, _)| {
            let keep = live
                .get(table)
                .is_some_and(|rows| rows.contains_key(row_id))
                || staged.contains(&(table.clone(), *row_id));
            if !keep {
                discarded.insert((table.clone(), *row_id));
            }
            keep
        });
        if discarded.is_empty() {
            return;
        }
        // The delete also staged this row's outgoing deletion obligation. That
        // obligation is the part a peer would see, so a traceless no-op has to
        // drop it too, or the next push carries a deletion this node never
        // performed.
        ws.config_writes.retain(|(key, encoded)| {
            if !key.starts_with(Self::DURABLE_LINEAGE_CONFIG_PREFIX) {
                return true;
            }
            let Ok(record) = RedbPersistence::decode_config_value::<DurableLineageRecord>(encoded)
            else {
                return true;
            };
            if record.delete_obligation != DurableDeleteObligation::Pending {
                return true;
            }
            let Some(row_id) = record.local_row_id else {
                return true;
            };
            !discarded.contains(&(record.table.clone(), row_id))
        });
    }

    fn deleted_row_ids_by_table(ws: &WriteSet) -> HashMap<String, HashSet<RowId>> {
        let mut deleted = HashMap::<String, HashSet<RowId>>::new();
        for (table, row_id, _) in &ws.relational_deletes {
            deleted.entry(table.clone()).or_default().insert(*row_id);
        }
        deleted
    }

    fn deleted_row_snapshots_by_table(
        &self,
        ws: &WriteSet,
    ) -> HashMap<String, HashMap<RowId, VersionedRow>> {
        if ws.relational_deletes.is_empty() {
            return HashMap::new();
        }
        let mut seen = HashSet::new();
        let mut keys = Vec::with_capacity(ws.relational_deletes.len());
        for (table, row_id, _) in &ws.relational_deletes {
            if seen.insert((table.clone(), *row_id)) {
                keys.push((table.clone(), *row_id));
            }
        }
        self.relational_store.live_rows_by_id(&keys)
    }

    fn relational_insert_prefix_identity(ws: &WriteSet, end: usize) -> Vec<(String, RowId)> {
        ws.relational_inserts
            .iter()
            .take(end)
            .map(|(table, row)| (table.clone(), row.row_id))
            .collect()
    }

    fn relational_insert_prefix_unchanged(ws: &WriteSet, expected: &[(String, RowId)]) -> bool {
        ws.relational_inserts.len() >= expected.len()
            && ws.relational_inserts.iter().zip(expected.iter()).all(
                |((table, row), (expected_table, expected_row_id))| {
                    table == expected_table && row.row_id == *expected_row_id
                },
            )
    }

    fn value_can_be_tuple_key(value: &Value) -> bool {
        !matches!(value, Value::Float64(_) | Value::Json(_) | Value::Vector(_))
    }

    fn values_can_be_tuple_key(values: &[Value]) -> bool {
        values.iter().all(Self::value_can_be_tuple_key)
    }

    fn add_staged_tuple_columns(
        columns_by_table: &mut HashMap<String, Vec<Vec<String>>>,
        table: &str,
        columns: Vec<String>,
    ) {
        if columns.is_empty() {
            return;
        }
        let table_columns = columns_by_table.entry(table.to_string()).or_default();
        if !table_columns.iter().any(|existing| existing == &columns) {
            table_columns.push(columns);
        }
    }

    fn staged_tuple_key_columns_by_table(&self) -> HashMap<String, Vec<Vec<String>>> {
        let metas = self.relational_store.table_meta.read();
        let mut columns_by_table = HashMap::<String, Vec<Vec<String>>>::new();

        for (table, meta) in metas.iter() {
            for column in &meta.columns {
                if column.primary_key || column.unique {
                    Self::add_staged_tuple_columns(
                        &mut columns_by_table,
                        table,
                        vec![column.name.clone()],
                    );
                }
                if let Some(reference) = &column.references {
                    Self::add_staged_tuple_columns(
                        &mut columns_by_table,
                        table,
                        vec![column.name.clone()],
                    );
                    Self::add_staged_tuple_columns(
                        &mut columns_by_table,
                        &reference.table,
                        vec![reference.column.clone()],
                    );
                }
            }

            for unique_constraint in meta.enforced_unique_tuples() {
                Self::add_staged_tuple_columns(
                    &mut columns_by_table,
                    table,
                    unique_constraint.clone(),
                );
            }

            for fk in &meta.composite_foreign_keys {
                Self::add_staged_tuple_columns(
                    &mut columns_by_table,
                    table,
                    fk.child_columns.clone(),
                );
                Self::add_staged_tuple_columns(
                    &mut columns_by_table,
                    &fk.parent_table,
                    fk.parent_columns.clone(),
                );
            }
        }

        columns_by_table
    }

    fn add_commit_stat(counter: &AtomicU64, delta: u64) {
        if delta > 0 {
            counter.fetch_add(delta, Ordering::SeqCst);
        }
    }

    fn add_commit_stage_stats(&self, stats: &CommitStageStats) {
        Self::add_commit_stat(&self.commit_rows_validated, stats.rows_validated);
        Self::add_commit_stat(&self.commit_indexed_probes, stats.indexed_probes);
        Self::add_commit_stat(
            &self.commit_staged_vs_staged_comparisons,
            stats.staged_vs_staged_comparisons,
        );
        Self::add_commit_stat(&self.commit_scan_rows_touched, stats.scan_rows_touched);
        Self::add_commit_stat(
            &self.commit_index_maintenance_visits,
            stats.index_maintenance_visits,
        );
        #[cfg(feature = "test-seams")]
        if let Some(stage_wall_nanos) = stats.stage_wall_nanos {
            for (counter, delta) in self.commit_stage_wall_nanos.iter().zip(stage_wall_nanos) {
                Self::add_commit_stat(counter, delta);
            }
        }
    }

    fn committed_unique_conflict_row_id(
        &self,
        table: &str,
        columns: &[String],
        values: &[Value],
        snapshot: SnapshotId,
        skip_deleted: &HashSet<RowId>,
        stats: Option<&mut CommitStageStats>,
    ) -> Result<Option<RowId>> {
        let mut stats = stats;
        if columns.is_empty() || columns.len() != values.len() {
            return Ok(None);
        }

        if let Some(row_id) = self.indexed_visible_row_id_by_columns(
            table,
            columns,
            values,
            snapshot,
            skip_deleted,
            stats.as_deref_mut(),
        ) {
            return Ok(row_id);
        }

        let before_scan_rows = stats
            .as_ref()
            .map(|_| self.relational_store.scan_rows_touched());
        let rows = self
            .relational
            .scan_filter_with_tx(None, table, snapshot, &|row| {
                !skip_deleted.contains(&row.row_id)
                    && columns
                        .iter()
                        .zip(values.iter())
                        .all(|(column, value)| row.values.get(column) == Some(value))
            })?;
        if let (Some(stats), Some(before_scan_rows)) = (stats, before_scan_rows) {
            stats.scan_rows_touched = stats.scan_rows_touched.saturating_add(
                self.relational_store
                    .scan_rows_touched()
                    .saturating_sub(before_scan_rows),
            );
        }
        Ok(rows.into_iter().next().map(|row| row.row_id))
    }

    fn indexed_visible_row_id_by_columns(
        &self,
        table: &str,
        columns: &[String],
        values: &[Value],
        snapshot: SnapshotId,
        skip_deleted: &HashSet<RowId>,
        stats: Option<&mut CommitStageStats>,
    ) -> Option<Option<RowId>> {
        if columns.is_empty() || columns.len() != values.len() {
            return Some(None);
        }

        fn visible_posting(
            entries: &[contextdb_relational::IndexEntry],
            snapshot: SnapshotId,
            skip_deleted: &HashSet<RowId>,
        ) -> Option<RowId> {
            entries
                .iter()
                .find(|entry| !skip_deleted.contains(&entry.row_id) && entry.visible_at(snapshot))
                .map(|entry| entry.row_id)
        }

        let (index_checked, indexed_row_id) = {
            let indexes = self.relational_store.indexes.read();
            if columns.len() == 1 {
                let column = &columns[0];
                let pk_key = format!("__pk_{column}");
                let unique_key = format!("__unique_{column}");
                let storage = indexes.get(table).and_then(|table_indexes| {
                    table_indexes
                        .get(&pk_key)
                        .filter(|idx| idx.columns.len() == 1 && idx.columns[0].0 == *column)
                        .or_else(|| {
                            table_indexes
                                .get(&unique_key)
                                .filter(|idx| idx.columns.len() == 1 && idx.columns[0].0 == *column)
                        })
                        .or_else(|| {
                            table_indexes
                                .values()
                                .find(|idx| idx.columns.len() == 1 && idx.columns[0].0 == *column)
                        })
                });
                match storage {
                    Some(storage) => {
                        let key = index_key_from_values(&storage.columns[..1], values);
                        (
                            true,
                            storage.exact_postings(&key).and_then(|entries| {
                                visible_posting(entries, snapshot, skip_deleted)
                            }),
                        )
                    }
                    None => (false, None),
                }
            } else {
                let storage = indexes.get(table).and_then(|table_indexes| {
                    table_indexes.values().find(|idx| {
                        idx.columns.len() >= columns.len()
                            && (!idx.exact_only() || idx.columns.len() == columns.len())
                            && idx
                                .columns
                                .iter()
                                .zip(columns.iter())
                                .all(|((have, _), want)| have == want)
                    })
                });
                match storage {
                    Some(storage) => {
                        let prefix =
                            index_key_from_values(&storage.columns[..columns.len()], values);
                        let row_id = if storage.columns.len() == columns.len() {
                            storage.exact_postings(&prefix).and_then(|entries| {
                                visible_posting(entries, snapshot, skip_deleted)
                            })
                        } else {
                            storage
                                .tree
                                .range(prefix.clone()..)
                                .take_while(|(key, _)| {
                                    key.len() >= prefix.len() && key[..prefix.len()] == prefix[..]
                                })
                                .find_map(|(_, entries)| {
                                    visible_posting(entries, snapshot, skip_deleted)
                                })
                        };
                        (true, row_id)
                    }
                    None => (false, None),
                }
            }
        };

        if !index_checked {
            return None;
        }

        if let Some(stats) = stats {
            stats.indexed_probes = stats.indexed_probes.saturating_add(1);
        }
        Some(indexed_row_id)
    }

    fn required_indexed_visible_row_by_columns(
        &self,
        table: &str,
        columns: &[String],
        values: &[Value],
        snapshot: SnapshotId,
        skip_deleted: &HashSet<RowId>,
    ) -> Result<Option<VersionedRow>> {
        let Some(row_id) = self.indexed_visible_row_id_by_columns(
            table,
            columns,
            values,
            snapshot,
            skip_deleted,
            None,
        ) else {
            return Err(Error::Other(format!(
                "exact sync key probe on {table}({}) has no covering index",
                columns.join(", ")
            )));
        };
        Ok(row_id.and_then(|row_id| self.relational_store.row_by_id(table, row_id, snapshot)))
    }

    fn required_indexed_visible_row_by_column(
        &self,
        table: &str,
        column: &str,
        value: &Value,
        snapshot: SnapshotId,
        skip_deleted: &HashSet<RowId>,
    ) -> Result<Option<VersionedRow>> {
        let columns = vec![column.to_string()];
        let values = vec![value.clone()];
        self.required_indexed_visible_row_by_columns(
            table,
            &columns,
            &values,
            snapshot,
            skip_deleted,
        )
    }

    fn committed_unique_conflict(
        &self,
        table: &str,
        columns: &[String],
        values: &[Value],
        snapshot: SnapshotId,
        skip_deleted: &HashSet<RowId>,
        stats: Option<&mut CommitStageStats>,
    ) -> Result<Option<VersionedRow>> {
        let Some(row_id) = self.committed_unique_conflict_row_id(
            table,
            columns,
            values,
            snapshot,
            skip_deleted,
            stats,
        )?
        else {
            return Ok(None);
        };
        Ok(self.relational_store.row_by_id(table, row_id, snapshot))
    }

    fn committed_unique_probe_required_for_replacement(
        &self,
        row_id: RowId,
        columns: &[String],
        values: &[Value],
        skip_deleted: &HashSet<RowId>,
        deleted_rows: Option<&HashMap<RowId, VersionedRow>>,
    ) -> bool {
        if !skip_deleted.contains(&row_id) {
            return true;
        }
        !deleted_rows
            .and_then(|rows| rows.get(&row_id))
            .is_some_and(|committed| {
                columns
                    .iter()
                    .zip(values.iter())
                    .all(|(column, value)| committed.values.get(column) == Some(value))
            })
    }

    fn staged_unique_conflict_in_write_set(
        ws: &WriteSet,
        insert_index: usize,
        table: &str,
        columns: &[String],
        values: &[Value],
        stats: Option<&mut CommitStageStats>,
    ) -> Option<RowId> {
        let mut stats = stats;
        for (other_index, (other_table, other_row)) in ws.relational_inserts.iter().enumerate() {
            if other_index == insert_index || other_table != table {
                continue;
            }
            if let Some(stats) = stats.as_deref_mut() {
                stats.staged_vs_staged_comparisons =
                    stats.staged_vs_staged_comparisons.saturating_add(1);
            }
            if ws.relational_inserts[insert_index].1.row_id == other_row.row_id {
                continue;
            }
            if columns
                .iter()
                .zip(values.iter())
                .all(|(column, value)| other_row.values.get(column) == Some(value))
            {
                return Some(other_row.row_id);
            }
        }
        None
    }

    fn indexed_visible_row_exists(
        &self,
        table: &str,
        column: &str,
        value: &Value,
        snapshot: SnapshotId,
        skip_deleted: &HashSet<RowId>,
        stats: Option<&mut CommitStageStats>,
    ) -> Option<bool> {
        use contextdb_core::{DirectedValue, TotalOrdAsc, TotalOrdDesc};

        let indexes = self.relational_store.indexes.read();
        let pk_key = format!("__pk_{column}");
        let unique_key = format!("__unique_{column}");
        let storage = indexes.get(table).and_then(|table_indexes| {
            table_indexes
                .get(&pk_key)
                .filter(|idx| idx.columns.len() == 1 && idx.columns[0].0 == column)
                .or_else(|| {
                    table_indexes
                        .get(&unique_key)
                        .filter(|idx| idx.columns.len() == 1 && idx.columns[0].0 == column)
                })
                .or_else(|| {
                    table_indexes
                        .values()
                        .find(|idx| idx.columns.len() == 1 && idx.columns[0].0 == column)
                })
        })?;
        let key = match storage.columns.first().map(|(_, direction)| direction) {
            Some(SortDirection::Desc) => vec![DirectedValue::Desc(TotalOrdDesc(value.clone()))],
            _ => vec![DirectedValue::Asc(TotalOrdAsc(value.clone()))],
        };
        if let Some(stats) = stats {
            stats.indexed_probes = stats.indexed_probes.saturating_add(1);
        }
        Some(storage.exact_postings(&key).is_some_and(|entries| {
            entries
                .iter()
                .any(|entry| !skip_deleted.contains(&entry.row_id) && entry.visible_at(snapshot))
        }))
    }

    fn visible_row_exists_by_column(
        &self,
        table: &str,
        column: &str,
        value: &Value,
        snapshot: SnapshotId,
        skip_deleted: &HashSet<RowId>,
        stats: Option<&mut CommitStageStats>,
    ) -> Result<bool> {
        let mut stats = stats;
        if let Some(exists) = self.indexed_visible_row_exists(
            table,
            column,
            value,
            snapshot,
            skip_deleted,
            stats.as_deref_mut(),
        ) {
            return Ok(exists);
        }

        let before_scan_rows = stats
            .as_ref()
            .map(|_| self.relational_store.scan_rows_touched());
        let rows = self
            .relational
            .scan_filter_with_tx(None, table, snapshot, &|row| {
                !skip_deleted.contains(&row.row_id) && row.values.get(column) == Some(value)
            })?;
        if let (Some(stats), Some(before_scan_rows)) = (stats, before_scan_rows) {
            stats.scan_rows_touched = stats.scan_rows_touched.saturating_add(
                self.relational_store
                    .scan_rows_touched()
                    .saturating_sub(before_scan_rows),
            );
        }
        Ok(!rows.is_empty())
    }

    /// The committed row carrying a whole sync identity — every key column
    /// matched through the covering index.
    fn visible_row_by_natural_key(
        &self,
        table: &str,
        natural_key: &NaturalKey,
        snapshot: SnapshotId,
        skip_deleted: &HashSet<RowId>,
    ) -> Result<Option<VersionedRow>> {
        self.required_indexed_visible_row_by_columns(
            table,
            &natural_key.key_columns(),
            &natural_key.key_values(),
            snapshot,
            skip_deleted,
        )
    }

    fn indexed_visible_row_exists_by_columns(
        &self,
        table: &str,
        columns: &[String],
        values: &[Value],
        snapshot: SnapshotId,
        skip_deleted: &HashSet<RowId>,
        stats: Option<&mut CommitStageStats>,
    ) -> Result<bool> {
        if columns.is_empty() || columns.len() != values.len() {
            return Ok(false);
        }

        fn visible_posting(
            entries: &[contextdb_relational::IndexEntry],
            snapshot: SnapshotId,
            skip_deleted: &HashSet<RowId>,
        ) -> Option<RowId> {
            entries
                .iter()
                .find(|entry| !skip_deleted.contains(&entry.row_id) && entry.visible_at(snapshot))
                .map(|entry| entry.row_id)
        }

        let row_id = {
            let indexes = self.relational_store.indexes.read();
            let Some(storage) = indexes.get(table).and_then(|table_indexes| {
                table_indexes.values().find(|storage| {
                    storage.columns.len() >= columns.len()
                        && (!storage.exact_only() || storage.columns.len() == columns.len())
                        && storage
                            .columns
                            .iter()
                            .zip(columns.iter())
                            .all(|((indexed_column, _), wanted)| indexed_column == wanted)
                })
            }) else {
                self.fk_full_scan_fallbacks.fetch_add(1, Ordering::SeqCst);
                return Err(Error::Other(format!(
                    "composite foreign key probe on {table}({}) has no covering index",
                    columns.join(", ")
                )));
            };

            self.fk_indexed_tuple_probes.fetch_add(1, Ordering::SeqCst);
            if let Some(stats) = stats {
                stats.indexed_probes = stats.indexed_probes.saturating_add(1);
            }
            let prefix = index_key_from_values(&storage.columns[..columns.len()], values);
            if storage.columns.len() == columns.len() {
                storage
                    .exact_postings(&prefix)
                    .and_then(|entries| visible_posting(entries, snapshot, skip_deleted))
            } else {
                storage
                    .tree
                    .range(prefix.clone()..)
                    .take_while(|(key, _)| {
                        key.len() >= prefix.len() && key[..prefix.len()] == prefix[..]
                    })
                    .find_map(|(_, entries)| visible_posting(entries, snapshot, skip_deleted))
            }
        };
        Ok(row_id.is_some())
    }

    fn apply_commit_time_upsert(
        &self,
        ws: &mut WriteSet,
        insert_index: usize,
        conflict_row: &VersionedRow,
        intent: &PendingUpsertIntent,
        snapshot: SnapshotId,
    ) -> Result<Option<CommitTimeUpsertRewrite>> {
        if intent.table != ws.relational_inserts[insert_index].0
            || intent.row_id != ws.relational_inserts[insert_index].1.row_id
        {
            return Ok(None);
        }

        let (table, incoming) = ws.relational_inserts[insert_index].clone();
        let on_conflict = OnConflictPlan {
            columns: intent.conflict_columns.clone(),
            update_columns: intent.update_columns.clone(),
        };
        let mut original_insert_values = intent.insert_values.clone();
        self.rewrite_txid_placeholders_in_values(
            &table,
            intent.active_tx,
            incoming.created_tx,
            &mut original_insert_values,
        );
        let mut values = apply_on_conflict_updates(
            self,
            &table,
            original_insert_values.clone(),
            conflict_row,
            &on_conflict,
            &intent.params,
            Some(intent.active_tx),
        )?;
        self.rewrite_txid_placeholders_in_values(
            &table,
            intent.active_tx,
            incoming.created_tx,
            &mut values,
        );
        for (column, incoming_value) in &incoming.values {
            if original_insert_values.get(column) != Some(incoming_value) {
                values.insert(column.clone(), incoming_value.clone());
            }
        }
        self.validate_commit_time_upsert_replacement(&table, conflict_row, &values, snapshot)?;

        let incoming_row_bytes = self
            .table_meta(&table)
            .map(|meta| retained_row_bytes_for_meta(&table, &incoming.values, &meta, true))
            .unwrap_or_else(|| incoming.estimated_bytes());
        let replacement_row_bytes = self
            .table_meta(&table)
            .map(|meta| retained_row_bytes_for_meta(&table, &values, &meta, true))
            .unwrap_or_else(|| {
                let mut replacement = incoming.clone();
                replacement.values = values.clone();
                replacement.estimated_bytes()
            });
        let extra_row_bytes = replacement_row_bytes.saturating_sub(incoming_row_bytes);
        if extra_row_bytes > 0 {
            self.accountant.try_allocate_for(
                extra_row_bytes,
                "insert",
                "commit_time_upsert_row_rewrite",
                "Reduce row size or raise MEMORY_LIMIT before committing this UPSERT.",
            )?;
        }

        let mut replacement = incoming;
        let incoming_row_id = replacement.row_id;
        replacement.row_id = conflict_row.row_id;
        replacement.values = values;
        if let Err(err) = self.reconcile_commit_time_upsert_vectors(
            ws,
            &table,
            incoming_row_id,
            conflict_row.row_id,
            &replacement.values,
            replacement.created_tx,
            replacement.lsn,
            snapshot,
        ) {
            if extra_row_bytes > 0 {
                self.accountant.release(extra_row_bytes);
            }
            return Err(err);
        }
        if incoming_row_bytes > replacement_row_bytes {
            self.accountant
                .release(incoming_row_bytes - replacement_row_bytes);
        }
        let row_uuid = replacement
            .values
            .get("id")
            .and_then(Value::as_uuid)
            .copied();
        let new_state = self
            .table_meta(&table)
            .and_then(|meta| meta.state_machine)
            .and_then(|sm| replacement.values.get(&sm.column))
            .and_then(Value::as_text)
            .map(std::borrow::ToOwned::to_owned);
        let changed = replacement
            .values
            .iter()
            .any(|(column, value)| conflict_row.values.get(column) != Some(value));
        let mut lookup_delta = StagedTupleLookupDelta::default();
        lookup_delta.remove(&table, &ws.relational_inserts[insert_index].1);
        lookup_delta.add(&table, &replacement);
        ws.relational_inserts[insert_index] = (table.clone(), replacement);
        if !ws
            .relational_deletes
            .iter()
            .any(|(t, row_id, _)| t == &table && *row_id == conflict_row.row_id)
        {
            ws.relational_deletes.push((
                table.clone(),
                conflict_row.row_id,
                ws.relational_inserts[insert_index].1.created_tx,
            ));
        }
        if changed && let (Some(uuid), Some(state)) = (row_uuid, new_state.as_deref()) {
            let replacement_tx = ws.relational_inserts[insert_index].1.created_tx;
            let mut propagation_options = PreparedPropagationOptions {
                tx: replacement_tx,
                snapshot,
                lookup_delta: Some(&mut lookup_delta),
            };
            self.propagate_state_change_in_prepared_write_set(
                ws,
                &table,
                Some(uuid),
                Some(state),
                &mut propagation_options,
            )?;
        }
        Ok(Some(CommitTimeUpsertRewrite {
            table,
            row_id: conflict_row.row_id,
            lookup_delta,
        }))
    }

    fn relational_insert_index_by_row(
        ws: &WriteSet,
        table: &str,
        row_id: RowId,
        preferred_index: usize,
    ) -> Option<usize> {
        if ws
            .relational_inserts
            .get(preferred_index)
            .is_some_and(|(candidate_table, row)| candidate_table == table && row.row_id == row_id)
        {
            return Some(preferred_index);
        }
        if let Some(index) = preferred_index.checked_sub(1)
            && ws
                .relational_inserts
                .get(index)
                .is_some_and(|(candidate_table, row)| {
                    candidate_table == table && row.row_id == row_id
                })
        {
            return Some(index);
        }
        ws.relational_inserts
            .iter()
            .position(|(candidate_table, row)| candidate_table == table && row.row_id == row_id)
    }

    fn validate_commit_time_upsert_replacement(
        &self,
        table: &str,
        conflict_row: &VersionedRow,
        values: &HashMap<ColName, Value>,
        snapshot: SnapshotId,
    ) -> Result<()> {
        if self.relational_store().is_immutable(table) {
            return Err(Error::ImmutableTable(table.to_string()));
        }
        self.assert_row_write_allowed(table, conflict_row.row_id, &conflict_row.values, snapshot)?;
        self.assert_row_write_allowed(table, conflict_row.row_id, values, snapshot)?;
        self.validate_commit_time_upsert_state_transition(table, conflict_row, values)?;
        self.validate_commit_time_upsert_vectors(table, values)
    }

    fn validate_commit_time_upsert_state_transition(
        &self,
        table: &str,
        conflict_row: &VersionedRow,
        values: &HashMap<ColName, Value>,
    ) -> Result<()> {
        let Some(meta) = self.table_meta(table) else {
            return Ok(());
        };
        let Some(state_machine) = meta.state_machine else {
            return Ok(());
        };

        let old_state = conflict_row
            .values
            .get(&state_machine.column)
            .and_then(Value::as_text);
        let new_state = values.get(&state_machine.column).and_then(Value::as_text);
        let (Some(old_state), Some(new_state)) = (old_state, new_state) else {
            return Ok(());
        };

        if self.relational_store().validate_state_transition(
            table,
            &state_machine.column,
            old_state,
            new_state,
        ) {
            return Ok(());
        }

        Err(Error::InvalidStateTransition(format!(
            "{old_state} -> {new_state}"
        )))
    }

    fn validate_commit_time_upsert_vectors(
        &self,
        table: &str,
        values: &HashMap<ColName, Value>,
    ) -> Result<()> {
        let Some(meta) = self.table_meta(table) else {
            return Ok(());
        };

        for column in &meta.columns {
            if let ColumnType::Vector(expected) = column.column_type
                && let Some(Value::Vector(vector)) = values.get(&column.name)
            {
                let got = vector.len();
                if got != expected {
                    return Err(self.direct_vector_dimension_error(
                        &VectorIndexRef::new(table, column.name.clone()),
                        expected,
                        got,
                    ));
                }
            }
        }

        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    fn reconcile_commit_time_upsert_vectors(
        &self,
        ws: &mut WriteSet,
        table: &str,
        incoming_row_id: RowId,
        conflict_row_id: RowId,
        replacement_values: &HashMap<ColName, Value>,
        replacement_tx: TxId,
        replacement_lsn: Lsn,
        snapshot: SnapshotId,
    ) -> Result<()> {
        let Some(meta) = self.table_meta(table) else {
            return Ok(());
        };
        let vector_columns = meta
            .columns
            .iter()
            .filter(|column| matches!(column.column_type, ColumnType::Vector(_)))
            .map(|column| column.name.clone())
            .collect::<Vec<_>>();
        if vector_columns.is_empty() {
            return Ok(());
        }

        let mut pending_by_column = HashMap::<ColName, VectorEntry>::new();
        let mut pos = 0;
        while pos < ws.vector_inserts.len() {
            let entry = &ws.vector_inserts[pos];
            if entry.index.table == table && entry.row_id == incoming_row_id {
                let entry = ws.vector_inserts.remove(pos);
                if let Some(replaced) = pending_by_column.insert(entry.index.column.clone(), entry)
                {
                    self.accountant.release(
                        self.vector_insert_accounted_bytes(&replaced.index, replaced.vector.len()),
                    );
                }
            } else {
                pos += 1;
            }
        }

        for column in vector_columns {
            let index = VectorIndexRef::new(table, column.clone());
            let existing =
                self.vector_store
                    .load_live_entry_for_row(&index, conflict_row_id, snapshot)?;
            let final_vector = match replacement_values.get(&column) {
                Some(Value::Vector(vector)) => Some(vector.clone()),
                _ => None,
            };
            let Some(final_vector) = final_vector else {
                if let Some(pending) = pending_by_column.remove(&column) {
                    self.accountant.release(
                        self.vector_insert_accounted_bytes(&pending.index, pending.vector.len()),
                    );
                }
                if existing.is_some()
                    && !ws
                        .vector_deletes
                        .iter()
                        .any(|(pending_index, pending_row_id, _)| {
                            *pending_index == index && *pending_row_id == conflict_row_id
                        })
                {
                    ws.vector_deletes
                        .push((index.clone(), conflict_row_id, replacement_tx));
                }
                continue;
            };

            if existing
                .as_ref()
                .is_some_and(|entry| entry.vector == final_vector)
            {
                if let Some(pending) = pending_by_column.remove(&column) {
                    self.accountant.release(
                        self.vector_insert_accounted_bytes(&pending.index, pending.vector.len()),
                    );
                }
                continue;
            }

            if existing.is_some()
                && !ws
                    .vector_deletes
                    .iter()
                    .any(|(pending_index, pending_row_id, _)| {
                        *pending_index == index && *pending_row_id == conflict_row_id
                    })
            {
                ws.vector_deletes
                    .push((index.clone(), conflict_row_id, replacement_tx));
            }

            let mut entry = match pending_by_column.remove(&column) {
                Some(mut pending) if pending.vector == final_vector => {
                    pending.row_id = conflict_row_id;
                    pending.created_tx = replacement_tx;
                    pending.deleted_tx = None;
                    pending.lsn = replacement_lsn;
                    pending
                }
                Some(pending) => {
                    self.accountant.release(
                        self.vector_insert_accounted_bytes(&pending.index, pending.vector.len()),
                    );
                    let bytes = self.vector_insert_accounted_bytes(&index, final_vector.len());
                    self.accountant.try_allocate_for(
                        bytes,
                        "insert",
                        &format!("vector_insert@{}.{}", index.table, index.column),
                        "Reduce vector dimensionality, insert fewer rows, or raise MEMORY_LIMIT.",
                    )?;
                    VectorEntry {
                        index: index.clone(),
                        row_id: conflict_row_id,
                        vector: final_vector.clone(),
                        created_tx: replacement_tx,
                        deleted_tx: None,
                        lsn: replacement_lsn,
                    }
                }
                None => {
                    let bytes = self.vector_insert_accounted_bytes(&index, final_vector.len());
                    self.accountant.try_allocate_for(
                        bytes,
                        "insert",
                        &format!("vector_insert@{}.{}", index.table, index.column),
                        "Reduce vector dimensionality, insert fewer rows, or raise MEMORY_LIMIT.",
                    )?;
                    VectorEntry {
                        index: index.clone(),
                        row_id: conflict_row_id,
                        vector: final_vector.clone(),
                        created_tx: replacement_tx,
                        deleted_tx: None,
                        lsn: replacement_lsn,
                    }
                }
            };
            entry.index = index;

            let mut replaced_entries = Vec::new();
            let mut pos = 0;
            while pos < ws.vector_inserts.len() {
                if ws.vector_inserts[pos].index == entry.index
                    && ws.vector_inserts[pos].row_id == conflict_row_id
                {
                    replaced_entries.push(ws.vector_inserts.remove(pos));
                } else {
                    pos += 1;
                }
            }
            for replaced in replaced_entries {
                self.accountant.release(
                    self.vector_insert_accounted_bytes(&replaced.index, replaced.vector.len()),
                );
            }
            ws.vector_inserts.push(entry);
        }

        for pending in pending_by_column.into_values() {
            self.accountant
                .release(self.vector_insert_accounted_bytes(&pending.index, pending.vector.len()));
        }
        Ok(())
    }

    fn apply_original_commit_time_upsert_if_needed(
        &self,
        ws: &mut WriteSet,
        insert_index: usize,
        skip_deleted: &HashSet<RowId>,
        upsert_lookup: &CommitTimeUpsertLookup<'_>,
        snapshot: SnapshotId,
        stats: Option<&mut CommitStageStats>,
    ) -> Result<Option<CommitTimeUpsertRewrite>> {
        let mut stats = stats;
        let (table, row) = ws.relational_inserts[insert_index].clone();
        let Some(intent_indexes) = upsert_lookup.by_row.get(&(table.clone(), row.row_id)) else {
            return Ok(None);
        };
        for intent_index in intent_indexes {
            let intent = &upsert_lookup.intents[*intent_index];
            if intent.conflict_columns.is_empty() {
                continue;
            }
            let mut insert_values = intent.insert_values.clone();
            self.rewrite_txid_placeholders_in_values(
                &table,
                intent.active_tx,
                row.created_tx,
                &mut insert_values,
            );
            let mut conflict_values = Vec::with_capacity(intent.conflict_columns.len());
            let mut has_null = false;
            for column in &intent.conflict_columns {
                match insert_values.get(column) {
                    Some(Value::Null) | None => {
                        has_null = true;
                        break;
                    }
                    Some(value) => conflict_values.push(value.clone()),
                }
            }
            if has_null {
                continue;
            }

            let Some(conflict) = self.committed_unique_conflict(
                &table,
                &intent.conflict_columns,
                &conflict_values,
                snapshot,
                skip_deleted,
                stats.as_deref_mut(),
            )?
            else {
                continue;
            };
            if let Some(replacement) =
                self.apply_commit_time_upsert(ws, insert_index, &conflict, intent, snapshot)?
            {
                return Ok(Some(replacement));
            }
        }

        Ok(None)
    }

    fn validate_unique_constraints_in_write_set(
        &self,
        ws: &mut WriteSet,
        snapshot: SnapshotId,
        upsert_intents: &[PendingUpsertIntent],
        deleted_rows_by_table: &mut HashMap<String, HashMap<RowId, VersionedRow>>,
        stats: &mut CommitStageStats,
    ) -> Result<()> {
        let upsert_lookup = CommitTimeUpsertLookup {
            intents: upsert_intents,
            by_row: Self::upsert_intent_indexes_by_row(upsert_intents),
        };
        let upsert_intent_by_conflict = Self::upsert_intent_index_by_conflict(upsert_intents);
        let staged_tuple_columns = self.staged_tuple_key_columns_by_table();
        let mut staged_lookup = StagedTupleLookup::from_write_set(&staged_tuple_columns, ws);
        let mut deleted_by_table = Self::deleted_row_ids_by_table(ws);
        let empty_deleted = HashSet::new();
        let mut index = 0;
        'validate: while index < ws.relational_inserts.len() {
            let (table, row) = ws.relational_inserts[index].clone();
            let meta = self
                .table_meta(&table)
                .ok_or_else(|| Error::TableNotFound(table.clone()))?;
            let skip_deleted = deleted_by_table.get(&table).unwrap_or(&empty_deleted);
            stats.rows_validated = stats.rows_validated.saturating_add(1);

            if let Some(rewrite) = self.apply_original_commit_time_upsert_if_needed(
                ws,
                index,
                skip_deleted,
                &upsert_lookup,
                snapshot,
                Some(stats),
            )? {
                staged_lookup.apply_delta(&staged_tuple_columns, &rewrite.lookup_delta);
                deleted_by_table = Self::deleted_row_ids_by_table(ws);
                *deleted_rows_by_table = self.deleted_row_snapshots_by_table(ws);
                index =
                    Self::relational_insert_index_by_row(ws, &rewrite.table, rewrite.row_id, index)
                        .unwrap_or_else(|| index.min(ws.relational_inserts.len()));
                continue 'validate;
            }

            for column in meta
                .columns
                .iter()
                .filter(|column| column.primary_key || column.unique)
            {
                let Some(value) = row.values.get(&column.name) else {
                    continue;
                };
                if *value == Value::Null {
                    continue;
                }
                let columns = vec![column.name.clone()];
                let values = vec![value.clone()];
                let staged_conflict = if Self::values_can_be_tuple_key(&values) {
                    staged_lookup
                        .staged_unique_conflict(&table, row.row_id, &columns, &values, stats)
                } else {
                    Self::staged_unique_conflict_in_write_set(
                        ws,
                        index,
                        &table,
                        &columns,
                        &values,
                        Some(stats),
                    )
                };
                if staged_conflict.is_some() {
                    return Err(Error::UniqueViolation {
                        table,
                        column: column.name.clone(),
                    });
                }
                let upsert_intent_index = upsert_intent_by_conflict
                    .get(&(table.clone(), row.row_id, columns.clone()))
                    .copied();
                let deleted_rows = deleted_rows_by_table.get(&table);
                let conflict = if self.committed_unique_probe_required_for_replacement(
                    row.row_id,
                    &columns,
                    &values,
                    skip_deleted,
                    deleted_rows,
                ) {
                    if upsert_intent_index.is_some() {
                        self.committed_unique_conflict(
                            &table,
                            &columns,
                            &values,
                            snapshot,
                            skip_deleted,
                            Some(stats),
                        )?
                    } else if self
                        .committed_unique_conflict_row_id(
                            &table,
                            &columns,
                            &values,
                            snapshot,
                            skip_deleted,
                            Some(stats),
                        )?
                        .is_some()
                    {
                        Some(VersionedRow {
                            row_id: RowId(0),
                            values: HashMap::new(),
                            created_tx: TxId(0),
                            deleted_tx: None,
                            lsn: Lsn(0),
                            created_at: None,
                        })
                    } else {
                        None
                    }
                } else {
                    None
                };
                if let Some(conflict) = conflict {
                    if let Some(intent_index) = upsert_intent_index
                        && let Some(rewrite) = self.apply_commit_time_upsert(
                            ws,
                            index,
                            &conflict,
                            &upsert_intents[intent_index],
                            snapshot,
                        )?
                    {
                        staged_lookup.apply_delta(&staged_tuple_columns, &rewrite.lookup_delta);
                        deleted_by_table = Self::deleted_row_ids_by_table(ws);
                        *deleted_rows_by_table = self.deleted_row_snapshots_by_table(ws);
                        index = Self::relational_insert_index_by_row(
                            ws,
                            &rewrite.table,
                            rewrite.row_id,
                            index,
                        )
                        .unwrap_or_else(|| index.min(ws.relational_inserts.len()));
                        continue 'validate;
                    }
                    return Err(Error::UniqueViolation {
                        table,
                        column: column.name.clone(),
                    });
                }
            }

            for unique_constraint in meta.enforced_unique_tuples() {
                let mut values = Vec::with_capacity(unique_constraint.len());
                let mut has_null = false;
                for column in unique_constraint {
                    match row.values.get(column) {
                        Some(Value::Null) | None => {
                            has_null = true;
                            break;
                        }
                        Some(value) => values.push(value.clone()),
                    }
                }
                if has_null {
                    continue;
                }
                let staged_conflict = if Self::values_can_be_tuple_key(&values) {
                    staged_lookup.staged_unique_conflict(
                        &table,
                        row.row_id,
                        unique_constraint,
                        &values,
                        stats,
                    )
                } else {
                    Self::staged_unique_conflict_in_write_set(
                        ws,
                        index,
                        &table,
                        unique_constraint,
                        &values,
                        Some(stats),
                    )
                };
                if staged_conflict.is_some() {
                    return Err(Error::UniqueViolation {
                        table,
                        column: unique_constraint.first().cloned().unwrap_or_default(),
                    });
                }
                let upsert_intent_index = upsert_intent_by_conflict
                    .get(&(table.clone(), row.row_id, unique_constraint.clone()))
                    .copied();
                let deleted_rows = deleted_rows_by_table.get(&table);
                let conflict = if self.committed_unique_probe_required_for_replacement(
                    row.row_id,
                    unique_constraint,
                    &values,
                    skip_deleted,
                    deleted_rows,
                ) {
                    if upsert_intent_index.is_some() {
                        self.committed_unique_conflict(
                            &table,
                            unique_constraint,
                            &values,
                            snapshot,
                            skip_deleted,
                            Some(stats),
                        )?
                    } else if self
                        .committed_unique_conflict_row_id(
                            &table,
                            unique_constraint,
                            &values,
                            snapshot,
                            skip_deleted,
                            Some(stats),
                        )?
                        .is_some()
                    {
                        Some(VersionedRow {
                            row_id: RowId(0),
                            values: HashMap::new(),
                            created_tx: TxId(0),
                            deleted_tx: None,
                            lsn: Lsn(0),
                            created_at: None,
                        })
                    } else {
                        None
                    }
                } else {
                    None
                };
                if let Some(conflict) = conflict {
                    if let Some(intent_index) = upsert_intent_index
                        && let Some(rewrite) = self.apply_commit_time_upsert(
                            ws,
                            index,
                            &conflict,
                            &upsert_intents[intent_index],
                            snapshot,
                        )?
                    {
                        staged_lookup.apply_delta(&staged_tuple_columns, &rewrite.lookup_delta);
                        deleted_by_table = Self::deleted_row_ids_by_table(ws);
                        *deleted_rows_by_table = self.deleted_row_snapshots_by_table(ws);
                        index = Self::relational_insert_index_by_row(
                            ws,
                            &rewrite.table,
                            rewrite.row_id,
                            index,
                        )
                        .unwrap_or_else(|| index.min(ws.relational_inserts.len()));
                        continue 'validate;
                    }
                    return Err(Error::UniqueViolation {
                        table,
                        column: unique_constraint.first().cloned().unwrap_or_default(),
                    });
                }
            }

            index += 1;
        }
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    fn reject_if_incoming_lineage_matches_purged(
        record: &DurableLineageRecord,
        table: &str,
        natural_key: &NaturalKey,
        table_generation: u64,
        lineage_root: &str,
        author_node_id: &str,
        author_database_incarnation: &str,
        author_local_mutation_position: u64,
    ) -> Result<()> {
        let exact_purged_root = record.delete_obligation == DurableDeleteObligation::Purged
            && record.table == table
            && record.natural_key == *natural_key
            && record.table_generation == table_generation
            && record.lineage_root == lineage_root
            && record.author_node_id.as_deref() == Some(author_node_id)
            && record.author_database_incarnation.as_deref() == Some(author_database_incarnation)
            && record.author_local_mutation_position == author_local_mutation_position;
        if !exact_purged_root {
            return Ok(());
        }
        let Some(frontier) = record
            .purge_frontier
            .as_deref()
            .and_then(|frontier| frontier.parse::<u64>().ok())
        else {
            return Ok(());
        };
        Err(Error::PurgeCausalityFence {
            table: table.to_string(),
            key: natural_key.pairs(),
            lineage_root: lineage_root.to_string(),
            frontier: Lsn(frontier),
        })
    }

    /// A transaction that began before an authoritative purge can still carry
    /// an update of the destroyed row. Local work is fenced by its pinned
    /// RowId; authenticated sync work is fenced by the exact staged creator
    /// sidecar, so remote RowIds and delete-only writes never decide ancestry.
    fn reject_purged_lineage_recreation(&self, ws: &WriteSet) -> Result<()> {
        for (table, row) in &ws.relational_inserts {
            let Some(meta) = self.table_meta(table) else {
                continue;
            };
            let Some(natural_key) = natural_key_from_row_values(&meta, &row.values) else {
                continue;
            };
            let generation = self.durable_lineage_table_generation(table)?;
            let purged_lives =
                self.purged_lineage_records_at_generation(table, &natural_key, generation)?;
            if purged_lives.is_empty() {
                continue;
            }
            let sidecar_key = Self::durable_row_lineage_config_key(table, &natural_key, generation);
            if let Some((_, encoded)) = ws.config_writes.iter().find(|(key, _)| key == &sidecar_key)
            {
                let incoming: DurableRowLineageSidecar =
                    RedbPersistence::decode_config_value(encoded)?;
                for record in &purged_lives {
                    Self::reject_if_incoming_lineage_matches_purged(
                        record,
                        table,
                        &natural_key,
                        incoming.table_generation,
                        &incoming.lineage_root,
                        &incoming.author_node_id,
                        &incoming.author_database_incarnation.to_hex(),
                        incoming.author_local_mutation_position.0,
                    )?;
                }
                // Authenticated ancestry is the discriminator for this staged
                // sync row. A different creator root is a fresh lineage even
                // if adjudication began while the old local RowId was visible.
                continue;
            }
            for record in purged_lives {
                if record.local_row_id != Some(row.row_id) {
                    continue;
                }
                if let Some(frontier) = record
                    .purge_frontier
                    .as_deref()
                    .and_then(|frontier| frontier.parse::<u64>().ok())
                {
                    return Err(Error::PurgeCausalityFence {
                        table: table.clone(),
                        key: natural_key.pairs(),
                        lineage_root: record.lineage_root,
                        frontier: Lsn(frontier),
                    });
                }
            }
        }
        for (key, encoded) in &ws.config_writes {
            if let Some(suffix) = key.strip_prefix("sync_row_lineage.v1.") {
                let incoming: DurableRowLineageSidecar =
                    RedbPersistence::decode_config_value(encoded)?;
                let purged_lives = {
                    let lineage_state = self.lineage_state_lock.lock();
                    self.purged_lineage_records_for_suffix(&lineage_state, suffix)?
                };
                for current in &purged_lives {
                    Self::reject_if_incoming_lineage_matches_purged(
                        current,
                        &current.table,
                        &current.natural_key,
                        incoming.table_generation,
                        &incoming.lineage_root,
                        &incoming.author_node_id,
                        &incoming.author_database_incarnation.to_hex(),
                        incoming.author_local_mutation_position.0,
                    )?;
                }
                continue;
            }
            if let Some(suffix) = key.strip_prefix(Self::DURABLE_LINEAGE_CONFIG_PREFIX) {
                let incoming: DurableLineageRecord = RedbPersistence::decode_config_value(encoded)?;
                let purged_lives = {
                    let lineage_state = self.lineage_state_lock.lock();
                    self.purged_lineage_records_for_suffix(&lineage_state, suffix)?
                };
                for current in &purged_lives {
                    Self::reject_if_incoming_lineage_matches_purged(
                        current,
                        &incoming.table,
                        &incoming.natural_key,
                        incoming.table_generation,
                        &incoming.lineage_root,
                        incoming.author_node_id.as_deref().unwrap_or_default(),
                        incoming
                            .author_database_incarnation
                            .as_deref()
                            .unwrap_or_default(),
                        incoming.author_local_mutation_position,
                    )?;
                }
            }
        }
        Ok(())
    }

    fn validate_foreign_keys_in_write_set(
        &self,
        ws: &WriteSet,
        snapshot: SnapshotId,
        deleted_rows_by_table: &HashMap<String, HashMap<RowId, VersionedRow>>,
        stats: &mut CommitStageStats,
    ) -> Result<()> {
        let staged_lookup = StagedTupleLookup::rebuild(self, ws)?;
        let deleted_by_table = Self::deleted_row_ids_by_table(ws);
        let empty_deleted = HashSet::new();
        for (table, row) in &ws.relational_inserts {
            stats.rows_validated = stats.rows_validated.saturating_add(1);
            let meta = self
                .table_meta(table)
                .ok_or_else(|| Error::TableNotFound(table.clone()))?;
            for column in &meta.columns {
                let Some(reference) = &column.references else {
                    continue;
                };
                let Some(value) = row.values.get(&column.name) else {
                    continue;
                };
                if *value == Value::Null {
                    continue;
                }
                let staged_deletes = deleted_by_table
                    .get(&reference.table)
                    .unwrap_or(&empty_deleted);
                let parent_columns = vec![reference.column.clone()];
                let parent_values = std::slice::from_ref(value);
                let staged_match = if Self::values_can_be_tuple_key(parent_values) {
                    staged_lookup.contains_tuple(
                        &reference.table,
                        &parent_columns,
                        parent_values,
                        Some(stats),
                    )
                } else {
                    staged_tuple_exists(ws, &reference.table, &parent_columns, parent_values)
                };
                let committed_match = if staged_match {
                    true
                } else {
                    self.visible_row_exists_by_column(
                        &reference.table,
                        &reference.column,
                        value,
                        snapshot,
                        staged_deletes,
                        Some(stats),
                    )?
                };
                if !staged_match && !committed_match {
                    return Err(Error::ForeignKeyViolation {
                        child_table: table.clone(),
                        child_columns: vec![column.name.clone()],
                        parent_table: reference.table.clone(),
                        parent_columns: vec![reference.column.clone()],
                    });
                }
            }
        }

        let reverse_refs = {
            let metas = self.relational_store.table_meta.read();
            metas
                .iter()
                .flat_map(|(child_table, meta)| {
                    meta.columns.iter().filter_map(|column| {
                        column.references.as_ref().map(|reference| {
                            (
                                reference.table.clone(),
                                reference.column.clone(),
                                child_table.clone(),
                                column.name.clone(),
                            )
                        })
                    })
                })
                .collect::<Vec<_>>()
        };

        for (parent_table, parent_row_id, _) in &ws.relational_deletes {
            stats.rows_validated = stats.rows_validated.saturating_add(1);
            let Some(parent_row) = deleted_rows_by_table
                .get(parent_table)
                .and_then(|rows| rows.get(parent_row_id))
            else {
                continue;
            };
            for (ref_table, ref_column, child_table, child_column) in &reverse_refs {
                if ref_table != parent_table {
                    continue;
                }
                let Some(parent_value) = parent_row.values.get(ref_column) else {
                    continue;
                };
                if *parent_value == Value::Null {
                    continue;
                }
                let parent_columns = vec![ref_column.clone()];
                let parent_values = std::slice::from_ref(parent_value);
                let parent_replaced_with_same_key = if Self::values_can_be_tuple_key(parent_values)
                {
                    staged_lookup.contains_tuple(
                        parent_table,
                        &parent_columns,
                        parent_values,
                        Some(stats),
                    )
                } else {
                    staged_tuple_exists(ws, parent_table, &parent_columns, parent_values)
                };
                if parent_replaced_with_same_key {
                    continue;
                }
                let child_deletes = deleted_by_table.get(child_table).unwrap_or(&empty_deleted);
                if self.visible_row_exists_by_column(
                    child_table,
                    child_column,
                    parent_value,
                    snapshot,
                    child_deletes,
                    Some(stats),
                )? {
                    return Err(Error::ForeignKeyViolation {
                        child_table: child_table.clone(),
                        child_columns: vec![child_column.clone()],
                        parent_table: parent_table.clone(),
                        parent_columns: vec![ref_column.clone()],
                    });
                }
            }
        }

        Ok(())
    }

    fn validate_composite_foreign_keys_in_write_set(
        &self,
        ws: &WriteSet,
        snapshot: SnapshotId,
        deleted_rows_by_table: &HashMap<String, HashMap<RowId, VersionedRow>>,
        stats: &mut CommitStageStats,
    ) -> Result<()> {
        let staged_lookup = StagedTupleLookup::rebuild(self, ws)?;
        let deleted_by_table = Self::deleted_row_ids_by_table(ws);
        let empty_deleted = HashSet::new();
        for (table, row) in &ws.relational_inserts {
            stats.rows_validated = stats.rows_validated.saturating_add(1);
            let meta = self
                .table_meta(table)
                .ok_or_else(|| Error::TableNotFound(table.clone()))?;
            for fk in &meta.composite_foreign_keys {
                let Some(values) = tuple_values_for_row(row, &fk.child_columns) else {
                    continue;
                };
                let parent_deletes = deleted_by_table
                    .get(&fk.parent_table)
                    .unwrap_or(&empty_deleted);
                let staged_match = if Self::values_can_be_tuple_key(&values) {
                    staged_lookup.contains_tuple(
                        &fk.parent_table,
                        &fk.parent_columns,
                        &values,
                        Some(stats),
                    )
                } else {
                    staged_tuple_exists(ws, &fk.parent_table, &fk.parent_columns, &values)
                };
                let committed_match = if staged_match {
                    true
                } else {
                    self.indexed_visible_row_exists_by_columns(
                        &fk.parent_table,
                        &fk.parent_columns,
                        &values,
                        snapshot,
                        parent_deletes,
                        Some(stats),
                    )?
                };
                if !staged_match && !committed_match {
                    return Err(Error::ForeignKeyViolation {
                        child_table: table.clone(),
                        child_columns: fk.child_columns.clone(),
                        parent_table: fk.parent_table.clone(),
                        parent_columns: fk.parent_columns.clone(),
                    });
                }
            }
        }

        let reverse_refs = {
            let metas = self.relational_store.table_meta.read();
            metas
                .iter()
                .flat_map(|(child_table, meta)| {
                    meta.composite_foreign_keys.iter().map(|fk| {
                        (
                            fk.parent_table.clone(),
                            fk.parent_columns.clone(),
                            child_table.clone(),
                            fk.child_columns.clone(),
                        )
                    })
                })
                .collect::<Vec<_>>()
        };

        for (parent_table, parent_row_id, _) in &ws.relational_deletes {
            stats.rows_validated = stats.rows_validated.saturating_add(1);
            let Some(parent_row) = deleted_rows_by_table
                .get(parent_table)
                .and_then(|rows| rows.get(parent_row_id))
            else {
                continue;
            };
            for (ref_table, ref_columns, child_table, child_columns) in &reverse_refs {
                if ref_table != parent_table {
                    continue;
                }
                let Some(parent_values) = tuple_values_for_row(parent_row, ref_columns) else {
                    continue;
                };
                let parent_replaced_with_same_key = if Self::values_can_be_tuple_key(&parent_values)
                {
                    staged_lookup.contains_tuple(
                        parent_table,
                        ref_columns,
                        &parent_values,
                        Some(stats),
                    )
                } else {
                    staged_tuple_exists(ws, parent_table, ref_columns, &parent_values)
                };
                if parent_replaced_with_same_key {
                    continue;
                }

                let staged_child_match = if Self::values_can_be_tuple_key(&parent_values) {
                    staged_lookup.contains_tuple(
                        child_table,
                        child_columns,
                        &parent_values,
                        Some(stats),
                    )
                } else {
                    staged_tuple_exists(ws, child_table, child_columns, &parent_values)
                };
                if staged_child_match {
                    return Err(Error::ForeignKeyViolation {
                        child_table: child_table.clone(),
                        child_columns: child_columns.clone(),
                        parent_table: parent_table.clone(),
                        parent_columns: ref_columns.clone(),
                    });
                }

                let child_deletes = deleted_by_table.get(child_table).unwrap_or(&empty_deleted);
                if self.indexed_visible_row_exists_by_columns(
                    child_table,
                    child_columns,
                    &parent_values,
                    snapshot,
                    child_deletes,
                    Some(stats),
                )? {
                    return Err(Error::ForeignKeyViolation {
                        child_table: child_table.clone(),
                        child_columns: child_columns.clone(),
                        parent_table: parent_table.clone(),
                        parent_columns: ref_columns.clone(),
                    });
                }
            }
        }

        Ok(())
    }

    fn revalidate_conditional_updates(
        &self,
        ws: &mut WriteSet,
        snapshot: SnapshotId,
        guards: &[PendingConditionalUpdateGuard],
        mut stats: Option<&mut CommitStageStats>,
    ) -> Result<CommitValidationOutcome> {
        let mut outcome = CommitValidationOutcome::default();
        for guard in guards.iter().rev() {
            if let Some(stats) = stats.as_deref_mut() {
                stats.rows_validated = stats.rows_validated.saturating_add(1);
            }
            let matches = match self.table_meta(&guard.table) {
                Some(meta) => {
                    let predicate_columns = guard
                        .predicates
                        .iter()
                        .map(|(column, _)| column.clone())
                        .collect::<Vec<_>>();
                    let vector_columns = meta
                        .columns
                        .iter()
                        .filter(|column| matches!(column.column_type, ColumnType::Vector(_)))
                        .map(|column| column.name.as_str())
                        .collect::<HashSet<_>>();
                    let resident =
                        self.relational_store
                            .row_by_id(&guard.table, guard.row_id, snapshot);
                    let needs_body = resident.as_ref().is_some_and(|row| {
                        predicate_columns.iter().any(|column| {
                            !vector_columns.contains(column.as_str())
                                && !row.values.contains_key(column)
                        })
                    });
                    let row = if needs_body {
                        self.committed_row_at(&guard.table, guard.row_id, snapshot)?
                    } else {
                        resident
                    };
                    match row {
                        Some(mut row) => {
                            self.supplement_selected_vector_columns(
                                &guard.table,
                                snapshot,
                                None,
                                Some(&predicate_columns),
                                std::slice::from_mut(&mut row),
                            )?;
                            row_conditions_match(&row, &meta, &guard.predicates)
                        }
                        None => false,
                    }
                }
                None => false,
            };
            if matches {
                continue;
            }

            self.release_insert_allocations_for_slice(ws, guard.before, guard.after);
            remove_write_set_slice(ws, guard.before, guard.after);
            if guard.fail_on_conflict {
                outcome.conditional_conflict_count =
                    outcome.conditional_conflict_count.saturating_add(1);
            } else {
                outcome.conditional_noop_count = outcome.conditional_noop_count.saturating_add(1);
            }
        }
        Ok(outcome)
    }

    /// A fresh creator delete is authorized for one exact committed row
    /// instance. If that row is replaced or edited before commit, fail the
    /// entire sync transaction so its receipt and lineage writes cannot be
    /// acknowledged without the delete.
    fn validate_sync_lineage_guards(
        &self,
        snapshot: SnapshotId,
        guards: &[PendingSyncLineageGuard],
    ) -> Result<()> {
        for guard in guards {
            let unchanged = self
                .relational_store
                .row_by_id(&guard.table, guard.row_id, snapshot)
                .is_some_and(|row| row.values == guard.values);
            if !unchanged {
                return Err(Error::SyncError(format!(
                    "authenticated creator delete target {} row {} changed before commit; retry the sync unit",
                    guard.table, guard.row_id.0
                )));
            }
        }
        Ok(())
    }

    fn release_insert_allocations_for_slice(
        &self,
        ws: &WriteSet,
        before: WriteSetCounts,
        after: WriteSetCounts,
    ) {
        for (table, row) in ws
            .relational_inserts
            .iter()
            .skip(before.relational_inserts)
            .take(
                after
                    .relational_inserts
                    .saturating_sub(before.relational_inserts),
            )
        {
            let bytes = self.staged_row_release_bytes(ws, table, row, self.table_meta(table));
            self.accountant.release(bytes);
        }

        for edge in ws
            .adj_inserts
            .iter()
            .skip(before.adj_inserts)
            .take(after.adj_inserts.saturating_sub(before.adj_inserts))
        {
            self.accountant.release(edge.estimated_bytes());
        }

        for entry in ws
            .vector_inserts
            .iter()
            .skip(before.vector_inserts)
            .take(after.vector_inserts.saturating_sub(before.vector_inserts))
        {
            self.accountant
                .release(self.vector_insert_accounted_bytes(&entry.index, entry.vector.len()));
        }
    }

    pub(crate) fn propagate_state_change_if_needed(
        &self,
        tx: TxId,
        table: &str,
        row_uuid: Option<uuid::Uuid>,
        new_state: Option<&str>,
    ) -> Result<()> {
        if let (Some(uuid), Some(state)) = (row_uuid, new_state) {
            if !self.propagation_rules_can_react(table, state) {
                return Ok(());
            }
            let already_propagating = self
                .tx_mgr
                .with_write_set(tx, |ws| ws.propagation_in_progress)?;
            if !already_propagating {
                self.tx_mgr
                    .with_write_set(tx, |ws| ws.propagation_in_progress = true)?;
                let propagate_result = self.propagate(tx, table, uuid, state);
                self.tx_mgr
                    .with_write_set(tx, |ws| ws.propagation_in_progress = false)?;
                propagate_result?;
            }
        }

        Ok(())
    }

    pub(crate) fn propagation_rules_can_react(&self, table: &str, state: &str) -> bool {
        let metas = self.relational_store().table_meta.read();
        if metas.get(table).is_some_and(|meta| {
            meta.propagation_rules.iter().any(|rule| match rule {
                PropagationRule::Edge { trigger_state, .. }
                | PropagationRule::VectorExclusion { trigger_state } => trigger_state == state,
                PropagationRule::ForeignKey { .. } => false,
            })
        }) {
            return true;
        }
        metas.values().any(|meta| {
            meta.propagation_rules.iter().any(|rule| {
                matches!(
                    rule,
                    PropagationRule::ForeignKey {
                        referenced_table,
                        trigger_state,
                        ..
                    } if referenced_table == table && trigger_state == state
                )
            })
        })
    }

    fn propagate(
        &self,
        tx: TxId,
        table: &str,
        row_uuid: uuid::Uuid,
        new_state: &str,
    ) -> Result<()> {
        let snapshot = self.snapshot_for_read();
        let metas = self.relational_store().table_meta.read().clone();
        let mut queue: VecDeque<PropagationQueueEntry> = VecDeque::new();
        let mut visited: HashSet<(String, uuid::Uuid)> = HashSet::new();
        let mut abort_violation: Option<Error> = None;
        let ctx = PropagationContext {
            tx,
            snapshot,
            metas: &metas,
        };
        let root = PropagationSource {
            table,
            uuid: row_uuid,
            state: new_state,
            depth: 0,
        };

        self.enqueue_fk_children(&ctx, &mut queue, root);
        self.enqueue_edge_children(&ctx, &mut queue, root)?;
        self.apply_vector_exclusions(&ctx, root)?;

        while let Some(entry) = queue.pop_front() {
            if !visited.insert((entry.table.clone(), entry.uuid)) {
                continue;
            }

            let Some(meta) = metas.get(&entry.table) else {
                continue;
            };

            let Some(state_machine) = &meta.state_machine else {
                let msg = format!(
                    "warning: propagation target table {} has no state machine",
                    entry.table
                );
                eprintln!("{msg}");
                if entry.abort_on_failure && abort_violation.is_none() {
                    abort_violation = Some(Error::PropagationAborted {
                        table: entry.table.clone(),
                        column: String::new(),
                        from: String::new(),
                        to: entry.target_state.clone(),
                    });
                }
                continue;
            };

            let state_column = state_machine.column.clone();
            let Some(existing) = self.relational.point_lookup_with_tx(
                Some(tx),
                &entry.table,
                "id",
                &Value::Uuid(entry.uuid),
                snapshot,
            )?
            else {
                continue;
            };

            let from_state = existing
                .values
                .get(&state_column)
                .and_then(Value::as_text)
                .unwrap_or("")
                .to_string();

            let mut next_values = existing.values.clone();
            next_values.insert(
                state_column.clone(),
                Value::Text(entry.target_state.clone()),
            );

            self.assert_row_write_allowed(
                &entry.table,
                existing.row_id,
                &existing.values,
                snapshot,
            )?;
            self.assert_row_write_allowed(&entry.table, existing.row_id, &next_values, snapshot)?;

            let upsert_outcome =
                self.relational
                    .upsert(tx, &entry.table, "id", next_values, snapshot);

            let reached_state = match upsert_outcome {
                Ok(UpsertResult::Updated) => entry.target_state.as_str(),
                Ok(UpsertResult::NoOp) | Ok(UpsertResult::Inserted) => continue,
                Err(Error::InvalidStateTransition(_)) => {
                    eprintln!(
                        "warning: skipped invalid propagated transition {}.{} {} -> {}",
                        entry.table, state_column, from_state, entry.target_state
                    );
                    if entry.abort_on_failure && abort_violation.is_none() {
                        abort_violation = Some(Error::PropagationAborted {
                            table: entry.table.clone(),
                            column: state_column.clone(),
                            from: from_state,
                            to: entry.target_state.clone(),
                        });
                    }
                    continue;
                }
                Err(err) => return Err(err),
            };

            self.enqueue_edge_children(
                &ctx,
                &mut queue,
                PropagationSource {
                    table: &entry.table,
                    uuid: entry.uuid,
                    state: reached_state,
                    depth: entry.depth,
                },
            )?;
            self.apply_vector_exclusions(
                &ctx,
                PropagationSource {
                    table: &entry.table,
                    uuid: entry.uuid,
                    state: reached_state,
                    depth: entry.depth,
                },
            )?;

            self.enqueue_fk_children(
                &ctx,
                &mut queue,
                PropagationSource {
                    table: &entry.table,
                    uuid: entry.uuid,
                    state: reached_state,
                    depth: entry.depth,
                },
            );
        }

        if let Some(err) = abort_violation {
            return Err(err);
        }

        Ok(())
    }

    fn propagate_state_change_in_prepared_write_set(
        &self,
        ws: &mut WriteSet,
        table: &str,
        row_uuid: Option<uuid::Uuid>,
        new_state: Option<&str>,
        options: &mut PreparedPropagationOptions<'_>,
    ) -> Result<()> {
        let (Some(uuid), Some(state)) = (row_uuid, new_state) else {
            return Ok(());
        };
        if !self.propagation_rules_can_react(table, state) {
            return Ok(());
        }
        if ws.propagation_in_progress {
            return Ok(());
        }

        ws.propagation_in_progress = true;
        let result = self.propagate_in_prepared_write_set(ws, table, uuid, state, options);
        ws.propagation_in_progress = false;
        result
    }

    fn propagate_in_prepared_write_set(
        &self,
        ws: &mut WriteSet,
        table: &str,
        row_uuid: uuid::Uuid,
        new_state: &str,
        options: &mut PreparedPropagationOptions<'_>,
    ) -> Result<()> {
        let metas = self.relational_store().table_meta.read().clone();
        let mut queue: VecDeque<PropagationQueueEntry> = VecDeque::new();
        let mut visited: HashSet<(String, uuid::Uuid)> = HashSet::new();
        let mut abort_violation: Option<Error> = None;
        let ctx = PropagationContext {
            tx: options.tx,
            snapshot: options.snapshot,
            metas: &metas,
        };
        let root = PropagationSource {
            table,
            uuid: row_uuid,
            state: new_state,
            depth: 0,
        };

        self.enqueue_fk_children_in_prepared_write_set(ws, &ctx, &mut queue, root);
        self.enqueue_edge_children_in_prepared_write_set(ws, &ctx, &mut queue, root)?;
        self.apply_vector_exclusions_in_prepared_write_set(ws, &ctx, root)?;

        while let Some(entry) = queue.pop_front() {
            if !visited.insert((entry.table.clone(), entry.uuid)) {
                continue;
            }

            let Some(meta) = metas.get(&entry.table) else {
                continue;
            };

            let Some(state_machine) = &meta.state_machine else {
                let msg = format!(
                    "warning: propagation target table {} has no state machine",
                    entry.table
                );
                eprintln!("{msg}");
                if entry.abort_on_failure && abort_violation.is_none() {
                    abort_violation = Some(Error::PropagationAborted {
                        table: entry.table.clone(),
                        column: String::new(),
                        from: String::new(),
                        to: entry.target_state.clone(),
                    });
                }
                continue;
            };

            let state_column = state_machine.column.clone();
            let Some(existing) = self.point_lookup_in_prepared_write_set(
                ws,
                &entry.table,
                "id",
                &Value::Uuid(entry.uuid),
                options.snapshot,
            )?
            else {
                continue;
            };

            let from_state = existing
                .values
                .get(&state_column)
                .and_then(Value::as_text)
                .unwrap_or("")
                .to_string();

            let mut next_values = existing.values.clone();
            next_values.insert(
                state_column.clone(),
                Value::Text(entry.target_state.clone()),
            );

            self.assert_row_write_allowed(
                &entry.table,
                existing.row_id,
                &existing.values,
                options.snapshot,
            )?;
            self.assert_row_write_allowed(
                &entry.table,
                existing.row_id,
                &next_values,
                options.snapshot,
            )?;

            let reached_state = match self.upsert_row_in_prepared_write_set(
                ws,
                &entry.table,
                &state_column,
                &existing,
                next_values,
                options,
            ) {
                Ok(true) => entry.target_state.as_str(),
                Ok(false) => continue,
                Err(Error::InvalidStateTransition(_)) => {
                    eprintln!(
                        "warning: skipped invalid propagated transition {}.{} {} -> {}",
                        entry.table, state_column, from_state, entry.target_state
                    );
                    if entry.abort_on_failure && abort_violation.is_none() {
                        abort_violation = Some(Error::PropagationAborted {
                            table: entry.table.clone(),
                            column: state_column.clone(),
                            from: from_state,
                            to: entry.target_state.clone(),
                        });
                    }
                    continue;
                }
                Err(err) => return Err(err),
            };

            let propagated = PropagationSource {
                table: &entry.table,
                uuid: entry.uuid,
                state: reached_state,
                depth: entry.depth,
            };
            self.enqueue_edge_children_in_prepared_write_set(ws, &ctx, &mut queue, propagated)?;
            self.apply_vector_exclusions_in_prepared_write_set(ws, &ctx, propagated)?;
            self.enqueue_fk_children_in_prepared_write_set(ws, &ctx, &mut queue, propagated);
        }

        if let Some(err) = abort_violation {
            return Err(err);
        }

        Ok(())
    }

    fn enqueue_fk_children_in_prepared_write_set(
        &self,
        ws: &WriteSet,
        ctx: &PropagationContext<'_>,
        queue: &mut VecDeque<PropagationQueueEntry>,
        source: PropagationSource<'_>,
    ) {
        for (owner_table, owner_meta) in ctx.metas {
            for rule in &owner_meta.propagation_rules {
                let PropagationRule::ForeignKey {
                    fk_column,
                    referenced_table,
                    trigger_state,
                    target_state,
                    max_depth,
                    abort_on_failure,
                    ..
                } = rule
                else {
                    continue;
                };

                if referenced_table != source.table || trigger_state != source.state {
                    continue;
                }

                if source.depth >= *max_depth {
                    continue;
                }

                let rows = match self.scan_filter_in_prepared_write_set(
                    ws,
                    owner_table,
                    ctx.snapshot,
                    &|row| row.values.get(fk_column) == Some(&Value::Uuid(source.uuid)),
                ) {
                    Ok(rows) => rows,
                    Err(err) => {
                        eprintln!(
                            "warning: propagation scan failed for {owner_table}.{fk_column}: {err}"
                        );
                        continue;
                    }
                };

                for row in rows {
                    if let Some(id) = row.values.get("id").and_then(Value::as_uuid).copied() {
                        queue.push_back(PropagationQueueEntry {
                            table: owner_table.clone(),
                            uuid: id,
                            target_state: target_state.clone(),
                            depth: source.depth + 1,
                            abort_on_failure: *abort_on_failure,
                        });
                    }
                }
            }
        }
    }

    fn enqueue_edge_children_in_prepared_write_set(
        &self,
        ws: &WriteSet,
        ctx: &PropagationContext<'_>,
        queue: &mut VecDeque<PropagationQueueEntry>,
        source: PropagationSource<'_>,
    ) -> Result<()> {
        let Some(meta) = ctx.metas.get(source.table) else {
            return Ok(());
        };

        for rule in &meta.propagation_rules {
            let PropagationRule::Edge {
                edge_type,
                direction,
                trigger_state,
                target_state,
                max_depth,
                abort_on_failure,
            } = rule
            else {
                continue;
            };

            if trigger_state != source.state || source.depth >= *max_depth {
                continue;
            }

            let bfs = self.query_bfs(
                source.uuid,
                Some(std::slice::from_ref(edge_type)),
                *direction,
                1,
                ctx.snapshot,
            )?;

            for node in bfs.nodes {
                if self
                    .point_lookup_in_prepared_write_set(
                        ws,
                        source.table,
                        "id",
                        &Value::Uuid(node.id),
                        ctx.snapshot,
                    )?
                    .is_some()
                {
                    queue.push_back(PropagationQueueEntry {
                        table: source.table.to_string(),
                        uuid: node.id,
                        target_state: target_state.clone(),
                        depth: source.depth + 1,
                        abort_on_failure: *abort_on_failure,
                    });
                }
            }
        }

        Ok(())
    }

    fn apply_vector_exclusions_in_prepared_write_set(
        &self,
        ws: &mut WriteSet,
        ctx: &PropagationContext<'_>,
        source: PropagationSource<'_>,
    ) -> Result<()> {
        let Some(meta) = ctx.metas.get(source.table) else {
            return Ok(());
        };

        for rule in &meta.propagation_rules {
            let PropagationRule::VectorExclusion { trigger_state } = rule else {
                continue;
            };
            if trigger_state != source.state {
                continue;
            }
            let Some(index) = self.table_meta(source.table).and_then(|meta| {
                meta.columns
                    .iter()
                    .find(|column| matches!(column.column_type, ColumnType::Vector(_)))
                    .map(|column| VectorIndexRef::new(source.table, column.name.clone()))
            }) else {
                continue;
            };
            for row_id in self.logical_row_ids_for_uuid_in_prepared_write_set(
                ws,
                source.table,
                source.uuid,
                ctx.snapshot,
            )? {
                self.delete_vector_in_prepared_write_set(
                    ws,
                    ctx.tx,
                    index.clone(),
                    row_id,
                    ctx.snapshot,
                )?;
            }
        }

        Ok(())
    }

    fn scan_in_prepared_write_set(
        &self,
        ws: &WriteSet,
        table: &str,
        snapshot: SnapshotId,
    ) -> Result<Vec<VersionedRow>> {
        let mut result = self.committed_rows_at(table, snapshot)?;

        let committed_row_ids: HashSet<RowId> = result.iter().map(|row| row.row_id).collect();
        let deleted_row_ids: HashSet<RowId> = ws
            .relational_deletes
            .iter()
            .filter(|(delete_table, _, _)| delete_table == table)
            .map(|(_, row_id, _)| *row_id)
            .collect();
        result.retain(|row| {
            !deleted_row_ids.contains(&row.row_id)
                && !row_matches_delete_predicates(&ws.relational_delete_predicates, table, row)
        });

        let mut seen_inserts = HashSet::new();
        let mut inserts = ws
            .relational_inserts
            .iter()
            .rev()
            .filter(|(insert_table, row)| {
                insert_table == table
                    && seen_inserts.insert(row.row_id)
                    && (!deleted_row_ids.contains(&row.row_id)
                        || committed_row_ids.contains(&row.row_id))
            })
            .map(|(_, row)| row.clone())
            .collect::<Vec<_>>();
        inserts.reverse();
        result.extend(inserts);

        Ok(result)
    }

    fn scan_filter_in_prepared_write_set(
        &self,
        ws: &WriteSet,
        table: &str,
        snapshot: SnapshotId,
        predicate: &dyn Fn(&VersionedRow) -> bool,
    ) -> Result<Vec<VersionedRow>> {
        Ok(self
            .scan_in_prepared_write_set(ws, table, snapshot)?
            .into_iter()
            .filter(predicate)
            .collect())
    }

    fn point_lookup_in_prepared_write_set(
        &self,
        ws: &WriteSet,
        table: &str,
        col: &str,
        value: &Value,
        snapshot: SnapshotId,
    ) -> Result<Option<VersionedRow>> {
        Ok(self
            .scan_in_prepared_write_set(ws, table, snapshot)?
            .into_iter()
            .find(|row| row.values.get(col) == Some(value)))
    }

    fn row_by_id_in_prepared_write_set(
        &self,
        ws: &WriteSet,
        table: &str,
        row_id: RowId,
        snapshot: SnapshotId,
    ) -> Result<Option<VersionedRow>> {
        Ok(self
            .scan_in_prepared_write_set(ws, table, snapshot)?
            .into_iter()
            .find(|row| row.row_id == row_id))
    }

    fn logical_row_ids_for_uuid_in_prepared_write_set(
        &self,
        ws: &WriteSet,
        table: &str,
        uuid: uuid::Uuid,
        snapshot: SnapshotId,
    ) -> Result<Vec<RowId>> {
        Ok(self
            .scan_in_prepared_write_set(ws, table, snapshot)?
            .into_iter()
            .filter(|row| row.values.get("id") == Some(&Value::Uuid(uuid)))
            .map(|row| row.row_id)
            .collect())
    }

    fn upsert_row_in_prepared_write_set(
        &self,
        ws: &mut WriteSet,
        table: &str,
        state_column: &str,
        existing: &VersionedRow,
        next_values: HashMap<ColName, Value>,
        options: &mut PreparedPropagationOptions<'_>,
    ) -> Result<bool> {
        if self.relational_store().is_immutable(table) {
            return Err(Error::ImmutableTable(table.to_string()));
        }

        let old_state = existing
            .values
            .get(state_column)
            .and_then(Value::as_text)
            .unwrap_or("");
        let new_state = next_values
            .get(state_column)
            .and_then(Value::as_text)
            .unwrap_or("");
        if !self.relational_store().validate_state_transition(
            table,
            state_column,
            old_state,
            new_state,
        ) {
            return Err(Error::InvalidStateTransition(format!(
                "{old_state} -> {new_state}"
            )));
        }

        let changed = next_values
            .iter()
            .any(|(column, value)| existing.values.get(column) != Some(value));
        if !changed {
            return Ok(false);
        }

        self.validate_primary_key_values_present(table, &next_values)?;

        let meta = self
            .table_meta(table)
            .ok_or_else(|| Error::TableNotFound(table.to_string()))?;
        let row_bytes = self.admit_retained_row_bytes(
            table,
            &next_values,
            &meta,
            "update",
            "prepared_state_propagation_row_replace",
            "Reduce row growth or raise MEMORY_LIMIT before committing this propagated update.",
        )?;

        if let Err(err) = self.delete_row_in_prepared_write_set(
            ws,
            options.tx,
            table,
            existing.row_id,
            options.lookup_delta.as_deref_mut(),
        ) {
            self.accountant.release(row_bytes);
            return Err(err);
        }

        let inserted = VersionedRow {
            row_id: existing.row_id,
            values: next_values,
            created_tx: options.tx,
            deleted_tx: None,
            lsn: ws.commit_lsn.unwrap_or(Lsn(0)),
            created_at: Some(current_wallclock()),
        };
        if let Some(delta) = options.lookup_delta.as_deref_mut() {
            delta.add(table, &inserted);
        }
        ws.set_relational_insert_admitted_bytes(table, inserted.row_id, row_bytes);
        ws.relational_inserts.push((table.to_string(), inserted));
        Ok(true)
    }

    fn delete_row_in_prepared_write_set(
        &self,
        ws: &mut WriteSet,
        tx: TxId,
        table: &str,
        row_id: RowId,
        mut lookup_delta: Option<&mut StagedTupleLookupDelta>,
    ) -> Result<()> {
        if !self.relational_store.table_meta.read().contains_key(table) {
            return Err(Error::TableNotFound(table.to_string()));
        }
        if self.relational_store().is_immutable(table) {
            return Err(Error::ImmutableTable(table.to_string()));
        }

        let mut removed_inserts = Vec::new();
        let mut pos = 0;
        while pos < ws.relational_inserts.len() {
            if ws.relational_inserts[pos].0 == table
                && ws.relational_inserts[pos].1.row_id == row_id
            {
                removed_inserts.push(ws.relational_inserts.remove(pos));
            } else {
                pos += 1;
            }
        }
        for (removed_table, row) in removed_inserts {
            if let Some(delta) = lookup_delta.as_deref_mut() {
                delta.remove(&removed_table, &row);
            }
            let bytes = self.staged_row_release_bytes(
                ws,
                &removed_table,
                &row,
                self.table_meta(&removed_table),
            );
            self.accountant.release(bytes);
            ws.forget_relational_insert_admitted_bytes(&removed_table, row.row_id);
        }

        let committed_row_exists = self
            .relational_store
            .row_by_id(table, row_id, SnapshotId::from_raw_wire(u64::MAX))
            .is_some();
        if committed_row_exists
            && !ws
                .relational_deletes
                .iter()
                .any(|(delete_table, deleted_row_id, _)| {
                    delete_table == table && *deleted_row_id == row_id
                })
        {
            ws.relational_deletes.push((table.to_string(), row_id, tx));
        }

        Ok(())
    }

    fn delete_vector_in_prepared_write_set(
        &self,
        ws: &mut WriteSet,
        tx: TxId,
        index: VectorIndexRef,
        row_id: RowId,
        snapshot: SnapshotId,
    ) -> Result<()> {
        self.vector_store.index_layout(&index)?;
        let Some(row) = self.row_by_id_in_prepared_write_set(ws, &index.table, row_id, snapshot)?
        else {
            return Err(Error::NotFound(format!(
                "row {row_id} in table {}",
                index.table
            )));
        };
        self.assert_row_write_allowed(&index.table, row.row_id, &row.values, snapshot)?;
        let existing_live = self
            .vector_store
            .has_live_entry_for_row(&index, row_id, snapshot);
        let mut canceled_inserts = Vec::new();
        let mut pos = 0;
        while pos < ws.vector_inserts.len() {
            if ws.vector_inserts[pos].index == index && ws.vector_inserts[pos].row_id == row_id {
                canceled_inserts.push(ws.vector_inserts.remove(pos));
            } else {
                pos += 1;
            }
        }

        let mut moved_sources = Vec::new();
        let mut pos = 0;
        while pos < ws.vector_moves.len() {
            let (move_index, old_row_id, new_row_id, _) = &ws.vector_moves[pos];
            if *move_index == index && *new_row_id == row_id {
                moved_sources.push(*old_row_id);
                ws.vector_moves.remove(pos);
            } else {
                pos += 1;
            }
        }
        let pending_move_from_row = ws
            .vector_moves
            .iter()
            .any(|(move_index, old_row_id, _, _)| *move_index == index && *old_row_id == row_id);
        let canceled_move_to_row = !moved_sources.is_empty();
        for old_row_id in moved_sources {
            if !ws
                .vector_deletes
                .iter()
                .any(|(pending_index, pending_row_id, _)| {
                    *pending_index == index && *pending_row_id == old_row_id
                })
            {
                ws.vector_deletes.push((index.clone(), old_row_id, tx));
            }
        }

        let already_deleted = ws
            .vector_deletes
            .iter()
            .any(|(pending_index, pending_row_id, _)| {
                *pending_index == index && *pending_row_id == row_id
            });
        if !pending_move_from_row
            && ((canceled_inserts.is_empty() && !canceled_move_to_row) || existing_live)
            && !already_deleted
        {
            ws.vector_deletes.push((index.clone(), row_id, tx));
        }
        for entry in canceled_inserts {
            self.accountant
                .release(self.vector_insert_accounted_bytes(&entry.index, entry.vector.len()));
        }
        Ok(())
    }

    fn enqueue_fk_children(
        &self,
        ctx: &PropagationContext<'_>,
        queue: &mut VecDeque<PropagationQueueEntry>,
        source: PropagationSource<'_>,
    ) {
        for (owner_table, owner_meta) in ctx.metas {
            for rule in &owner_meta.propagation_rules {
                let PropagationRule::ForeignKey {
                    fk_column,
                    referenced_table,
                    trigger_state,
                    target_state,
                    max_depth,
                    abort_on_failure,
                    ..
                } = rule
                else {
                    continue;
                };

                if referenced_table != source.table || trigger_state != source.state {
                    continue;
                }

                if source.depth >= *max_depth {
                    continue;
                }

                let rows = match self.relational.scan_filter_with_tx(
                    Some(ctx.tx),
                    owner_table,
                    ctx.snapshot,
                    &|row| row.values.get(fk_column) == Some(&Value::Uuid(source.uuid)),
                ) {
                    Ok(rows) => rows,
                    Err(err) => {
                        eprintln!(
                            "warning: propagation scan failed for {owner_table}.{fk_column}: {err}"
                        );
                        continue;
                    }
                };

                for row in rows {
                    if let Some(id) = row.values.get("id").and_then(Value::as_uuid).copied() {
                        queue.push_back(PropagationQueueEntry {
                            table: owner_table.clone(),
                            uuid: id,
                            target_state: target_state.clone(),
                            depth: source.depth + 1,
                            abort_on_failure: *abort_on_failure,
                        });
                    }
                }
            }
        }
    }

    fn enqueue_edge_children(
        &self,
        ctx: &PropagationContext<'_>,
        queue: &mut VecDeque<PropagationQueueEntry>,
        source: PropagationSource<'_>,
    ) -> Result<()> {
        let Some(meta) = ctx.metas.get(source.table) else {
            return Ok(());
        };

        for rule in &meta.propagation_rules {
            let PropagationRule::Edge {
                edge_type,
                direction,
                trigger_state,
                target_state,
                max_depth,
                abort_on_failure,
            } = rule
            else {
                continue;
            };

            if trigger_state != source.state || source.depth >= *max_depth {
                continue;
            }

            let bfs = self.query_bfs(
                source.uuid,
                Some(std::slice::from_ref(edge_type)),
                *direction,
                1,
                ctx.snapshot,
            )?;

            for node in bfs.nodes {
                if self
                    .relational
                    .point_lookup_with_tx(
                        Some(ctx.tx),
                        source.table,
                        "id",
                        &Value::Uuid(node.id),
                        ctx.snapshot,
                    )?
                    .is_some()
                {
                    queue.push_back(PropagationQueueEntry {
                        table: source.table.to_string(),
                        uuid: node.id,
                        target_state: target_state.clone(),
                        depth: source.depth + 1,
                        abort_on_failure: *abort_on_failure,
                    });
                }
            }
        }

        Ok(())
    }

    fn apply_vector_exclusions(
        &self,
        ctx: &PropagationContext<'_>,
        source: PropagationSource<'_>,
    ) -> Result<()> {
        let Some(meta) = ctx.metas.get(source.table) else {
            return Ok(());
        };

        for rule in &meta.propagation_rules {
            let PropagationRule::VectorExclusion { trigger_state } = rule else {
                continue;
            };
            if trigger_state != source.state {
                continue;
            }
            for row_id in self.logical_row_ids_for_uuid(ctx.tx, source.table, source.uuid) {
                let index = self
                    .table_meta(source.table)
                    .and_then(|meta| {
                        meta.columns
                            .iter()
                            .find(|column| {
                                matches!(column.column_type, contextdb_core::ColumnType::Vector(_))
                            })
                            .map(|column| VectorIndexRef::new(source.table, column.name.clone()))
                    })
                    .unwrap_or_default();
                self.delete_vector(ctx.tx, index, row_id)?;
            }
        }

        Ok(())
    }

    /// Delete a row and everything the row owns.
    ///
    /// A vector column lives in its own index, not in the relational row, so
    /// removing the relational body alone leaves every vector behind: the row
    /// is gone from `SELECT` and still answered by nearest-neighbour search,
    /// and the store keeps paying for what it holds.
    pub fn delete_row(&self, tx: TxId, table: &str, row_id: RowId) -> Result<()> {
        self.delete_row_inner(tx, table, row_id, true)
    }

    /// Remove only the relational body of a row whose vectors the caller is
    /// about to move or re-place itself, as row replacement does.
    pub(crate) fn delete_row_keeping_vectors(
        &self,
        tx: TxId,
        table: &str,
        row_id: RowId,
    ) -> Result<()> {
        self.delete_row_inner(tx, table, row_id, false)
    }

    fn delete_row_inner(
        &self,
        tx: TxId,
        table: &str,
        row_id: RowId,
        release_vectors: bool,
    ) -> Result<()> {
        self.ensure_no_mixed_local_schema_dml(tx)?;
        let trigger_callback_bound = self.trigger_callback_tx_bound_matches(tx);
        let _operation = if trigger_callback_bound || self.sql_write_control_bypass_active(tx) {
            None
        } else {
            Some(self.open_operation_after_write_control_wait(tx, "delete_row")?)
        };
        self.ensure_trigger_table_ready(table, "delete_row")?;
        self.assert_row_id_write_allowed(Some(tx), table, row_id, self.snapshot_for_read())?;
        if let Some(row) = self.row_visible_at_snapshot(table, row_id, self.snapshot_for_read())
            && let Some(meta) = self.table_meta(table)
            && let Some(natural_key) = natural_key_from_row_values(&meta, &row.values)
        {
            // A local delete replaces any older pulled tombstone for this key.
            // Sync apply records its own marker again only after its delete
            // commits, so a failed inbound delete never becomes suppressible.
            self.clear_sync_tombstone(table, &natural_key);
        }
        if release_vectors {
            // Before the relational body goes, so a failure leaves the row and
            // its vectors together rather than a row with no embeddings.
            for index in self.vector_indexes_of_table(table) {
                if self.vector_store.has_live_entry_for_row(
                    &index,
                    row_id,
                    self.snapshot_for_read(),
                ) {
                    self.delete_vector(tx, index, row_id)?;
                }
            }
        }
        self.delete_relational_row_releasing_staged(tx, table, row_id)
    }

    /// One index reference per vector column the table declares.
    pub(crate) fn vector_indexes_of_table(&self, table: &str) -> Vec<VectorIndexRef> {
        self.table_meta(table)
            .map(|meta| {
                meta.columns
                    .iter()
                    .filter(|column| {
                        matches!(column.column_type, contextdb_core::ColumnType::Vector(_))
                    })
                    .map(|column| VectorIndexRef::new(table, column.name.clone()))
                    .collect()
            })
            .unwrap_or_default()
    }

    pub fn scan(&self, table: &str, snapshot: SnapshotId) -> Result<Vec<VersionedRow>> {
        let _operation = self.open_operation()?;
        #[cfg(feature = "test-seams")]
        observe_read_execution_convergence(ReadExecutionConvergenceEvent::EagerRowSourceTouch);
        let rows = self.committed_rows_at(table, snapshot)?;
        let mut rows = self.filter_rows_for_read(table, rows, snapshot)?;
        self.supplement_quantized_vectors(table, snapshot, &mut rows)?;
        Ok(rows)
    }

    pub(crate) fn committed_row_at(
        &self,
        table: &str,
        row_id: RowId,
        snapshot: SnapshotId,
    ) -> Result<Option<VersionedRow>> {
        if self.relational_store.uses_disk_backed_committed_bodies() {
            let meta = self
                .table_meta(table)
                .ok_or_else(|| Error::TableNotFound(table.to_owned()))?;
            return self
                .persistence
                .as_ref()
                .expect("disk-backed relational bodies require persistence")
                .load_relational_row_by_id_at(table, &meta, row_id, snapshot);
        }
        Ok(self.relational_store.row_by_id(table, row_id, snapshot))
    }

    fn committed_rows_at(&self, table: &str, snapshot: SnapshotId) -> Result<Vec<VersionedRow>> {
        if self.relational_store.uses_disk_backed_committed_bodies() {
            self.table_meta(table)
                .ok_or_else(|| Error::TableNotFound(table.to_owned()))?;
            let rows = self
                .persistence
                .as_ref()
                .expect("disk-backed relational bodies require persistence")
                .load_relational_table(table)?;
            return Ok(rows
                .into_iter()
                .filter(|row| row.visible_at(snapshot))
                .collect());
        }
        self.relational.scan(table, snapshot)
    }

    /// Schema replacement rewrites every retained MVCC version, including
    /// tombstoned history. A file-backed writer therefore has to source the
    /// projection from Redb rather than its lightweight resident directory.
    pub(crate) fn table_versions_for_projection(&self, table: &str) -> Result<Vec<VersionedRow>> {
        if self.relational_store.uses_disk_backed_committed_bodies() {
            self.table_meta(table)
                .ok_or_else(|| Error::TableNotFound(table.to_owned()))?;
            return self
                .persistence
                .as_ref()
                .expect("disk-backed relational bodies require persistence")
                .load_relational_table(table);
        }
        Ok(self
            .relational_store
            .tables
            .read()
            .get(table)
            .cloned()
            .unwrap_or_default())
    }

    fn overlay_transaction_rows(
        &self,
        tx: TxId,
        table: &str,
        rows: &mut Vec<VersionedRow>,
    ) -> Result<()> {
        self.tx_mgr.with_write_set(tx, |ws| {
            let committed_row_ids: HashSet<RowId> = rows.iter().map(|row| row.row_id).collect();
            let deleted_row_ids: HashSet<RowId> = ws
                .relational_deletes
                .iter()
                .filter(|(candidate, _, _)| candidate == table)
                .map(|(_, row_id, _)| *row_id)
                .collect();
            rows.retain(|row| {
                !deleted_row_ids.contains(&row.row_id)
                    && !row_matches_delete_predicates(&ws.relational_delete_predicates, table, row)
            });
            let mut seen = HashSet::new();
            let mut inserts = ws
                .relational_inserts
                .iter()
                .rev()
                .filter(|(candidate, row)| {
                    candidate == table
                        && seen.insert(row.row_id)
                        && (!deleted_row_ids.contains(&row.row_id)
                            || committed_row_ids.contains(&row.row_id))
                })
                .map(|(_, row)| row.clone())
                .collect::<Vec<_>>();
            inserts.reverse();
            rows.extend(inserts);
        })
    }

    pub(crate) fn scan_in_tx_raw(
        &self,
        tx: TxId,
        table: &str,
        snapshot: SnapshotId,
    ) -> Result<Vec<VersionedRow>> {
        #[cfg(feature = "test-seams")]
        observe_read_execution_convergence(ReadExecutionConvergenceEvent::EagerRowSourceTouch);
        let mut rows = self.committed_rows_at(table, snapshot)?;
        self.overlay_transaction_rows(tx, table, &mut rows)?;
        self.supplement_quantized_vectors(table, snapshot, &mut rows)?;
        Ok(rows)
    }

    /// Compute the in-tx overlay (deleted row_ids + matching staged inserts)
    /// for an index-driven scan of `table` matching `shape` on `column`.
    /// Internal helper for the IndexScan executor arm.
    pub(crate) fn index_scan_tx_overlay(
        &self,
        tx: TxId,
        table: &str,
        column: &str,
        shape: &crate::executor::IndexPredicateShape,
    ) -> Result<IndexScanTxOverlay> {
        use crate::executor::{IndexPredicateShape, range_includes};
        let mut overlay = IndexScanTxOverlay::default();
        self.tx_mgr.with_write_set(tx, |ws| {
            for (t, _row_id, _) in &ws.relational_deletes {
                if t == table {
                    overlay.deleted_row_ids.insert(*_row_id);
                }
            }
            for (t, row) in &ws.relational_inserts {
                if t != table {
                    continue;
                }
                let v = row.values.get(column).cloned().unwrap_or(Value::Null);
                let include = match shape {
                    IndexPredicateShape::Equality(target) => v == *target,
                    IndexPredicateShape::NotEqual(target) => v != *target,
                    IndexPredicateShape::InList(list) => list.contains(&v),
                    IndexPredicateShape::Range { lower, upper } => range_includes(&v, lower, upper),
                    IndexPredicateShape::IsNull => v == Value::Null,
                    IndexPredicateShape::IsNotNull => v != Value::Null,
                };
                if include {
                    overlay.matching_inserts.push(row.clone());
                }
            }
        })?;
        Ok(overlay)
    }

    pub fn scan_filter(
        &self,
        table: &str,
        snapshot: SnapshotId,
        predicate: &dyn Fn(&VersionedRow) -> bool,
    ) -> Result<Vec<VersionedRow>> {
        let _operation = self.open_operation()?;
        let rows = self.committed_rows_at(table, snapshot)?;
        let mut rows = self.filter_rows_for_read(table, rows, snapshot)?;
        self.supplement_rows_for_caller(table, &mut rows)?;
        Ok(rows.into_iter().filter(|row| predicate(row)).collect())
    }

    pub fn point_lookup(
        &self,
        table: &str,
        col: &str,
        value: &Value,
        snapshot: SnapshotId,
    ) -> Result<Option<VersionedRow>> {
        let _operation = self.open_operation()?;
        self.assert_table_read_allowed(table)?;
        let Some(row) = self.relational.point_lookup(table, col, value, snapshot)? else {
            return Ok(None);
        };
        let row = self
            .committed_row_at(table, row.row_id, snapshot)?
            .unwrap_or(row);
        let meta = self
            .table_meta(table)
            .ok_or_else(|| Error::TableNotFound(table.to_string()))?;
        if self.read_allowed_for_row(table, &meta, &row, snapshot)? {
            let mut found = [row];
            let selected_row_ids = HashSet::from([found[0].row_id]);
            self.vector_store
                .ensure_raw_partitions_containing_rows(table, &selected_row_ids)?;
            self.supplement_rows_for_caller(table, &mut found)?;
            let [row] = found;
            Ok(Some(row))
        } else {
            Ok(None)
        }
    }

    pub(crate) fn point_lookup_in_tx(
        &self,
        tx: TxId,
        table: &str,
        col: &str,
        value: &Value,
        snapshot: SnapshotId,
    ) -> Result<Option<VersionedRow>> {
        let row = self
            .relational
            .point_lookup_with_tx(Some(tx), table, col, value, snapshot)?;
        let Some(row) = row else {
            return Ok(None);
        };
        let staged = self.tx_mgr.with_write_set(tx, |ws| {
            ws.relational_inserts
                .iter()
                .rev()
                .any(|(staged_table, staged)| staged_table == table && staged.row_id == row.row_id)
        })?;
        if staged {
            Ok(Some(row))
        } else {
            self.committed_row_at(table, row.row_id, snapshot)
        }
    }

    pub(crate) fn record_relational_delete_predicate(
        &self,
        tx: TxId,
        table: String,
        predicates: Vec<(ColName, Value)>,
    ) -> Result<()> {
        if predicates.is_empty() {
            return Ok(());
        }
        self.tx_mgr.with_write_set(tx, |ws| {
            let predicate = RelationalDeletePredicate { table, predicates };
            if !ws.relational_delete_predicates.contains(&predicate) {
                ws.relational_delete_predicates.push(predicate);
            }
        })
    }

    pub(crate) fn conflict_lookup_in_tx(
        &self,
        tx: TxId,
        table: &str,
        columns: &[ColName],
        values: &[Value],
        snapshot: SnapshotId,
    ) -> Result<Option<VersionedRow>> {
        if columns.is_empty() || columns.len() != values.len() {
            return Err(Error::Other(
                "ON CONFLICT target must include matching columns and values".to_string(),
            ));
        }
        if let ([column], [value]) = (columns, values) {
            return self.point_lookup_in_tx(tx, table, column, value, snapshot);
        }
        let deleted_row_ids = self
            .tx_mgr
            .with_write_set(tx, |ws| Self::deleted_row_ids_for_table(ws, table))?;
        if let Some(committed) = self.committed_unique_conflict(
            table,
            columns,
            values,
            snapshot,
            &deleted_row_ids,
            None,
        )? {
            return Ok(Some(committed));
        }

        self.tx_mgr.with_write_set(tx, |ws| {
            let mut seen_inserts = HashSet::new();
            ws.relational_inserts
                .iter()
                .rev()
                .filter(|(insert_table, row)| {
                    insert_table == table
                        && seen_inserts.insert(row.row_id)
                        && (!deleted_row_ids.contains(&row.row_id)
                            || self
                                .relational_store
                                .row_by_id(table, row.row_id, snapshot)
                                .is_some())
                })
                .find(|(_, row)| {
                    columns
                        .iter()
                        .zip(values.iter())
                        .all(|(column, value)| row.values.get(column) == Some(value))
                })
                .map(|(_, row)| row.clone())
        })
    }

    pub(crate) fn unique_row_lookup_in_tx(
        &self,
        tx: TxId,
        table: &str,
        columns: &[ColName],
        values: &[Value],
        snapshot: SnapshotId,
    ) -> Result<Option<VersionedRow>> {
        if columns.is_empty() || columns.len() != values.len() {
            return Ok(None);
        }

        let skip_deleted = HashSet::new();
        if let Some(committed) =
            self.committed_unique_conflict(table, columns, values, snapshot, &skip_deleted, None)?
        {
            let deleted_in_tx = self.tx_mgr.with_write_set(tx, |ws| {
                ws.relational_deletes
                    .iter()
                    .any(|(delete_table, row_id, _)| {
                        delete_table == table && *row_id == committed.row_id
                    })
            })?;
            if !deleted_in_tx {
                return Ok(Some(committed));
            }
        }

        if let Some(staged) = self.tx_mgr.with_write_set(tx, |ws| {
            ws.relational_inserts
                .iter()
                .rev()
                .find_map(|(insert_table, row)| {
                    if insert_table != table
                        || tuple_values_for_row(row, columns).as_deref() != Some(values)
                    {
                        return None;
                    }
                    let deleted_in_tx =
                        ws.relational_deletes
                            .iter()
                            .any(|(delete_table, row_id, _)| {
                                delete_table == table && *row_id == row.row_id
                            });
                    let replaces_committed_row = deleted_in_tx
                        && self
                            .relational_store
                            .row_by_id(table, row.row_id, snapshot)
                            .is_some();
                    (!deleted_in_tx || replaces_committed_row).then(|| row.clone())
                })
        })? {
            return Ok(Some(staged));
        }

        Ok(None)
    }

    pub(crate) fn logical_row_ids_for_uuid(
        &self,
        tx: TxId,
        table: &str,
        uuid: uuid::Uuid,
    ) -> Vec<RowId> {
        let mut row_ids = HashSet::new();

        if let Some(rows) = self.relational_store.tables.read().get(table) {
            for row in rows {
                if row.values.get("id") == Some(&Value::Uuid(uuid)) {
                    row_ids.insert(row.row_id);
                }
            }
        }

        let _ = self.tx_mgr.with_write_set(tx, |ws| {
            for (insert_table, row) in &ws.relational_inserts {
                if insert_table == table && row.values.get("id") == Some(&Value::Uuid(uuid)) {
                    row_ids.insert(row.row_id);
                }
            }
        });

        row_ids.into_iter().collect()
    }

    pub fn insert_edge(
        &self,
        tx: TxId,
        source: NodeId,
        target: NodeId,
        edge_type: EdgeType,
        properties: HashMap<String, Value>,
    ) -> Result<bool> {
        let _operation = self.open_operation_after_write_control_wait(tx, "insert_edge")?;
        let snapshot = self.snapshot();
        self.assert_node_write_allowed(source, snapshot)?;
        self.assert_node_write_allowed(target, snapshot)?;
        self.assert_graph_edge_write_allowed(Some(tx), source, target, &edge_type, snapshot)?;
        let bytes = estimate_edge_bytes(source, target, &edge_type, &properties);
        self.accountant.try_allocate_for(
            bytes,
            "graph_insert",
            "insert_edge",
            "Reduce edge fan-out or raise MEMORY_LIMIT before inserting more graph edges.",
        )?;

        match self
            .graph
            .insert_edge(tx, source, target, edge_type, properties)
        {
            Ok(inserted) => {
                if !inserted {
                    self.accountant.release(bytes);
                }
                Ok(inserted)
            }
            Err(err) => {
                self.accountant.release(bytes);
                Err(err)
            }
        }
    }

    pub fn delete_edge(
        &self,
        tx: TxId,
        source: NodeId,
        target: NodeId,
        edge_type: &str,
    ) -> Result<()> {
        let _operation = self.open_operation_after_write_control_wait(tx, "delete_edge")?;
        let snapshot = self.snapshot();
        self.assert_node_write_allowed(source, snapshot)?;
        self.assert_node_write_allowed(target, snapshot)?;
        self.assert_graph_edge_write_allowed(Some(tx), source, target, edge_type, snapshot)?;
        self.graph.delete_edge(tx, source, target, edge_type)
    }

    pub fn query_bfs(
        &self,
        start: NodeId,
        edge_types: Option<&[EdgeType]>,
        direction: Direction,
        max_depth: u32,
        snapshot: SnapshotId,
    ) -> Result<TraversalResult> {
        let _operation = self.open_operation()?;
        if self.access_is_admin() {
            self.graph
                .bfs(start, edge_types, direction, 1, max_depth, snapshot)
        } else {
            self.query_bfs_gated(start, edge_types, direction, 1, max_depth, snapshot)
        }
    }

    pub fn edge_count(
        &self,
        source: NodeId,
        edge_type: &str,
        snapshot: SnapshotId,
    ) -> Result<usize> {
        let _operation = self.open_operation()?;
        if self.access_is_admin() {
            return Ok(self.graph.edge_count(source, edge_type, snapshot));
        }
        if !self.node_read_allowed(source, snapshot)? {
            return Ok(0);
        }
        let edge_types = [edge_type.to_string()];
        let mut count = 0;
        for (target, edge_type, _, edge_source, edge_target) in self
            .graph_neighbors_with_orientation(
                source,
                Some(&edge_types),
                Direction::Outgoing,
                snapshot,
            )?
        {
            if self.node_read_allowed(target, snapshot)?
                && self.edge_read_allowed(edge_source, edge_target, &edge_type, snapshot)?
            {
                count += 1;
            }
        }
        Ok(count)
    }

    pub fn get_edge_properties(
        &self,
        source: NodeId,
        target: NodeId,
        edge_type: &str,
        snapshot: SnapshotId,
    ) -> Result<Option<HashMap<String, Value>>> {
        let _operation = self.open_operation()?;
        if !self.access_is_admin()
            && (!self.node_read_allowed(source, snapshot)?
                || !self.node_read_allowed(target, snapshot)?
                || !self.edge_read_allowed(source, target, edge_type, snapshot)?)
        {
            return Ok(None);
        }
        let props = self
            .graph_store
            .forward_adj
            .read()
            .get(&source)
            .and_then(|entries| {
                entries
                    .iter()
                    .rev()
                    .find(|entry| {
                        entry.target == target
                            && entry.edge_type == edge_type
                            && entry.visible_at(snapshot)
                    })
                    .map(|entry| entry.properties.clone())
            });
        Ok(props)
    }

    /// Put every vector column of a row into the vector search store.
    ///
    /// A `VECTOR(N)` column IS a named index, so the vector store is the one
    /// place a vector lives and the row-write API is what puts it there.
    /// Before this, only the SQL executor made the second call, so a caller
    /// that wrote a row through this API left the column unindexed -- present
    /// in the row, absent from every vector search, and charged nothing.
    ///
    /// Answers with what each write was charged, so a caller whose statement
    /// fails afterwards hands back exactly what it took.
    /// Leave only quantized vector columns empty in the row that is about to
    /// be stored.
    ///
    /// F32 remains an ordinary relational value. SQ4/SQ8 keep their body only
    /// in the vector store; their relational slot remains NULL internally and
    /// is filled from the vector store on caller-facing projection.
    pub(crate) fn blank_quantized_vector_values(
        &self,
        table: &str,
        values: &mut HashMap<ColName, Value>,
    ) {
        let Some(meta) = self.table_meta(table) else {
            return;
        };
        for column in &meta.columns {
            if !matches!(column.column_type, contextdb_core::ColumnType::Vector(_)) {
                continue;
            }
            if matches!(column.quantization, VectorQuantization::F32) {
                continue;
            }
            if let Some(slot) = values.get_mut(&column.name)
                && matches!(slot, Value::Vector(_))
            {
                *slot = Value::Null;
            }
        }
    }

    /// Fill in the quantized vector columns of rows on their way to an
    /// answer, from the store that holds them.
    ///
    /// The row does not keep a copy, so a reader that projects the column
    /// takes the value from the store the column declared. What comes back is
    /// what every other route already answers with -- the stored
    /// approximation, not the caller's original -- so no answer changes.
    pub(crate) fn supplement_quantized_vectors(
        &self,
        table: &str,
        snapshot: SnapshotId,
        rows: &mut [VersionedRow],
    ) -> Result<()> {
        let Some(meta) = self.table_meta(table) else {
            return Ok(());
        };
        let vector_columns: Vec<String> = meta
            .columns
            .iter()
            .filter(|column| matches!(column.column_type, contextdb_core::ColumnType::Vector(_)))
            .map(|column| column.name.clone())
            .collect();
        if vector_columns.is_empty() {
            return Ok(());
        }
        for column in vector_columns {
            for row in rows.iter_mut() {
                if !matches!(row.values.get(&column), Some(Value::Null) | None) {
                    continue;
                }
                if let Some(vector) =
                    self.load_row_vector_for_column(None, table, &column, row, snapshot)?
                {
                    row.values.insert(column.clone(), Value::Vector(vector));
                }
            }
        }
        Ok(())
    }

    /// Fill only vector columns the caller's expression actually reads.
    /// `None` is the explicit `SELECT *` case; `Some(&[])` deliberately loads
    /// no vector body. Lazy partitions may fail while loading, so this route
    /// must preserve that error instead of returning a row with a false NULL.
    pub(crate) fn supplement_selected_vector_columns(
        &self,
        table: &str,
        snapshot: SnapshotId,
        tx: Option<TxId>,
        selected: Option<&[String]>,
        rows: &mut [VersionedRow],
    ) -> Result<()> {
        let Some(meta) = self.table_meta(table) else {
            return Ok(());
        };
        let vector_columns: Vec<String> = meta
            .columns
            .iter()
            .filter(|column| matches!(column.column_type, contextdb_core::ColumnType::Vector(_)))
            .map(|column| column.name.clone())
            .filter(|column| selected.is_none_or(|selected| selected.contains(column)))
            .collect();
        for column in vector_columns {
            for row in rows.iter_mut() {
                if !matches!(row.values.get(&column), Some(Value::Null) | None) {
                    continue;
                }
                #[cfg(feature = "test-seams")]
                crate::read_work_probe::note_vector_body_access();
                contextdb_core::find_attribution::count("vector_body_accesses", 1);
                let vector = self.load_row_vector_for_column(tx, table, &column, row, snapshot)?;
                if let Some(vector) = vector {
                    row.values.insert(column.clone(), Value::Vector(vector));
                }
            }
        }
        Ok(())
    }

    /// What one row hands to a peer: its own values, with every quantized
    /// vector column read back out of the store that holds it.
    ///
    /// The row keeps no copy of such a column, so a changeset assembled
    /// straight from `row.values` would carry nothing where a vector belongs.
    /// Filling it here is what keeps the payload a peer receives exactly what
    /// it received before -- the same dequantized vector, under the same
    /// column name, in the same shape -- on every route that builds one.
    pub(crate) fn outbound_row_values(
        &self,
        table: &str,
        row: &VersionedRow,
    ) -> Result<HashMap<ColName, Value>> {
        let mut values = row.values.clone();
        values.extend(self.shed_committed_values_for_change(
            table,
            row,
            &ChangeProjection::unbounded(),
        )?);
        self.fill_quantized_from_store(table, row, &mut values)?;
        Ok(values)
    }

    fn fill_quantized_from_store(
        &self,
        table: &str,
        row: &VersionedRow,
        values: &mut HashMap<ColName, Value>,
    ) -> Result<()> {
        self.fill_quantized_columns(table, row.row_id, row.lsn, values)
    }

    fn fill_quantized_columns(
        &self,
        table: &str,
        row_id: RowId,
        lsn: Lsn,
        values: &mut HashMap<ColName, Value>,
    ) -> Result<()> {
        for column in self.quantized_vector_columns(table) {
            if !matches!(values.get(&column), Some(Value::Null) | None) {
                continue;
            }
            let index = VectorIndexRef::new(table, column.clone());
            let vector = match self
                .vector_store
                .load_vector_for_row_lsn(&index, row_id, lsn)?
            {
                some @ Some(_) => some,
                None => self
                    .vector_store
                    .load_live_entry_for_row(&index, row_id, self.snapshot())?
                    .map(|entry| entry.vector),
            };
            if let Some(vector) = vector {
                values.insert(column, Value::Vector(vector));
            }
        }
        Ok(())
    }

    /// Fill the quantized vector columns of whole rows on their way back to a
    /// caller of the row API.
    ///
    /// `scan_filter` and `point_lookup` hand the caller the row itself -- there
    /// is no projection to say which columns are wanted -- so every column the
    /// row declares has to be answerable. A quantized column lives only in its
    /// vector index, so a row handed back unfilled carries NULL where the
    /// embedding belongs: a predicate testing it never matches, and a caller
    /// reading it is told the row has no vector.
    pub(crate) fn supplement_rows_for_caller(
        &self,
        table: &str,
        rows: &mut [VersionedRow],
    ) -> Result<()> {
        if self.quantized_vector_columns(table).is_empty() {
            return Ok(());
        }
        for row in rows.iter_mut() {
            let (row_id, lsn) = (row.row_id, row.lsn);
            let mut values = std::mem::take(&mut row.values);
            self.fill_quantized_columns(table, row_id, lsn, &mut values)?;
            row.values = values;
        }
        Ok(())
    }

    /// What a column will hold once the value given for it is written.
    ///
    /// A quantized column keeps an approximation of the vector it is given, so
    /// this is what a diff has to compare against the stored row -- comparing
    /// the caller's full-precision input instead reports a change that writing
    /// it would not make.
    fn stored_form_of_value(&self, table: &str, column: &str, value: &Value) -> Value {
        let Value::Vector(vector) = value else {
            return value.clone();
        };
        let Some(meta) = self.table_meta(table) else {
            return value.clone();
        };
        let Some(declared) = meta
            .columns
            .iter()
            .find(|candidate| candidate.name == column)
        else {
            return value.clone();
        };
        if !matches!(declared.column_type, contextdb_core::ColumnType::Vector(_))
            || matches!(
                declared.quantization,
                contextdb_core::VectorQuantization::F32
            )
        {
            return value.clone();
        }
        Value::Vector(contextdb_vector::stored_vector_value(
            vector,
            declared.quantization,
        ))
    }

    /// Fallible row projection for the lazy raw-vector store. The exact row
    /// version is preferred, and only a directory that can answer it is
    /// loaded. A transaction's staged vector remains authoritative over the
    /// committed body.
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn bounded_score_committed_vector_row(
        &self,
        index: &VectorIndexRef,
        row_id: RowId,
        snapshot: SnapshotId,
        query: &[f32],
        before_checkpoint: &mut dyn FnMut() -> std::result::Result<
            (),
            crate::executor::BoundedExecutionError,
        >,
        before_distance: &mut dyn FnMut() -> std::result::Result<
            (),
            crate::executor::BoundedExecutionError,
        >,
        before_retain: &mut dyn FnMut(
            usize,
        ) -> std::result::Result<
            (),
            crate::executor::BoundedExecutionError,
        >,
        release_retained: &mut dyn FnMut(usize),
    ) -> std::result::Result<Option<f32>, crate::executor::BoundedExecutionError> {
        self.vector_store.bounded_score_live_row(
            index,
            row_id,
            snapshot,
            query,
            before_checkpoint,
            before_distance,
            before_retain,
            release_retained,
        )
    }

    fn authenticate_selected_row_vector(
        &self,
        index: &VectorIndexRef,
        row_id: RowId,
        loaded: Option<Vec<f32>>,
    ) -> Result<Option<Vec<f32>>> {
        let Some(vector) = loaded else {
            return Ok(None);
        };
        if let Some(source) = &self.retained_relational_source {
            let quantization = self
                .table_meta(&index.table)
                .and_then(|meta| {
                    meta.columns
                        .into_iter()
                        .find(|column| column.name == index.column)
                })
                .ok_or_else(|| Error::UnknownVectorIndex {
                    index: index.clone(),
                })?
                .quantization;
            source.authenticate_selected_vector(index, row_id, &vector, quantization)?;
        }
        Ok(Some(vector))
    }

    pub(crate) fn load_row_vector_for_column(
        &self,
        tx: Option<TxId>,
        table: &str,
        column: &str,
        row: &VersionedRow,
        snapshot: SnapshotId,
    ) -> Result<Option<Vec<f32>>> {
        let index = VectorIndexRef::new(table, column.to_owned());
        if tx.is_some() {
            let loaded = self
                .vector_entry_for_row_in_tx(tx, &index, row.row_id, snapshot)
                .map(|entry| entry.map(|entry| entry.vector))?;
            return self.authenticate_selected_row_vector(&index, row.row_id, loaded);
        }
        if let Some(vector) = self
            .vector_store
            .load_vector_for_row_lsn(&index, row.row_id, row.lsn)?
        {
            return self.authenticate_selected_row_vector(&index, row.row_id, Some(vector));
        }
        // Writable open keeps only the current membership in each dormant
        // partition directory so retired bodies do not become permanent live
        // residency. An older relational snapshot can still name its exact
        // checksummed membership; load that one body directly without
        // widening the live directory or its accountant ownership.
        if let Some(persistence) = self.persistence.as_ref() {
            let meta = self
                .table_meta(table)
                .ok_or_else(|| Error::TableNotFound(table.to_owned()))?;
            let declaration = meta
                .columns
                .iter()
                .find(|declared| declared.name == column)
                .ok_or_else(|| Error::UnknownVectorIndex {
                    index: index.clone(),
                })?;
            let dimension = match declaration.column_type {
                ColumnType::Vector(dimension) => dimension,
                _ => {
                    return Err(Error::UnknownVectorIndex {
                        index: index.clone(),
                    });
                }
            };
            let partition_key = crate::composite_store::vector_partition_key_for_row(
                &index,
                &meta,
                declaration,
                row,
            )?;
            let membership = persistence
                .load_vector_partition_memberships_for_row(&index, &partition_key, row.row_id)?
                .into_iter()
                .filter(|membership| {
                    membership.index == index
                        && membership.row_id == row.row_id
                        && membership.row_lsn == row.lsn
                        && membership.visible_from.0 <= snapshot.0
                        && membership
                            .deleted_tx
                            .is_none_or(|deleted| deleted.0 > snapshot.0)
                })
                .max_by_key(|membership| (membership.vector_lsn, membership.vector_created_tx));
            if let Some(membership) = membership {
                let loaded = persistence
                    .load_vector_entries_for_memberships(&[membership], dimension, None)
                    .map(|mut entries| entries.pop().map(|entry| entry.vector))?;
                return self.authenticate_selected_row_vector(&index, row.row_id, loaded);
            }
        }
        let loaded = self
            .vector_store
            .load_live_entry_for_row(&index, row.row_id, snapshot)
            .map(|entry| entry.map(|entry| entry.vector))?;
        self.authenticate_selected_row_vector(&index, row.row_id, loaded)
    }

    pub(crate) fn load_row_vector_for_column_identity(
        &self,
        tx: Option<TxId>,
        table: &str,
        column: &str,
        row_id: RowId,
        lsn: Lsn,
        snapshot: SnapshotId,
    ) -> Result<Option<Vec<f32>>> {
        let index = VectorIndexRef::new(table, column.to_owned());
        if tx.is_some() {
            return self
                .vector_entry_for_row_in_tx(tx, &index, row_id, snapshot)
                .map(|entry| entry.map(|entry| entry.vector));
        }
        if let Some(vector) = self
            .vector_store
            .load_vector_for_row_lsn(&index, row_id, lsn)?
        {
            return self.authenticate_selected_row_vector(&index, row_id, Some(vector));
        }
        let row = self.row_projection_for_vector_load(tx, table, column, row_id, lsn, snapshot)?;
        self.load_row_vector_for_column(tx, table, column, &row, snapshot)
    }

    /// Which of a table's vector columns keep their value in the vector store.
    pub(crate) fn quantized_vector_columns(&self, table: &str) -> Vec<String> {
        self.table_meta(table)
            .map(|meta| {
                meta.columns
                    .iter()
                    .filter(|column| {
                        matches!(column.column_type, contextdb_core::ColumnType::Vector(_))
                    })
                    .map(|column| column.name.clone())
                    .collect()
            })
            .unwrap_or_default()
    }

    /// The vector columns a row about to be written carries, taken before the
    /// row's values are handed to the relational store.
    pub(crate) fn row_vector_values(
        &self,
        table: &str,
        values: &HashMap<ColName, Value>,
    ) -> Vec<(VectorIndexRef, Vec<f32>)> {
        let Some(meta) = self.table_meta(table) else {
            return Vec::new();
        };
        meta.columns
            .iter()
            .filter(|column| matches!(column.column_type, contextdb_core::ColumnType::Vector(_)))
            .filter_map(|column| match values.get(&column.name) {
                Some(Value::Vector(vector)) => Some((
                    VectorIndexRef::new(table, column.name.clone()),
                    vector.clone(),
                )),
                _ => None,
            })
            .collect()
    }

    /// Place a staged row's vector columns, and if any of them cannot be
    /// placed, take the row back out of the write set.
    ///
    /// The vector store's write needs the row to be staged already -- it
    /// checks that the identity it is given may be written -- so the vectors
    /// cannot go first. What CAN hold is the invariant the executor's
    /// accounting depends on: an insert that fails leaves NOTHING staged, so
    /// the caller's compensation release is the only one that hands the row's
    /// charge back. A row left staged behind a failure is released a second
    /// time by the rollback.
    pub(crate) fn write_row_vectors_or_unstage(
        &self,
        tx: TxId,
        table: &str,
        row_id: RowId,
        values: &HashMap<ColName, Value>,
        staged_before: usize,
    ) -> Result<()> {
        let captured = self.row_vector_values(table, values);
        if captured.is_empty() {
            return Ok(());
        }
        match self.write_row_vectors(tx, row_id, captured) {
            Ok(_) => Ok(()),
            Err(error) => {
                let _ = self.tx_mgr.with_write_set(tx, |ws| {
                    ws.relational_inserts.truncate(staged_before);
                    ws.forget_admitted_bytes_for_unstaged_rows();
                });
                Err(error)
            }
        }
    }

    /// How many rows this transaction has staged, read before one more is.
    pub(crate) fn staged_row_count(&self, tx: TxId) -> usize {
        self.tx_mgr
            .with_write_set(tx, |ws| ws.relational_inserts.len())
            .unwrap_or(0)
    }

    pub(crate) fn write_row_vectors(
        &self,
        tx: TxId,
        row_id: RowId,
        captured: Vec<(VectorIndexRef, Vec<f32>)>,
    ) -> Result<Vec<usize>> {
        let mut charged = Vec::new();
        for (index, vector) in captured {
            let bytes = self.vector_insert_accounted_bytes(&index, vector.len());
            if let Err(error) = self.insert_vector_strict(tx, index, row_id, vector) {
                for taken in &charged {
                    self.accountant.release(*taken);
                }
                return Err(error);
            }
            charged.push(bytes);
        }
        Ok(charged)
    }

    pub fn insert_vector(
        &self,
        tx: TxId,
        index: VectorIndexRef,
        row_id: RowId,
        vector: Vec<f32>,
    ) -> Result<()> {
        let _operation = self.open_operation_after_write_control_wait(tx, "insert_vector")?;
        let _vector_schema = self.vector_schema_read(&index);
        self.ensure_trigger_table_ready(&index.table, "insert_vector")?;
        self.vector_store.index_layout(&index)?;
        self.assert_existing_row_id_write_allowed(Some(tx), &index.table, row_id, self.snapshot())?;
        if let Some(expected) = self.pending_vector_dimension(tx, &index)?
            && expected != vector.len()
        {
            return Err(self.direct_vector_dimension_error(&index, expected, vector.len()));
        }
        self.insert_vector_strict(tx, index.clone(), row_id, vector)
            .map_err(|err| match err {
                Error::VectorIndexDimensionMismatch {
                    expected, actual, ..
                } => self.direct_vector_dimension_error(&index, expected, actual),
                other => other,
            })
    }

    pub(crate) fn insert_vector_strict(
        &self,
        tx: TxId,
        index: VectorIndexRef,
        row_id: RowId,
        vector: Vec<f32>,
    ) -> Result<()> {
        let _vector_schema = self.vector_schema_read(&index);
        self.record_vector_schema_epoch(tx, &index)?;
        self.ensure_trigger_table_ready(&index.table, "insert_vector")?;
        self.vector_store.validate_vector(&index, vector.len())?;
        self.assert_row_id_write_allowed(Some(tx), &index.table, row_id, self.snapshot())?;
        let bytes = self.vector_insert_accounted_bytes(&index, vector.len());
        self.accountant.try_allocate_for(
            bytes,
            "insert",
            &format!("vector_insert@{}.{}", index.table, index.column),
            "Reduce vector dimensionality, insert fewer rows, or raise MEMORY_LIMIT.",
        )?;
        let existing_live =
            self.vector_store
                .has_live_entry_for_row(&index, row_id, self.snapshot());
        let entry = VectorEntry {
            index: index.clone(),
            row_id,
            vector,
            created_tx: tx,
            deleted_tx: None,
            lsn: Lsn(0),
        };
        let replaced_inserts = match self.tx_mgr.with_write_set(tx, |ws| {
            let mut replaced_inserts = Vec::new();
            let mut pos = 0;
            while pos < ws.vector_inserts.len() {
                if ws.vector_inserts[pos].index == index && ws.vector_inserts[pos].row_id == row_id
                {
                    replaced_inserts.push(ws.vector_inserts.remove(pos));
                } else {
                    pos += 1;
                }
            }

            let mut moved_sources = Vec::new();
            let mut pos = 0;
            while pos < ws.vector_moves.len() {
                let (move_index, old_row_id, new_row_id, _) = &ws.vector_moves[pos];
                if *move_index == index && *new_row_id == row_id {
                    moved_sources.push(*old_row_id);
                    ws.vector_moves.remove(pos);
                } else {
                    pos += 1;
                }
            }
            for old_row_id in moved_sources {
                if !ws
                    .vector_deletes
                    .iter()
                    .any(|(pending_index, pending_row_id, _)| {
                        *pending_index == index && *pending_row_id == old_row_id
                    })
                {
                    ws.vector_deletes.push((index.clone(), old_row_id, tx));
                }
            }

            let already_deleted =
                ws.vector_deletes
                    .iter()
                    .any(|(pending_index, pending_row_id, _)| {
                        *pending_index == index && *pending_row_id == row_id
                    });
            if existing_live && !already_deleted {
                ws.vector_deletes.push((index.clone(), row_id, tx));
            }
            ws.vector_inserts.push(entry);
            replaced_inserts
        }) {
            Ok(replaced_inserts) => replaced_inserts,
            Err(err) => {
                self.accountant.release(bytes);
                return Err(err);
            }
        };
        for replaced in replaced_inserts {
            self.accountant.release(
                self.vector_insert_accounted_bytes(&replaced.index, replaced.vector.len()),
            );
        }
        Ok(())
    }

    pub fn delete_vector(&self, tx: TxId, index: VectorIndexRef, row_id: RowId) -> Result<()> {
        let _operation = self.open_operation_after_write_control_wait(tx, "delete_vector")?;
        let _vector_schema = self.vector_schema_read(&index);
        self.record_vector_schema_epoch(tx, &index)?;
        self.ensure_trigger_table_ready(&index.table, "delete_vector")?;
        self.vector_store.index_layout(&index)?;
        self.assert_row_id_write_allowed(Some(tx), &index.table, row_id, self.snapshot())?;
        let existing_live =
            self.vector_store
                .has_live_entry_for_row(&index, row_id, self.snapshot());
        let canceled_inserts = self.tx_mgr.with_write_set(tx, |ws| {
            let mut canceled_inserts = Vec::new();
            let mut pos = 0;
            while pos < ws.vector_inserts.len() {
                if ws.vector_inserts[pos].index == index && ws.vector_inserts[pos].row_id == row_id
                {
                    canceled_inserts.push(ws.vector_inserts.remove(pos));
                } else {
                    pos += 1;
                }
            }
            let mut moved_sources = Vec::new();
            let mut pos = 0;
            while pos < ws.vector_moves.len() {
                let (move_index, old_row_id, new_row_id, _) = &ws.vector_moves[pos];
                if *move_index == index && *new_row_id == row_id {
                    moved_sources.push(*old_row_id);
                    ws.vector_moves.remove(pos);
                } else {
                    pos += 1;
                }
            }
            let pending_move_from_row =
                ws.vector_moves
                    .iter()
                    .any(|(move_index, old_row_id, _, _)| {
                        *move_index == index && *old_row_id == row_id
                    });
            for old_row_id in moved_sources {
                if !ws
                    .vector_deletes
                    .iter()
                    .any(|(pending_index, pending_row_id, _)| {
                        *pending_index == index && *pending_row_id == old_row_id
                    })
                {
                    ws.vector_deletes.push((index.clone(), old_row_id, tx));
                }
            }
            let already_deleted =
                ws.vector_deletes
                    .iter()
                    .any(|(pending_index, pending_row_id, _)| {
                        *pending_index == index && *pending_row_id == row_id
                    });
            if !pending_move_from_row && existing_live && !already_deleted {
                ws.vector_deletes.push((index, row_id, tx));
            }
            canceled_inserts
        })?;
        for entry in canceled_inserts {
            self.accountant
                .release(self.vector_insert_accounted_bytes(&entry.index, entry.vector.len()));
        }
        Ok(())
    }

    pub(crate) fn move_vector(
        &self,
        tx: TxId,
        index: VectorIndexRef,
        old_row_id: RowId,
        new_row_id: RowId,
    ) -> Result<()> {
        let _vector_schema = self.vector_schema_read(&index);
        self.record_vector_schema_epoch(tx, &index)?;
        self.ensure_trigger_table_ready(&index.table, "move_vector")?;
        if !self.vector_store.contains_index(&index) {
            return Err(Error::UnknownVectorIndex { index });
        }
        if old_row_id == new_row_id {
            let meta = self
                .table_meta(&index.table)
                .ok_or_else(|| Error::TableNotFound(index.table.clone()))?;
            let declaration = meta
                .columns
                .iter()
                .find(|column| column.name == index.column)
                .ok_or_else(|| Error::UnknownVectorIndex {
                    index: index.clone(),
                })?;
            if declaration.partition_key_columns.is_none() {
                return Ok(());
            }
            let snapshot = self.snapshot_for_read();
            let Some(old_row) = self
                .relational_store
                .row_by_id(&index.table, old_row_id, snapshot)
            else {
                return Ok(());
            };
            let new_row =
                self.find_row_by_id_in_tx(Some(tx), &index.table, new_row_id, snapshot)?;
            let old_key = crate::composite_store::vector_partition_key_for_row(
                &index,
                &meta,
                declaration,
                &old_row,
            )?;
            let new_key = crate::composite_store::vector_partition_key_for_row(
                &index,
                &meta,
                declaration,
                &new_row,
            )?;
            if old_key == new_key {
                self.tx_mgr.with_write_set(tx, |ws| {
                    ws.vector_moves.retain(|(i, from, to, _)| {
                        !(i == &index && *from == old_row_id && *to == new_row_id)
                    })
                })?;
                return Ok(());
            }
        }
        let existing_live =
            self.vector_store
                .has_live_entry_for_row(&index, old_row_id, self.snapshot());
        let replaced_inserts = self.tx_mgr.with_write_set(tx, |ws| {
            let old_row_deleted =
                ws.vector_deletes
                    .iter()
                    .any(|(pending_index, pending_row_id, _)| {
                        *pending_index == index && *pending_row_id == old_row_id
                    });

            let mut moving_insert = None;
            let mut replaced_inserts = Vec::new();
            let mut pos = 0;
            while pos < ws.vector_inserts.len() {
                if ws.vector_inserts[pos].index == index
                    && ws.vector_inserts[pos].row_id == old_row_id
                {
                    let entry = ws.vector_inserts.remove(pos);
                    if let Some(previous) = moving_insert.replace(entry) {
                        replaced_inserts.push(previous);
                    }
                } else {
                    pos += 1;
                }
            }

            let mut moved_any = moving_insert.is_some();
            let mut has_move_from_old = false;
            for (move_index, source_row_id, destination_row_id, _) in &mut ws.vector_moves {
                if *move_index != index {
                    continue;
                }
                if *destination_row_id == old_row_id {
                    *destination_row_id = new_row_id;
                    moved_any = true;
                }
                if *source_row_id == old_row_id {
                    *destination_row_id = new_row_id;
                    has_move_from_old = true;
                    moved_any = true;
                }
            }

            if !moved_any && existing_live && !old_row_deleted {
                ws.vector_moves
                    .push((index.clone(), old_row_id, new_row_id, tx));
                moved_any = true;
                has_move_from_old = true;
            }

            if moved_any {
                let mut pos = 0;
                while pos < ws.vector_inserts.len() {
                    if ws.vector_inserts[pos].index == index
                        && ws.vector_inserts[pos].row_id == new_row_id
                    {
                        replaced_inserts.push(ws.vector_inserts.remove(pos));
                    } else {
                        pos += 1;
                    }
                }
            }

            if let Some(mut entry) = moving_insert {
                entry.row_id = new_row_id;
                ws.vector_inserts.push(entry);
            } else if has_move_from_old {
                let mut seen_move_from_old = false;
                ws.vector_moves.retain(|(move_index, source_row_id, _, _)| {
                    if *move_index == index && *source_row_id == old_row_id {
                        if seen_move_from_old {
                            false
                        } else {
                            seen_move_from_old = true;
                            true
                        }
                    } else {
                        true
                    }
                });
            }

            replaced_inserts
        })?;
        for replaced in replaced_inserts {
            self.accountant.release(
                self.vector_insert_accounted_bytes(&replaced.index, replaced.vector.len()),
            );
        }
        Ok(())
    }

    /// One owner-door vector search: the single search over every admitted
    /// partition that a SQL find runs. It charges this database's accountant
    /// directly rather than a bounded read's budget, so a saved graph it loads
    /// takes over the bytes the search charged for it and nothing is handed
    /// back to a request.
    fn owner_vector_search(
        &self,
        index: VectorIndexRef,
        query: &[f32],
        k: usize,
        candidates: Option<&RoaringTreemap>,
        snapshot: SnapshotId,
        mode: contextdb_core::VectorSearchMode,
    ) -> Result<(contextdb_vector::mem::SearchScores, VectorSearchDebugTrace)> {
        crate::memory_accounting::with_vector_load_reservation_transfer(
            &self.accountant,
            Arc::new(|_bytes| Ok(())),
            || {
                self.vector
                    .search_with_mode_owned(index, query, k, candidates, snapshot, mode)
            },
        )
    }

    pub fn query_vector(
        &self,
        index: VectorIndexRef,
        query: &[f32],
        k: usize,
        candidates: Option<&RoaringTreemap>,
        snapshot: SnapshotId,
    ) -> Result<Vec<(RowId, f32)>> {
        let _operation = self.open_operation()?;
        let _membership_capture = self.relational_store.begin_membership_capture();
        let _snapshot_registration = self.snapshot_registry.register_statement(snapshot);
        let _vector_schema = self.vector_schema_read(&index);
        if !self.vector_store.contains_index(&index) {
            return Err(Error::UnknownVectorIndex { index });
        }
        let search_mode = self.resolved_vector_search_mode(&index, None)?;
        let effective_candidates =
            self.effective_vector_read_candidates(&index, snapshot, candidates, search_mode)?;
        let (rows, trace) = self.owner_vector_search(
            index,
            query,
            k,
            effective_candidates.as_ref(),
            snapshot,
            search_mode,
        )?;
        self.last_vector_search_used_hnsw
            .store(trace.used_hnsw, Ordering::SeqCst);
        *self.last_vector_search_trace.write() = Some(trace);
        Ok(rows.into_vec())
    }

    pub fn semantic_search(&self, query: SemanticQuery) -> Result<Vec<SearchResult>> {
        let _operation = self.open_operation()?;
        self.semantic_search_with_candidates(query, None)
    }

    #[doc(hidden)]
    #[cfg(any(test, feature = "test-seams"))]
    pub fn __semantic_search_in_tx_for_test(
        &self,
        tx: TxId,
        query: SemanticQuery,
    ) -> Result<Vec<SearchResult>> {
        let _operation = self.open_operation()?;
        let index = VectorIndexRef::new(query.table.clone(), query.vector_column.clone());
        let _vector_schema = self.vector_schema_read(&index);
        self.semantic_search_with_candidates_under_schema_read_in_tx_with_strategy(
            Some(tx),
            query,
            None,
        )
        .map(|(results, _)| results)
    }

    pub(crate) fn semantic_search_with_candidates(
        &self,
        query: SemanticQuery,
        candidates: Option<RoaringTreemap>,
    ) -> Result<Vec<SearchResult>> {
        let index = VectorIndexRef::new(query.table.clone(), query.vector_column.clone());
        let _vector_schema = self.vector_schema_read(&index);
        self.semantic_search_with_candidates_under_schema_read(query, candidates)
    }

    pub(crate) fn semantic_search_with_candidates_under_schema_read(
        &self,
        query: SemanticQuery,
        candidates: Option<RoaringTreemap>,
    ) -> Result<Vec<SearchResult>> {
        self.semantic_search_with_candidates_under_schema_read_with_strategy(query, candidates)
            .map(|(results, _)| results)
    }

    pub(crate) fn semantic_search_with_candidates_under_schema_read_with_strategy(
        &self,
        query: SemanticQuery,
        candidates: Option<RoaringTreemap>,
    ) -> Result<(Vec<SearchResult>, bool)> {
        self.semantic_search_with_candidates_under_schema_read_in_tx_with_strategy(
            None, query, candidates,
        )
        .map(|(results, trace)| (results, trace.used_hnsw))
    }

    pub(crate) fn semantic_search_with_candidates_under_schema_read_in_tx_with_strategy(
        &self,
        tx: Option<TxId>,
        query: SemanticQuery,
        candidates: Option<RoaringTreemap>,
    ) -> Result<(Vec<SearchResult>, VectorSearchDebugTrace)> {
        let index = VectorIndexRef::new(query.table.clone(), query.vector_column.clone());
        let _membership_capture = self.relational_store.begin_membership_capture();
        let snapshot = self.snapshot_for_read();
        let _snapshot_registration = self.snapshot_registry.register_statement(snapshot);
        let meta = self
            .table_meta(&query.table)
            .ok_or_else(|| Error::TableNotFound(query.table.clone()))?;
        let vector_column = meta
            .columns
            .iter()
            .find(|column| column.name == query.vector_column)
            .ok_or_else(|| Error::UnknownVectorIndex {
                index: index.clone(),
            })?;
        let mut search_mode = query.search_mode.unwrap_or(vector_column.search_mode);

        let mut candidate_bitmap = candidates;
        if query.where_clause.is_some()
            || self.bounded_read_requires_candidate_filter(&index.table)?
        {
            let where_clause = query.where_clause.as_deref().unwrap_or("");
            let (where_bitmap, complete_indexed_route) = self.semantic_where_candidate_bitmap(
                tx,
                &index,
                where_clause,
                snapshot,
                search_mode == contextdb_core::VectorSearchMode::Indexed,
                search_mode == contextdb_core::VectorSearchMode::Auto,
            )?;
            if search_mode == contextdb_core::VectorSearchMode::Auto && !complete_indexed_route {
                search_mode = contextdb_core::VectorSearchMode::Exact;
            }
            candidate_bitmap = Some(match candidate_bitmap {
                Some(mut existing) => {
                    existing &= where_bitmap;
                    existing
                }
                None => where_bitmap,
            });
        }

        let Some(sort_key) = query.sort_key.as_deref() else {
            // A score floor filters the nearest LIMIT candidates; it never
            // widens an indexed query to the whole authorized population.
            let (mut rows, trace) = self.query_vector_strict_in_tx_with_strategy(
                tx,
                index.clone(),
                &query.query,
                query.limit,
                candidate_bitmap.as_ref(),
                snapshot,
                search_mode,
            )?;
            if let Some(min_similarity) = query.min_similarity {
                rows.retain(|(_, score)| *score >= min_similarity);
                rows.truncate(query.limit);
            }
            let results = rows
                .into_iter()
                .map(|(row_id, vector_score)| {
                    let anchor = self.find_row_by_id_in_tx(tx, &query.table, row_id, snapshot)?;
                    let values = self.search_result_values_in_tx(
                        tx,
                        &index,
                        row_id,
                        snapshot,
                        anchor.values,
                    )?;
                    Ok(SearchResult {
                        row_id,
                        values,
                        vector_score,
                        rank: vector_score,
                    })
                })
                .collect::<Result<Vec<_>>>()?;
            return Ok((results, trace));
        };

        let Some(policy) = vector_column.rank_policy.as_ref() else {
            return Err(Error::RankPolicyNotFound {
                index: rank_index_name(&query.table, &query.vector_column),
                sort_key: sort_key.to_string(),
            });
        };
        if policy.sort_key != sort_key {
            return Err(Error::RankPolicyNotFound {
                index: rank_index_name(&query.table, &query.vector_column),
                sort_key: sort_key.to_string(),
            });
        }
        let formula = self.rank_formula(&query.table, &query.vector_column)?;
        let entry_count = self.vector_entry_count_in_tx(tx, &index, snapshot)?;
        let whole_pool = self.rank_policy_candidate_k(
            &index,
            entry_count,
            query.limit,
            true,
            candidate_bitmap.as_ref(),
            snapshot,
        )?;
        let internal_k = self.rank_policy_candidate_k(
            &index,
            entry_count,
            query.limit,
            search_mode == contextdb_core::VectorSearchMode::Exact,
            candidate_bitmap.as_ref(),
            snapshot,
        )?;
        let (mut raw, mut trace) =
            contextdb_vector::mem::with_search_policy_limit(query.limit, || {
                self.query_vector_strict_in_tx_with_strategy(
                    tx,
                    index.clone(),
                    &query.query,
                    internal_k,
                    candidate_bitmap.as_ref(),
                    snapshot,
                    search_mode,
                )
            })?;
        if search_mode == contextdb_core::VectorSearchMode::Auto
            && !trace.used_hnsw
            && internal_k < whole_pool
            && raw.len() >= internal_k
        {
            // AUTO resolved to the exact route -- below the automatic
            // crossover, or because the graph could not serve this read --
            // and inherits that route's candidate meaning: the formula runs
            // over every allowed stored vector. The bounded pool it was
            // handed can have cut the best-scoring row before the formula
            // ever saw it, so the read is repeated over the whole pool,
            // behind the same score-budget refusal an explicit EXACT read
            // passes.
            drop(raw);
            let (rerun, rerun_trace) = self.query_vector_strict_in_tx_with_strategy(
                tx,
                index.clone(),
                &query.query,
                whole_pool,
                candidate_bitmap.as_ref(),
                snapshot,
                search_mode,
            )?;
            raw = rerun;
            trace = rerun_trace;
        }
        if let Some(min_similarity) = query.min_similarity {
            raw.retain(|(_, score)| *score >= min_similarity);
        }

        // Only the rows still in contention for the answer are held: one
        // evaluated candidate past `LIMIT` is enough to know which to drop, so
        // a rank over the whole table holds `LIMIT` rows' values, never every
        // row's. The scores themselves are what the exact budget pays for.
        let mut contenders = std::collections::BinaryHeap::new();
        for (row_id, vector_score) in raw {
            crate::executor::observe_bounded_rank_candidate();
            let anchor = self.find_row_by_id_in_tx(tx, &query.table, row_id, snapshot)?;
            let joined = self.joined_row_for_rank_policy(tx, policy, &anchor, snapshot)?;
            self.rank_policy_eval_count.fetch_add(1, Ordering::SeqCst);
            let eval = formula.eval_with_resolver(vector_score, |column| {
                self.resolve_rank_formula_column(policy, &anchor, joined.as_ref(), column)
            });
            let rank = match eval {
                Ok(Some(rank)) => rank,
                Ok(None) => f32::NAN,
                Err(err) => {
                    let error_row_id =
                        if matches!(err, FormulaEvalError::CorruptJoinedColumn { .. }) {
                            joined.as_ref().map(|row| row.row_id).unwrap_or(row_id)
                        } else {
                            row_id
                        };
                    self.warn_rank_eval_error(
                        &query.table,
                        &query.vector_column,
                        error_row_id,
                        &err,
                    );
                    continue;
                }
            };
            contenders.push(RankedSearchCandidate {
                row_id,
                vector_score,
                rank,
                anchor,
                joined,
            });
            if contenders.len() > query.limit {
                // The heap's top is the candidate that ranks last.
                contenders.pop();
            }
        }
        let mut ranked = Vec::with_capacity(contenders.len());
        for candidate in contenders.into_sorted_vec() {
            let values = self.search_result_values_in_tx(
                tx,
                &index,
                candidate.row_id,
                snapshot,
                merged_rank_values(&candidate.anchor, candidate.joined.as_ref()),
            )?;
            ranked.push(SearchResult {
                row_id: candidate.row_id,
                values,
                vector_score: candidate.vector_score,
                rank: candidate.rank,
            });
        }
        Ok((ranked, trace))
    }

    #[doc(hidden)]
    #[cfg(any(test, feature = "test-seams"))]
    pub fn __rank_policy_eval_count(&self) -> u64 {
        let _operation = self.assert_open_operation();
        self.rank_policy_eval_count.load(Ordering::SeqCst)
    }

    #[doc(hidden)]
    #[cfg(any(test, feature = "test-seams"))]
    pub fn __reset_rank_policy_eval_count(&self) {
        let _operation = self.assert_open_operation();
        self.rank_policy_eval_count.store(0, Ordering::SeqCst);
    }

    #[doc(hidden)]
    #[cfg(any(test, feature = "test-seams"))]
    pub fn __rank_policy_formula_parse_count(&self) -> u64 {
        let _operation = self.assert_open_operation();
        self.rank_policy_formula_parse_count.load(Ordering::SeqCst)
    }

    /// Acceptance-test accessor: threads currently in this database's trigger
    /// callback owner map. Zero at rest — nonzero after every callback
    /// completed means `TriggerCallbackThreadGuard::drop` leaked an entry.
    #[doc(hidden)]
    #[cfg(any(test, feature = "test-seams"))]
    pub fn trigger_callback_owner_thread_count_for_test(&self) -> usize {
        self.trigger.owner_thread_count()
    }

    /// Acceptance-test accessor. Reads at steady state (after stop signal
    /// + writer-threads joined). Snapshots are not atomic across counters.
    #[doc(hidden)]
    #[cfg(any(test, feature = "test-seams"))]
    pub fn trigger_progress_telemetry_snapshot_for_test(&self) -> TriggerProgressTelemetrySnapshot {
        TriggerProgressTelemetrySnapshot {
            wait_observed: self.trigger.wait_observed_count.load(Ordering::SeqCst),
            typed_err_observed_same_db: self
                .trigger
                .typed_err_observed_same_db_count
                .load(Ordering::SeqCst),
            deadlock_guard_timeout_observed: self
                .trigger
                .deadlock_guard_timeout_observed_count
                .load(Ordering::SeqCst),
        }
    }

    #[doc(hidden)]
    #[cfg(any(test, feature = "test-seams"))]
    pub fn __inject_raw_joined_row_value_for_test(
        &self,
        table: &str,
        row_id: RowId,
        column: &str,
        _raw_bytes: Vec<u8>,
    ) -> Result<()> {
        let _operation = self.open_operation()?;
        self.corrupt_joined_values
            .write()
            .insert((table.to_string(), row_id, column.to_string()));
        Ok(())
    }

    /// Transaction, scope, snapshot, and mode are separate execution inputs;
    /// combining them would obscure the vector-query contract at each caller.
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn query_vector_strict_in_tx_with_strategy(
        &self,
        tx: Option<TxId>,
        index: VectorIndexRef,
        query: &[f32],
        k: usize,
        candidates: Option<&RoaringTreemap>,
        snapshot: SnapshotId,
        search_mode: contextdb_core::VectorSearchMode,
    ) -> Result<(contextdb_vector::mem::SearchScores, VectorSearchDebugTrace)> {
        self.vector_store.validate_vector(&index, query.len())?;
        if let Some(tx) = tx {
            let overlay_result = self.tx_mgr.with_write_set(tx, |ws| {
                if write_set_touches_vector_search(ws, &index) {
                    Some(self.query_vector_strict_with_write_set_overlay(
                        ws,
                        StrictVectorOverlayRequest {
                            index: index.clone(),
                            query,
                            k,
                            candidates,
                            snapshot,
                            search_mode,
                        },
                    ))
                } else {
                    None
                }
            })?;
            if let Some(result) = overlay_result {
                return result;
            }
        }
        let effective_candidates =
            self.effective_vector_read_candidates(&index, snapshot, candidates, search_mode)?;
        let (rows, trace) = self.owner_vector_search(
            index,
            query,
            k,
            effective_candidates.as_ref(),
            snapshot,
            search_mode,
        )?;
        self.last_vector_search_used_hnsw
            .store(trace.used_hnsw, Ordering::SeqCst);
        *self.last_vector_search_trace.write() = Some(trace.clone());
        Ok((rows, trace))
    }

    pub(crate) fn resolved_vector_search_mode(
        &self,
        index: &VectorIndexRef,
        requested: Option<contextdb_core::VectorSearchMode>,
    ) -> Result<contextdb_core::VectorSearchMode> {
        if let Some(requested) = requested {
            return Ok(requested);
        }
        let meta = self
            .table_meta(&index.table)
            .ok_or_else(|| Error::TableNotFound(index.table.clone()))?;
        meta.columns
            .iter()
            .find(|column| column.name == index.column)
            .map(|column| column.search_mode)
            .ok_or_else(|| Error::UnknownVectorIndex {
                index: index.clone(),
            })
    }

    fn query_vector_strict_with_write_set_overlay(
        &self,
        ws: &WriteSet,
        request: StrictVectorOverlayRequest<'_>,
    ) -> Result<(contextdb_vector::mem::SearchScores, VectorSearchDebugTrace)> {
        let StrictVectorOverlayRequest {
            index,
            query,
            k,
            candidates,
            snapshot,
            search_mode,
        } = request;
        if k == 0 {
            return Ok((
                contextdb_vector::mem::SearchScores::new(index.clone(), self.accountant.clone()),
                VectorSearchDebugTrace {
                    index,
                    used_hnsw: false,
                    hnsw_len: None,
                    hnsw_candidate_count: 0,
                    hnsw_candidate_row_ids: Vec::new(),
                    final_row_ids: Vec::new(),
                    supplemented_row_count: 0,
                    fallback_reason: Some("empty_limit"),
                    partition_routes: Vec::new(),
                    hnsw_ef_search: None,
                    selected_generations: Vec::new(),
                    budget_receipt: None,
                },
            ));
        }
        let layout = self.vector_store.index_layout(&index)?;
        let staged_entries = ws
            .vector_inserts
            .iter()
            .filter(|entry| entry.index == index && entry.deleted_tx.is_none())
            .count();
        let removed_entries = ws
            .vector_deletes
            .iter()
            .filter(|(delete_index, _, _)| delete_index == &index)
            .count()
            .saturating_add(
                ws.relational_deletes
                    .iter()
                    .filter(|(table, _, _)| table == &index.table)
                    .count(),
            );
        let moved_entries = ws
            .vector_moves
            .iter()
            .filter(|(move_index, _, _, _)| move_index == &index)
            .count();
        let overlay_bytes = estimate_active_tx_vector_overlay_bytes(
            staged_entries
                .saturating_add(removed_entries)
                .saturating_add(moved_entries),
            layout.dimension,
        );
        self.accountant.try_allocate_for(
            overlay_bytes,
            "query",
            &format!("active_tx_vector_overlay@{}.{}", index.table, index.column),
            "Reduce active transaction vector search scope or raise MEMORY_LIMIT.",
        )?;

        let result =
            (|| -> Result<(contextdb_vector::mem::SearchScores, VectorSearchDebugTrace)> {
                let mut removed = HashSet::new();
                for (delete_table, row_id, _) in &ws.relational_deletes {
                    let has_same_row_replacement =
                        ws.relational_inserts.iter().any(|(insert_table, row)| {
                            insert_table == &index.table && row.row_id == *row_id
                        });
                    if delete_table == &index.table && !has_same_row_replacement {
                        removed.insert(*row_id);
                    }
                }
                for (delete_index, row_id, _) in &ws.vector_deletes {
                    if delete_index == &index {
                        removed.insert(*row_id);
                    }
                }
                let moved = ws
                    .vector_moves
                    .iter()
                    .filter(|(move_index, _, _, _)| move_index == &index)
                    .map(|(_, from_row_id, to_row_id, _)| (*from_row_id, *to_row_id))
                    .collect::<HashMap<_, _>>();
                let staged_identities = ws
                    .vector_inserts
                    .iter()
                    .filter(|entry| entry.index == index && entry.deleted_tx.is_none())
                    .map(|entry| entry.row_id)
                    .collect::<HashSet<_>>();

                let mut committed_candidates = candidates.cloned();
                if let Some(committed_candidates) = committed_candidates.as_mut() {
                    for (from, to) in &moved {
                        if committed_candidates.contains(to.0) {
                            committed_candidates.insert(from.0);
                        }
                    }
                }
                let effective_candidates = self.effective_vector_read_candidates(
                    &index,
                    snapshot,
                    committed_candidates.as_ref(),
                    search_mode,
                )?;
                let mut committed_k = k
                    .saturating_add(removed.len())
                    .saturating_add(moved.len())
                    .saturating_add(staged_identities.len());
                let mut previous_progress = None;
                let (mut scored, mut trace) = loop {
                    let (committed, next_trace) = self.owner_vector_search(
                        index.clone(),
                        query,
                        committed_k,
                        effective_candidates.as_ref(),
                        snapshot,
                        search_mode,
                    )?;
                    let returned = committed.len();
                    let mut eligible = contextdb_vector::mem::SearchScores::new(
                        index.clone(),
                        self.accountant.clone(),
                    );
                    if search_mode == contextdb_core::VectorSearchMode::Exact {
                        eligible = eligible.for_exact();
                    }
                    eligible.reserve(returned.saturating_add(staged_entries))?;
                    for (row_id, score) in committed {
                        if removed.contains(&row_id)
                            || staged_identities.contains(&row_id)
                            || moved.contains_key(&row_id)
                        {
                            continue;
                        }
                        let row_id = moved.get(&row_id).copied().unwrap_or(row_id);
                        if let Some(candidates) = candidates
                            && !candidates.contains(row_id.0)
                        {
                            continue;
                        }
                        if !self.row_id_read_allowed_in_write_set_for_query(
                            ws,
                            &index.table,
                            row_id,
                            snapshot,
                        )? {
                            continue;
                        }
                        eligible.try_push((row_id, score))?;
                    }
                    if eligible.len() >= k || previous_progress == Some((returned, eligible.len()))
                    {
                        break (eligible, next_trace);
                    }
                    previous_progress = Some((returned, eligible.len()));
                    let refill = k.saturating_sub(eligible.len()).max(1);
                    let next_k = committed_k
                        .saturating_add(refill)
                        .max(committed_k.saturating_mul(2));
                    if next_k == committed_k {
                        break (eligible, next_trace);
                    }
                    committed_k = next_k;
                };

                let mut newest_staged = HashMap::<RowId, &VectorEntry>::new();
                for entry in &ws.vector_inserts {
                    if entry.index == index && entry.deleted_tx.is_none() {
                        newest_staged.insert(entry.row_id, entry);
                    }
                }
                for (from, to) in &moved {
                    if removed.contains(to)
                        || staged_identities.contains(to)
                        || candidates.is_some_and(|ids| !ids.contains(to.0))
                    {
                        continue;
                    }
                    if !self.vector_staged_row_in_selected_partitions(ws, &index, *to)?
                        || !self.row_id_read_allowed_in_write_set_for_query(
                            ws,
                            &index.table,
                            *to,
                            snapshot,
                        )?
                    {
                        continue;
                    }
                    if let Some(score) = self.vector_store.bounded_score_live_row(
                        &index,
                        *from,
                        snapshot,
                        query,
                        || Ok::<_, Error>(()),
                        || Ok::<_, Error>(()),
                        |bytes| {
                            self.accountant.try_allocate_for(
                                bytes,
                                "vector_search",
                                "score_moved_vector",
                                "Reduce transaction scope or raise MEMORY_LIMIT.",
                            )
                        },
                        |bytes| self.accountant.release(bytes),
                    )? {
                        scored.try_push((*to, score))?;
                    }
                }
                for (row_id, entry) in newest_staged {
                    if !self.vector_staged_row_in_selected_partitions(ws, &index, row_id)? {
                        continue;
                    }
                    if let Some(candidates) = candidates
                        && !candidates.contains(row_id.0)
                    {
                        continue;
                    }
                    if !self.row_id_read_allowed_in_write_set_for_query(
                        ws,
                        &index.table,
                        row_id,
                        snapshot,
                    )? {
                        continue;
                    }
                    scored.try_push((row_id, cosine_similarity(&entry.vector, query)))?;
                }
                scored.sort_unstable_by(|left, right| {
                    right
                        .1
                        .total_cmp(&left.1)
                        .then_with(|| left.0.cmp(&right.0))
                });
                scored.truncate(k);
                trace.final_row_ids = scored.iter().map(|(row_id, _)| *row_id).collect();
                trace.supplemented_row_count = trace
                    .supplemented_row_count
                    .saturating_add(staged_entries.min(scored.len()));
                let used_hnsw = trace.used_hnsw;
                self.last_vector_search_used_hnsw
                    .store(used_hnsw, Ordering::SeqCst);
                *self.last_vector_search_trace.write() = Some(trace.clone());
                Ok((scored, trace))
            })();
        self.accountant.release(overlay_bytes);
        result
    }

    pub(crate) fn register_rank_formula(
        &self,
        table: &str,
        column: &str,
        formula: Arc<RankFormula>,
    ) {
        let mut cache = self.rank_formula_cache.write();
        cache.insert((table.to_string(), column.to_string()), formula);
        self.rank_policy_formula_parse_count
            .store(cache.len() as u64, Ordering::SeqCst);
    }

    pub(crate) fn remove_rank_formula(&self, table: &str, column: &str) {
        let mut cache = self.rank_formula_cache.write();
        cache.remove(&(table.to_string(), column.to_string()));
        self.rank_policy_formula_parse_count
            .store(cache.len() as u64, Ordering::SeqCst);
    }

    pub(crate) fn remove_rank_formulas_for_table(&self, table: &str) {
        let mut cache = self.rank_formula_cache.write();
        cache.retain(|(policy_table, _), _| policy_table != table);
        self.rank_policy_formula_parse_count
            .store(cache.len() as u64, Ordering::SeqCst);
    }

    fn rebuild_rank_formula_cache_from_meta(
        &self,
        metas: &HashMap<String, TableMeta>,
    ) -> Result<()> {
        let cache = Self::prepare_rank_formula_cache(metas)?;
        self.publish_prepared_rank_formula_cache(cache);
        Ok(())
    }

    fn prepare_rank_formula_cache(
        metas: &HashMap<String, TableMeta>,
    ) -> Result<HashMap<(String, String), Arc<RankFormula>>> {
        let mut cache = HashMap::new();
        for (table, meta) in metas {
            for column in &meta.columns {
                if let Some(policy) = &column.rank_policy {
                    let formula = RankFormula::compile_for_index(
                        &rank_index_name(table, &column.name),
                        &policy.formula,
                    )?;
                    cache.insert((table.clone(), column.name.clone()), Arc::new(formula));
                }
            }
        }
        Ok(cache)
    }

    fn publish_prepared_rank_formula_cache(
        &self,
        cache: HashMap<(String, String), Arc<RankFormula>>,
    ) {
        let count = cache.len() as u64;
        *self.rank_formula_cache.write() = cache;
        self.rank_policy_formula_parse_count
            .store(count, Ordering::SeqCst);
    }

    fn rank_formula(&self, table: &str, column: &str) -> Result<Arc<RankFormula>> {
        self.rank_formula_cache
            .read()
            .get(&(table.to_string(), column.to_string()))
            .cloned()
            .ok_or_else(|| {
                Error::Other(format!(
                    "rank policy formula cache missing for {}",
                    rank_index_name(table, column)
                ))
            })
    }

    pub(crate) fn vector_entry_count(&self, index: &VectorIndexRef, snapshot: SnapshotId) -> usize {
        self.vector_store.visible_entry_count(index, snapshot)
    }

    fn vector_entry_count_in_tx(
        &self,
        tx: Option<TxId>,
        index: &VectorIndexRef,
        snapshot: SnapshotId,
    ) -> Result<usize> {
        let base = self.vector_store.visible_entry_count(index, snapshot);
        let Some(tx) = tx else {
            return Ok(base);
        };
        self.tx_mgr.with_write_set(tx, |ws| {
            base.saturating_add(
                ws.vector_inserts
                    .iter()
                    .filter(|entry| entry.index == *index && entry.deleted_tx.is_none())
                    .count(),
            )
        })
    }

    /// EXACT ranks every allowed vector; indexed ranking uses the column's
    /// resolved candidate breadth. The caller's LIMIT is resolved only once.
    #[allow(clippy::too_many_arguments)]
    fn rank_policy_candidate_k(
        &self,
        index: &VectorIndexRef,
        entry_count: usize,
        limit: usize,
        exact_route: bool,
        candidates: Option<&RoaringTreemap>,
        snapshot: SnapshotId,
    ) -> Result<usize> {
        if entry_count == 0 || limit == 0 {
            return Ok(limit);
        }
        if exact_route {
            return Ok(entry_count);
        }
        let bytes = candidates
            .map_or(0, |ids| ids.len() as usize)
            .saturating_mul(std::mem::size_of::<u64>());
        let _credit = crate::memory_accounting::ScopedMemoryReservation::try_new_for(
            self.accountant(),
            bytes,
            "vector_search",
            "rank_candidate_ids",
            "Narrow the authorized scope or raise MEMORY_LIMIT.",
        )?;
        let ids = candidates.map(|ids| ids.iter().collect::<Vec<_>>());
        let groups = self.vector.bounded_candidate_groups(
            index,
            ids.as_deref(),
            snapshot,
            || Ok::<_, Error>(()),
            || Ok::<_, Error>(()),
            |bytes| {
                self.accountant.try_allocate_for(
                    bytes,
                    "vector_search",
                    "rank_candidate_sources",
                    "Narrow the authorized scope or raise MEMORY_LIMIT.",
                )
            },
            |bytes| self.accountant.release(bytes),
        )?;
        let candidate_k =
            self.vector
                .bounded_rank_candidate_k_grouped(index, limit, &groups, || Ok::<_, Error>(()));
        self.accountant.release(groups.into_retained_bytes());
        candidate_k
    }

    fn semantic_where_candidate_bitmap(
        &self,
        tx: Option<TxId>,
        index: &VectorIndexRef,
        where_clause: &str,
        snapshot: SnapshotId,
        require_bounded_route: bool,
        preflight_auto_fallback: bool,
    ) -> Result<(RoaringTreemap, bool)> {
        let table = index.table.as_str();
        let sql = if where_clause.is_empty() {
            format!("SELECT row_id AS __vector_candidate_identity FROM {table}")
        } else {
            format!(
                "SELECT row_id AS __vector_candidate_identity FROM {table} WHERE {where_clause}"
            )
        };
        let stmt = contextdb_parser::parse(&sql)?;
        let Statement::Select(select) = &stmt else {
            return Err(Error::ParseError("semantic WHERE parse failed".into()));
        };
        let params = HashMap::new();
        let plan = contextdb_planner::plan(&stmt)?;
        if let Some(expr) = select.body.where_clause.as_ref() {
            crate::executor::bind_vector_search_parameters(expr, Some(&plan), &params)?;
        }
        let route = crate::executor::vector_candidate_route(self, index, Some(&plan), &params)?;
        let access_filter = route.access_filter;
        let access_plan = route.candidates;
        let scope = route.scope;
        let directory_route = route.directory_route;
        let complete = route.complete;
        if require_bounded_route && !complete {
            return Err(Error::VectorFilteredRouteUnavailable {
                index: index.clone(),
                predicate_columns: crate::executor::vector_candidate_refusal_columns(
                    self,
                    index,
                    access_plan.as_ref(),
                    access_filter,
                ),
            });
        }
        if preflight_auto_fallback && !complete {
            let exact_score_bytes = self
                .vector_entry_count(index, snapshot)
                .saturating_mul(std::mem::size_of::<(RowId, f32)>());
            if crate::memory_accounting::ScopedMemoryReservation::try_new_for(
                self.accountant(),
                exact_score_bytes,
                "vector_search",
                "preflight_filtered_exact_scores",
                "Add a relational index for the filter, reduce vector volume, or raise MEMORY_LIMIT.",
            )
            .is_err()
            {
                return Err(Error::VectorFilteredRouteUnavailable {
                    index: index.clone(),
            predicate_columns: crate::executor::vector_candidate_refusal_columns(self, index, access_plan.as_ref(), access_filter),
                });
            }
        }
        let mut bitmap = RoaringTreemap::new();
        if directory_route {
            bitmap = self.vector_directory_candidate_bitmap(
                tx,
                index,
                snapshot,
                select.body.where_clause.as_ref(),
                &params,
                scope.as_ref(),
            )?;
        } else {
            let result =
                self.run_read_plan(access_plan.as_ref().unwrap_or(&plan), &params, tx, snapshot)?;
            let row_id_column = result
                .columns
                .iter()
                .position(|column| column == "__vector_candidate_identity")
                .ok_or_else(|| {
                    Error::PlanError("semantic candidate source omitted row identity".into())
                })?;
            for row in result.rows {
                if let Some(Value::Int64(id)) = row.get(row_id_column) {
                    bitmap.insert(*id as u64);
                }
            }
        }
        Ok((bitmap, complete))
    }

    pub(crate) fn vector_directory_candidate_bitmap(
        &self,
        tx: Option<TxId>,
        index: &VectorIndexRef,
        snapshot: SnapshotId,
        filter: Option<&contextdb_parser::ast::Expr>,
        params: &HashMap<String, Value>,
        scope: Option<&crate::executor::VectorPartitionScope>,
    ) -> Result<RoaringTreemap> {
        let table = index.table.as_str();
        let mut bitmap = RoaringTreemap::new();
        let meta = self
            .table_meta(table)
            .ok_or_else(|| Error::TableNotFound(table.to_owned()))?;
        let mut admit = |id| -> Result<()> {
            let row = match self.find_row_by_id_in_tx(tx, table, id, snapshot) {
                Ok(row) => row,
                Err(Error::NotFound(_)) => return Ok(()),
                Err(error) => return Err(error),
            };
            if let Some(expr) = filter
                && !crate::executor::row_matches(&row, expr, params)?
            {
                return Ok(());
            }
            if self.bounded_read_allowed_for_row(tx, table, &meta, &row, snapshot, &mut |_| {
                Ok::<(), Error>(())
            })? {
                bitmap.insert(id.0);
            }
            Ok(())
        };
        let mut collect = || {
            self.vector.bounded_visit_visible_ids(
                index,
                snapshot,
                || Ok(()),
                |bytes| {
                    self.accountant.try_allocate_for(
                        bytes,
                        "vector_search",
                        "authorized_directory",
                        "Narrow the authorized scope or raise MEMORY_LIMIT.",
                    )
                },
                |bytes| self.accountant.release(bytes),
                &mut admit,
            )
        };
        if let Some(prefixes) =
            scope.and_then(crate::executor::VectorPartitionScope::resolved_prefixes)
        {
            contextdb_vector::mem::with_selected_partition_prefixes(
                index,
                prefixes.to_vec(),
                collect,
            )?;
        } else {
            collect()?;
        }
        if let Some(tx) = tx {
            let staged = self.tx_mgr.with_write_set(tx, |ws| {
                ws.relational_inserts
                    .iter()
                    .filter(|(row_table, _)| row_table == table)
                    .map(|(_, row)| row.row_id)
                    .collect::<Vec<_>>()
            })?;
            for id in staged {
                admit(id)?;
            }
        }
        Ok(bitmap)
    }

    fn effective_vector_read_candidates(
        &self,
        index: &VectorIndexRef,
        snapshot: SnapshotId,
        candidates: Option<&RoaringTreemap>,
        mode: contextdb_core::VectorSearchMode,
    ) -> Result<Option<RoaringTreemap>> {
        if candidates.is_none() && self.bounded_read_requires_candidate_filter(&index.table)? {
            return self
                .semantic_where_candidate_bitmap(
                    None,
                    index,
                    "",
                    snapshot,
                    mode == contextdb_core::VectorSearchMode::Indexed,
                    mode == contextdb_core::VectorSearchMode::Auto,
                )
                .map(|(ids, _)| Some(ids));
        }
        self.effective_read_candidates(&index.table, snapshot, candidates)
    }

    fn find_row_by_id_at(
        &self,
        table: &str,
        row_id: RowId,
        snapshot: SnapshotId,
    ) -> Result<VersionedRow> {
        self.committed_row_at(table, row_id, snapshot)?
            .ok_or_else(|| Error::NotFound(format!("row {row_id} in table {table}")))
    }

    fn joined_row_for_rank_policy(
        &self,
        tx: Option<TxId>,
        policy: &RankPolicy,
        anchor: &VersionedRow,
        snapshot: SnapshotId,
    ) -> Result<Option<VersionedRow>> {
        if policy.anchor_column.is_empty() {
            return Err(Error::Other(format!(
                "rank policy on index {}.{} has no resolved anchor join column",
                policy.joined_table, policy.joined_column
            )));
        }
        let join_value = anchor
            .values
            .get(&policy.anchor_column)
            .cloned()
            .unwrap_or(Value::Null);
        if join_value == Value::Null {
            return Ok(None);
        }

        let indexes = self.relational_store.indexes.read();
        let storage = indexes
            .get(&policy.joined_table)
            .and_then(|table_indexes| table_indexes.get(&policy.protected_index))
            .ok_or_else(|| {
                Error::Other(format!(
                    "rank policy protected index `{}` missing on table `{}`",
                    policy.protected_index, policy.joined_table
                ))
            })?;
        let Some((first_column, direction)) = storage.columns.first() else {
            return Err(Error::Other(format!(
                "rank policy protected index `{}` on `{}` has no columns",
                policy.protected_index, policy.joined_table
            )));
        };
        if first_column != &policy.joined_column {
            return Err(Error::Other(format!(
                "rank policy protected index `{}` on `{}` no longer leads with `{}`",
                policy.protected_index, policy.joined_table, policy.joined_column
            )));
        }
        if let Some(tx) = tx {
            drop(indexes);
            return self.joined_row_for_rank_policy_in_tx(tx, policy, &join_value, snapshot);
        }

        let key_component = match direction {
            SortDirection::Asc => DirectedValue::Asc(TotalOrdAsc(join_value.clone())),
            SortDirection::Desc => DirectedValue::Desc(TotalOrdDesc(join_value.clone())),
        };
        let mut best_row_id: Option<RowId> = None;
        let mut consider = |entries: &[contextdb_relational::IndexEntry]| {
            for entry in entries {
                if entry.visible_at(snapshot)
                    && best_row_id.is_none_or(|current| current < entry.row_id)
                {
                    best_row_id = Some(entry.row_id);
                }
            }
        };

        if storage.columns.len() == 1 {
            if let Some(entries) = storage.exact_postings(&vec![key_component.clone()]) {
                consider(entries);
            }
        } else if !storage.exact_only() {
            for (key, entries) in storage.tree.range(vec![key_component.clone()]..) {
                if key.first() != Some(&key_component) {
                    break;
                }
                consider(entries);
            }
        }
        drop(indexes);

        let Some(row_id) = best_row_id else {
            return Ok(None);
        };
        let Some(row) = self.committed_row_at(&policy.joined_table, row_id, snapshot)? else {
            return Ok(None);
        };
        let Some(value) = row.values.get(&policy.joined_column) else {
            return Ok(None);
        };
        if !values_equal_for_rank_join(value, &join_value) {
            return Ok(None);
        }
        if !self.row_read_allowed_for_change(&policy.joined_table, &row, snapshot) {
            return Ok(None);
        }
        Ok(Some(row))
    }

    fn joined_row_for_rank_policy_in_tx(
        &self,
        tx: TxId,
        policy: &RankPolicy,
        join_value: &Value,
        snapshot: SnapshotId,
    ) -> Result<Option<VersionedRow>> {
        let rows = self.scan_in_tx_raw(tx, &policy.joined_table, snapshot)?;
        let mut best: Option<VersionedRow> = None;
        for row in rows {
            let Some(value) = row.values.get(&policy.joined_column) else {
                continue;
            };
            if !values_equal_for_rank_join(value, join_value) {
                continue;
            }
            if !self.row_read_allowed_for_change(&policy.joined_table, &row, snapshot) {
                continue;
            }
            if best
                .as_ref()
                .is_none_or(|current| current.row_id < row.row_id)
            {
                best = Some(row);
            }
        }
        Ok(best)
    }

    fn resolve_rank_formula_column(
        &self,
        policy: &RankPolicy,
        anchor: &VersionedRow,
        joined: Option<&VersionedRow>,
        column: &str,
    ) -> std::result::Result<Option<f32>, FormulaEvalError> {
        if let Some(value) = anchor.values.get(column) {
            return rank_value_to_number(value, column);
        }
        let Some(joined) = joined else {
            return Ok(None);
        };
        if self.corrupt_joined_values.read().contains(&(
            policy.joined_table.clone(),
            joined.row_id,
            column.to_string(),
        )) {
            return Err(FormulaEvalError::CorruptJoinedColumn {
                column: column.to_string(),
            });
        }
        let value = joined.values.get(column).unwrap_or(&Value::Null);
        rank_value_to_number(value, column)
    }

    fn warn_rank_eval_error(
        &self,
        table: &str,
        column: &str,
        row_id: RowId,
        err: &FormulaEvalError,
    ) {
        let mut reason = err.reason();
        if reason.len() > 256 {
            reason.truncate(253);
            reason.push_str("...");
        }
        tracing::warn!(
            name: "rank_policy_eval_error",
            target: "rank_policy_eval_error",
            index = %rank_index_name(table, column),
            row_id = row_id.0,
            reason = %reason,
            "rank_policy_eval_error"
        );
    }

    fn search_result_values_in_tx(
        &self,
        tx: Option<TxId>,
        index: &VectorIndexRef,
        row_id: RowId,
        snapshot: SnapshotId,
        mut values: HashMap<String, Value>,
    ) -> Result<HashMap<String, Value>> {
        if let Some(entry) = self.vector_entry_for_row_in_tx(tx, index, row_id, snapshot)? {
            values.insert(index.column.clone(), Value::Vector(entry.vector));
        }
        Ok(values)
    }

    fn pending_vector_dimension(&self, tx: TxId, index: &VectorIndexRef) -> Result<Option<usize>> {
        self.tx_mgr.with_write_set(tx, |ws| {
            ws.vector_inserts
                .iter()
                .rev()
                .find(|entry| entry.index == *index && entry.deleted_tx.is_none())
                .map(|entry| entry.vector.len())
        })
    }

    fn direct_vector_dimension_error(
        &self,
        index: &VectorIndexRef,
        expected: usize,
        actual: usize,
    ) -> Error {
        Error::VectorIndexDimensionMismatch {
            index: index.clone(),
            expected,
            actual,
        }
    }

    /// What admitting one vector body into the vector store costs, at
    /// admission and at the rollback that returns it alike. This is the raw
    /// body only: an F32 column's relational projection lives inside the row
    /// values and is carried by the row's own charge, never by the vector.
    pub(crate) fn vector_insert_accounted_bytes(
        &self,
        index: &VectorIndexRef,
        dimension: usize,
    ) -> usize {
        self.vector_store
            .index_layout(index)
            .ok()
            .map(|layout| layout.quantization)
            .unwrap_or(VectorQuantization::F32)
            .storage_bytes(dimension)
    }

