/// Deterministic observation points inside a memory-limit transition, so a
/// concurrency contract can be stated as a measurement instead of an argument.
/// The hook fires on the transitioning thread while another thread inspects the
/// accountant; production carries neither the module nor its fire sites.
#[cfg(feature = "test-seams")]
pub(crate) mod memory_limit_transition_seam {
    use std::cell::RefCell;
    use std::sync::Arc;

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub(crate) enum TransitionPhase {
        BeforeDurableWrite,
        AfterDurableWrite,
    }

    type Hook = Arc<dyn Fn(TransitionPhase) + Send + Sync>;

    thread_local! {
        /// Armed on the thread that performs the transition, so a test that
        /// suspends one transition can never suspend an unrelated one running
        /// beside it.
        static PAUSE: RefCell<Option<Hook>> = const { RefCell::new(None) };
    }

    pub(crate) fn arm_memory_limit_transition_pause_for_test(hook: Hook) {
        PAUSE.with(|pause| *pause.borrow_mut() = Some(hook));
    }

    pub(crate) fn disarm_memory_limit_transition_pause_for_test() {
        PAUSE.with(|pause| *pause.borrow_mut() = None);
    }

    pub(super) fn observe(phase: TransitionPhase) {
        let hook = PAUSE.with(|pause| pause.borrow().clone());
        if let Some(hook) = hook {
            hook(phase);
        }
    }
}

#[cfg(test)]
mod stale_staged_delete_tests {
    use super::*;

    fn by_id(id: uuid::Uuid) -> HashMap<String, Value> {
        HashMap::from([("id".to_owned(), Value::Uuid(id))])
    }

    /// A delete whose row another writer already removed commits as a no-op,
    /// and a no-op is traceless: the second commit reports no affected row,
    /// the history a push would carry gains no second deletion, and the
    /// reopened store is the one the first delete left.
    #[test]
    fn a_stale_staged_delete_leaves_no_second_deletion_anywhere() {
        let directory = tempfile::TempDir::new().expect("task-scoped stale-delete directory");
        let path = directory.path().join("stale-delete.db");
        let id = uuid::Uuid::from_u128(0x5721);

        let db = Database::open(&path).expect("open the store");
        db.execute(
            "CREATE TABLE notes (id UUID PRIMARY KEY, body TEXT)",
            &HashMap::new(),
        )
        .expect("declare the table");
        db.execute("CREATE INDEX notes_body ON notes (body)", &HashMap::new())
            .expect("declare the index the delete has to maintain");
        db.execute(
            "INSERT INTO notes (id, body) VALUES ($id, 'first')",
            &by_id(id),
        )
        .expect("seed the row both writers will delete");

        let stale = db
            .begin()
            .expect("begin the transaction that will go stale");
        let staged = db
            .execute_in_tx(stale, "DELETE FROM notes WHERE id = $id", &by_id(id))
            .expect("stage the delete while the row is still there");
        assert_eq!(staged.rows_affected, 1, "the delete staged one row");

        db.execute("DELETE FROM notes WHERE id = $id", &by_id(id))
            .expect("another writer removes the same row first");

        let after_the_real_delete = db.changes_since(Lsn(0));
        let deletions_before = after_the_real_delete
            .rows
            .iter()
            .filter(|change| change.deleted)
            .count();
        assert_eq!(deletions_before, 1, "one writer deleted the row once");

        db.commit(stale).expect("the stale delete commits");

        let after_the_stale_commit = db.changes_since(Lsn(0));
        assert_eq!(
            after_the_stale_commit
                .rows
                .iter()
                .filter(|change| change.deleted)
                .count(),
            deletions_before,
            "the no-op raises no second deletion for a peer to apply"
        );
        assert_eq!(
            after_the_stale_commit.rows.len(),
            after_the_real_delete.rows.len(),
            "the no-op adds nothing at all to the history a push would carry"
        );
        assert!(
            db.execute("SELECT id FROM notes", &HashMap::new())
                .expect("read the table back")
                .rows
                .is_empty(),
            "the row is gone, deleted exactly once"
        );

        db.close().expect("close the store");
        let reopened = Database::open(&path).expect("reopen the store");
        assert!(
            reopened
                .execute("SELECT id FROM notes", &HashMap::new())
                .expect("read the reopened table")
                .rows
                .is_empty(),
            "the reopened store holds what the one real delete left"
        );
        assert_eq!(
            reopened
                .changes_since(Lsn(0))
                .rows
                .iter()
                .filter(|change| change.deleted)
                .count(),
            deletions_before,
            "the durable history carries one deletion, not two"
        );
        reopened.close().expect("close the reopened store");
    }
}

#[cfg(test)]
mod checkpoint_export_body_tests {
    use super::*;
    use crate::Database;
    use contextdb_core::Value;
    use std::collections::HashMap;
    use std::path::Path;

    /// Big enough that the disk-backed committed directory sheds it, which is
    /// the whole reason the export has to go back to the store for it.
    const WIDE_BODY: usize = 8 * 1024;

    fn seeded(path: &Path) -> Database {
        let database = Database::open(path).expect("claim a store to seed");
        database
            .execute(
                "CREATE TABLE notes (id INTEGER PRIMARY KEY, body TEXT NOT NULL)",
                &HashMap::new(),
            )
            .expect("declare the exported table");
        database
            .execute(
                "INSERT INTO notes (id, body) VALUES (1, $body)",
                &HashMap::from([("body".to_owned(), Value::Text("n".repeat(WIDE_BODY)))]),
            )
            .expect("commit one wide body");
        database
    }

    /// The rows the export loop hands the loader: the committed directory's
    /// own, whose large bodies it no longer carries.
    fn exportable_rows(database: &Database, table: &str) -> Vec<VersionedRow> {
        database
            .relational_store
            .tables
            .read()
            .get(table)
            .cloned()
            .unwrap_or_default()
    }

    /// An artifact claims one commit boundary and every body in it. A body the
    /// captured snapshot cannot produce is not something to paper over with
    /// whatever the directory happened to keep: the row would restore with a
    /// payload it never had. So the export stops instead, and it stops the
    /// same way whether the row is gone or the whole table is.
    #[test]
    fn an_exported_body_the_captured_snapshot_cannot_produce_stops_the_export() {
        let directory = tempfile::TempDir::new().expect("task-scoped export directory");
        let path = directory.path().join("export-body.db");
        let database = seeded(&path);
        let meta = database.table_meta("notes").expect("the declared table");
        let source = database
            .persistence
            .as_ref()
            .expect("a stored database has a checkpoint source")
            .checkpoint_read_source()
            .expect("capture the pinned durable source");

        let mut rows = exportable_rows(&database, "notes");
        assert_eq!(rows.len(), 1, "one committed row to export");
        rows[0]
            .values
            .insert("body".to_owned(), Value::Text(String::new()));
        let (filled, admitted) = source
            .load_export_row_values("notes", &meta, &mut rows)
            .expect("the pinned source restores the committed body");
        assert_eq!(filled, 1, "the whole run fits the default budget");
        drop(admitted);
        assert_eq!(
            rows[0].values.get("body"),
            Some(&Value::Text("n".repeat(WIDE_BODY))),
            "the healthy body comes back whole from the snapshot the artifact claims"
        );

        let mut absent_row = rows.clone();
        absent_row[0].lsn = Lsn(absent_row[0].lsn.0.saturating_add(1_000));
        let refused = source
            .load_export_row_values("notes", &meta, &mut absent_row)
            .map(|(filled, _)| filled)
            .expect_err("a row the captured snapshot does not hold stops the export");
        assert!(
            matches!(refused, Error::StoreCorrupted { .. }),
            "a body the snapshot cannot produce is a corruption refusal, not a silent gap: \
             {refused}"
        );

        let mut orphan_table = rows.clone();
        let missing = source
            .load_export_row_values("never_created", &meta, &mut orphan_table)
            .map(|(filled, _)| filled)
            .expect_err("a table the captured snapshot does not hold stops the export");
        assert!(
            matches!(missing, Error::StoreCorrupted { .. }),
            "a table the snapshot cannot produce is a corruption refusal too: {missing}"
        );

        drop(source);
        database.close().expect("release the store");
    }

    /// An export of bodies the directory has shed is a copy out of the store,
    /// and a copy is memory. It is admitted through the same budget the rest
    /// of the database answers to, before the body is read out, and an export
    /// whose bodies do not all fit at once comes back in runs that do rather
    /// than in one copy nothing admitted. A budget that cannot hold even one
    /// body is the typed refusal, because there is no smaller run to fall
    /// back to.
    #[test]
    fn exported_bodies_come_back_in_runs_the_memory_budget_admits() {
        const BODIES: usize = 4;
        let directory = tempfile::TempDir::new().expect("task-scoped export directory");
        let path = directory.path().join("export-admission.db");
        let database = Database::open(&path).expect("claim a store to seed");
        database
            .execute(
                "CREATE TABLE notes (id INTEGER PRIMARY KEY, body TEXT NOT NULL)",
                &HashMap::new(),
            )
            .expect("declare the exported table");
        for id in 0..BODIES {
            database
                .execute(
                    "INSERT INTO notes (id, body) VALUES ($id, $body)",
                    &HashMap::from([
                        ("id".to_owned(), Value::Int64(id as i64)),
                        ("body".to_owned(), Value::Text("n".repeat(WIDE_BODY))),
                    ]),
                )
                .expect("commit one wide body");
        }
        let meta = database.table_meta("notes").expect("the declared table");
        let source = database
            .persistence
            .as_ref()
            .expect("a stored database has a checkpoint source")
            .checkpoint_read_source()
            .expect("capture the pinned durable source");
        let mut rows = exportable_rows(&database, "notes");
        assert_eq!(rows.len(), BODIES, "one committed row per seeded body");

        // Room for one body's copy and not for all of them.
        let one_body = WIDE_BODY.saturating_mul(2).saturating_add(4096);
        database
            .set_memory_limit(Some(
                database.accountant().usage().used.saturating_add(one_body),
            ))
            .expect("declare a budget one body fits in");
        let (filled, admitted) = source
            .load_export_row_values("notes", &meta, &mut rows)
            .expect("a run the budget admits is not a refusal");
        assert!(
            (1..BODIES).contains(&filled),
            "the run stops at the last body the budget admitted, not at the batch: {filled}"
        );
        assert!(
            database.accountant().usage().used > 0,
            "the copied bodies are charged while the caller still holds them"
        );
        for row in &mut rows[..filled] {
            row.values = HashMap::new();
        }
        drop(admitted);

        let (next, admitted) = source
            .load_export_row_values("notes", &meta, &mut rows[filled..])
            .expect("the next run picks up where the budget stopped the last one");
        assert!(next >= 1, "every run makes progress");
        drop(admitted);

        // A budget with no room for one body at all.
        database
            .set_memory_limit(Some(database.accountant().usage().used.saturating_add(8)))
            .expect("declare a budget no body fits in");
        let refused = source
            .load_export_row_values("notes", &meta, &mut rows)
            .map(|(filled, _)| filled)
            .expect_err("a body that does not fit on its own is refused");
        assert!(
            matches!(refused, Error::MemoryBudgetExceeded { .. }),
            "a body the budget cannot hold is the typed memory refusal: {refused}"
        );

        drop(source);
        database.set_memory_limit(None).expect("lift the budget");
        database.close().expect("release the store");
    }
}

#[cfg(test)]
mod table_size_estimate_tests {
    use super::*;
    use crate::Database;
    use contextdb_core::Value;
    use std::collections::HashMap;

    /// Bigger than the resident projection keeps, so the answer has to come
    /// from the store.
    const WIDE_BODY: usize = 8 * 1024;
    const ROWS: usize = 4;

    fn seeded(path: &std::path::Path) -> Database {
        let database = Database::open(path).expect("claim a store to seed");
        database
            .execute(
                "CREATE TABLE notes (id INTEGER PRIMARY KEY, body TEXT NOT NULL)",
                &HashMap::new(),
            )
            .expect("declare the measured table");
        for id in 0..ROWS {
            database
                .execute(
                    "INSERT INTO notes (id, body) VALUES ($id, $body)",
                    &HashMap::from([
                        ("id".to_owned(), Value::Int64(id as i64)),
                        ("body".to_owned(), Value::Text("n".repeat(WIDE_BODY))),
                    ]),
                )
                .expect("commit one wide body");
        }
        database
    }

    /// The size of a table is what it occupies, and an operator sizing a disk
    /// acts on it. So a run of rows is admitted before it is inspected, and a
    /// stored length that cannot be read is said out loud: the answer that
    /// carries a reason fails with it, and the answer that carries none says
    /// nothing rather than a number that is too small.
    #[test]
    fn a_table_size_that_cannot_be_read_is_never_reported_as_a_smaller_table() {
        let directory = tempfile::TempDir::new().expect("task-scoped size directory");
        let path = directory.path().join("sized.db");
        let database = seeded(&path);

        let healthy = database
            .table_size_estimates()
            .expect("a healthy store answers for its tables");
        let notes = healthy
            .iter()
            .find(|estimate| estimate.table == "notes")
            .expect("the measured table is answered for");
        assert_eq!(notes.row_count, ROWS as u64, "every live row is counted");
        assert!(
            notes.estimated_live_bytes >= (ROWS * WIDE_BODY) as u64,
            "the answer accounts for the bodies the file is holding: {notes:?}"
        );

        crate::persistence::arm_stored_relational_row_bytes_fault_for_test();
        let failed = database
            .table_size_estimates()
            .expect_err("a stored size that cannot be read stops the answer");
        assert!(
            failed
                .to_string()
                .contains("injected stored relational row size read failure"),
            "the caller is told what failed: {failed}"
        );

        crate::persistence::arm_stored_relational_row_bytes_fault_for_test();
        assert!(
            database.table_size_estimate("notes").is_none(),
            "the answer with nowhere to put a reason says nothing at all rather than \
             a figure that is too small"
        );

        // A run of rows is room, and room is admitted: a budget with none left
        // refuses the answer instead of building the whole table's lists.
        let used = database.accountant().usage().used;
        database
            .set_memory_limit(Some(used.saturating_add(8)))
            .expect("declare a budget with no room to spare");
        let refused = database
            .table_size_estimates()
            .expect_err("sizing a table takes room it must be admitted for");
        assert!(
            matches!(refused, Error::MemoryBudgetExceeded { .. }),
            "the refusal is the typed memory one: {refused}"
        );
        database.set_memory_limit(None).expect("lift the budget");

        database.close().expect("release the store");
    }
}

#[cfg(test)]
mod policy_hold_legacy_format_tests {
    use super::*;

    // Serialize-only snapshots of the durable layouts before dependency metadata
    // was appended. They deliberately cannot decode on behalf of the new types.
    #[derive(Serialize)]
    struct LegacyHold<'a> {
        source_node_id: &'a str,
        tenant_id: &'a Option<TenantId>,
        source_incarnation: &'a Option<Incarnation>,
        author_node_id: &'a Option<String>,
        source_lsn: Lsn,
        table: &'a str,
        refusal: &'a str,
        table_absent: bool,
    }

    #[derive(Serialize)]
    struct LegacyHeldData<'a> {
        changes: &'a ChangeSet,
        arrivals: &'a HashMap<Lsn, Option<Lsn>>,
        receipt: &'a SyncApplyReceipt,
        hub_node_id: &'a str,
        lineages: &'a Vec<(String, NaturalKey, Lsn, crate::protocol::WireRowLineage)>,
        outcome_key: &'a SyncPushOutcomeKey,
    }

    #[test]
    fn old_policy_hold_tuple_and_map_decode_with_empty_edge_types_and_stable_release_key() {
        let hold = DurablePolicyHold {
            source_node_id: "source".into(),
            tenant_id: Some(TenantId::from("tenant")),
            source_incarnation: Some(Incarnation(17)),
            author_node_id: Some("author".into()),
            source_lsn: Lsn(23),
            table: "edges".into(),
            refusal: "policy refusal".into(),
            table_absent: true,
            dag_edge_types: Vec::new(),
        };
        let old = LegacyHold {
            source_node_id: &hold.source_node_id,
            tenant_id: &hold.tenant_id,
            source_incarnation: &hold.source_incarnation,
            author_node_id: &hold.author_node_id,
            source_lsn: hold.source_lsn,
            table: &hold.table,
            refusal: &hold.refusal,
            table_absent: hold.table_absent,
        };
        let tuple = rmp_serde::to_vec(&old).expect("old hold tuple");
        let map = rmp_serde::to_vec_named(&old).expect("old hold map");
        for bytes in [&tuple, &map] {
            let decoded: DurablePolicyHold =
                rmp_serde::from_slice(bytes).expect("old hold layout remains readable");
            assert_eq!(decoded, hold);
            assert!(decoded.dag_edge_types.is_empty());
        }
        let old_digest = blake3::hash(&tuple).to_hex().to_string();
        assert_eq!(
            Database::policy_hold_release_key(&hold).expect("release key"),
            format!("{}{old_digest}", Database::POLICY_HOLD_RELEASE_PREFIX)
        );
    }

    #[test]
    fn old_held_data_tuple_and_map_decode_with_empty_held_tables() {
        let changes = ChangeSet::default();
        let arrivals = HashMap::from([(Lsn(23), Some(Lsn(29)))]);
        let receipt = SyncApplyReceipt {
            tenant_id: TenantId::from("tenant"),
            node_id: "source".into(),
            incarnation: Incarnation(17),
            source_lsn: Lsn(23),
            dependency_complete: true,
            hub_contact_ms: Some(1234),
        };
        let lineages = Vec::new();
        let outcome_key = SyncPushOutcomeKey {
            storage_key: "legacy outcome".into(),
            incarnation: Incarnation(17),
            request_digest: [7; 32],
            diagnostic_identities: Vec::new(),
        };
        let old = LegacyHeldData {
            changes: &changes,
            arrivals: &arrivals,
            receipt: &receipt,
            hub_node_id: "hub",
            lineages: &lineages,
            outcome_key: &outcome_key,
        };
        for bytes in [
            rmp_serde::to_vec(&old).expect("old held data tuple"),
            rmp_serde::to_vec_named(&old).expect("old held data map"),
        ] {
            let decoded: DurablePolicyHeldData =
                rmp_serde::from_slice(&bytes).expect("old held data layout remains readable");
            assert_eq!(decoded.arrivals, arrivals);
            assert_eq!(decoded.receipt.source_lsn, receipt.source_lsn);
            assert_eq!(
                decoded.outcome_key.request_digest,
                outcome_key.request_digest
            );
            assert!(decoded.changes.is_empty());
            assert!(decoded.lineages.is_empty());
            assert!(decoded.held_tables.is_empty());
        }
    }
}

